def normalize_signal_record(item: dict[str, Any], fallback_key: str | None = None) -> dict[str, Any] | None:
    """Normalize an ACTIVE setup candidate into a durable signal record."""

    if not isinstance(item, dict):
        return None

    payload = item.get("signal") if isinstance(item.get("signal"), dict) else item
    if not isinstance(payload, dict):
        return None

    signal_id = str(
        payload.get("signalId")
        or item.get("signalId")
        or fallback_key
        or ""
    ).strip()

    symbol = str(payload.get("symbol") or item.get("symbol") or "").upper().strip()
    setup_slug = str(payload.get("setupSlug") or item.get("setupSlug") or "").strip()

    if not signal_id and symbol and setup_slug:
        created = str(payload.get("createdAt") or item.get("updatedAt") or datetime.now(timezone.utc).isoformat())
        signal_id = f"stock:{symbol}:{setup_slug}:{created}"

    if not signal_id or not symbol:
        return None

    now_iso = datetime.now(timezone.utc).isoformat()
    candle_freshness = payload.get("candleFreshness") if isinstance(payload.get("candleFreshness"), dict) else {}
    trigger_time = (
        payload.get("triggerTime")
        or item.get("triggerTime")
        or candle_freshness.get("latestCandleAt")
        or payload.get("createdAt")
        or item.get("updatedAt")
        or now_iso
    )

    created_at = str(payload.get("createdAt") or item.get("updatedAt") or now_iso)
    session_date = str(trigger_time or created_at)[:10]

    targets = payload.get("targets") if isinstance(payload.get("targets"), list) else item.get("targets")
    targets = targets if isinstance(targets, list) else []

    # S8.23A: every client candidate needs a clear invalidation.
    # If the setup engine did not provide a text invalidation, derive it from the hard stop.
    direction_value = str(payload.get("direction") or item.get("direction") or "").lower().strip()
    stop_value = payload.get("stop") if payload.get("stop") is not None else item.get("stop")
    invalidation_value = (
        payload.get("invalidation")
        or item.get("invalidation")
        or payload.get("invalidIf")
        or item.get("invalidIf")
        or payload.get("invalidationReason")
        or item.get("invalidationReason")
    )

    if (invalidation_value is None or str(invalidation_value).strip() == "") and stop_value is not None:
        if direction_value == "long":
            invalidation_value = f"Invalid if price loses the stop level at {stop_value}."
        elif direction_value == "short":
            invalidation_value = f"Invalid if price reclaims above the stop level at {stop_value}."
        else:
            invalidation_value = f"Invalid if price trades through the stop level at {stop_value}."

    record = {
        "signalId": signal_id,
        "assetType": payload.get("assetType") or "stock",
        "symbol": symbol,
        "setupSlug": setup_slug,
        "setupName": payload.get("setupName") or item.get("setupName"),
        "direction": payload.get("direction") or item.get("direction"),
        "status": payload.get("status") or item.get("status"),
        "entry": payload.get("entry"),
        "entryZone": payload.get("entryZone") or item.get("entryZone"),
        "stop": payload.get("stop") or item.get("stop"),
        "targets": targets,
        "invalidation": invalidation_value,
        "invalidIf": invalidation_value,
        "rrToTp1": payload.get("rrToTp1") or item.get("rrToTp1"),
        "rrToTp2": payload.get("rrToTp2") or item.get("rrToTp2"),
        "entryDistancePct": payload.get("entryDistancePct") or item.get("entryDistancePct"),
        "primaryTrigger": payload.get("primaryTrigger") or item.get("primaryTrigger"),
        "triggers": payload.get("triggers") or item.get("triggers") or [],
        "signalScore": payload.get("signalScore") or item.get("signalScore"),
        "signalGrade": payload.get("signalGrade") or item.get("signalGrade"),
        "premiumSignal": bool(payload.get("premiumSignal") or item.get("premiumSignal")),
        "telegramEligible": bool(payload.get("telegramEligible") or item.get("telegramEligible")),
        "qualityStatus": item.get("qualityStatus") or payload.get("qualityStatus"),
        "confirmation": payload.get("confirmation") or item.get("confirmation"),
        "candleFreshness": payload.get("candleFreshness") or item.get("candleFreshness"),
        "isCandleFresh": payload.get("isCandleFresh") if "isCandleFresh" in payload else item.get("isCandleFresh"),
        "createdAt": created_at,
        "triggerTime": trigger_time,
        "sessionDate": session_date,
        "storedAt": now_iso,
        "engineVersion": payload.get("engineVersion") or item.get("engineVersion") or settings.engine_version,
        "rawSignal": payload,
        "source": _s831a2_source_dict(payload, item),
        "candleContext": _s831a2_candle_context(payload, item),
        "marketContext": _s831a2_market_context(payload, item),
        "featureSnapshot": _s831a2_feature_snapshot(payload, item),
        "featureSnapshotVersion": S831A2_FEATURE_SNAPSHOT_VERSION
    }

    return record


def _safe_int(value: Any, fallback: int = 0) -> int:
    try:
        if value is None or value == "":
            return fallback
        return int(float(value))
    except Exception:
        return fallback


def build_signal_storage_key(record: dict[str, Any], fallback_key: str = "") -> str:
    symbol = str(record.get("symbol") or "").upper().strip()
    setup_slug = str(record.get("setupSlug") or "setup").strip()
    session_date = str(record.get("sessionDate") or "").strip()

    if not session_date:
        created_at = str(record.get("createdAt") or record.get("triggerTime") or "")
        session_date = created_at[:10] if len(created_at) >= 10 else datetime.now(timezone.utc).date().isoformat()

    if not symbol:
        symbol = str(fallback_key).split(":", 1)[0].upper().strip() or "UNKNOWN"

    return f"{symbol}:{setup_slug}:{session_date}"


def should_replace_signal(existing: dict[str, Any] | None, incoming: dict[str, Any]) -> bool:
    if not existing:
        return True

    old_score = _safe_int(existing.get("signalScore"))
    new_score = _safe_int(incoming.get("signalScore"))

    if new_score > old_score:
        return True
    if new_score < old_score:
        return False

    old_created = str(existing.get("createdAt") or existing.get("storedAt") or "")
    new_created = str(incoming.get("createdAt") or incoming.get("storedAt") or "")
    return new_created >= old_created



# === S8.31A2 Persistent signal feature snapshot capture ===
S831A2_FEATURE_SNAPSHOT_VERSION = "s8_31a2_persistent_signal_feature_snapshot_v1"


def _s831a2_num(value: Any, fallback: float | None = None) -> float | None:
    if value is None or isinstance(value, bool):
        return fallback
    try:
        if isinstance(value, str):
            cleaned = value.strip().replace("%", "").replace(",", "")
            if not cleaned:
                return fallback
            return float(cleaned)
        return float(value)
    except Exception:
        return fallback


def _s831a2_nested(obj: dict[str, Any], path: str) -> Any:
    cur: Any = obj
    for part in str(path or "").split("."):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return None
    return cur


def _s831a2_first(*values: Any) -> Any:
    for value in values:
        if value is None:
            continue
        if isinstance(value, str) and not value.strip():
            continue
        return value
    return None


def _s831a2_source_dict(payload: dict[str, Any], item: dict[str, Any]) -> dict[str, Any]:
    for candidate in (
        payload.get("source"),
        item.get("source"),
        _s831a2_nested(payload, "rawSignal.source"),
        _s831a2_nested(item, "rawSignal.source"),
    ):
        if isinstance(candidate, dict) and candidate:
            return dict(candidate)
    return {}


def _s831a2_candle_context(payload: dict[str, Any], item: dict[str, Any]) -> dict[str, Any]:
    source = _s831a2_source_dict(payload, item)
    for candidate in (
        source.get("candleContext"),
        payload.get("candleContext"),
        item.get("candleContext"),
        _s831a2_nested(payload, "source.candleContext"),
        _s831a2_nested(item, "source.candleContext"),
    ):
        if isinstance(candidate, dict) and candidate:
            return dict(candidate)
    return {}


def _s831a2_market_context(payload: dict[str, Any], item: dict[str, Any]) -> dict[str, Any]:
    for candidate in (
        payload.get("marketContext"),
        item.get("marketContext"),
        _s831a2_nested(payload, "source.marketContext"),
        _s831a2_nested(item, "source.marketContext"),
    ):
        if isinstance(candidate, dict) and candidate:
            return dict(candidate)
    return {}


def _s831a2_feature_snapshot(payload: dict[str, Any], item: dict[str, Any]) -> dict[str, Any]:
    source = _s831a2_source_dict(payload, item)
    candle = _s831a2_candle_context(payload, item)
    market = _s831a2_market_context(payload, item)

    entry = _s831a2_num(_s831a2_first(payload.get("entry"), item.get("entry"), _s831a2_nested(payload, "entryZone.min")))
    stop = _s831a2_num(_s831a2_first(payload.get("stop"), item.get("stop")))

    risk = abs(float(entry) - float(stop)) if entry is not None and stop is not None else None
    risk_pct = round((abs(float(risk)) / abs(float(entry))) * 100.0, 4) if risk is not None and entry not in (None, 0) else None

    vwap = _s831a2_num(_s831a2_first(candle.get("vwap"), payload.get("vwap"), item.get("vwap")))
    distance_from_vwap_pct = _s831a2_num(_s831a2_first(
        candle.get("distanceFromVwapPct"),
        payload.get("distanceFromVwapPct"),
        item.get("distanceFromVwapPct"),
    ))

    if distance_from_vwap_pct is None and entry is not None and vwap not in (None, 0):
        distance_from_vwap_pct = round(((float(entry) - float(vwap)) / float(vwap)) * 100.0, 4)

    snapshot = {
        "version": S831A2_FEATURE_SNAPSHOT_VERSION,
        "capturedAt": datetime.now(timezone.utc).isoformat(),

        "entry": entry,
        "stop": stop,
        "risk": risk,
        "riskPct": risk_pct,

        "vwap": vwap,
        "ema20_5m": _s831a2_num(_s831a2_first(candle.get("ema20_5m"), payload.get("ema20_5m"), item.get("ema20_5m"))),
        "atr14_5m": _s831a2_num(_s831a2_first(candle.get("atr14_5m"), payload.get("atr14_5m"), item.get("atr14_5m"))),
        "rsi14_5m": _s831a2_num(_s831a2_first(candle.get("rsi14_5m"), payload.get("rsi14_5m"), item.get("rsi14_5m"))),
        "hod": _s831a2_num(_s831a2_first(candle.get("hod"), payload.get("hod"), item.get("hod"))),
        "lod": _s831a2_num(_s831a2_first(candle.get("lod"), payload.get("lod"), item.get("lod"))),
        "volumeAcceleration": _s831a2_num(_s831a2_first(candle.get("volumeAcceleration"), payload.get("volumeAcceleration"), item.get("volumeAcceleration"))),
        "distanceFromVwapPct": distance_from_vwap_pct,

        "gapPct": _s831a2_num(_s831a2_first(market.get("gapPct"), payload.get("gapPct"), payload.get("gapPercent"), item.get("gapPct"), item.get("gapPercent"))),
        "changePct": _s831a2_num(_s831a2_first(market.get("changePct"), market.get("changePercent"), payload.get("changePct"), payload.get("changePercent"), item.get("changePct"), item.get("changePercent"))),
        "rvol": _s831a2_num(_s831a2_first(market.get("rvol"), market.get("relativeVolume"), payload.get("rvol"), payload.get("relativeVolume"), item.get("rvol"), item.get("relativeVolume"))),
        "volume": _s831a2_num(_s831a2_first(market.get("volume"), payload.get("volume"), item.get("volume"))),
        "premarketVolume": _s831a2_num(_s831a2_first(market.get("premarketVolume"), market.get("preMarketVolume"), payload.get("premarketVolume"), item.get("premarketVolume"))),
        "spreadPct": _s831a2_num(_s831a2_first(market.get("spreadPct"), market.get("spreadPercent"), payload.get("spreadPct"), item.get("spreadPct"))),
        "marketCap": _s831a2_num(_s831a2_first(market.get("marketCap"), payload.get("marketCap"), item.get("marketCap"))),
        "floatShares": _s831a2_num(_s831a2_first(market.get("floatShares"), market.get("float"), payload.get("floatShares"), payload.get("float"), item.get("floatShares"), item.get("float"))),
        "shortFloatPct": _s831a2_num(_s831a2_first(market.get("shortFloatPct"), market.get("shortFloat"), payload.get("shortFloatPct"), payload.get("shortFloat"), item.get("shortFloatPct"), item.get("shortFloat"))),

        "sourceAvailable": bool(source),
        "candleContextAvailable": bool(candle),
        "marketContextAvailable": bool(market),
    }

    critical = [
        "entry",
        "stop",
        "risk",
        "vwap",
        "ema20_5m",
        "atr14_5m",
        "rsi14_5m",
        "volumeAcceleration",
        "distanceFromVwapPct",
        "gapPct",
        "changePct",
        "rvol",
        "spreadPct",
    ]

    missing = [key for key in critical if snapshot.get(key) is None]
    snapshot["missingCriticalFields"] = missing
    snapshot["missingCriticalCount"] = len(missing)
    snapshot["hasEnoughForFailureAnalysis"] = len(missing) <= 6

    return snapshot

# === /S8.31A2 Persistent signal feature snapshot capture ===



# === S8.31A3 Feature Snapshot Enrichment ===
S831A3_FEATURE_SNAPSHOT_ENRICHMENT_VERSION = "s8_31a3_feature_snapshot_enrichment_v1"


def _s831a3_pct(numerator: Any, denominator: Any) -> float | None:
    a = _s831a2_num(numerator)
    b = _s831a2_num(denominator)
    if a is None or b in (None, 0):
        return None
    return round(((float(a) - float(b)) / float(b)) * 100.0, 4)


def _s831a3_watch_candidate(payload: dict[str, Any], item: dict[str, Any]) -> dict[str, Any]:
    source = _s831a2_source_dict(payload, item)

    for candidate in (
        source.get("watchCandidate"),
        payload.get("watchCandidate"),
        item.get("watchCandidate"),
        _s831a2_nested(payload, "source.watchCandidate"),
        _s831a2_nested(item, "source.watchCandidate"),
    ):
        if isinstance(candidate, dict) and candidate:
            return dict(candidate)

    return {}


def _s831a3_raw_quote(watch: dict[str, Any]) -> dict[str, Any]:
    raw = watch.get("raw") if isinstance(watch.get("raw"), dict) else {}
    quote = raw.get("quote") if isinstance(raw.get("quote"), dict) else {}

    merged: dict[str, Any] = {}
    for src in (quote, raw, watch):
        if isinstance(src, dict):
            for key, value in src.items():
                if key not in merged and value is not None:
                    merged[key] = value

    return merged


def _s831a2_market_context(payload: dict[str, Any], item: dict[str, Any]) -> dict[str, Any]:
    explicit: dict[str, Any] = {}

    for candidate in (
        payload.get("marketContext"),
        item.get("marketContext"),
        _s831a2_nested(payload, "source.marketContext"),
        _s831a2_nested(item, "source.marketContext"),
    ):
        if isinstance(candidate, dict) and candidate:
            explicit.update(candidate)

    watch = _s831a3_watch_candidate(payload, item)
    quote = _s831a3_raw_quote(watch)

    open_price = _s831a2_first(quote.get("open"), watch.get("open"))
    previous_close = _s831a2_first(
        quote.get("previousClose"),
        quote.get("previous_close"),
        watch.get("previousClose"),
        watch.get("previous_close"),
    )

    gap_pct = _s831a2_first(
        explicit.get("gapPct"),
        explicit.get("gapPercent"),
        quote.get("gapPct"),
        quote.get("gapPercent"),
        _s831a3_pct(open_price, previous_close),
    )

    return {
        **explicit,
        "price": _s831a2_first(explicit.get("price"), quote.get("price"), watch.get("price")),
        "open": open_price,
        "previousClose": previous_close,
        "gapPct": gap_pct,
        "changePct": _s831a2_first(
            explicit.get("changePct"),
            explicit.get("changePercent"),
            watch.get("changePercent"),
            watch.get("changePct"),
            quote.get("changePercentage"),
            quote.get("changesPercentage"),
            quote.get("changePercent"),
            quote.get("changePct"),
        ),
        "volume": _s831a2_first(
            explicit.get("volume"),
            watch.get("volume"),
            quote.get("volume"),
        ),
        "marketCap": _s831a2_first(
            explicit.get("marketCap"),
            watch.get("marketCap"),
            quote.get("marketCap"),
        ),
        "dayHigh": _s831a2_first(quote.get("dayHigh"), watch.get("dayHigh")),
        "dayLow": _s831a2_first(quote.get("dayLow"), watch.get("dayLow")),
        "yearHigh": _s831a2_first(quote.get("yearHigh"), watch.get("yearHigh")),
        "yearLow": _s831a2_first(quote.get("yearLow"), watch.get("yearLow")),
        "universe": _s831a2_first(watch.get("universe"), explicit.get("universe")),
        "sourceBucket": _s831a2_first(watch.get("sourceBucket"), explicit.get("sourceBucket")),
        "inPlayScore": _s831a2_first(watch.get("inPlayScore"), explicit.get("inPlayScore")),
    }


def _s831a2_candle_context(payload: dict[str, Any], item: dict[str, Any]) -> dict[str, Any]:
    source = _s831a2_source_dict(payload, item)

    candle: dict[str, Any] = {}

    for candidate in (
        source.get("candleContext"),
        payload.get("candleContext"),
        item.get("candleContext"),
        _s831a2_nested(payload, "source.candleContext"),
        _s831a2_nested(item, "source.candleContext"),
    ):
        if isinstance(candidate, dict) and candidate:
            candle.update(candidate)

    confirmation = payload.get("confirmation") if isinstance(payload.get("confirmation"), dict) else {}
    if not confirmation and isinstance(item.get("confirmation"), dict):
        confirmation = item.get("confirmation")

    ema_loss = confirmation.get("ema20Loss5m") if isinstance(confirmation.get("ema20Loss5m"), dict) else {}
    vwap_rejection = confirmation.get("vwapRejection5m") if isinstance(confirmation.get("vwapRejection5m"), dict) else {}
    failed_hod = confirmation.get("failedHodReclaim5m") if isinstance(confirmation.get("failedHodReclaim5m"), dict) else {}

    if candle.get("vwap") is None:
        candle["vwap"] = _s831a2_first(vwap_rejection.get("vwap"), payload.get("vwap"), item.get("vwap"))

    if candle.get("ema20_5m") is None:
        candle["ema20_5m"] = _s831a2_first(ema_loss.get("ema20_5m"), payload.get("ema20_5m"), item.get("ema20_5m"))

    if candle.get("hod") is None:
        candle["hod"] = _s831a2_first(failed_hod.get("hod"), payload.get("hod"), item.get("hod"))

    if candle.get("latestPrice") is None:
        candle["latestPrice"] = _s831a2_first(payload.get("currentPrice"), payload.get("price"), item.get("currentPrice"), item.get("price"), payload.get("entry"), item.get("entry"))

    if candle.get("distanceFromVwapPct") is None:
        entry = _s831a2_first(payload.get("entry"), item.get("entry"))
        candle["distanceFromVwapPct"] = _s831a3_pct(entry, candle.get("vwap"))

    if candle:
        candle["enrichmentVersion"] = S831A3_FEATURE_SNAPSHOT_ENRICHMENT_VERSION

    return candle


def _s831a2_feature_snapshot(payload: dict[str, Any], item: dict[str, Any]) -> dict[str, Any]:
    source = _s831a2_source_dict(payload, item)
    candle = _s831a2_candle_context(payload, item)
    market = _s831a2_market_context(payload, item)

    entry = _s831a2_num(_s831a2_first(payload.get("entry"), item.get("entry"), _s831a2_nested(payload, "entryZone.min")))
    stop = _s831a2_num(_s831a2_first(payload.get("stop"), item.get("stop")))

    risk = abs(float(entry) - float(stop)) if entry is not None and stop is not None else None
    risk_pct = round((abs(float(risk)) / abs(float(entry))) * 100.0, 4) if risk is not None and entry not in (None, 0) else None

    vwap = _s831a2_num(_s831a2_first(candle.get("vwap"), payload.get("vwap"), item.get("vwap")))
    distance_from_vwap_pct = _s831a2_num(_s831a2_first(
        candle.get("distanceFromVwapPct"),
        payload.get("distanceFromVwapPct"),
        item.get("distanceFromVwapPct"),
    ))

    if distance_from_vwap_pct is None and entry is not None and vwap not in (None, 0):
        distance_from_vwap_pct = round(((float(entry) - float(vwap)) / float(vwap)) * 100.0, 4)

    snapshot = {
        "version": S831A3_FEATURE_SNAPSHOT_ENRICHMENT_VERSION,
        "capturedAt": datetime.now(timezone.utc).isoformat(),

        "entry": entry,
        "stop": stop,
        "risk": risk,
        "riskPct": risk_pct,

        "vwap": vwap,
        "ema20_5m": _s831a2_num(_s831a2_first(candle.get("ema20_5m"), payload.get("ema20_5m"), item.get("ema20_5m"))),
        "atr14_5m": _s831a2_num(_s831a2_first(candle.get("atr14_5m"), payload.get("atr14_5m"), item.get("atr14_5m"))),
        "rsi14_5m": _s831a2_num(_s831a2_first(candle.get("rsi14_5m"), payload.get("rsi14_5m"), item.get("rsi14_5m"))),
        "hod": _s831a2_num(_s831a2_first(candle.get("hod"), payload.get("hod"), item.get("hod"))),
        "lod": _s831a2_num(_s831a2_first(candle.get("lod"), payload.get("lod"), item.get("lod"))),
        "volumeAcceleration": _s831a2_num(_s831a2_first(candle.get("volumeAcceleration"), payload.get("volumeAcceleration"), item.get("volumeAcceleration"))),
        "distanceFromVwapPct": distance_from_vwap_pct,

        "gapPct": _s831a2_num(_s831a2_first(market.get("gapPct"), payload.get("gapPct"), payload.get("gapPercent"), item.get("gapPct"), item.get("gapPercent"))),
        "changePct": _s831a2_num(_s831a2_first(market.get("changePct"), market.get("changePercent"), payload.get("changePct"), payload.get("changePercent"), item.get("changePct"), item.get("changePercent"))),
        "rvol": _s831a2_num(_s831a2_first(market.get("rvol"), market.get("relativeVolume"), payload.get("rvol"), payload.get("relativeVolume"), item.get("rvol"), item.get("relativeVolume"))),
        "volume": _s831a2_num(_s831a2_first(market.get("volume"), payload.get("volume"), item.get("volume"))),
        "premarketVolume": _s831a2_num(_s831a2_first(market.get("premarketVolume"), market.get("preMarketVolume"), payload.get("premarketVolume"), item.get("premarketVolume"))),
        "spreadPct": _s831a2_num(_s831a2_first(market.get("spreadPct"), market.get("spreadPercent"), payload.get("spreadPct"), item.get("spreadPct"))),
        "marketCap": _s831a2_num(_s831a2_first(market.get("marketCap"), payload.get("marketCap"), item.get("marketCap"))),
        "floatShares": _s831a2_num(_s831a2_first(market.get("floatShares"), market.get("float"), payload.get("floatShares"), payload.get("float"), item.get("floatShares"), item.get("float"))),
        "shortFloatPct": _s831a2_num(_s831a2_first(market.get("shortFloatPct"), market.get("shortFloat"), payload.get("shortFloatPct"), payload.get("shortFloat"), item.get("shortFloatPct"), item.get("shortFloat"))),

        "sourceAvailable": bool(source),
        "candleContextAvailable": bool(candle),
        "marketContextAvailable": bool(market),
    }

    critical = [
        "entry",
        "stop",
        "risk",
        "vwap",
        "ema20_5m",
        "atr14_5m",
        "rsi14_5m",
        "volumeAcceleration",
        "distanceFromVwapPct",
        "gapPct",
        "changePct",
        "rvol",
        "spreadPct",
    ]

    missing = [key for key in critical if snapshot.get(key) is None]
    snapshot["missingCriticalFields"] = missing
    snapshot["missingCriticalCount"] = len(missing)
    snapshot["hasEnoughForFailureAnalysis"] = len(missing) <= 6

    return snapshot

# === /S8.31A3 Feature Snapshot Enrichment ===


def store_active_signals() -> dict[str, Any]:
    """Rebuild runtime signal storage from current ARMED + ACTIVE candidates.

    Product rule:
    - /engine/signals must show ARMED + ACTIVE so the dashboard is not empty
      while the engine is waiting for 5m confirmation;
    - Telegram remains strict: only ACTIVE + PASSED + premium + telegramEligible
      records are eligible for /engine/signals/telegram;
    - SIGNALS is runtime UI/API storage, rebuilt from the current registry state
      to avoid stale ghost cards after every discovery refresh.
    """

    SIGNALS.clear()

    stored = 0
    stored_armed = 0
    stored_active = 0
    skipped = 0

    registry_items: list[tuple[str, str, dict[str, Any]]] = [
        *[(str(key), "ARMED", item) for key, item in ARMED.items()],
        *[(str(key), "ACTIVE", item) for key, item in ACTIVE.items()],
    ]

    for key, expected_status, item in registry_items:
        record = normalize_signal_record(item, fallback_key=key)
        if not record:
            skipped += 1
            continue

        status = str(record.get("status") or expected_status or "").upper()
        if status not in {"ARMED", "ACTIVE"}:
            skipped += 1
            continue

        record["status"] = status
        record["lifecycleStatus"] = status
        record["dashboardVisible"] = True
        record["waitingForConfirmation"] = status == "ARMED"

        # ARMED cards are useful for the dashboard, but must never be sent to Telegram.
        if status == "ARMED":
            record["qualityStatus"] = record.get("qualityStatus") or "WAITING_CONFIRMATION"
            record["premiumSignal"] = False
            record["telegramEligible"] = False

        # S8.22A: ACTIVE cards can exist in cockpit, but client delivery stays strictly gated.
        if status == "ACTIVE":
            client_block_reasons: list[str] = []

            raw_signal = record.get("rawSignal") if isinstance(record.get("rawSignal"), dict) else {}

            try:
                strategy_config = _s819_strategy_config_for_row(record)
            except Exception:
                strategy_config = {}

            registry_status = str(strategy_config.get("registryStatus") or "").upper().strip()
            product_mode = str(strategy_config.get("productMode") or "").upper().strip()
            client_visible_mode = str(strategy_config.get("clientVisibleMode") or "").upper().strip()

            record["clientDeliveryPolicy"] = {
                "version": "s8_22a_strict_client_delivery_gate_v1",
                "registryStatus": registry_status,
                "productMode": product_mode,
                "clientVisibleMode": client_visible_mode,
                "minRrToTp1": 2.0,
                "allowedGrades": sorted(TELEGRAM_ALLOWED_GRADES),
            }

            if registry_status in {"DEMOTE_TO_MONITOR_ONLY", "PAPER_ONLY_UNTIL_SAMPLE_GROWS"}:
                client_block_reasons.append(f"registry_status_blocks_client_delivery:{registry_status}")
            if product_mode in {"MONITOR_ONLY", "PAPER_TEST_ONLY"}:
                client_block_reasons.append(f"product_mode_blocks_client_delivery:{product_mode}")
            if client_visible_mode == "TEST_ONLY":
                client_block_reasons.append("client_visible_mode_TEST_ONLY")

            grade = str(record.get("signalGrade") or "").upper().strip()
            if TELEGRAM_ALLOWED_GRADES and grade not in TELEGRAM_ALLOWED_GRADES:
                client_block_reasons.append("grade_not_allowed_for_client_delivery")

            try:
                rr1_float = float(record.get("rrToTp1") if record.get("rrToTp1") is not None else 0)
            except Exception:
                rr1_float = 0.0
            if rr1_float < 2.0:
                client_block_reasons.append("rrToTp1_below_2R")

            entry_value = record.get("entry") if record.get("entry") is not None else raw_signal.get("entry")
            stop_value = record.get("stop") if record.get("stop") is not None else raw_signal.get("stop")
            targets_value = record.get("targets") if isinstance(record.get("targets"), list) else raw_signal.get("targets")
            targets_value = targets_value if isinstance(targets_value, list) else []
            tp1_value = targets_value[0].get("price") if targets_value and isinstance(targets_value[0], dict) else None
            invalidation_value = (
                record.get("invalidation")
                or raw_signal.get("invalidation")
                or raw_signal.get("invalidIf")
                or raw_signal.get("invalidationReason")
            )

            if entry_value is None or str(entry_value).strip() == "":
                client_block_reasons.append("missing_entry")
            if stop_value is None or str(stop_value).strip() == "":
                client_block_reasons.append("missing_stop")
            if tp1_value is None or str(tp1_value).strip() == "":
                client_block_reasons.append("missing_tp1")
            if invalidation_value is None or str(invalidation_value).strip() == "":
                client_block_reasons.append("missing_invalidation")

            # S8.23C: derive client eligibility from the final gate.
            # Do not depend on stale upstream premiumSignal/telegramEligible flags.
            base_client_candidate = (
                record.get("qualityStatus") == "PASSED"
                and not client_block_reasons
            )

            firewall_passed = False
            firewall_reasons: list[str] = []
            firewall_policy: dict[str, Any] = {}

            if base_client_candidate:
                firewall_probe = dict(record)
                firewall_probe["premiumSignal"] = True
                firewall_probe["telegramEligible"] = True

                try:
                    firewall_result = evaluate_telegram_quality_firewall(firewall_probe)
                except Exception as exc:
                    firewall_result = {
                        "passed": False,
                        "reasons": [f"firewall_exception:{type(exc).__name__}"],
                    }

                firewall_passed = firewall_result.get("passed") is True
                firewall_reasons = firewall_result.get("reasons") if isinstance(firewall_result.get("reasons"), list) else []
                firewall_policy = firewall_result.get("policy") if isinstance(firewall_result.get("policy"), dict) else {}

                for reason in firewall_reasons:
                    reason_value = str(reason or "").strip()
                    if reason_value and reason_value not in client_block_reasons:
                        client_block_reasons.append(reason_value)

            passed_client_delivery = bool(base_client_candidate and firewall_passed and not client_block_reasons)

            record["clientDeliveryAllowed"] = passed_client_delivery
            record["clientDeliveryBlockedReasons"] = client_block_reasons
            record["clientDeliveryFirewall"] = {
                "passed": firewall_passed,
                "reasons": firewall_reasons,
                "policy": firewall_policy,
                "derivedFromFinalGate": True,
                "version": "s8_23c_derive_client_eligibility_from_final_gate_v1",
            }

            if passed_client_delivery:
                record["telegramEligible"] = True
                record["premiumSignal"] = True
            else:
                record["telegramEligible"] = False
                record["premiumSignal"] = False

        storage_key = build_signal_storage_key(record, fallback_key=key)
        record["storageKey"] = storage_key

        # ACTIVE should win over ARMED if both ever share the same symbol/setup/session key.
        existing = SIGNALS.get(storage_key)
        if existing:
            existing_status = str(existing.get("status") or "").upper()
            if existing_status == "ACTIVE" and status == "ARMED":
                skipped += 1
                continue

        SIGNALS[storage_key] = record
        db.upsert_signal(storage_key, record)
        stored += 1

        if status == "ARMED":
            stored_armed += 1
        elif status == "ACTIVE":
            stored_active += 1

    return {
        "stored": stored,
        "storedArmed": stored_armed,
        "storedActive": stored_active,
        "replaced": 0,
        "skipped": skipped,
        "totalStored": len(SIGNALS),
        "telegramEligibleStored": sum(1 for item in SIGNALS.values() if item.get("telegramEligible") is True),
        "storageMode": "armed_plus_active_runtime",
    }

def sorted_signal_items(limit: int = 100, premium_only: bool = False, telegram_only: bool = False) -> list[dict[str, Any]]:
    items = list(SIGNALS.values())

    if premium_only:
        items = [item for item in items if item.get("premiumSignal") is True]

    if telegram_only:
        items = [item for item in items if item.get("telegramEligible") is True]

    items = sorted(
        items,
        key=lambda item: str(item.get("createdAt") or item.get("storedAt") or ""),
        reverse=True,
    )

    return items[: max(1, min(limit, 500))]



def build_runtime_cache_payload() -> dict[str, Any]:
    """Build runtime payload from the same tolerant sources as the Cockpit.

    S5.14E: older implementation referenced local variables that only exist
    inside the cockpit builder. That could make /engine/cache/publish fail and
    could also wipe counters when API memory was empty after a restart.
    """
    raw_watch_source = _s416_watchlist_items()
    raw_armed_source = _s416_armed_items()
    raw_active_source = _s416_active_items()
    raw_signal_source = _s416_signal_items()
    telegram_items = [item for item in raw_signal_source if isinstance(item, dict) and item.get("telegramEligible") is True]

    return {
        "runtimeStatus": {
            "startedAt": ENGINE_STARTED_AT.isoformat(),
            "watchCount": len(raw_watch_source),
            "armedCount": len(raw_armed_source),
            "activeCount": len(raw_active_source),
            "signalCount": len(raw_signal_source),
            "telegramEligibleSignalCount": len(telegram_items),
            "backtestOutcomeCount": len(BACKTEST_OUTCOMES),
            "updatedAt": datetime.now(timezone.utc).isoformat(),
            "source": "s5_14e_runtime_source_of_truth",
        },
        "watchlist": sorted(
            [item for item in raw_watch_source if isinstance(item, dict)],
            key=lambda item: int(item.get("inPlayScore") or 0),
            reverse=True,
        )[:100],
        "armed": sorted(
            [item for item in raw_armed_source if isinstance(item, dict)],
            key=lambda item: int(item.get("confidence") or item.get("signalScore") or 0),
            reverse=True,
        )[:100],
        "active": sorted(
            [item for item in raw_active_source if isinstance(item, dict)],
            key=lambda item: int(item.get("signalScore") or item.get("confidence") or 0),
            reverse=True,
        )[:100],
        "signals": sorted_signal_items(limit=100),
        "telegramSignals": sorted(
            telegram_items,
            key=lambda item: str(item.get("createdAt") or item.get("storedAt") or ""),
            reverse=True,
        )[:100],
    }


def publish_runtime_cache(reason: str = "manual", ttl_seconds: int = 900) -> dict[str, Any]:
    payload = build_runtime_cache_payload()
    base = {
        "reason": reason,
        "publishedAt": datetime.now(timezone.utc).isoformat(),
        "storageVersion": "s412_runtime_cache_v1",
    }
    items = {
        "engine:runtime_status": {**base, **payload["runtimeStatus"]},
        "engine:watchlist": {**base, "count": len(payload["watchlist"]), "items": payload["watchlist"]},
        "engine:armed": {**base, "count": len(payload["armed"]), "items": payload["armed"]},
        "engine:active": {**base, "count": len(payload["active"]), "items": payload["active"]},
        "engine:signals": {**base, "count": len(payload["signals"]), "items": payload["signals"]},
        "engine:telegram_signals": {**base, "count": len(payload["telegramSignals"]), "items": payload["telegramSignals"]},
    }
    result = runtime_cache.publish_many(items, ttl_seconds=ttl_seconds)
    return {
        **result,
        "reason": reason,
        "runtimeStatus": payload["runtimeStatus"],
        "storageVersion": "s412_runtime_cache_v1",
    }



