# === S8.29A Promotion evidence board endpoint ===
@app.get("/engine/promotion/evidence")
def engine_promotion_evidence_board(
    min_closed: int = 30,
    preferred_closed: int = 50,
    min_win_rate: float = 55.0,
    min_avg_r: float = 0.35,
    max_stop_rate: float = 45.0,
    include_grades: bool = False,
):
    min_closed = max(1, int(min_closed or 30))
    preferred_closed = max(1, int(preferred_closed or 50))
    min_win_rate = float(min_win_rate or 55.0)
    min_avg_r = float(min_avg_r or 0.35)
    max_stop_rate = float(max_stop_rate or 45.0)

    items = load_persistent_outcome_items()
    stats_rows = build_setup_statistics(items)

    stats_by_slug: dict[str, dict[str, Any]] = {}
    if isinstance(stats_rows, list):
        for row in stats_rows:
            if isinstance(row, dict):
                slug = str(row.get("setupSlug") or "").strip()
                if slug:
                    stats_by_slug[slug] = row

    registry = globals().get("S819_STRATEGY_REGISTRY")
    registry_slugs = set(registry.keys()) if isinstance(registry, dict) else set()
    all_slugs = sorted(set(stats_by_slug.keys()) | registry_slugs)

    rows: list[dict[str, Any]] = []

    for slug in all_slugs:
        row = stats_by_slug.get(slug) or {}
        registry_row = _s828b_registry_row(slug)

        decision = _s828b_quality_decision(
            row=row,
            registry=registry_row,
            min_closed=min_closed,
            preferred_closed=preferred_closed,
            min_win_rate=min_win_rate,
            min_avg_r=min_avg_r,
            max_stop_rate=max_stop_rate,
        )

        closed = _s828b_int(row.get("closed"), 0)

        if decision.get("promotionDecision") == "PROMOTION_REVIEW_READY_NOT_AUTO":
            board_bucket = "PROMOTION_REVIEW_READY"
        elif decision.get("sampleOk") is False:
            board_bucket = "COLLECT_SAMPLE"
        elif decision.get("performanceOk") is False:
            board_bucket = "WEAK_EVIDENCE"
        elif decision.get("registryAllowsReview") is False or decision.get("productAllowsReview") is False:
            board_bucket = "REGISTRY_BLOCKED"
        else:
            board_bucket = "ADMIN_REVIEW"

        compact = {
            "setupSlug": slug,
            "setupName": row.get("setupName") or registry_row.get("setupName") or slug.replace("_", " ").title(),
            "registryStatus": registry_row.get("registryStatus"),
            "productMode": registry_row.get("productMode"),
            "clientVisibleMode": registry_row.get("clientVisibleMode"),

            "count": row.get("count"),
            "rawCount": row.get("rawCount"),
            "evaluableCount": row.get("evaluableCount"),
            "closed": closed,
            "worked": row.get("worked"),
            "failed": row.get("failed"),
            "open": row.get("open"),
            "expiredSession": row.get("expiredSession"),

            "winRateClosed": row.get("winRateClosed"),
            "avgResultRClosed": row.get("avgResultRClosed"),
            "stopRateClosed": row.get("stopRateClosed"),
            "telegramEligibleRate": row.get("telegramEligibleRate"),
            "premiumSignalRate": row.get("premiumSignalRate"),

            "sampleGapToMinClosed": max(0, min_closed - closed),
            "sampleGapToPreferredClosed": max(0, preferred_closed - closed),

            "sampleOk": decision.get("sampleOk"),
            "performanceOk": decision.get("performanceOk"),
            "registryAllowsReview": decision.get("registryAllowsReview"),
            "productAllowsReview": decision.get("productAllowsReview"),

            "promotionDecision": decision.get("promotionDecision"),
            "nextAction": decision.get("nextAction"),
            "boardBucket": board_bucket,
            "reasons": decision.get("reasons") or [],

            "autoPromotionAllowed": False,
            "clientDeliveryChangeAllowed": False,
            "safeToApplyAutomatically": False,
        }

        if include_grades and row:
            compact["gradeEvidence"] = _s828b_compact_grade_rows(row)

        rows.append(compact)

    rows = sorted(
        rows,
        key=lambda r: (
            0 if r.get("promotionDecision") == "PROMOTION_REVIEW_READY_NOT_AUTO" else 1,
            -int(r.get("closed") or 0),
            -float(r.get("avgResultRClosed") or -999),
            str(r.get("setupSlug") or ""),
        ),
    )

    bucket_counts: dict[str, int] = {}
    decision_counts: dict[str, int] = {}

    for row in rows:
        bucket = str(row.get("boardBucket") or "UNKNOWN")
        decision_name = str(row.get("promotionDecision") or "UNKNOWN")
        bucket_counts[bucket] = bucket_counts.get(bucket, 0) + 1
        decision_counts[decision_name] = decision_counts.get(decision_name, 0) + 1

    promotion_ready = [
        row for row in rows
        if row.get("promotionDecision") == "PROMOTION_REVIEW_READY_NOT_AUTO"
    ]

    board_state = (
        "PROMOTION_REVIEW_READY_NOT_AUTO"
        if promotion_ready
        else "NO_SETUP_READY_FOR_CLIENT_DELIVERY"
    )

    return {
        "ok": True,
        "storageVersion": "s8_29a_promotion_evidence_board_v1",
        "evaluatedAt": datetime.now(timezone.utc).isoformat(),
        "boardState": board_state,
        "topAction": "ADMIN_REVIEW_REQUIRED_NO_AUTO_DELIVERY" if promotion_ready else "KEEP_COLLECTING_OUTCOMES_AND_TIGHTEN_EXECUTION",
        "thresholds": {
            "minClosed": min_closed,
            "preferredClosed": preferred_closed,
            "minWinRateClosed": min_win_rate,
            "minAvgResultRClosed": min_avg_r,
            "maxStopRateClosed": max_stop_rate,
        },
        "summary": {
            "setupCount": len(rows),
            "promotionReadyCount": len(promotion_ready),
            "bucketCounts": dict(sorted(bucket_counts.items())),
            "decisionCounts": dict(sorted(decision_counts.items())),
        },
        "promotionReady": promotion_ready[:20],
        "items": rows,
        "policy": {
            "mode": "READ_ONLY_PROMOTION_EVIDENCE_BOARD",
            "doesNotChangeRegistry": True,
            "doesNotEnableClientDelivery": True,
            "doesNotSendTelegram": True,
            "autoPromotionAllowed": False,
            "principle": "Promotion board is evidence-only. Client delivery remains blocked until sample and performance thresholds pass.",
        },
    }

# === /S8.29A Promotion evidence board endpoint ===




# === S8.30C Stale stock OPEN outcome repair ===
S830C_STALE_STOCK_OPEN_REPAIR_VERSION = "s8_30c_stale_stock_open_repair_v1"


def _s830c_parse_stock_signal_id(signal_id: str) -> dict[str, Any]:
    raw = str(signal_id or "").strip()
    parts = raw.split(":", 3)

    if len(parts) != 4 or parts[0] != "stock":
        return {}

    symbol = parts[1].upper().strip()
    setup_slug = parts[2].strip()
    iso_time = parts[3].strip()

    if not symbol or not setup_slug or len(iso_time) < 10:
        return {}

    return {
        "symbol": symbol,
        "setupSlug": setup_slug,
        "triggerTime": iso_time,
        "createdAt": iso_time,
        "sessionDate": iso_time[:10],
    }


def _s830c_is_open_outcome(item: dict[str, Any]) -> bool:
    status = str(item.get("status") or "").upper().strip()
    result = str(item.get("result") or "").upper().strip()

    if status == "OPEN" or result == "OPEN":
        return True

    if not result and status not in {"WORKED", "FAILED", "EXPIRED_SESSION", "NO_EVAL_LATE_SESSION"}:
        return True

    return False


def _s830c_age_days(session_date: str) -> int | None:
    try:
        day = datetime.fromisoformat(str(session_date)[:10]).date()
        return (datetime.now(timezone.utc).date() - day).days
    except Exception:
        return None


def _s830c_finalize_stale_stock_open(item: dict[str, Any]) -> dict[str, Any]:
    repaired = dict(item)
    signal_id = str(repaired.get("signalId") or "").strip()
    parsed = _s830c_parse_stock_signal_id(signal_id)

    for key, value in parsed.items():
        if not repaired.get(key):
            repaired[key] = value

    now_iso = datetime.now(timezone.utc).isoformat()

    repaired["status"] = "EXPIRED_SESSION"
    repaired["result"] = "SESSION_CLOSE"
    repaired["firstEvent"] = repaired.get("firstEvent") or "SESSION_CLOSE"
    repaired["firstEventAt"] = repaired.get("firstEventAt") or None
    repaired["resultR"] = repaired.get("resultR") if repaired.get("resultR") is not None else 0
    repaired["evaluatedAt"] = now_iso
    repaired["repairAppliedAt"] = now_iso
    repaired["repairVersion"] = S830C_STALE_STOCK_OPEN_REPAIR_VERSION
    repaired["repairReason"] = "stale_stock_open_missing_metadata_session_close_finalized"
    repaired["storageVersion"] = S830C_STALE_STOCK_OPEN_REPAIR_VERSION

    return repaired


@app.post("/engine/outcomes/repair-stale-stock-open")
def engine_outcomes_repair_stale_stock_open(
    dry_run: bool = True,
    min_age_days: int = 1,
    limit: int = 5000,
):
    items = load_persistent_outcome_items(limit=max(1, min(int(limit or 5000), 20000)))

    scanned = 0
    candidates = 0
    finalized = 0
    applied = 0
    skipped = 0
    by_setup: dict[str, int] = {}
    samples: list[dict[str, Any]] = []

    for item in items:
        if not isinstance(item, dict):
            skipped += 1
            continue

        scanned += 1
        signal_id = str(item.get("signalId") or "").strip()

        if not signal_id.startswith("stock:"):
            continue

        if not _s830c_is_open_outcome(item):
            continue

        parsed = _s830c_parse_stock_signal_id(signal_id)
        if not parsed:
            skipped += 1
            continue

        session_date = str(item.get("sessionDate") or parsed.get("sessionDate") or "")[:10]
        age_days = _s830c_age_days(session_date)

        if age_days is None or age_days < int(min_age_days or 1):
            continue

        candidates += 1
        setup_slug = str(item.get("setupSlug") or parsed.get("setupSlug") or "unknown")
        by_setup[setup_slug] = by_setup.get(setup_slug, 0) + 1

        repaired = _s830c_finalize_stale_stock_open(item)
        finalized += 1

        if len(samples) < 20:
            samples.append({
                "signalId": signal_id,
                "symbol": repaired.get("symbol"),
                "setupSlug": repaired.get("setupSlug"),
                "fromStatus": item.get("status"),
                "fromResult": item.get("result"),
                "toStatus": repaired.get("status"),
                "toResult": repaired.get("result"),
                "sessionDate": repaired.get("sessionDate"),
                "ageDays": age_days,
                "dryRun": dry_run,
            })

        if not dry_run:
            BACKTEST_OUTCOMES[str(signal_id)] = repaired
            db.upsert_outcome(repaired)
            applied += 1

    return {
        "ok": True,
        "storageVersion": S830C_STALE_STOCK_OPEN_REPAIR_VERSION,
        "dryRun": dry_run,
        "evaluatedAt": datetime.now(timezone.utc).isoformat(),
        "scanned": scanned,
        "candidates": candidates,
        "finalized": finalized,
        "applied": applied,
        "skipped": skipped,
        "minAgeDays": min_age_days,
        "bySetup": dict(sorted(by_setup.items(), key=lambda kv: kv[1], reverse=True)),
        "samples": samples,
        "policy": {
            "mode": "metadata_repair_and_session_close_finalizer",
            "onlySignalIdPrefix": "stock:",
            "onlyOpenOutcomes": True,
            "doesNotEnableClientDelivery": True,
            "doesNotChangeRegistry": True,
            "dryRunDefault": True,
        },
    }

# === /S8.30C Stale stock OPEN outcome repair ===




# === S8.31A AI Research Feature Matrix ===
S831A_FEATURE_MATRIX_VERSION = "s8_31a_ai_research_feature_matrix_v1"


def _s831a_first(*values: Any) -> Any:
    for value in values:
        if value is None:
            continue
        if isinstance(value, str) and not value.strip():
            continue
        return value
    return None


def _s831a_num(value: Any, fallback: float | None = None) -> float | None:
    if value is None or isinstance(value, bool):
        return fallback
    try:
        if isinstance(value, str):
            cleaned = value.strip().replace("%", "").replace(",", "")
            if not cleaned:
                return fallback
            return float(cleaned)
        return float(value)
    except Exception:
        return fallback


def _s831a_text(value: Any, fallback: str | None = None) -> str | None:
    if value is None:
        return fallback
    text = str(value).strip()
    return text if text else fallback


def _s831a_nested(obj: dict[str, Any], *paths: str) -> Any:
    for path in paths:
        cur: Any = obj
        ok = True
        for part in path.split("."):
            if isinstance(cur, dict) and part in cur:
                cur = cur.get(part)
            else:
                ok = False
                break
        if ok and cur is not None and not (isinstance(cur, str) and not cur.strip()):
            return cur
    return None


def _s831a_parse_dt(value: Any):
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        if raw.endswith("Z"):
            raw = raw[:-1] + "+00:00"
        return datetime.fromisoformat(raw)
    except Exception:
        return None


def _s831a_target_price(item: dict[str, Any], payload: dict[str, Any], index: int) -> float | None:
    direct_keys = [
        f"tp{index + 1}",
        f"target{index + 1}",
        f"target{index + 1}Price",
    ]
    for key in direct_keys:
        value = _s831a_first(item.get(key), payload.get(key))
        parsed = _s831a_num(value)
        if parsed is not None:
            return parsed

    targets = _s831a_first(item.get("targets"), payload.get("targets"))
    if isinstance(targets, list) and len(targets) > index:
        target = targets[index]
        if isinstance(target, dict):
            return _s831a_num(_s831a_first(target.get("price"), target.get("target"), target.get("value")))
        return _s831a_num(target)

    return None


def _s831a_risk(entry: float | None, stop: float | None, direction: str | None) -> float | None:
    if entry is None or stop is None:
        return None
    risk = abs(float(entry) - float(stop))
    if risk <= 0:
        return None
    return risk


def _s831a_pct_distance(a: float | None, b: float | None) -> float | None:
    if a is None or b is None or b == 0:
        return None
    return round(((float(a) - float(b)) / float(b)) * 100.0, 4)


def _s831a_outcome_class(item: dict[str, Any]) -> str:
    status = str(item.get("status") or "").upper().strip()
    result = str(item.get("result") or "").upper().strip()

    if status == "WORKED" or result in {"TP1", "TP2", "WORKED"}:
        return "WIN"
    if status == "FAILED" or result in {"FAILED_STOP", "STOP", "STOP_HIT"}:
        return "LOSS"
    if status == "EXPIRED_SESSION" or result == "SESSION_CLOSE":
        return "EXPIRED"
    if status == "NO_EVAL_LATE_SESSION":
        return "NO_EVAL_LATE_SESSION"
    if status == "OPEN":
        return "OPEN"
    return status or result or "UNKNOWN"


def _s831a_feature_row(item: dict[str, Any]) -> dict[str, Any]:
    payload = item.get("rawSignal") if isinstance(item.get("rawSignal"), dict) else {}
    feature_snapshot = item.get("featureSnapshot") if isinstance(item.get("featureSnapshot"), dict) else {}
    if feature_snapshot:
        payload = {**payload, **{key: value for key, value in feature_snapshot.items() if value is not None}}

    signal_id = _s831a_text(_s831a_first(item.get("signalId"), payload.get("signalId")))
    symbol = _s831a_text(_s831a_first(item.get("symbol"), payload.get("symbol")), "UNKNOWN")
    if symbol:
        symbol = symbol.upper()

    setup_slug = _s831a_text(_s831a_first(item.get("setupSlug"), payload.get("setupSlug")), "unknown")
    setup_name = _s831a_text(_s831a_first(item.get("setupName"), payload.get("setupName")), setup_slug)
    direction = _s831a_text(_s831a_first(item.get("direction"), payload.get("direction")))
    if direction:
        direction = direction.lower()

    trigger_time = _s831a_text(_s831a_first(
        item.get("triggerTime"),
        payload.get("triggerTime"),
        item.get("createdAt"),
        payload.get("createdAt"),
        item.get("storedAt"),
        payload.get("storedAt"),
    ))

    session_date = _s831a_text(_s831a_first(
        item.get("sessionDate"),
        payload.get("sessionDate"),
        trigger_time[:10] if trigger_time and len(trigger_time) >= 10 else None,
        item.get("storedAt")[:10] if item.get("storedAt") and len(str(item.get("storedAt"))) >= 10 else None,
    ))

    dt = _s831a_parse_dt(trigger_time)

    entry = _s831a_num(_s831a_first(
        item.get("entry"),
        item.get("entryPrice"),
        payload.get("entry"),
        payload.get("entryPrice"),
        _s831a_nested(payload, "entryZone.min"),
    ))
    stop = _s831a_num(_s831a_first(
        item.get("stop"),
        item.get("stopLoss"),
        payload.get("stop"),
        payload.get("stopLoss"),
    ))
    tp1 = _s831a_target_price(item, payload, 0)
    tp2 = _s831a_target_price(item, payload, 1)
    risk = _s831a_num(_s831a_first(item.get("risk"), payload.get("risk")), _s831a_risk(entry, stop, direction))
    risk_pct = (
        round((abs(float(risk)) / abs(float(entry))) * 100.0, 4)
        if risk is not None and entry not in (None, 0)
        else None
    )

    current_price = _s831a_num(_s831a_first(
        item.get("currentPrice"),
        item.get("price"),
        payload.get("currentPrice"),
        payload.get("price"),
    ))

    vwap = _s831a_num(_s831a_first(
        item.get("vwap"),
        payload.get("vwap"),
        _s831a_nested(item, "source.candleContext.vwap", "candleContext.vwap"),
        _s831a_nested(payload, "source.candleContext.vwap", "candleContext.vwap"),
    ))
    ema20 = _s831a_num(_s831a_first(
        item.get("ema20_5m"),
        payload.get("ema20_5m"),
        _s831a_nested(item, "source.candleContext.ema20_5m", "candleContext.ema20_5m"),
        _s831a_nested(payload, "source.candleContext.ema20_5m", "candleContext.ema20_5m"),
    ))
    atr14 = _s831a_num(_s831a_first(
        item.get("atr14_5m"),
        payload.get("atr14_5m"),
        _s831a_nested(item, "source.candleContext.atr14_5m", "candleContext.atr14_5m"),
        _s831a_nested(payload, "source.candleContext.atr14_5m", "candleContext.atr14_5m"),
    ))
    rsi14 = _s831a_num(_s831a_first(
        item.get("rsi14_5m"),
        payload.get("rsi14_5m"),
        _s831a_nested(item, "source.candleContext.rsi14_5m", "candleContext.rsi14_5m"),
        _s831a_nested(payload, "source.candleContext.rsi14_5m", "candleContext.rsi14_5m"),
    ))
    volume_accel = _s831a_num(_s831a_first(
        item.get("volumeAcceleration"),
        payload.get("volumeAcceleration"),
        _s831a_nested(item, "source.candleContext.volumeAcceleration", "candleContext.volumeAcceleration"),
        _s831a_nested(payload, "source.candleContext.volumeAcceleration", "candleContext.volumeAcceleration"),
    ))
    distance_from_vwap_pct = _s831a_num(_s831a_first(
        item.get("distanceFromVwapPct"),
        payload.get("distanceFromVwapPct"),
        _s831a_nested(item, "source.candleContext.distanceFromVwapPct", "candleContext.distanceFromVwapPct"),
        _s831a_nested(payload, "source.candleContext.distanceFromVwapPct", "candleContext.distanceFromVwapPct"),
        _s831a_pct_distance(entry, vwap),
    ))

    gap_pct = _s831a_num(_s831a_first(
        item.get("gapPct"),
        item.get("gapPercent"),
        payload.get("gapPct"),
        payload.get("gapPercent"),
        payload.get("gap"),
    ))
    change_pct = _s831a_num(_s831a_first(
        item.get("changePercent"),
        item.get("changePct"),
        payload.get("changePercent"),
        payload.get("changePct"),
        payload.get("changesPercentage"),
    ))
    rvol = _s831a_num(_s831a_first(
        item.get("rvol"),
        item.get("relativeVolume"),
        payload.get("rvol"),
        payload.get("relativeVolume"),
    ))
    volume = _s831a_num(_s831a_first(item.get("volume"), payload.get("volume")))
    premarket_volume = _s831a_num(_s831a_first(
        item.get("premarketVolume"),
        item.get("preMarketVolume"),
        payload.get("premarketVolume"),
        payload.get("preMarketVolume"),
    ))
    spread_pct = _s831a_num(_s831a_first(
        item.get("spreadPct"),
        item.get("spreadPercent"),
        payload.get("spreadPct"),
        payload.get("spreadPercent"),
    ))
    market_cap = _s831a_num(_s831a_first(item.get("marketCap"), payload.get("marketCap")))
    float_shares = _s831a_num(_s831a_first(
        item.get("float"),
        item.get("floatShares"),
        payload.get("float"),
        payload.get("floatShares"),
    ))
    short_float = _s831a_num(_s831a_first(
        item.get("shortFloat"),
        item.get("shortFloatPct"),
        payload.get("shortFloat"),
        payload.get("shortFloatPct"),
    ))

    result_r = _s831a_num(item.get("resultR"))
    mfe_r = _s831a_num(_s831a_first(item.get("mfeR"), item.get("maxFavorableExcursionR")))
    mae_r = _s831a_num(_s831a_first(item.get("maeR"), item.get("maxAdverseExcursionR")))

    outcome_class = _s831a_outcome_class(item)
    is_win = outcome_class == "WIN"
    is_loss = outcome_class == "LOSS"
    is_expired = outcome_class == "EXPIRED"

    critical = {
        "entry": entry,
        "stop": stop,
        "tp1": tp1,
        "risk": risk,
        "vwap": vwap,
        "ema20_5m": ema20,
        "atr14_5m": atr14,
        "rsi14_5m": rsi14,
        "volumeAcceleration": volume_accel,
        "distanceFromVwapPct": distance_from_vwap_pct,
        "gapPct": gap_pct,
        "changePct": change_pct,
        "rvol": rvol,
        "spreadPct": spread_pct,
    }
    missing_critical = [key for key, value in critical.items() if value is None]

    row = {
        "signalId": signal_id,
        "symbol": symbol,
        "setupSlug": setup_slug,
        "setupName": setup_name,
        "direction": direction,
        "sessionDate": session_date,
        "triggerTime": trigger_time,
        "hourUtc": dt.hour if dt else None,
        "minuteUtc": dt.minute if dt else None,

        "status": item.get("status"),
        "result": item.get("result"),
        "outcomeClass": outcome_class,
        "isWin": is_win,
        "isLoss": is_loss,
        "isExpired": is_expired,
        "resultR": result_r,
        "mfeR": mfe_r,
        "maeR": mae_r,

        "entry": entry,
        "stop": stop,
        "tp1": tp1,
        "tp2": tp2,
        "risk": risk,
        "riskPct": risk_pct,
        "currentPrice": current_price,

        "score": _s831a_num(_s831a_first(item.get("score"), payload.get("score"), payload.get("signalScore"))),
        "confidence": _s831a_num(_s831a_first(item.get("confidence"), payload.get("confidence"))),
        "signalGrade": _s831a_text(_s831a_first(item.get("signalGrade"), payload.get("signalGrade"), payload.get("grade"))),
        "qualityStatus": _s831a_text(_s831a_first(item.get("qualityStatus"), payload.get("qualityStatus"))),
        "premiumSignal": bool(_s831a_first(item.get("premiumSignal"), payload.get("premiumSignal"), False)),
        "telegramEligible": bool(_s831a_first(item.get("telegramEligible"), payload.get("telegramEligible"), False)),

        "vwap": vwap,
        "ema20_5m": ema20,
        "atr14_5m": atr14,
        "rsi14_5m": rsi14,
        "volumeAcceleration": volume_accel,
        "distanceFromVwapPct": distance_from_vwap_pct,

        "gapPct": gap_pct,
        "changePct": change_pct,
        "rvol": rvol,
        "volume": volume,
        "premarketVolume": premarket_volume,
        "spreadPct": spread_pct,
        "marketCap": market_cap,
        "floatShares": float_shares,
        "shortFloatPct": short_float,

        "psychology": {
            "isExtendedFromVwap": abs(distance_from_vwap_pct) >= 2.0 if distance_from_vwap_pct is not None else None,
            "isNearVwap": abs(distance_from_vwap_pct) <= 1.2 if distance_from_vwap_pct is not None else None,
            "hasVolumeAcceleration": volume_accel >= 1.2 if volume_accel is not None else None,
            "hasHighRvol": rvol >= 2.0 if rvol is not None else None,
            "isTightRisk": risk_pct <= 1.0 if risk_pct is not None else None,
            "isWideRisk": risk_pct >= 3.0 if risk_pct is not None else None,
            "isLateUtc": dt.hour >= 19 if dt else None,
        },

        "featureQuality": {
            "criticalFeatureCount": len(critical),
            "missingCriticalCount": len(missing_critical),
            "missingCriticalFields": missing_critical,
            "hasEnoughForFailureAnalysis": len(missing_critical) <= 6,
        },

        "source": _s831a_text(_s831a_first(item.get("source"), payload.get("source"))),
        "storageVersion": S831A_FEATURE_MATRIX_VERSION,
    }

    return row


def _s831a_feature_matrix_summary(rows: list[dict[str, Any]]) -> dict[str, Any]:
    by_setup: dict[str, dict[str, Any]] = {}

    for row in rows:
        setup_slug = str(row.get("setupSlug") or "unknown")
        stat = by_setup.setdefault(setup_slug, {
            "setupSlug": setup_slug,
            "count": 0,
            "closed": 0,
            "wins": 0,
            "losses": 0,
            "expired": 0,
            "avgResultRClosed": None,
            "winRateClosed": None,
            "avgMissingCritical": None,
            "readyForFailureAnalysis": 0,
            "_resultR": [],
            "_missing": [],
        })

        stat["count"] += 1

        if row.get("isWin") or row.get("isLoss"):
            stat["closed"] += 1
            if row.get("isWin"):
                stat["wins"] += 1
            if row.get("isLoss"):
                stat["losses"] += 1
            if row.get("resultR") is not None:
                stat["_resultR"].append(float(row.get("resultR")))

        if row.get("isExpired"):
            stat["expired"] += 1

        fq = row.get("featureQuality") if isinstance(row.get("featureQuality"), dict) else {}
        stat["_missing"].append(int(fq.get("missingCriticalCount") or 0))
        if fq.get("hasEnoughForFailureAnalysis") is True:
            stat["readyForFailureAnalysis"] += 1

    result: list[dict[str, Any]] = []
    for stat in by_setup.values():
        closed = int(stat.get("closed") or 0)
        wins = int(stat.get("wins") or 0)
        result_r = stat.pop("_resultR", [])
        missing = stat.pop("_missing", [])

        stat["winRateClosed"] = round((wins / closed) * 100, 2) if closed else None
        stat["avgResultRClosed"] = round(sum(result_r) / len(result_r), 4) if result_r else None
        stat["avgMissingCritical"] = round(sum(missing) / len(missing), 2) if missing else None
        stat["failureAnalysisCoveragePct"] = round((float(stat.get("readyForFailureAnalysis") or 0) / float(stat.get("count") or 1)) * 100, 2)
        result.append(stat)

    return {
        "setupCount": len(result),
        "bySetup": sorted(result, key=lambda row: (int(row.get("closed") or 0), int(row.get("count") or 0)), reverse=True),
    }


@app.get("/engine/research/feature-matrix")
def engine_research_feature_matrix(
    limit: int = 5000,
    include_rows: bool = False,
    max_rows: int = 200,
    publish: bool = True,
):
    safe_limit = max(1, min(int(limit or 5000), 50000))
    rows_limit = max(1, min(int(max_rows or 200), 2000))

    items = load_persistent_outcome_items(limit=safe_limit)
    rows = [_s831a_feature_row(item) for item in items if isinstance(item, dict)]
    summary = _s831a_feature_matrix_summary(rows)

    publish_info: dict[str, Any] = {
        "requested": bool(publish),
        "ok": False,
        "path": None,
        "latestPath": None,
        "error": None,
    }

    payload = {
        "ok": True,
        "storageVersion": S831A_FEATURE_MATRIX_VERSION,
        "evaluatedAt": datetime.now(timezone.utc).isoformat(),
        "limit": safe_limit,
        "rowsBuilt": len(rows),
        "rowsReturned": len(rows[:rows_limit]) if include_rows else 0,
        "setupCount": summary.get("setupCount"),
        "summary": {
            "setupCount": summary.get("setupCount"),
            "rowsBuilt": len(rows),
            "criticalFeatureCount": 14,
            "purpose": "AI Research Lab feature matrix for failure analysis, setup calibration, strategy validation and future virtual trader readiness.",
        },
        "bySetup": summary.get("bySetup"),
        "policy": {
            "mode": "READ_ONLY_FEATURE_MATRIX",
            "doesNotChangeRegistry": True,
            "doesNotEnableClientDelivery": True,
            "doesNotSendTelegram": True,
            "doesNotExecuteTrades": True,
        },
    }

    if include_rows:
        payload["rows"] = rows[:rows_limit]

    if publish:
        try:
            import json
            from pathlib import Path

            out_dir = Path("reports") / "ai_research" / "feature_matrix"
            out_dir.mkdir(parents=True, exist_ok=True)
            stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
            report_path = out_dir / f"{stamp}.json"
            latest_path = out_dir / "latest.json"

            report_payload = dict(payload)
            report_payload["rows"] = rows

            report_path.write_text(json.dumps(report_payload, ensure_ascii=False, indent=2, default=str), encoding="utf-8")
            latest_path.write_text(json.dumps(report_payload, ensure_ascii=False, indent=2, default=str), encoding="utf-8")

            publish_info.update({
                "ok": True,
                "path": str(report_path),
                "latestPath": str(latest_path),
            })
        except Exception as exc:
            publish_info["error"] = str(exc)

    payload["publish"] = publish_info
    return payload

