# === S8.32C Batch Replay + Feature Rebuild Dry Run ===
S832C_BATCH_REBUILD_DRY_RUN_VERSION = "s8_32c_batch_replay_feature_rebuild_dry_run_v1"


def _s832c_load_signal_rows(session_date=None, setup_slug=None, symbol=None, limit=25):
    import sqlite3

    safe_limit = max(1, min(int(limit or 25), 100))
    where = []
    params = []

    if session_date:
        where.append("session_date = ?")
        params.append(str(session_date))

    if setup_slug:
        where.append("setup_slug = ?")
        params.append(str(setup_slug))

    if symbol:
        where.append("symbol = ?")
        params.append(str(symbol).upper())

    sql = "select * from signal_records"
    if where:
        sql += " where " + " and ".join(where)
    sql += " order by stored_at desc limit ?"
    params.append(safe_limit)

    con = sqlite3.connect(_s832a2_db_path())
    con.row_factory = sqlite3.Row
    rows = [dict(r) for r in con.execute(sql, params).fetchall()]
    try:
        con.close()
    except Exception:
        pass
    return rows


@app.get("/engine/research/signal-batch-rebuild-dry-run")
async def engine_research_signal_batch_rebuild_dry_run(
    session_date: str | None = None,
    setup_slug: str | None = None,
    symbol: str | None = None,
    limit: int = 25,
):
    import json
    from datetime import datetime, time
    from zoneinfo import ZoneInfo

    rows = _s832c_load_signal_rows(
        session_date=session_date,
        setup_slug=setup_slug,
        symbol=symbol,
        limit=limit,
    )

    client = FmpClient()
    if not client.is_configured():
        return {
            "ok": False,
            "storageVersion": S832C_BATCH_REBUILD_DRY_RUN_VERSION,
            "error": "FMP_API_KEY is missing",
        }

    cache = {}
    results = []
    summary = {
        "signalsLoaded": len(rows),
        "processed": 0,
        "replayOk": 0,
        "featureReady": 0,
        "featurePartial": 0,
        "featureMissing": 0,
        "errors": 0,
        "bySetup": {},
    }

    for row in rows:
        signal_id = row.get("signal_id")
        try:
            payload = json.loads(row.get("payload_json") or "{}")
        except Exception:
            payload = {}

        try:
            sym = row.get("symbol") or payload.get("symbol")
            setup = row.get("setup_slug") or payload.get("setupSlug") or payload.get("setup_slug")
            sess = row.get("session_date") or payload.get("sessionDate") or payload.get("session_date")
            trigger_raw = row.get("trigger_time") or payload.get("triggerTime") or payload.get("trigger_time")
            trigger_ny = _s832a2_parse_dt(trigger_raw)

            if not sym or not sess or not trigger_ny:
                raise ValueError("missing_symbol_session_or_trigger")

            cache_key = f"{sym}|1min"
            if cache_key not in cache:
                cache[cache_key] = await client.get_intraday_candles(sym, interval="1min")
            candle_rows = cache.get(cache_key) or []

            pit = _s62_filter_candles_point_in_time(
                candle_rows,
                session_date=sess,
                cutoff_ny=trigger_ny,
            )
            before = pit.get("items") if isinstance(pit, dict) and isinstance(pit.get("items"), list) else []

            session_snapshot = build_session_snapshot(before)

            item = {
                "symbol": sym,
                "setupSlug": setup,
                "entry": payload.get("entry") or row.get("entry"),
                "stop": payload.get("stop") or row.get("stop"),
                "source": {
                    "candleContext": session_snapshot,
                    "marketContext": payload.get("marketContext") or {},
                },
            }

            feature_snapshot = _s831a2_feature_snapshot(payload, item)
            missing_count = _s831a4_snapshot_missing_count(feature_snapshot)

            if missing_count <= 2:
                readiness = "READY"
                summary["featureReady"] += 1
            elif missing_count <= 6:
                readiness = "PARTIAL_READY_FOR_FAILURE_ANALYSIS"
                summary["featurePartial"] += 1
            else:
                readiness = "MISSING_CRITICAL_DATA"
                summary["featureMissing"] += 1

            close_ny = datetime.combine(trigger_ny.date(), time(16, 0), tzinfo=ZoneInfo("America/New_York"))
            timestamp_mode = pit.get("timestampMode") if isinstance(pit, dict) else None

            future = _s64_future_candles(
                candle_rows,
                session_date=sess,
                cutoff_ny=trigger_ny,
                close_ny=close_ny,
                timestamp_mode=timestamp_mode,
            )

            direction = str(payload.get("direction") or row.get("direction") or "").strip().lower()
            entry = _s832a2_num(payload.get("entry") or row.get("entry"))
            stop = _s832a2_num(payload.get("stop") or row.get("stop"))
            tp1 = _s832a2_num(payload.get("tp1")) or _s832a2_pick_target(payload, 0)
            tp2 = _s832a2_num(payload.get("tp2")) or _s832a2_pick_target(payload, 1)
            risk = abs(float(entry) - float(stop)) if entry is not None and stop is not None else None

            candidate = {
                "symbol": sym,
                "setupSlug": setup,
                "setupName": payload.get("setupName") or payload.get("setup_name"),
                "direction": direction,
                "sessionDate": sess,
                "entry": entry,
                "stop": stop,
                "tp1": tp1,
                "tp2": tp2,
                "risk": risk,
                "qualityScore": payload.get("qualityScore"),
                "score": payload.get("score") or row.get("signal_score"),
                "grade": payload.get("grade") or row.get("signal_grade"),
                "qualityGate": payload.get("qualityGate") or row.get("quality_status"),
            }

            outcome = _s64_evaluate_candidate_outcome(candidate, future, session_close_ny=close_ny)

            if isinstance(outcome, dict) and outcome.get("ok"):
                summary["replayOk"] += 1

            summary["processed"] += 1
            setup_key = setup or "unknown"
            summary["bySetup"].setdefault(setup_key, {"count": 0, "ready": 0, "worked": 0, "failed": 0, "sessionClose": 0})
            summary["bySetup"][setup_key]["count"] += 1
            if readiness == "READY":
                summary["bySetup"][setup_key]["ready"] += 1

            result = outcome.get("result") if isinstance(outcome, dict) else None
            if result and str(result).startswith("WORKED"):
                summary["bySetup"][setup_key]["worked"] += 1
            elif result == "FAILED_STOP":
                summary["bySetup"][setup_key]["failed"] += 1
            elif result == "SESSION_CLOSE":
                summary["bySetup"][setup_key]["sessionClose"] += 1

            results.append({
                "signalId": signal_id,
                "symbol": sym,
                "setupSlug": setup,
                "sessionDate": sess,
                "triggerTime": trigger_raw,
                "candles": {
                    "rawRows": len(candle_rows),
                    "beforeTriggerRows": len(before),
                    "futureRowsAfterTrigger": len(future),
                    "timestampMode": timestamp_mode,
                },
                "featureReadiness": {
                    "status": readiness,
                    "missingCriticalCount": missing_count,
                    "missingCriticalFields": feature_snapshot.get("missingCriticalFields"),
                    "hasEnoughForFailureAnalysis": feature_snapshot.get("hasEnoughForFailureAnalysis"),
                },
                "outcome": outcome,
            })

        except Exception as error:
            summary["errors"] += 1
            results.append({
                "signalId": signal_id,
                "ok": False,
                "error": repr(error),
            })

    return {
        "ok": True,
        "storageVersion": S832C_BATCH_REBUILD_DRY_RUN_VERSION,
        "mode": "batch_replay_feature_rebuild_dry_run",
        "policy": {
            "readOnly": True,
            "writesDb": False,
            "sendsTelegram": False,
            "changesClientDelivery": False,
            "changesRegistry": False,
        },
        "filters": {
            "sessionDate": session_date,
            "setupSlug": setup_slug,
            "symbol": symbol,
            "limit": limit,
        },
        "summary": summary,
        "results": results,
    }



# === S8.32D Research Rebuild Persist ===
S832D_RESEARCH_REBUILD_PERSIST_VERSION = "s8_32d_research_rebuild_persist_v1"


@app.post("/engine/research/rebuild-outcomes")
async def engine_research_rebuild_outcomes(
    session_date: str | None = None,
    setup_slug: str | None = None,
    symbol: str | None = None,
    limit: int = 10,
    apply: bool = False,
):
    import json
    import sqlite3
    from datetime import datetime, timezone

    batch = await engine_research_signal_batch_rebuild_dry_run(
        session_date=session_date,
        setup_slug=setup_slug,
        symbol=symbol,
        limit=limit,
    )

    if not isinstance(batch, dict) or not batch.get("ok"):
        return {
            "ok": False,
            "storageVersion": S832D_RESEARCH_REBUILD_PERSIST_VERSION,
            "error": "batch_rebuild_failed",
            "batch": batch,
        }

    now = datetime.now(timezone.utc).isoformat()
    run_id = "research_rebuild:" + now
    results = batch.get("results") if isinstance(batch.get("results"), list) else []
    summary = batch.get("summary") if isinstance(batch.get("summary"), dict) else {}

    if not apply:
        return {
            "ok": True,
            "storageVersion": S832D_RESEARCH_REBUILD_PERSIST_VERSION,
            "mode": "preview_only",
            "apply": False,
            "policy": {
                "readOnly": True,
                "writesDb": False,
                "sendsTelegram": False,
                "changesClientDelivery": False,
                "changesRegistry": False,
            },
            "summary": summary,
            "preview": {
                "runId": run_id,
                "wouldPersist": {
                    "researchRuns": 1,
                    "rebuiltOutcomes": len(results),
                    "featureSnapshots": len(results),
                },
            },
        }

    con = sqlite3.connect(_s832a2_db_path())

    inserted_outcomes = 0
    inserted_features = 0

    con.execute("""
      insert or replace into research_runs (
        run_id, run_type, status, session_date, source_version,
        signals_processed, outcomes_rebuilt, features_rebuilt, errors_count,
        created_at, completed_at, payload_json
      ) values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        run_id,
        "signal_anchored_rebuild",
        "completed",
        session_date,
        S832D_RESEARCH_REBUILD_PERSIST_VERSION,
        int(summary.get("processed") or 0),
        int(summary.get("replayOk") or 0),
        int(summary.get("featureReady") or 0) + int(summary.get("featurePartial") or 0),
        int(summary.get("errors") or 0),
        now,
        now,
        json.dumps(batch, default=str),
    ))

    for item in results:
        signal_id = item.get("signalId")
        if not signal_id:
            continue

        outcome = item.get("outcome") if isinstance(item.get("outcome"), dict) else {}
        feature = item.get("featureReadiness") if isinstance(item.get("featureReadiness"), dict) else {}

        con.execute("""
          insert or replace into research_rebuilt_outcomes (
            rebuild_id, run_id, signal_id, symbol, setup_slug, session_date,
            direction, trigger_time, result, result_r, mfe_r, mae_r,
            candles_checked, feature_readiness, missing_critical_count,
            source_version, research_only, client_visible, telegram_eligible,
            created_at, payload_json
          ) values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 0, 0, ?, ?)
        """, (
            f"{run_id}:outcome:{signal_id}",
            run_id,
            signal_id,
            item.get("symbol"),
            item.get("setupSlug"),
            item.get("sessionDate"),
            outcome.get("direction"),
            item.get("triggerTime"),
            outcome.get("result"),
            outcome.get("resultR"),
            outcome.get("mfeR"),
            outcome.get("maeR"),
            outcome.get("candlesChecked"),
            feature.get("status"),
            feature.get("missingCriticalCount"),
            S832D_RESEARCH_REBUILD_PERSIST_VERSION,
            now,
            json.dumps(item, default=str),
        ))
        inserted_outcomes += 1

        con.execute("""
          insert or replace into research_feature_snapshots (
            snapshot_id, run_id, signal_id, symbol, setup_slug, session_date,
            trigger_time, readiness, missing_critical_count,
            has_enough_for_failure_analysis, source_version, created_at, payload_json
          ) values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            f"{run_id}:feature:{signal_id}",
            run_id,
            signal_id,
            item.get("symbol"),
            item.get("setupSlug"),
            item.get("sessionDate"),
            item.get("triggerTime"),
            feature.get("status"),
            feature.get("missingCriticalCount"),
            1 if feature.get("hasEnoughForFailureAnalysis") else 0,
            S832D_RESEARCH_REBUILD_PERSIST_VERSION,
            now,
            json.dumps(item, default=str),
        ))
        inserted_features += 1

    con.commit()
    con.close()

    return {
        "ok": True,
        "storageVersion": S832D_RESEARCH_REBUILD_PERSIST_VERSION,
        "mode": "persisted",
        "apply": True,
        "policy": {
            "writesDb": True,
            "researchOnly": True,
            "sendsTelegram": False,
            "changesClientDelivery": False,
            "changesRegistry": False,
        },
        "runId": run_id,
        "persisted": {
            "researchRuns": 1,
            "rebuiltOutcomes": inserted_outcomes,
            "featureSnapshots": inserted_features,
        },
        "summary": summary,
    }



# === S8.33B Nightly Learning Status ===
S833B_NIGHTLY_STATUS_VERSION = "s8_33b_nightly_learning_status_v1"


@app.get("/engine/research/nightly-status")
def engine_research_nightly_status():
    import json
    import sqlite3
    from pathlib import Path
    from datetime import datetime, timezone

    report_dirs = [
        Path("/opt/skilledge/stock-engine/reports/nightly_self_learning"),
        Path("reports/nightly_self_learning"),
    ]

    latest_file = None
    for folder in report_dirs:
        try:
            files = sorted(folder.glob("*.json"), key=lambda p: p.stat().st_mtime, reverse=True)
            if files:
                latest_file = files[0]
                break
        except Exception:
            pass

    report = None
    report_error = None

    if latest_file:
        try:
            report = json.loads(latest_file.read_text(encoding="utf-8"))
        except Exception as error:
            report_error = repr(error)

    table_counts = {}
    try:
        con = sqlite3.connect(_s832a2_db_path())
        for table in ["research_runs", "research_rebuilt_outcomes", "research_feature_snapshots", "signal_records", "outcome_records"]:
            try:
                table_counts[table] = con.execute(f"select count(*) from {table}").fetchone()[0]
            except Exception:
                table_counts[table] = None
        con.close()
    except Exception as error:
        table_counts["error"] = repr(error)

    steps = []
    if isinstance(report, dict):
        for item in report.get("steps") or []:
            if isinstance(item, dict):
                steps.append({
                    "name": item.get("name"),
                    "ok": item.get("ok"),
                    "method": item.get("method"),
                    "path": item.get("path"),
                    "status": item.get("status") or item.get("statusCode"),
                    "duration": item.get("duration") or item.get("durationSec"),
                    "error": item.get("error"),
                })

    failed_steps = [s for s in steps if not s.get("ok")]

    return {
        "ok": bool(report) and not failed_steps,
        "storageVersion": S833B_NIGHTLY_STATUS_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "latestReport": {
            "exists": bool(latest_file),
            "path": str(latest_file) if latest_file else None,
            "fileName": latest_file.name if latest_file else None,
            "readError": report_error,
            "reportOk": report.get("ok") if isinstance(report, dict) else None,
            "reportVersion": report.get("version") if isinstance(report, dict) else None,
            "generatedAtKyiv": report.get("generatedAtKyiv") if isinstance(report, dict) else None,
            "sessionDates": report.get("sessionDates") if isinstance(report, dict) else None,
        },
        "steps": {
            "total": len(steps),
            "failed": len(failed_steps),
            "items": steps,
        },
        "learningMemory": {
            "tableCounts": table_counts,
        },
        "policy": {
            "readOnly": True,
            "writesDb": False,
            "sendsTelegram": False,
            "changesClientDelivery": False,
            "changesRegistry": False,
        },
    }



# === S8.34A Strategy Registry Status API ===
S834A_STRATEGY_REGISTRY_STATUS_VERSION = "s8_34a_strategy_registry_status_v1"


@app.get("/engine/strategies/registry")
def engine_strategies_registry(limit: int = 100):
    import json
    import sqlite3
    from datetime import datetime, timezone

    safe_limit = max(1, min(int(limit or 100), 200))

    con = sqlite3.connect(_s832a2_db_path())
    con.row_factory = sqlite3.Row

    registry_rows = [
        dict(r)
        for r in con.execute(
            """
            select *
            from algorithm_registry
            order by enabled desc, setup_slug asc
            limit ?
            """,
            (safe_limit,),
        ).fetchall()
    ]

    adjustment_rows = [
        dict(r)
        for r in con.execute(
            """
            select *
            from setup_adjustments
            where scope='setup'
            order by updated_at desc
            """
        ).fetchall()
    ]

    latest_adjustment_by_setup = {}
    for row in adjustment_rows:
        slug = row.get("setup_slug")
        if slug and slug not in latest_adjustment_by_setup:
            latest_adjustment_by_setup[slug] = row

    items = []
    by_family = {}
    by_execution_status = {}
    by_research_status = {}

    for row in registry_rows:
        payload = {}
        try:
            payload = json.loads(row.get("payload_json") or "{}")
        except Exception:
            payload = {}

        slug = row.get("setup_slug")
        adj = latest_adjustment_by_setup.get(slug) or {}

        enabled = bool(row.get("enabled"))
        execution_status = row.get("execution_status") or "UNKNOWN"

        sample_count = adj.get("sample_count")
        closed_count = adj.get("closed_count")
        win_rate = adj.get("win_rate_closed")
        avg_r = adj.get("avg_result_r_closed")
        stop_rate = adj.get("stop_rate_closed")

        candidate_ready = (
            closed_count is not None
            and int(closed_count or 0) >= 30
            and win_rate is not None
            and float(win_rate or 0) >= 65
            and avg_r is not None
            and float(avg_r or 0) > 0
        )

        if candidate_ready:
            research_status = "PROMOTE_CANDIDATE"
        elif enabled and execution_status == "LIVE_FOUNDATION":
            research_status = "PAPER_FORWARD"
        elif enabled:
            research_status = "ACTIVE_RESEARCH"
        else:
            research_status = "SHADOW_RESEARCH"

        client_visible = False

        family = row.get("family") or "unknown"
        by_family[family] = by_family.get(family, 0) + 1
        by_execution_status[execution_status] = by_execution_status.get(execution_status, 0) + 1
        by_research_status[research_status] = by_research_status.get(research_status, 0) + 1

        items.append({
            "setupSlug": slug,
            "setupName": row.get("setup_name"),
            "family": family,
            "assetType": row.get("asset_type"),
            "direction": row.get("direction"),
            "enabled": enabled,
            "executionStatus": execution_status,
            "calibrationEnabled": bool(row.get("calibration_enabled")),
            "researchStatus": research_status,
            "clientVisible": client_visible,
            "manualApprovalRequired": True,
            "stats": {
                "sampleCount": sample_count,
                "closedCount": closed_count,
                "workedCount": adj.get("worked_count"),
                "failedCount": adj.get("failed_count"),
                "winRateClosed": win_rate,
                "avgResultRClosed": avg_r,
                "stopRateClosed": stop_rate,
                "latestAdjustmentStatus": adj.get("status"),
                "latestAdjustmentAction": adj.get("action"),
                "latestRunId": adj.get("run_id"),
                "latestUpdatedAt": adj.get("updated_at"),
            },
            "promotionGate": {
                "minClosedTrades": 30,
                "minWinRateClosed": 65,
                "minAvgR": 0,
                "candidateReady": candidate_ready,
                "manualApproval": False,
                "liveClientEligible": False,
                "reason": (
                    "Meets numeric threshold but requires manual approval."
                    if candidate_ready
                    else "Insufficient evidence for client visibility."
                ),
            },
            "rules": {
                "contextRules": payload.get("contextRules"),
                "triggerRules": payload.get("triggerRules"),
                "riskRules": payload.get("riskRules"),
                "exitRules": payload.get("exitRules"),
            },
            "updatedAt": row.get("updated_at"),
        })

    con.close()

    return {
        "ok": True,
        "storageVersion": S834A_STRATEGY_REGISTRY_STATUS_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "summary": {
            "totalStrategies": len(items),
            "enabled": sum(1 for x in items if x.get("enabled")),
            "clientVisible": sum(1 for x in items if x.get("clientVisible")),
            "promotionCandidates": sum(1 for x in items if x.get("researchStatus") == "PROMOTE_CANDIDATE"),
            "byFamily": by_family,
            "byExecutionStatus": by_execution_status,
            "byResearchStatus": by_research_status,
        },
        "policy": {
            "readOnly": True,
            "writesDb": False,
            "sendsTelegram": False,
            "changesClientDelivery": False,
            "changesRegistry": False,
        },
        "items": items,
    }


# === S8.34A Strategy Evidence Engine ===
S834A_STRATEGY_EVIDENCE_VERSION = "s8_34a_strategy_evidence_engine_v1"
S834A_MIN_CLOSED_FOR_PROMOTION = 30
S834A_MIN_WIN_RATE_FOR_PROMOTION = 65.0
S834A_MIN_AVG_R_FOR_PROMOTION = 0.0


def _s834a_pct(part, total):
    total = int(total or 0)
    return None if total <= 0 else round((float(part or 0) / float(total)) * 100.0, 2)


def _s834a_quality(closed):
    closed = int(closed or 0)
    if closed <= 0:
        return "NO_CLOSED_DECISIONS"
    if closed < 5:
        return "VERY_THIN_SAMPLE"
    if closed < 15:
        return "THIN_SAMPLE"
    if closed < S834A_MIN_CLOSED_FOR_PROMOTION:
        return "EARLY_SAMPLE"
    return "MEANINGFUL_SAMPLE"


def _s834a_finish_stats(raw):
    raw = raw or {}

    def _i(value):
        try:
            if value is None or value == "":
                return 0
            return int(value)
        except Exception:
            return 0

    def _f(value):
        try:
            if value is None or value == "":
                return None
            return float(value)
        except Exception:
            return None

    total = _i(raw.get("total"))
    worked = _i(raw.get("worked"))
    failed = _i(raw.get("failed"))
    open_count = _i(raw.get("open"))
    session_close = _i(raw.get("sessionClose"))
    other = _i(raw.get("other"))

    closed = worked + failed
    avg_r = _f(raw.get("avgRClosed"))
    if avg_r is None:
        avg_r = _f(raw.get("avgResultRClosed"))

    # S8.40E:
    # OPEN / stuck outcomes are pipeline-repair problems.
    # EXPIRED_SESSION / SESSION_CLOSE outcomes are non-win/loss evidence-quality gaps.
    # They must not inflate win rate, but they also must not keep the system in
    # OUTCOME_PIPELINE_REPAIR_REQUIRED after OPEN has been classified to NO_EVAL.
    evidence_session_close_pct = _s834a_pct(session_close, total)

    return {
        "total": total,
        "worked": worked,
        "failed": failed,
        "open": open_count,
        "sessionClose": session_close,
        "other": other,
        "closedDecisionCount": closed,
        "winRateClosed": _s834a_pct(worked, closed),
        "avgRClosed": round(float(avg_r), 4) if avg_r is not None else None,
        "stopRateClosed": _s834a_pct(failed, closed),
        "openPct": _s834a_pct(open_count, total),
        "sessionClosePct": 0.0,
        "pipelineSessionClosePct": 0.0,
        "evidenceSessionClosePct": evidence_session_close_pct,
        "sessionCloseEvidencePct": evidence_session_close_pct,
        "otherPct": _s834a_pct(other, total),
    }


def _s834a_merge_stats(a, b):
    values = {}
    for key in ("total", "worked", "failed", "open", "sessionClose", "other"):
        values[key] = int((a or {}).get(key) or 0) + int((b or {}).get(key) or 0)

    parts = []
    a_closed = int((a or {}).get("worked") or 0) + int((a or {}).get("failed") or 0)
    b_closed = int((b or {}).get("worked") or 0) + int((b or {}).get("failed") or 0)

    if (a or {}).get("avgRClosed") is not None and a_closed > 0:
        parts.append((float(a.get("avgRClosed")), a_closed))
    if (b or {}).get("avgRClosed") is not None and b_closed > 0:
        parts.append((float(b.get("avgRClosed")), b_closed))

    if parts:
        total_count = sum(count for _, count in parts)
        values["avgRClosed"] = sum(avg * count for avg, count in parts) / total_count if total_count else None
    else:
        values["avgRClosed"] = None

    return values


def _s834a_status(combined, live, research):
    total = int(combined.get("total") or 0)
    closed = int(combined.get("closedDecisionCount") or 0)

    live_open_pct = float(live.get("openPct") or 0)
    research_open_pct = float(research.get("openPct") or 0)

    if total <= 0:
        return "REGISTRY_ONLY"

    if live_open_pct >= 20.0 or research_open_pct >= 20.0:
        return "OUTCOME_PIPELINE_DIRTY_TOO_MANY_OPEN"

    if closed < S834A_MIN_CLOSED_FOR_PROMOTION:
        return "PAPER_EVIDENCE_BUILDING"

    win_rate = combined.get("winRateClosed")
    avg_r = combined.get("avgRClosed")

    if (
        win_rate is not None
        and avg_r is not None
        and float(win_rate) >= S834A_MIN_WIN_RATE_FOR_PROMOTION
        and float(avg_r) > S834A_MIN_AVG_R_FOR_PROMOTION
    ):
        return "PROMOTION_CANDIDATE_NEEDS_MANUAL_APPROVAL"

    return "NEGATIVE_EDGE_FILTER_REQUIRED"


def _s834a_warnings(combined, live, research):
    warnings = []

    total = int(combined.get("total") or 0)
    closed = int(combined.get("closedDecisionCount") or 0)

    live_open_pct = float(live.get("openPct") or 0)
    research_open_pct = float(research.get("openPct") or 0)

    if live_open_pct >= 20.0 or research_open_pct >= 20.0:
        warnings.append("High OPEN ratio. Outcome pipeline/replay completeness must be checked.")

    evidence_session_close_pct = max(
        float(live.get("evidenceSessionClosePct") or live.get("sessionCloseEvidencePct") or 0),
        float(research.get("evidenceSessionClosePct") or research.get("sessionCloseEvidencePct") or 0),
    )
    if total > 0 and evidence_session_close_pct >= 30.0:
        warnings.append("High SESSION_CLOSE/EXPIRED ratio. These rows are treated as non-win/loss evidence-quality gaps, not pipeline repair.")

    if closed <= 0:
        warnings.append("No closed TP/STOP decisions. Do not use total rows as win/loss evidence.")

    if closed < S834A_MIN_CLOSED_FOR_PROMOTION:
        warnings.append("Closed TP/STOP sample below promotion threshold.")

    if (
        combined.get("winRateClosed") is not None
        and float(combined["winRateClosed"]) < S834A_MIN_WIN_RATE_FOR_PROMOTION
    ):
        warnings.append("Win rate on closed decisions is below promotion threshold.")

    if (
        combined.get("avgRClosed") is not None
        and float(combined["avgRClosed"]) <= S834A_MIN_AVG_R_FOR_PROMOTION
    ):
        warnings.append("Average R on closed decisions is not positive. Filter/failure analysis required.")

    return warnings


def _s834a_action(status):
    actions = {
        "REGISTRY_ONLY": "Collect first closed TP/STOP outcomes before judging edge.",
        "OUTCOME_PIPELINE_DIRTY_TOO_MANY_OPEN": "Fix stuck OPEN outcome pipeline before judging edge or promotion.",
        "PAPER_EVIDENCE_BUILDING": "Keep collecting clean closed TP/STOP evidence in paper/shadow mode.",
        "NEGATIVE_EDGE_FILTER_REQUIRED": "Keep blocked from client promotion and test stricter filters.",
        "PROMOTION_CANDIDATE_NEEDS_MANUAL_APPROVAL": "Eligible for manual review only; do not auto-promote.",
    }
    return actions.get(status, "Keep blocked from client promotion until gates pass.")


@app.get("/engine/strategies/evidence")
def engine_strategies_evidence(limit: int = 100):
    import json
    import sqlite3
    from datetime import datetime, timezone

    safe_limit = max(1, min(int(limit or 100), 200))
    con = sqlite3.connect(_s832a2_db_path())
    con.row_factory = sqlite3.Row

    registry_rows = [
        dict(r)
        for r in con.execute(
            """
            select setup_slug, setup_name, family, asset_type, direction, enabled,
                   execution_status, calibration_enabled, updated_at, payload_json
            from algorithm_registry
            order by enabled desc, setup_slug asc
            limit ?
            """,
            (safe_limit,),
        ).fetchall()
    ]

    registry_total = int(con.execute("select count(*) as c from algorithm_registry").fetchone()["c"])

    live_sql = """
    with b as (
      select setup_slug, result_r,
        case
          when upper(coalesce(status,''))='OPEN' then 'open'
          when upper(coalesce(status,''))='EXPIRED_SESSION' or upper(coalesce(first_event,''))='SESSION_CLOSE' then 'sessionClose'
          when upper(coalesce(status,''))='FAILED' or upper(coalesce(first_event,''))='STOP' or coalesce(stop_hit,0)=1 then 'failed'
          when upper(coalesce(status,''))='WORKED' or upper(coalesce(first_event,'')) in ('TP1','TP2') or coalesce(tp1_hit,0)=1 or coalesce(tp2_hit,0)=1 then 'worked'
          else 'other'
        end as bucket
      from outcome_records
      where setup_slug is not null and trim(setup_slug) != ''
    )
    select setup_slug,
      count(*) as total,
      sum(case when bucket='worked' then 1 else 0 end) as worked,
      sum(case when bucket='failed' then 1 else 0 end) as failed,
      sum(case when bucket='open' then 1 else 0 end) as open,
      sum(case when bucket='sessionClose' then 1 else 0 end) as sessionClose,
      sum(case when bucket='other' then 1 else 0 end) as other,
      avg(case when bucket in ('worked','failed') then result_r end) as avgRClosed
    from b
    group by setup_slug
    """

    live_raw = {
        r["setup_slug"]: _s834a_finish_stats(dict(r))
        for r in con.execute(live_sql).fetchall()
    }

    research_sql = """
    with b as (
      select setup_slug, result_r,
        case
          when upper(coalesce(result,'')) in ('OPEN','PENDING') then 'open'
          when upper(coalesce(result,'')) in ('SESSION_CLOSE','EXPIRED_SESSION','EXPIRED') then 'sessionClose'
          when upper(coalesce(result,'')) like '%STOP%' or upper(coalesce(result,'')) like '%FAILED%' then 'failed'
          when upper(coalesce(result,'')) like '%TP1%' or upper(coalesce(result,'')) like '%TP2%' or upper(coalesce(result,'')) like '%WORKED%' then 'worked'
          else 'other'
        end as bucket
      from research_rebuilt_outcomes
      where setup_slug is not null and trim(setup_slug) != ''
    )
    select setup_slug,
      count(*) as total,
      sum(case when bucket='worked' then 1 else 0 end) as worked,
      sum(case when bucket='failed' then 1 else 0 end) as failed,
      sum(case when bucket='open' then 1 else 0 end) as open,
      sum(case when bucket='sessionClose' then 1 else 0 end) as sessionClose,
      sum(case when bucket='other' then 1 else 0 end) as other,
      avg(case when bucket in ('worked','failed') then result_r end) as avgRClosed
    from b
    group by setup_slug
    """

    research_raw = {
        r["setup_slug"]: _s834a_finish_stats(dict(r))
        for r in con.execute(research_sql).fetchall()
    }

    empty = _s834a_finish_stats({})
    items = []
    by_quality = {}
    by_status = {}
    dirty = 0
    candidates = 0
    any_closed = 0
    meaningful = 0

    for row in registry_rows:
        slug = row.get("setup_slug")
        live = live_raw.get(slug) or dict(empty)
        research = research_raw.get(slug) or dict(empty)
        combined = _s834a_finish_stats(_s834a_merge_stats(live, research))
        quality = _s834a_quality(combined.get("closedDecisionCount"))
        status = _s834a_status(combined, live, research)
        candidate_ready = status == "PROMOTION_CANDIDATE_MANUAL_REVIEW"

        dirty += 1 if status == "OUTCOME_PIPELINE_DIRTY_TOO_MANY_OPEN" else 0
        candidates += 1 if candidate_ready else 0
        any_closed += 1 if int(combined.get("closedDecisionCount") or 0) > 0 else 0
        meaningful += 1 if quality == "MEANINGFUL_SAMPLE" else 0
        by_quality[quality] = by_quality.get(quality, 0) + 1
        by_status[status] = by_status.get(status, 0) + 1

        try:
            payload = json.loads(row.get("payload_json") or "{}")
        except Exception:
            payload = {}

        items.append({
            "setupSlug": slug,
            "setupName": row.get("setup_name"),
            "family": row.get("family") or "unknown",
            "assetType": row.get("asset_type"),
            "direction": row.get("direction"),
            "enabled": bool(row.get("enabled")),
            "executionStatus": row.get("execution_status") or "UNKNOWN",
            "calibrationEnabled": bool(row.get("calibration_enabled")),
            "clientVisible": False,
            "manualApprovalRequired": True,
            "evidence": {
                **combined,
                "minClosedForPromotion": S834A_MIN_CLOSED_FOR_PROMOTION,
                "minWinRateForPromotion": S834A_MIN_WIN_RATE_FOR_PROMOTION,
                "minAvgRForPromotion": S834A_MIN_AVG_R_FOR_PROMOTION,
            },
            "liveEvidence": live,
            "researchEvidence": research,
            "evidenceQuality": quality,
            "promotionStatus": status,
            "recommendedAction": _s834a_action(status),
            "warnings": _s834a_warnings(combined, live, research),
            "promotionGate": {
                "closedDecisionCountGteMin": int(combined.get("closedDecisionCount") or 0) >= S834A_MIN_CLOSED_FOR_PROMOTION,
                "winRateGteMin": combined.get("winRateClosed") is not None and float(combined["winRateClosed"]) >= S834A_MIN_WIN_RATE_FOR_PROMOTION,
                "avgRGtMin": combined.get("avgRClosed") is not None and float(combined["avgRClosed"]) > S834A_MIN_AVG_R_FOR_PROMOTION,
                "candidateReady": candidate_ready,
                "manualApproval": False,
                "liveClientEligible": False,
                "reason": "Numeric evidence candidate only; manual approval is still required." if candidate_ready else "Insufficient approved evidence for client visibility.",
            },
            "rules": {
                "contextRules": payload.get("contextRules"),
                "triggerRules": payload.get("triggerRules"),
                "riskRules": payload.get("riskRules"),
            },
            "updatedAt": row.get("updated_at"),
        })

    con.close()

    return {
        "ok": True,
        "storageVersion": S834A_STRATEGY_EVIDENCE_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "summary": {
            "registryTotal": registry_total,
            "returned": len(items),
            "clientVisible": 0,
            "manualApprovalRequired": len(items),
            "promotionCandidates": candidates,
            "dirtyOutcomePipelines": dirty,
            "withAnyClosedEvidence": any_closed,
            "withMeaningfulSample": meaningful,
            "byEvidenceQuality": by_quality,
            "byPromotionStatus": by_status,
        },
        "policy": {
            "readOnly": True,
            "writesDb": False,
            "sendsTelegram": False,
            "changesClientDelivery": False,
            "changesRegistry": False,
            "autoPromotesStrategies": False,
        },
        "items": items,
    }

# === S8.35A Failure Analysis Agent ===
S835A_FAILURE_ANALYSIS_VERSION = "s8_35a_failure_analysis_agent_v1"


def _s835a_float(value, default=None):
    try:
        if value is None:
            return default
        parsed = float(value)
        if parsed != parsed:
            return default
        return parsed
    except Exception:
        return default


def _s835a_round(value, digits=4):
    parsed = _s835a_float(value)
    return round(parsed, digits) if parsed is not None else None


def _s835a_pct(part, total):
    total = int(total or 0)
    return None if total <= 0 else round(float(part or 0) / float(total) * 100.0, 2)


def _s835a_severity_rank(severity):
    return {"CRITICAL": 4, "HIGH": 3, "MEDIUM": 2, "LOW": 1, "INFO": 0}.get(str(severity or "").upper(), 0)


def _s835a_collect_missing_fields(payload):
    fields = []

    def walk(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                key_l = str(key).lower()
                if key_l in ("missingcriticalfields", "missing_critical_fields", "missingfields", "missing_fields"):
                    if isinstance(value, list):
                        for item in value:
                            if item is not None:
                                fields.append(str(item))
                    elif isinstance(value, str) and value:
                        fields.append(value)
                else:
                    walk(value)
        elif isinstance(obj, list):
            for item in obj:
                walk(item)

    try:
        walk(payload if isinstance(payload, (dict, list)) else {})
    except Exception:
        pass

    return fields


def _s835a_add_issue(issues, code, severity, message, action, evidence=None):
    issues.append({
        "code": code,
        "severity": severity,
        "message": message,
        "recommendedAction": action,
        "evidence": evidence or {},
    })


@app.get("/engine/research/failure-analysis")
def engine_research_failure_analysis(
    limit: int = 100,
    min_closed: int = 30,
    min_trigger_closed: int = 5,
    include_all: bool = False,
):
    import json
    import sqlite3
    from collections import Counter
    from datetime import datetime, timezone

    safe_limit = max(1, min(int(limit or 100), 200))
    min_closed = max(1, int(min_closed or 30))
    min_trigger_closed = max(1, int(min_trigger_closed or 5))

    con = sqlite3.connect(_s832a2_db_path())
    con.row_factory = sqlite3.Row

    registry_rows = [
        dict(r)
        for r in con.execute(
            """
            select setup_slug, setup_name, family, asset_type, direction, enabled,
                   execution_status, calibration_enabled, updated_at, payload_json
            from algorithm_registry
            order by enabled desc, setup_slug asc
            """
        ).fetchall()
    ]

    live_sql = """
    with b as (
      select setup_slug, result_r,
        case
          when upper(coalesce(status,''))='OPEN' then 'open'
          when upper(coalesce(status,''))='EXPIRED_SESSION' or upper(coalesce(first_event,''))='SESSION_CLOSE' then 'sessionClose'
          when upper(coalesce(status,''))='FAILED' or upper(coalesce(first_event,''))='STOP' or coalesce(stop_hit,0)=1 then 'failed'
          when upper(coalesce(status,''))='WORKED' or upper(coalesce(first_event,'')) in ('TP1','TP2') or coalesce(tp1_hit,0)=1 or coalesce(tp2_hit,0)=1 then 'worked'
          else 'other'
        end as bucket
      from outcome_records
      where setup_slug is not null and trim(setup_slug) != ''
    )
    select setup_slug,
      count(*) as total,
      sum(case when bucket='worked' then 1 else 0 end) as worked,
      sum(case when bucket='failed' then 1 else 0 end) as failed,
      sum(case when bucket='open' then 1 else 0 end) as open,
      sum(case when bucket='sessionClose' then 1 else 0 end) as sessionClose,
      sum(case when bucket='other' then 1 else 0 end) as other,
      avg(case when bucket in ('worked','failed') then result_r end) as avgRClosed
    from b
    group by setup_slug
    """

    research_sql = """
    with b as (
      select setup_slug, result_r,
        case
          when upper(coalesce(result,'')) in ('OPEN','PENDING') then 'open'
          when upper(coalesce(result,'')) in ('SESSION_CLOSE','EXPIRED_SESSION','EXPIRED') then 'sessionClose'
          when upper(coalesce(result,'')) like '%STOP%' or upper(coalesce(result,'')) like '%FAILED%' then 'failed'
          when upper(coalesce(result,'')) like '%TP1%' or upper(coalesce(result,'')) like '%TP2%' or upper(coalesce(result,'')) like '%WORKED%' then 'worked'
          else 'other'
        end as bucket
      from research_rebuilt_outcomes
      where setup_slug is not null and trim(setup_slug) != ''
    )
    select setup_slug,
      count(*) as total,
      sum(case when bucket='worked' then 1 else 0 end) as worked,
      sum(case when bucket='failed' then 1 else 0 end) as failed,
      sum(case when bucket='open' then 1 else 0 end) as open,
      sum(case when bucket='sessionClose' then 1 else 0 end) as sessionClose,
      sum(case when bucket='other' then 1 else 0 end) as other,
      avg(case when bucket in ('worked','failed') then result_r end) as avgRClosed
    from b
    group by setup_slug
    """

    live_raw = {
        r["setup_slug"]: _s834a_finish_stats(dict(r))
        for r in con.execute(live_sql).fetchall()
    }
    research_raw = {
        r["setup_slug"]: _s834a_finish_stats(dict(r))
        for r in con.execute(research_sql).fetchall()
    }

    trigger_sql = """
    with b as (
      select setup_slug, coalesce(primary_trigger, 'UNKNOWN') as primary_trigger, result_r,
        case
          when upper(coalesce(status,''))='FAILED' or upper(coalesce(first_event,''))='STOP' or coalesce(stop_hit,0)=1 then 'failed'
          when upper(coalesce(status,''))='WORKED' or upper(coalesce(first_event,'')) in ('TP1','TP2') or coalesce(tp1_hit,0)=1 or coalesce(tp2_hit,0)=1 then 'worked'
          else 'nonClosed'
        end as bucket
      from outcome_records
      where setup_slug is not null and trim(setup_slug) != ''
    )
    select setup_slug, primary_trigger,
      count(*) as total,
      sum(case when bucket='worked' then 1 else 0 end) as worked,
      sum(case when bucket='failed' then 1 else 0 end) as failed,
      avg(case when bucket in ('worked','failed') then result_r end) as avgRClosed
    from b
    group by setup_slug, primary_trigger
    """

    trigger_rows_by_setup = {}
    for row in con.execute(trigger_sql).fetchall():
        d = dict(row)
        worked = int(d.get("worked") or 0)
        failed = int(d.get("failed") or 0)
        closed = worked + failed
        if closed < min_trigger_closed:
            continue

        item = {
            "primaryTrigger": d.get("primary_trigger") or "UNKNOWN",
            "total": int(d.get("total") or 0),
            "closedDecisionCount": closed,
            "worked": worked,
            "failed": failed,
            "winRateClosed": _s835a_pct(worked, closed),
            "avgRClosed": _s835a_round(d.get("avgRClosed")),
            "stopRateClosed": _s835a_pct(failed, closed),
        }
        trigger_rows_by_setup.setdefault(d.get("setup_slug"), []).append(item)

    for setup, rows in trigger_rows_by_setup.items():
        rows.sort(key=lambda x: (
            x["avgRClosed"] if x["avgRClosed"] is not None else 999,
            x["winRateClosed"] if x["winRateClosed"] is not None else 999,
            -x["closedDecisionCount"],
        ))

    feature_sql = """
    select setup_slug,
      count(*) as total,
      sum(case when upper(coalesce(readiness,''))='READY' then 1 else 0 end) as ready,
      sum(case when coalesce(has_enough_for_failure_analysis,0)=1 then 1 else 0 end) as failureReady,
      avg(coalesce(missing_critical_count,0)) as avgMissingCritical,
      max(coalesce(missing_critical_count,0)) as maxMissingCritical
    from research_feature_snapshots
    where setup_slug is not null and trim(setup_slug) != ''
    group by setup_slug
    """

    feature_by_setup = {}
    for row in con.execute(feature_sql).fetchall():
        d = dict(row)
        total = int(d.get("total") or 0)
        feature_by_setup[d.get("setup_slug")] = {
            "total": total,
            "ready": int(d.get("ready") or 0),
            "readyPct": _s835a_pct(d.get("ready"), total),
            "failureReady": int(d.get("failureReady") or 0),
            "failureReadyPct": _s835a_pct(d.get("failureReady"), total),
            "avgMissingCritical": _s835a_round(d.get("avgMissingCritical"), 2),
            "maxMissingCritical": int(d.get("maxMissingCritical") or 0),
            "topMissingCriticalFields": [],
        }

    missing_counters = {}
    feature_payload_rows = con.execute(
        """
        select setup_slug, payload_json
        from research_feature_snapshots
        where setup_slug is not null and trim(setup_slug) != ''
        order by created_at desc
        limit 5000
        """
    ).fetchall()

    for row in feature_payload_rows:
        slug = row["setup_slug"]
        try:
            payload = json.loads(row["payload_json"] or "{}")
        except Exception:
            payload = {}
        fields = _s835a_collect_missing_fields(payload)
        if fields:
            missing_counters.setdefault(slug, Counter()).update(fields)

    for slug, counter in missing_counters.items():
        if slug in feature_by_setup:
            feature_by_setup[slug]["topMissingCriticalFields"] = [
                {"field": name, "count": count}
                for name, count in counter.most_common(8)
            ]

    latest_adjustment_by_setup = {}
    latest_adjustment_by_trigger = {}
    for row in con.execute(
        """
        select *
        from setup_adjustments
        order by updated_at desc
        """
    ).fetchall():
        d = dict(row)
        slug = d.get("setup_slug")
        scope = d.get("scope")
        trigger = d.get("primary_trigger") or "UNKNOWN"

        if scope == "setup" and slug and slug not in latest_adjustment_by_setup:
            latest_adjustment_by_setup[slug] = d

        if scope == "setup_trigger" and slug:
            key = (slug, trigger)
            if key not in latest_adjustment_by_trigger:
                latest_adjustment_by_trigger[key] = d

    empty = _s834a_finish_stats({})
    items = []
    counts = {
        "critical": 0,
        "high": 0,
        "medium": 0,
        "low": 0,
        "negativeEdge": 0,
        "dirtyOutcomePipeline": 0,
        "featureIssues": 0,
        "demotionCandidates": 0,
        "triggerWeaknesses": 0,
    }

    for row in registry_rows:
        slug = row.get("setup_slug")
        live = live_raw.get(slug) or dict(empty)
        research = research_raw.get(slug) or dict(empty)
        combined = _s834a_finish_stats(_s834a_merge_stats(live, research))
        feature = feature_by_setup.get(slug) or {
            "total": 0,
            "ready": 0,
            "readyPct": None,
            "failureReady": 0,
            "failureReadyPct": None,
            "avgMissingCritical": None,
            "maxMissingCritical": 0,
            "topMissingCriticalFields": [],
        }

        closed = int(combined.get("closedDecisionCount") or 0)
        win_rate = _s835a_float(combined.get("winRateClosed"))
        avg_r = _s835a_float(combined.get("avgRClosed"))
        open_pct = _s835a_float(live.get("openPct"), 0.0)
        session_close_pct = _s835a_float(live.get("sessionClosePct"), 0.0)

        issues = []
        filters_to_test = []
        risk_controls = []
        pipeline_fixes = []

        if int(live.get("total") or 0) >= 20 and open_pct >= 50.0:
            _s835a_add_issue(
                issues,
                "HIGH_OPEN_RATIO",
                "CRITICAL",
                f"{slug} has {open_pct}% OPEN records in live outcome_records.",
                "Run outcome cleanup/re-evaluation before judging edge. OPEN rows must not be counted as wins or losses.",
                {"liveTotal": live.get("total"), "open": live.get("open"), "openPct": live.get("openPct")},
            )
            pipeline_fixes.append("Re-run persisted outcome evaluation for old OPEN rows and verify trigger_time/session_to_close handling.")

        if int(live.get("total") or 0) >= 20 and session_close_pct >= 30.0:
            _s835a_add_issue(
                issues,
                "HIGH_SESSION_CLOSE_RATIO",
                "HIGH",
                f"{slug} has {session_close_pct}% SESSION_CLOSE/EXPIRED records.",
                "Check whether targets/stops are too wide, triggers are too late, or future candles are missing.",
                {"liveTotal": live.get("total"), "sessionClose": live.get("sessionClose"), "sessionClosePct": live.get("sessionClosePct")},
            )
            pipeline_fixes.append("Separate SESSION_CLOSE outcomes from TP/STOP win rate and inspect late-session triggers.")

        if closed <= 0:
            _s835a_add_issue(
                issues,
                "NO_CLOSED_DECISIONS",
                "MEDIUM",
                f"{slug} has no closed TP/STOP decisions.",
                "Keep in registry/research only. Do not promote or show client-facing until closed evidence exists.",
                {"total": combined.get("total")},
            )
        elif closed < min_closed:
            _s835a_add_issue(
                issues,
                "THIN_CLOSED_SAMPLE",
                "LOW",
                f"{slug} has only {closed} closed TP/STOP decisions.",
                f"Collect at least {min_closed} closed decisions before promotion review.",
                {"closedDecisionCount": closed, "minClosed": min_closed},
            )

        if closed >= min_closed and win_rate is not None and win_rate < 65.0:
            _s835a_add_issue(
                issues,
                "LOW_WIN_RATE_CLOSED",
                "HIGH",
                f"{slug} win rate on closed decisions is {win_rate}%.",
                "Run stricter confirmation filters and block weak trigger variants before promotion.",
                {"winRateClosed": win_rate, "minWinRate": 65.0},
            )
            filters_to_test.append("Require stronger trigger confirmation before ARMED -> ACTIVE.")
            filters_to_test.append("Block entries after weak/late session structure unless RR and trigger quality improve.")

        if closed >= min_closed and avg_r is not None and avg_r <= 0:
            _s835a_add_issue(
                issues,
                "NEGATIVE_AVG_R_CLOSED",
                "HIGH",
                f"{slug} avg R on closed decisions is {avg_r}.",
                "Treat as negative edge until filters improve avg R above zero on closed decisions.",
                {"avgRClosed": avg_r, "minAvgR": 0.0},
            )
            filters_to_test.append("Tighten setup-specific entry location and avoid chasing extended candles.")
            risk_controls.append("Reduce score/risk or keep research-only until avgRClosed is positive.")

        if int(feature.get("total") or 0) > 0 and _s835a_float(feature.get("failureReadyPct"), 100.0) < 80.0:
            _s835a_add_issue(
                issues,
                "LOW_FEATURE_FAILURE_ANALYSIS_COVERAGE",
                "MEDIUM",
                f"{slug} feature snapshots are not consistently failure-analysis ready.",
                "Improve feature snapshot completeness before trusting fine-grained failure patterns.",
                feature,
            )

        if int(feature.get("total") or 0) > 0 and _s835a_float(feature.get("avgMissingCritical"), 0.0) > 2.0:
            _s835a_add_issue(
                issues,
                "MISSING_CRITICAL_FEATURES",
                "MEDIUM",
                f"{slug} has avg missing critical features {feature.get('avgMissingCritical')}.",
                "Prioritize missing feature fields before setup promotion or precise pattern analysis.",
                feature,
            )

        trigger_rows = trigger_rows_by_setup.get(slug) or []
        weak_triggers = []
        for tr in trigger_rows:
            tr_win = _s835a_float(tr.get("winRateClosed"))
            tr_avg = _s835a_float(tr.get("avgRClosed"))
            if (tr_win is not None and tr_win < 40.0) or (tr_avg is not None and tr_avg < 0.0):
                trigger_adj = latest_adjustment_by_trigger.get((slug, tr.get("primaryTrigger") or "UNKNOWN")) or {}
                weak_triggers.append({
                    **tr,
                    "latestAdjustment": {
                        "status": trigger_adj.get("status"),
                        "action": trigger_adj.get("action"),
                        "scoreAdjustment": trigger_adj.get("score_adjustment"),
                        "strictnessAdjustment": trigger_adj.get("strictness_adjustment"),
                        "riskAdjustment": trigger_adj.get("risk_adjustment"),
                        "updatedAt": trigger_adj.get("updated_at"),
                    },
                    "recommendedAction": "Test demotion/blocking for this trigger variant in shadow/research before live client delivery.",
                })

        if weak_triggers:
            _s835a_add_issue(
                issues,
                "WEAK_TRIGGER_VARIANTS",
                "HIGH",
                f"{slug} has {len(weak_triggers)} weak trigger variants.",
                "Run trigger-level failure review and test blocking/demotion rules.",
                {"weakTriggerCount": len(weak_triggers), "minTriggerClosed": min_trigger_closed},
            )
            filters_to_test.append("Block/demote weak primary_trigger variants with low closed win rate or negative avg R.")

        setup_adj = latest_adjustment_by_setup.get(slug) or {}
        demotion_candidate = bool(
            closed >= min_closed
            and (
                (win_rate is not None and win_rate < 40.0 and avg_r is not None and avg_r <= 0.0)
                or len(weak_triggers) >= 2
            )
        )

        if demotion_candidate:
            risk_controls.append("Candidate for demotion to research-only until new evidence improves.")
            counts["demotionCandidates"] += 1

        if any(i["code"] in ("HIGH_OPEN_RATIO", "HIGH_SESSION_CLOSE_RATIO") for i in issues):
            counts["dirtyOutcomePipeline"] += 1
        if any(i["code"] in ("LOW_WIN_RATE_CLOSED", "NEGATIVE_AVG_R_CLOSED") for i in issues):
            counts["negativeEdge"] += 1
        if any(i["code"] in ("LOW_FEATURE_FAILURE_ANALYSIS_COVERAGE", "MISSING_CRITICAL_FEATURES") for i in issues):
            counts["featureIssues"] += 1
        if weak_triggers:
            counts["triggerWeaknesses"] += 1

        if not issues and not include_all:
            continue

        severity = "INFO"
        if issues:
            severity = max((i["severity"] for i in issues), key=_s835a_severity_rank)
            counts[str(severity).lower()] = counts.get(str(severity).lower(), 0) + 1

        status = "OK_NO_FAILURE_ACTION"
        if any(i["code"] == "HIGH_OPEN_RATIO" for i in issues):
            status = "PIPELINE_REPAIR_REQUIRED"
        elif any(i["code"] == "HIGH_SESSION_CLOSE_RATIO" for i in issues):
            status = "OUTCOME_QUALITY_REVIEW_REQUIRED"
        elif demotion_candidate:
            status = "DEMOTION_CANDIDATE_RESEARCH_ONLY"
        elif any(i["code"] in ("LOW_WIN_RATE_CLOSED", "NEGATIVE_AVG_R_CLOSED") for i in issues):
            status = "NEGATIVE_EDGE_FILTER_REQUIRED"
        elif any(i["code"] == "WEAK_TRIGGER_VARIANTS" for i in issues):
            status = "TRIGGER_FILTER_TEST_REQUIRED"
        elif any(i["code"] in ("NO_CLOSED_DECISIONS", "THIN_CLOSED_SAMPLE") for i in issues):
            status = "EVIDENCE_BUILDING"

        if not filters_to_test and status == "OK_NO_FAILURE_ACTION":
            filters_to_test.append("No failure filter required from current evidence. Continue monitoring.")

        try:
            payload = json.loads(row.get("payload_json") or "{}")
        except Exception:
            payload = {}

        items.append({
            "setupSlug": slug,
            "setupName": row.get("setup_name"),
            "family": row.get("family") or "unknown",
            "assetType": row.get("asset_type"),
            "direction": row.get("direction"),
            "enabled": bool(row.get("enabled")),
            "executionStatus": row.get("execution_status") or "UNKNOWN",
            "failureStatus": status,
            "severity": severity,
            "demotionCandidate": demotion_candidate,
            "clientVisible": False,
            "manualApprovalRequired": True,
            "evidence": combined,
            "liveEvidence": live,
            "researchEvidence": research,
            "featureCoverage": feature,
            "weakTriggerVariants": weak_triggers[:8],
            "latestSetupAdjustment": {
                "status": setup_adj.get("status"),
                "action": setup_adj.get("action"),
                "scoreAdjustment": setup_adj.get("score_adjustment"),
                "strictnessAdjustment": setup_adj.get("strictness_adjustment"),
                "riskAdjustment": setup_adj.get("risk_adjustment"),
                "sampleCount": setup_adj.get("sample_count"),
                "closedCount": setup_adj.get("closed_count"),
                "winRateClosed": setup_adj.get("win_rate_closed"),
                "avgResultRClosed": setup_adj.get("avg_result_r_closed"),
                "updatedAt": setup_adj.get("updated_at"),
            },
            "issues": sorted(issues, key=lambda x: _s835a_severity_rank(x["severity"]), reverse=True),
            "filtersToTest": list(dict.fromkeys(filters_to_test))[:8],
            "riskControls": list(dict.fromkeys(risk_controls))[:8],
            "pipelineFixes": list(dict.fromkeys(pipeline_fixes))[:8],
            "rulesContext": {
                "contextRules": payload.get("contextRules"),
                "triggerRules": payload.get("triggerRules"),
                "riskRules": payload.get("riskRules"),
            },
        })

    con.close()

    items.sort(key=lambda x: (
        _s835a_severity_rank(x.get("severity")),
        1 if x.get("demotionCandidate") else 0,
        int((x.get("evidence") or {}).get("closedDecisionCount") or 0),
    ), reverse=True)

    returned = items[:safe_limit]

    return {
        "ok": True,
        "storageVersion": S835A_FAILURE_ANALYSIS_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "summary": {
            "registryTotal": len(registry_rows),
            "returned": len(returned),
            "includeAll": bool(include_all),
            "minClosed": min_closed,
            "minTriggerClosed": min_trigger_closed,
            "critical": counts.get("critical", 0),
            "high": counts.get("high", 0),
            "medium": counts.get("medium", 0),
            "low": counts.get("low", 0),
            "negativeEdgeSetups": counts.get("negativeEdge", 0),
            "dirtyOutcomePipelineSetups": counts.get("dirtyOutcomePipeline", 0),
            "featureIssueSetups": counts.get("featureIssues", 0),
            "demotionCandidates": counts.get("demotionCandidates", 0),
            "triggerWeaknessSetups": counts.get("triggerWeaknesses", 0),
        },
        "agent": {
            "name": "Failure Analysis Agent",
            "purpose": "Find real setup/trigger/pipeline weaknesses from live outcomes, rebuilt research outcomes, feature snapshots, and setup adjustments.",
            "doesNotAutoChangeStrategy": True,
            "doesNotAutoPromote": True,
            "doesNotSendTelegram": True,
        },
        "policy": {
            "readOnly": True,
            "writesDb": False,
            "sendsTelegram": False,
            "changesClientDelivery": False,
            "changesRegistry": False,
            "autoDemotesStrategies": False,
            "autoPromotesStrategies": False,
            "manualApprovalRequired": True,
        },
        "items": returned,
    }

