S837A_ADMIN_OPS_STATUS_VERSION = "s8_37a_admin_ops_commander_status_v1"


def _s837a_safe_call(name, fn, fallback=None):
    try:
        return fn()
    except Exception as error:
        return {
            "ok": False,
            "source": name,
            "error": repr(error),
            **(fallback or {}),
        }


# === S8.56 Admin Ops Storage Table Counts Repair =============================
def _s856_safe_table_identifier(table: Any) -> str | None:
    value = str(table or "").strip()
    if not value:
        return None
    if not all(ch.isalnum() or ch == "_" for ch in value):
        return None
    return value


def _s837a_db_table_counts(con, tables):
    counts = {}
    for table in tables:
        safe_table = _s856_safe_table_identifier(table)
        if not safe_table:
            counts[str(table)] = {"error": "unsafe_table_name"}
            continue

        try:
            row = con.execute(f'SELECT COUNT(*) AS c FROM "{safe_table}"').fetchone()
            if row is None:
                counts[safe_table] = 0
                continue

            try:
                counts[safe_table] = int(row["c"])
            except Exception:
                counts[safe_table] = int(row[0])
        except Exception as error:
            counts[safe_table] = {"error": repr(error)}
    return counts


def _s837a_systemd_units():
    import subprocess

    wanted = [
        "skilledge-stock-engine-api.service",
        "skilledge-daily-ai-desk.service",
        "skilledge-telegram-consumer.service",
        "skilledge-clean-elite-capture.timer",
        "skilledge-engine-watchdog.timer",
        "skilledge-nightly-self-learning.timer",
        "skilledge-post-close-evidence.timer",
        "skilledge-production-readiness.timer",
    ]

    units = []
    for unit in wanted:
        try:
            active = subprocess.run(
                ["systemctl", "is-active", unit],
                text=True,
                capture_output=True,
                timeout=4,
            )
            enabled = subprocess.run(
                ["systemctl", "is-enabled", unit],
                text=True,
                capture_output=True,
                timeout=4,
            )
            units.append({
                "unit": unit,
                "active": active.stdout.strip() or active.stderr.strip(),
                "enabled": enabled.stdout.strip() or enabled.stderr.strip(),
                "ok": active.returncode == 0 and (active.stdout.strip() in {"active"}),
            })
        except FileNotFoundError:
            units.append({
                "unit": unit,
                "active": "systemctl_not_available",
                "enabled": "unknown",
                "ok": None,
            })
        except Exception as error:
            units.append({
                "unit": unit,
                "active": "error",
                "enabled": "unknown",
                "ok": False,
                "error": repr(error),
            })

    return {
        "ok": all(x.get("ok") is True for x in units if x.get("ok") is not None),
        "items": units,
        "activeCount": len([x for x in units if x.get("active") == "active"]),
        "checkedCount": len(units),
    }



# === S8.55B Admin Ops Timer Run Health =======================================
def _s855b_systemd_show(unit: str, properties: list[str]) -> dict[str, Any]:
    import subprocess

    cmd = ["systemctl", "show", unit]
    for prop in properties:
        cmd.extend(["-p", prop])

    try:
        result = subprocess.run(
            cmd,
            text=True,
            capture_output=True,
            timeout=5,
        )
        data = {}
        for line in (result.stdout or "").splitlines():
            if "=" in line:
                key, value = line.split("=", 1)
                data[key] = value or None
        return {
            "ok": result.returncode == 0,
            "unit": unit,
            "returnCode": result.returncode,
            "data": data,
            "stderr": (result.stderr or "").strip() or None,
        }
    except Exception as error:
        return {
            "ok": False,
            "unit": unit,
            "error": repr(error),
            "data": {},
        }


def _s855b_admin_timer_run_health() -> dict[str, Any]:
    timer_props = [
        "ActiveState",
        "SubState",
        "UnitFileState",
        "NextElapseUSecRealtime",
        "LastTriggerUSec",
        "Result",
    ]
    service_props = [
        "ActiveState",
        "SubState",
        "Result",
        "ExecMainCode",
        "ExecMainStatus",
        "ActiveEnterTimestamp",
        "InactiveEnterTimestamp",
    ]

    targets = [
        {
            "key": "postCloseEvidence",
            "timer": "skilledge-post-close-evidence.timer",
            "service": "skilledge-post-close-evidence.service",
            "expectedCadence": "DAILY_POST_CLOSE",
            "expectedRunKyiv": "23:12 Kyiv",
        },
        {
            "key": "nightlySelfLearning",
            "timer": "skilledge-nightly-self-learning.timer",
            "service": "skilledge-nightly-self-learning.service",
            "expectedCadence": "DAILY_NIGHTLY_LEARNING",
            "expectedRunKyiv": "23:35 Kyiv",
        },
        {
            "key": "engineWatchdog",
            "timer": "skilledge-engine-watchdog.timer",
            "service": "skilledge-engine-watchdog.service",
            "expectedCadence": "EVERY_5_MINUTES",
            "expectedRunKyiv": "every 5 minutes",
        },
        {
            "key": "productionReadiness",
            "timer": "skilledge-production-readiness.timer",
            "service": "skilledge-production-readiness.service",
            "expectedCadence": "DAILY_READINESS",
            "expectedRunKyiv": "systemd timer schedule",
        },
    ]

    items = []
    for target in targets:
        timer_show = _s855b_systemd_show(target["timer"], timer_props)
        service_show = _s855b_systemd_show(target["service"], service_props)

        timer_data = timer_show.get("data") if isinstance(timer_show.get("data"), dict) else {}
        service_data = service_show.get("data") if isinstance(service_show.get("data"), dict) else {}

        timer_active = timer_data.get("ActiveState")
        service_result = service_data.get("Result")
        exec_status = service_data.get("ExecMainStatus")

        timer_ok = timer_show.get("ok") is True and timer_active == "active"
        last_service_ok = service_show.get("ok") is True and service_result in {None, "success"} and exec_status in {None, "0"}

        items.append({
            "key": target["key"],
            "timer": target["timer"],
            "service": target["service"],
            "ok": timer_ok and last_service_ok,
            "timerOk": timer_ok,
            "lastServiceOk": last_service_ok,
            "timerActiveState": timer_active,
            "timerSubState": timer_data.get("SubState"),
            "timerUnitFileState": timer_data.get("UnitFileState"),
            "nextRun": timer_data.get("NextElapseUSecRealtime"),
            "lastTrigger": timer_data.get("LastTriggerUSec"),
            "serviceActiveState": service_data.get("ActiveState"),
            "serviceSubState": service_data.get("SubState"),
            "serviceResult": service_result,
            "serviceExecMainStatus": exec_status,
            "serviceStartedAt": service_data.get("ActiveEnterTimestamp"),
            "serviceFinishedAt": service_data.get("InactiveEnterTimestamp"),
            "expectedCadence": target["expectedCadence"],
            "expectedRunKyiv": target["expectedRunKyiv"],
        })

    failed = [item for item in items if item.get("ok") is False]

    return {
        "ok": len(failed) == 0,
        "storageVersion": "s8_55b_admin_timer_run_health_v1",
        "checkedCount": len(items),
        "failedCount": len(failed),
        "items": items,
        "failed": failed,
        "policySummary": {
            "readOnly": True,
            "visibilityOnly": True,
            "usesSystemdShow": True,
            "sendsTelegram": False,
            "changesTimers": False,
            "changesServices": False,
            "changesClientDelivery": False,
        },
    }


def _s837a_latest_report_file(path_text):
    from pathlib import Path
    try:
        path = Path(path_text)
        if not path.exists():
            return {"exists": False, "path": str(path)}
        stat = path.stat()
        return {
            "exists": True,
            "path": str(path),
            "sizeBytes": int(stat.st_size),
            "modifiedAt": datetime.fromtimestamp(stat.st_mtime, timezone.utc).isoformat(),
        }
    except Exception as error:
        return {"exists": False, "path": path_text, "error": repr(error)}


# === S8.57 Admin Ops Status Level Upgrade ====================================
def _s857_summary_bool(summary: dict[str, Any], key: str, default: bool | None = None) -> bool | None:
    value = summary.get(key) if isinstance(summary, dict) else default
    if isinstance(value, bool):
        return value
    if value is None:
        return default
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in {"true", "1", "yes", "ok", "fresh"}:
            return True
        if lowered in {"false", "0", "no", "fail", "failed", "stale", "missing"}:
            return False
    return bool(value)


def _s857_summary_int(summary: dict[str, Any], key: str, default: int = 0) -> int:
    value = summary.get(key) if isinstance(summary, dict) else default
    try:
        return int(value or default)
    except Exception:
        return default


def _s857_freshness_bad(summary: dict[str, Any], key: str) -> bool:
    value = summary.get(key) if isinstance(summary, dict) else None
    if value is None:
        return False
    return str(value).strip().upper() not in {"FRESH", "OK"}


def _s837a_status_level(summary):
    if not isinstance(summary, dict):
        return "ADMIN_STATUS_SUMMARY_INVALID"

    if _s857_summary_bool(summary, "engineOk") is not True:
        return "CRITICAL_ENGINE_DOWN"

    if _s857_summary_bool(summary, "dbReadOk") is False:
        return "DB_STORAGE_ATTENTION_REQUIRED"

    if _s857_summary_bool(summary, "systemdOk") is False or _s857_summary_int(summary, "systemdInactiveCount") > 0:
        return "SYSTEMD_ATTENTION_REQUIRED"

    if _s857_summary_bool(summary, "timerRunOk") is False or _s857_summary_int(summary, "timerRunFailedCount") > 0:
        return "TIMER_RUN_ATTENTION_REQUIRED"

    if _s857_summary_int(summary, "dirtyOutcomePipelines") > 0:
        return "OUTCOME_PIPELINE_REPAIR_REQUIRED"

    if _s857_summary_int(summary, "approvalTableMissing") > 0:
        return "ADMIN_APPROVAL_TABLE_MISSING"

    if _s857_summary_bool(summary, "nightlyOk") is False or _s857_summary_int(summary, "nightlyFailedSteps") > 0:
        return "NIGHTLY_LEARNING_ATTENTION_REQUIRED"

    if _s857_summary_bool(summary, "postCloseOk") is False:
        return "POST_CLOSE_ATTENTION_REQUIRED"

    post_close_status = str(summary.get("postCloseStatus") or "").strip().upper()
    if post_close_status and post_close_status not in {"OK", "NO_TRADE_NO_BEST_IDEA"}:
        return "POST_CLOSE_ATTENTION_REQUIRED"

    if _s857_freshness_bad(summary, "postCloseFreshnessStatus"):
        return "REPORT_FRESHNESS_ATTENTION_REQUIRED"

    if _s857_freshness_bad(summary, "telegramGateFreshnessStatus"):
        return "REPORT_FRESHNESS_ATTENTION_REQUIRED"

    return "OPERATIONAL_WITH_GUARDS"




# === S8.52 Telegram Gate Split Freshness Guard ================================
def _s852_telegram_gate_split_freshness(report: dict[str, Any], max_fresh_minutes: int = 720) -> dict[str, Any]:
    from datetime import datetime, timezone

    checked_at = datetime.now(timezone.utc)
    generated_at_raw = report.get("generatedAt") if isinstance(report, dict) else None

    result = {
        "checkedAt": checked_at.isoformat(),
        "generatedAt": generated_at_raw,
        "ageMinutes": None,
        "maxFreshMinutes": int(max_fresh_minutes),
        "isFresh": False,
        "freshnessStatus": "MISSING",
    }

    if not generated_at_raw:
        return result

    try:
        generated_text = str(generated_at_raw).strip()
        if generated_text.endswith("Z"):
            generated_text = generated_text[:-1] + "+00:00"

        generated_at = datetime.fromisoformat(generated_text)
        if generated_at.tzinfo is None:
            generated_at = generated_at.replace(tzinfo=timezone.utc)

        age_minutes = max(
            0.0,
            (checked_at - generated_at.astimezone(timezone.utc)).total_seconds() / 60.0,
        )
        is_fresh = age_minutes <= float(max_fresh_minutes)

        result.update({
            "ageMinutes": round(age_minutes, 2),
            "isFresh": bool(is_fresh),
            "freshnessStatus": "FRESH" if is_fresh else "STALE",
        })
        return result
    except Exception as error:
        result.update({
            "freshnessStatus": "INVALID_TIMESTAMP",
            "error": repr(error),
        })
        return result



# === S8.55 Daily Report Freshness Policy =====================================
S855_DAILY_REPORT_MAX_FRESH_MINUTES = 1500  # 25h: daily post-close reports refresh once per evening
S855_DAILY_REPORT_FRESHNESS_POLICY = "DAILY_25H"
S855_POST_CLOSE_EXPECTED_CADENCE = "DAILY_POST_CLOSE"
S855_POST_CLOSE_EXPECTED_RUN_KYIV = "23:12 Kyiv"
S855_TELEGRAM_GATE_EXPECTED_CADENCE = "DAILY_POST_CLOSE_EXECSTARTPOST"
S855_TELEGRAM_GATE_EXPECTED_RUN_KYIV = "after 23:12 Kyiv post-close"


# === S8.53/S8.54 Post-Close Chain Health Visibility ===========================
def _s853_build_post_close_chain_health(report: dict[str, Any], max_fresh_minutes: int = 720) -> dict[str, Any]:
    summary = report.get("summary") if isinstance(report, dict) and isinstance(report.get("summary"), dict) else {}
    freshness = _s852_telegram_gate_split_freshness(report, max_fresh_minutes=max_fresh_minutes)

    has_report = bool(report) and isinstance(report, dict)
    report_ok = bool(report.get("ok")) if has_report else False

    if not has_report:
        status = "MISSING"
    elif freshness.get("freshnessStatus") == "STALE":
        status = "STALE"
    elif freshness.get("freshnessStatus") == "INVALID_TIMESTAMP":
        status = "INVALID_TIMESTAMP"
    elif report_ok:
        status = "OK"
    else:
        status = "FAILED"

    return {
        "ok": report_ok,
        "postCloseStatus": status,
        "version": report.get("version") if has_report else None,
        "generatedAt": report.get("generatedAt") if has_report else None,
        "freshnessStatus": freshness.get("freshnessStatus"),
        "isFresh": freshness.get("isFresh"),
        "ageMinutes": freshness.get("ageMinutes"),
        "maxFreshMinutes": freshness.get("maxFreshMinutes"),
        "forwardState": summary.get("forwardState"),
        "forwardSelectedBestCount": summary.get("forwardSelectedBestCount"),
        "healthOk": summary.get("healthOk"),
        "outcomesOk": summary.get("outcomesOk"),
        "forwardReportOk": summary.get("forwardReportOk"),
        "cleanEliteStatsOk": summary.get("cleanEliteStatsOk"),
        "cleanEliteStatsEffectiveOk": summary.get("cleanEliteStatsEffectiveOk"),
        "evidenceOk": summary.get("evidenceOk"),
        "evidenceEffectiveOk": summary.get("evidenceEffectiveOk"),
        "postCloseNoTradeNonFatal": summary.get("postCloseNoTradeNonFatal"),
        "nightCalibrationOk": summary.get("nightCalibrationOk"),
        "nightCalibrationNonFatal": summary.get("nightCalibrationNonFatal"),
        "policySummary": {
            "readOnly": True,
            "visibilityOnly": True,
            "sendsTelegram": False,
            "changesTelegramGate": False,
            "changesClientDelivery": False,
            "changesPostCloseAutomation": False,
            "freshnessGuardEnabled": True,
            "maxFreshMinutes": freshness.get("maxFreshMinutes"),
            "freshnessPolicy": S855_DAILY_REPORT_FRESHNESS_POLICY,
            "expectedCadence": S855_POST_CLOSE_EXPECTED_CADENCE,
            "expectedRunKyiv": S855_POST_CLOSE_EXPECTED_RUN_KYIV,
        },
    }


