# === S8.39A Strategy Manual Approval Storage ===
S839A_MANUAL_APPROVAL_STORAGE_VERSION = "s8_39a_strategy_manual_approval_storage_v1"

S839A_ALLOWED_APPROVAL_STATUSES = {
    "PENDING",
    "APPROVED",
    "CLIENT_VISIBLE_APPROVED",
    "REJECTED",
    "REVOKED",
}


def _s839a_now():
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).isoformat()


def _s839a_bool(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() in {"1", "true", "yes", "y", "approved", "client_visible", "enabled"}


def _s839a_text(value, fallback=""):
    text = str(value or "").strip()
    return text if text else fallback


def _s839a_ensure_manual_approval_table(con):
    con.execute(
        """
        create table if not exists strategy_manual_approvals (
            approval_id text primary key,
            setup_slug text not null,
            status text not null,
            approved integer default 0,
            client_visible integer default 0,
            reviewed_by text,
            reason text,
            notes text,
            source text,
            created_at text not null,
            updated_at text not null,
            payload_json text not null
        )
        """
    )
    con.execute(
        """
        create index if not exists idx_strategy_manual_approvals_setup_updated
        on strategy_manual_approvals(setup_slug, updated_at desc)
        """
    )
    con.execute(
        """
        create index if not exists idx_strategy_manual_approvals_status
        on strategy_manual_approvals(status)
        """
    )


def _s839a_registry_setup_exists(con, setup_slug):
    row = con.execute(
        "select setup_slug, setup_name, enabled, execution_status from algorithm_registry where setup_slug=?",
        (setup_slug,),
    ).fetchone()
    return dict(row) if row else None


def _s839a_latest_manual_approval_rows(con, limit):
    _s839a_ensure_manual_approval_table(con)
    rows = con.execute(
        """
        select *
        from strategy_manual_approvals
        order by updated_at desc
        limit ?
        """,
        (int(limit or 100),),
    ).fetchall()

    return [dict(row) for row in rows]


def _s839a_latest_by_setup(con):
    _s839a_ensure_manual_approval_table(con)
    rows = con.execute(
        """
        select a.*
        from strategy_manual_approvals a
        join (
            select setup_slug, max(updated_at) as max_updated_at
            from strategy_manual_approvals
            group by setup_slug
        ) latest
          on latest.setup_slug = a.setup_slug
         and latest.max_updated_at = a.updated_at
        order by a.updated_at desc
        """
    ).fetchall()
    return {row["setup_slug"]: dict(row) for row in rows}


@app.get("/engine/strategies/manual-approvals")
def engine_strategies_manual_approvals(limit: int = 100):
    import sqlite3
    import json
    from datetime import datetime, timezone

    safe_limit = max(1, min(int(limit or 100), 300))

    con = sqlite3.connect(_s832a2_db_path())
    con.row_factory = sqlite3.Row
    _s839a_ensure_manual_approval_table(con)
    con.commit()

    latest_by_setup = _s839a_latest_by_setup(con)
    rows = _s839a_latest_manual_approval_rows(con, safe_limit)

    registry_total = int(con.execute("select count(*) as c from algorithm_registry").fetchone()["c"])
    total_records = int(con.execute("select count(*) as c from strategy_manual_approvals").fetchone()["c"])

    by_status = {}
    approved_count = 0
    client_visible_count = 0

    for row in latest_by_setup.values():
        status = str(row.get("status") or "UNKNOWN").upper()
        by_status[status] = by_status.get(status, 0) + 1
        if int(row.get("approved") or 0) == 1:
            approved_count += 1
        if int(row.get("client_visible") or 0) == 1:
            client_visible_count += 1

    items = []
    for row in rows:
        setup = _s839a_registry_setup_exists(con, row.get("setup_slug")) or {}
        payload = {}
        try:
            payload = json.loads(row.get("payload_json") or "{}")
        except Exception:
            payload = {}

        items.append({
            "approvalId": row.get("approval_id"),
            "setupSlug": row.get("setup_slug"),
            "setupName": setup.get("setup_name"),
            "status": row.get("status"),
            "approved": bool(row.get("approved")),
            "clientVisibleApproved": bool(row.get("client_visible")) and bool(row.get("approved")),
            "reviewedBy": row.get("reviewed_by"),
            "reason": row.get("reason"),
            "notes": row.get("notes"),
            "source": row.get("source"),
            "createdAt": row.get("created_at"),
            "updatedAt": row.get("updated_at"),
            "registry": {
                "exists": bool(setup),
                "enabled": bool(setup.get("enabled")) if setup else None,
                "executionStatus": setup.get("execution_status") if setup else None,
            },
            "payload": payload,
        })

    con.close()

    return {
        "ok": True,
        "storageVersion": S839A_MANUAL_APPROVAL_STORAGE_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "summary": {
            "approvalTableExists": True,
            "registryTotal": registry_total,
            "totalApprovalRecords": total_records,
            "setupsWithApprovalRecord": len(latest_by_setup),
            "latestApprovedSetups": approved_count,
            "latestClientVisibleApprovedSetups": client_visible_count,
            "byLatestStatus": by_status,
        },
        "policy": {
            "adminOnly": True,
            "writesDb": False,
            "sendsTelegram": False,
            "changesClientDelivery": False,
            "changesRegistry": False,
            "autoPromotesStrategies": False,
            "manualApprovalStorageOnly": True,
        },
        "items": items,
    }


@app.post("/engine/strategies/manual-approvals")
def engine_strategies_manual_approval_upsert(payload: dict):
    import json
    import sqlite3
    import uuid
    from datetime import datetime, timezone

    payload = payload if isinstance(payload, dict) else {}

    setup_slug = _s839a_text(payload.get("setupSlug") or payload.get("setup_slug"))
    if not setup_slug:
        return {
            "ok": False,
            "storageVersion": S839A_MANUAL_APPROVAL_STORAGE_VERSION,
            "error": "setupSlug is required",
        }

    requested_status = _s839a_text(payload.get("status"), "PENDING").upper()
    if requested_status not in S839A_ALLOWED_APPROVAL_STATUSES:
        return {
            "ok": False,
            "storageVersion": S839A_MANUAL_APPROVAL_STORAGE_VERSION,
            "error": f"Unsupported status: {requested_status}",
            "allowedStatuses": sorted(S839A_ALLOWED_APPROVAL_STATUSES),
        }

    requested_approved = _s839a_bool(payload.get("approved")) or requested_status in {
        "APPROVED",
        "CLIENT_VISIBLE_APPROVED",
    }

    requested_client_visible = (
        _s839a_bool(payload.get("clientVisible"))
        or _s839a_bool(payload.get("client_visible"))
        or requested_status == "CLIENT_VISIBLE_APPROVED"
    )

    # Safety: client-visible approval can never exist without approved=True.
    approved = bool(requested_approved)
    client_visible = bool(requested_client_visible and approved)

    if requested_status in {"REJECTED", "REVOKED", "PENDING"}:
        if requested_status != "PENDING":
            approved = False
            client_visible = False
        if requested_status == "PENDING" and not _s839a_bool(payload.get("approved")):
            approved = False
            client_visible = False

    reviewed_by = _s839a_text(payload.get("reviewedBy") or payload.get("reviewed_by"), "admin")
    reason = _s839a_text(payload.get("reason"), "")
    notes = _s839a_text(payload.get("notes"), "")
    source = _s839a_text(payload.get("source"), "admin_manual")

    now = _s839a_now()
    approval_id = _s839a_text(payload.get("approvalId") or payload.get("approval_id"), f"manual_approval:{setup_slug}:{now}:{uuid.uuid4().hex[:10]}")

    con = sqlite3.connect(_s832a2_db_path())
    con.row_factory = sqlite3.Row
    _s839a_ensure_manual_approval_table(con)

    setup = _s839a_registry_setup_exists(con, setup_slug)
    if not setup:
        con.close()
        return {
            "ok": False,
            "storageVersion": S839A_MANUAL_APPROVAL_STORAGE_VERSION,
            "error": "setupSlug does not exist in algorithm_registry",
            "setupSlug": setup_slug,
        }

    stored_payload = {
        "input": payload,
        "safety": {
            "clientVisibleRequiresApproved": True,
            "doesNotChangeClientDelivery": True,
            "doesNotChangeRegistry": True,
            "doesNotSendTelegram": True,
            "promotionGuardMustStillPassNumericAndPipelineGates": True,
        },
    }

    con.execute(
        """
        insert or replace into strategy_manual_approvals (
            approval_id, setup_slug, status, approved, client_visible, reviewed_by,
            reason, notes, source, created_at, updated_at, payload_json
        )
        values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            approval_id,
            setup_slug,
            requested_status,
            1 if approved else 0,
            1 if client_visible else 0,
            reviewed_by,
            reason,
            notes,
            source,
            now,
            now,
            json.dumps(stored_payload, ensure_ascii=False, sort_keys=True),
        ),
    )
    con.commit()

    row = con.execute(
        "select * from strategy_manual_approvals where approval_id=?",
        (approval_id,),
    ).fetchone()
    saved = dict(row) if row else {}
    con.close()

    return {
        "ok": True,
        "storageVersion": S839A_MANUAL_APPROVAL_STORAGE_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "saved": {
            "approvalId": saved.get("approval_id"),
            "setupSlug": saved.get("setup_slug"),
            "status": saved.get("status"),
            "approved": bool(saved.get("approved")),
            "clientVisibleApproved": bool(saved.get("client_visible")) and bool(saved.get("approved")),
            "reviewedBy": saved.get("reviewed_by"),
            "reason": saved.get("reason"),
            "notes": saved.get("notes"),
            "source": saved.get("source"),
            "createdAt": saved.get("created_at"),
            "updatedAt": saved.get("updated_at"),
        },
        "registry": {
            "setupName": setup.get("setup_name"),
            "enabled": bool(setup.get("enabled")),
            "executionStatus": setup.get("execution_status"),
        },
        "policy": {
            "adminOnly": True,
            "writesDb": True,
            "sendsTelegram": False,
            "changesClientDelivery": False,
            "changesRegistry": False,
            "autoPromotesStrategies": False,
            "manualApprovalStorageOnly": True,
        },
    }

# === /S8.39A Strategy Manual Approval Storage ===


# === S8.40A Outcome Pipeline Repair Planner ===
S840A_OUTCOME_REPAIR_PLANNER_VERSION = "s8_40a_outcome_pipeline_repair_planner_v1_1"


def _s840a_has_table(con, table_name):
    row = con.execute(
        "select name from sqlite_master where type='table' and name=?",
        (table_name,),
    ).fetchone()
    return bool(row)


def _s840a_columns(con, table_name):
    if not _s840a_has_table(con, table_name):
        return []
    rows = con.execute(f"pragma table_info({table_name})").fetchall()
    return [row["name"] for row in rows]


def _s840a_col(columns, *names):
    for name in names:
        if name in columns:
            return name
    return None


def _s840a_num(value, fallback=0.0):
    try:
        if value is None:
            return fallback
        return float(value)
    except Exception:
        return fallback


def _s840a_int(value, fallback=0):
    try:
        if value is None:
            return fallback
        return int(value)
    except Exception:
        return fallback


def _s840a_ratio(part, total):
    total = _s840a_num(total)
    if total <= 0:
        return 0.0
    return round((_s840a_num(part) / total) * 100.0, 2)


def _s840a_status_bucket(status):
    s = str(status or "").strip().upper()
    if s in {"WORKED", "TP1", "TP2", "TARGET", "TARGET_HIT", "WIN"}:
        return "worked"
    if s in {"FAILED", "STOP", "STOPPED", "STOP_HIT", "LOSS"}:
        return "failed"
    if s in {"SESSION_CLOSE", "EXPIRED", "EXPIRED_SESSION", "SESSION_EXPIRED", "TIMEOUT", "NO_DECISION"}:
        return "session_close"
    if s in {"OPEN", "ACTIVE", "PENDING", "UNKNOWN", ""}:
        return "open"
    return "other"


def _s840a_safe_query_value(row, key, fallback=None):
    try:
        return row[key]
    except Exception:
        return fallback


@app.get("/engine/outcomes/repair-plan")
def engine_outcomes_repair_plan(
    limit: int = 20,
    min_total: int = 1,
    dirty_open_ratio: float = 20.0,
    dirty_session_close_ratio: float = 20.0,
    include_samples: bool = True,
):
    import json
    import sqlite3
    from datetime import datetime, timezone

    safe_limit = max(1, min(int(limit or 20), 100))
    safe_min_total = max(1, int(min_total or 1))
    safe_dirty_open_ratio = max(0.0, float(dirty_open_ratio))
    safe_dirty_session_close_ratio = max(0.0, float(dirty_session_close_ratio))

    con = sqlite3.connect(_s832a2_db_path())
    con.row_factory = sqlite3.Row

    if not _s840a_has_table(con, "outcome_records"):
        con.close()
        return {
            "ok": False,
            "storageVersion": S840A_OUTCOME_REPAIR_PLANNER_VERSION,
            "error": "outcome_records table not found",
            "policy": {
                "readOnly": True,
                "writesDb": False,
                "changesClientDelivery": False,
                "sendsTelegram": False,
            },
        }

    outcome_columns = _s840a_columns(con, "outcome_records")
    signal_id_col = _s840a_col(outcome_columns, "signal_id", "id")
    setup_col = _s840a_col(outcome_columns, "setup_slug", "setup")
    symbol_col = _s840a_col(outcome_columns, "symbol", "ticker")
    status_col = _s840a_col(outcome_columns, "status", "result")
    session_date_col = _s840a_col(outcome_columns, "session_date", "date")
    trigger_time_col = _s840a_col(outcome_columns, "trigger_time", "created_at", "evaluated_at", "stored_at")
    payload_col = _s840a_col(outcome_columns, "payload_json", "payload")

    required_missing = [
        name for name, col in {
            "signal_id": signal_id_col,
            "setup_slug": setup_col,
            "status": status_col,
        }.items()
        if not col
    ]

    if required_missing:
        con.close()
        return {
            "ok": False,
            "storageVersion": S840A_OUTCOME_REPAIR_PLANNER_VERSION,
            "error": "outcome_records missing required columns",
            "missingColumns": required_missing,
            "actualColumns": outcome_columns,
            "policy": {
                "readOnly": True,
                "writesDb": False,
                "changesClientDelivery": False,
                "sendsTelegram": False,
            },
        }

    select_parts = [
        f"{setup_col} as setup_slug",
        "count(*) as total",
        f"sum(case when upper(coalesce({status_col}, '')) in ('WORKED','TP1','TP2','TARGET','TARGET_HIT','WIN') then 1 else 0 end) as worked",
        f"sum(case when upper(coalesce({status_col}, '')) in ('FAILED','STOP','STOPPED','STOP_HIT','LOSS') then 1 else 0 end) as failed",
        f"sum(case when upper(coalesce({status_col}, '')) in ('OPEN','ACTIVE','PENDING','UNKNOWN','') then 1 else 0 end) as open_count",
        f"sum(case when upper(coalesce({status_col}, '')) in ('SESSION_CLOSE','EXPIRED','EXPIRED_SESSION','SESSION_EXPIRED','TIMEOUT','NO_DECISION') then 1 else 0 end) as session_close_count",
        f"sum(case when upper(coalesce({status_col}, '')) not in ('WORKED','TP1','TP2','TARGET','TARGET_HIT','WIN','FAILED','STOP','STOPPED','STOP_HIT','LOSS','OPEN','ACTIVE','PENDING','UNKNOWN','','SESSION_CLOSE','EXPIRED','EXPIRED_SESSION','SESSION_EXPIRED','TIMEOUT','NO_DECISION') then 1 else 0 end) as other_count",
    ]

    if payload_col:
        select_parts.append(f"sum(case when {payload_col} is not null and length(trim({payload_col})) > 2 then 1 else 0 end) as rows_with_payload")
    else:
        select_parts.append("0 as rows_with_payload")

    if trigger_time_col:
        select_parts.append(f"sum(case when {trigger_time_col} is not null and length(trim({trigger_time_col})) > 0 then 1 else 0 end) as rows_with_trigger_time")
    else:
        select_parts.append("0 as rows_with_trigger_time")

    if session_date_col:
        select_parts.append(f"min({session_date_col}) as first_session_date")
        select_parts.append(f"max({session_date_col}) as latest_session_date")
    else:
        select_parts.append("null as first_session_date")
        select_parts.append("null as latest_session_date")

    rows = con.execute(
        f"""
        select
            {", ".join(select_parts)}
        from outcome_records
        where {setup_col} is not null and trim({setup_col}) != ''
        group by {setup_col}
        having count(*) >= ?
        order by
            (sum(case when upper(coalesce({status_col}, '')) in ('OPEN','ACTIVE','PENDING','UNKNOWN','') then 1 else 0 end)
            + sum(case when upper(coalesce({status_col}, '')) in ('SESSION_CLOSE','EXPIRED','EXPIRED_SESSION','SESSION_EXPIRED','TIMEOUT','NO_DECISION') then 1 else 0 end)) desc,
            count(*) desc
        limit ?
        """,
        (safe_min_total, safe_limit),
    ).fetchall()

    total_outcomes = int(con.execute("select count(*) as c from outcome_records").fetchone()["c"])
    total_by_status_rows = con.execute(
        f"""
        select upper(coalesce({status_col}, 'UNKNOWN')) as status, count(*) as c
        from outcome_records
        group by upper(coalesce({status_col}, 'UNKNOWN'))
        order by c desc
        """
    ).fetchall()
    total_by_status = {str(row["status"] or "UNKNOWN"): int(row["c"] or 0) for row in total_by_status_rows}

    persisted_signal_table_exists = _s840a_has_table(con, "persisted_signal_records")
    signal_columns = _s840a_columns(con, "persisted_signal_records") if persisted_signal_table_exists else []
    signal_id_signal_col = _s840a_col(signal_columns, "signal_id", "id") if signal_columns else None

    items = []
    dirty_count = 0
    repair_candidate_total = 0
    not_repairable_total = 0

    for row in rows:
        total = _s840a_int(row["total"])
        worked = _s840a_int(row["worked"])
        failed = _s840a_int(row["failed"])
        open_count = _s840a_int(row["open_count"])
        session_close_count = _s840a_int(row["session_close_count"])
        other_count = _s840a_int(row["other_count"])
        closed = worked + failed
        dirty_total = open_count
        open_ratio = _s840a_ratio(open_count, total)
        session_close_ratio = _s840a_ratio(session_close_count, total)
        dirty_ratio = _s840a_ratio(dirty_total, total)
        rows_with_payload = _s840a_int(row["rows_with_payload"])
        rows_with_trigger_time = _s840a_int(row["rows_with_trigger_time"])

        is_dirty = open_ratio >= safe_dirty_open_ratio
        if is_dirty:
            dirty_count += 1

        repairable_score = 0
        if rows_with_payload > 0:
            repairable_score += 1
        if rows_with_trigger_time > 0:
            repairable_score += 1
        if persisted_signal_table_exists and signal_id_signal_col:
            repairable_score += 1

        if dirty_total <= 0:
            repair_mode = "NO_REPAIR_NEEDED"
        elif repairable_score >= 2:
            repair_mode = "REPLAY_FROM_SIGNAL_PAYLOAD_AND_CANDLES"
        elif repairable_score == 1:
            repair_mode = "PARTIAL_REPLAY_REQUIRES_PAYLOAD_AUDIT"
        else:
            repair_mode = "NOT_REPAIRABLE_WITH_CURRENT_DATA"

        if repair_mode in {"REPLAY_FROM_SIGNAL_PAYLOAD_AND_CANDLES", "PARTIAL_REPLAY_REQUIRES_PAYLOAD_AUDIT"}:
            repair_candidate_total += dirty_total
        elif dirty_total > 0:
            not_repairable_total += dirty_total

        warnings = []
        if open_ratio >= safe_dirty_open_ratio:
            warnings.append("High OPEN ratio. Replay completeness must be checked.")
        if session_close_ratio >= safe_dirty_session_close_ratio:
            warnings.append("High SESSION_CLOSE/EXPIRED ratio. These rows are evidence-quality gaps, not pipeline-repair rows, and must not be treated as wins/losses.")
        if closed <= 0:
            warnings.append("No closed TP/STOP decisions for this setup.")
        if repair_mode == "NOT_REPAIRABLE_WITH_CURRENT_DATA":
            warnings.append("Current stored rows do not expose enough payload/trigger data for safe replay.")

        samples = []
        if include_samples and is_dirty:
            sample_rows = con.execute(
                f"""
                select *
                from outcome_records
                where {setup_col}=?
                  and upper(coalesce({status_col}, '')) in ('OPEN','ACTIVE','PENDING','UNKNOWN','','SESSION_CLOSE','EXPIRED','EXPIRED_SESSION','SESSION_EXPIRED','TIMEOUT','NO_DECISION')
                order by coalesce({trigger_time_col if trigger_time_col else signal_id_col}, '') desc
                limit 5
                """,
                (row["setup_slug"],),
            ).fetchall()

            for sample in sample_rows:
                payload = {}
                if payload_col:
                    try:
                        payload = json.loads(sample[payload_col] or "{}")
                    except Exception:
                        payload = {}

                samples.append({
                    "signalId": _s840a_safe_query_value(sample, signal_id_col),
                    "symbol": _s840a_safe_query_value(sample, symbol_col) if symbol_col else None,
                    "setupSlug": _s840a_safe_query_value(sample, setup_col),
                    "status": _s840a_safe_query_value(sample, status_col),
                    "sessionDate": _s840a_safe_query_value(sample, session_date_col) if session_date_col else None,
                    "triggerTime": _s840a_safe_query_value(sample, trigger_time_col) if trigger_time_col else None,
                    "hasPayload": bool(payload),
                    "payloadKeys": sorted(list(payload.keys()))[:20] if isinstance(payload, dict) else [],
                })

        items.append({
            "setupSlug": row["setup_slug"],
            "totalOutcomes": total,
            "worked": worked,
            "failed": failed,
            "closedTpStop": closed,
            "open": open_count,
            "sessionCloseOrExpired": session_close_count,
            "other": other_count,
            "dirtyRows": dirty_total,
            "openRatioPct": open_ratio,
            "sessionCloseRatioPct": session_close_ratio,
            "dirtyRatioPct": dirty_ratio,
            "firstSessionDate": row["first_session_date"],
            "latestSessionDate": row["latest_session_date"],
            "rowsWithPayload": rows_with_payload,
            "rowsWithTriggerTime": rows_with_trigger_time,
            "repairMode": repair_mode,
            "isDirtyPipeline": is_dirty,
            "warnings": warnings,
            "sampleDirtyRows": samples,
        })

    con.close()

    return {
        "ok": True,
        "storageVersion": S840A_OUTCOME_REPAIR_PLANNER_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "summary": {
            "totalOutcomes": total_outcomes,
            "returnedSetups": len(items),
            "dirtySetupsReturned": dirty_count,
            "dirtyRowsInReturnedSetups": sum(int(item["dirtyRows"]) for item in items),
            "repairCandidateRowsInReturnedSetups": repair_candidate_total,
            "notRepairableRowsInReturnedSetups": not_repairable_total,
            "thresholds": {
                "minTotal": safe_min_total,
                "dirtyOpenRatioPct": safe_dirty_open_ratio,
                "dirtySessionCloseRatioPct": safe_dirty_session_close_ratio,
            },
            "tables": {
                "outcomeRecords": True,
                "persistedSignalRecords": persisted_signal_table_exists,
            },
            "totalByStatus": total_by_status,
        },
        "policy": {
            "readOnly": True,
            "writesDb": False,
            "changesOutcomes": False,
            "changesClientDelivery": False,
            "sendsTelegram": False,
            "autoPromotesStrategies": False,
            "plannerOnly": True,
        },
        "nextAllowedStep": "Build controlled repair executor only after this plan confirms replayable rows and safe backup strategy.",
        "items": items,
    }

# === /S8.40A Outcome Pipeline Repair Planner ===



# === S8.40B Outcome OPEN Replay Probe ===
S840B_OUTCOME_OPEN_REPLAY_PROBE_VERSION = "s8_40b_outcome_open_replay_probe_v1"


def _s840b_upper(value):
    return str(value or "").strip().upper()


def _s840b_result_bucket(result):
    raw = _s840b_upper(result)
    if raw.startswith("WORKED"):
        return "worked"
    if raw.startswith("FAILED") or raw in {"STOP_HIT", "AMBIGUOUS_STOP_FIRST"}:
        return "failed"
    if raw in {"SESSION_CLOSE", "EXPIRED_SESSION"}:
        return "sessionClose"
    if raw.startswith("INVALID"):
        return "invalid"
    if raw in {"OPEN", "ACTIVE", "PENDING", "UNKNOWN", ""}:
        return "open"
    return "other"


def _s840b_load_dirty_open_outcome_rows(setup_slug=None, symbol=None, session_date=None, limit=10):
    import sqlite3

    safe_limit = max(1, min(int(limit or 10), 50))

    where = ["upper(coalesce(status,'')) = 'OPEN'"]
    params = []

    if setup_slug:
        where.append("setup_slug = ?")
        params.append(str(setup_slug).strip())

    if symbol:
        where.append("upper(symbol) = upper(?)")
        params.append(str(symbol).strip())

    if session_date:
        where.append("session_date = ?")
        params.append(str(session_date).strip()[:10])

    sql = """
        select signal_id, symbol, setup_slug, session_date, status, result_r, mfe_r, mae_r,
               trigger_time, evaluated_at, stored_at, payload_json
        from outcome_records
        where {where_sql}
        order by stored_at desc
        limit ?
    """.format(where_sql=" and ".join(where))

    params.append(safe_limit)

    con = sqlite3.connect(_s832a2_db_path())
    con.row_factory = sqlite3.Row
    rows = [dict(row) for row in con.execute(sql, params).fetchall()]
    con.close()

    return rows


@app.get("/engine/outcomes/repair-probe")
async def engine_outcomes_repair_probe(
    setup_slug: str | None = None,
    symbol: str | None = None,
    session_date: str | None = None,
    limit: int = 10,
):
    import json
    from datetime import datetime, timezone

    safe_limit = max(1, min(int(limit or 10), 50))
    rows = _s840b_load_dirty_open_outcome_rows(
        setup_slug=setup_slug,
        symbol=symbol,
        session_date=session_date,
        limit=safe_limit,
    )

    summary = {
        "dirtyOpenRowsLoaded": len(rows),
        "probed": 0,
        "replayOk": 0,
        "worked": 0,
        "failed": 0,
        "sessionClose": 0,
        "invalid": 0,
        "open": 0,
        "other": 0,
        "errors": 0,
        "signalNotFound": 0,
        "missingRequiredFields": 0,
        "futureRowsZero": 0,
        "wouldBecomeClosedTpStop": 0,
        "wouldRemainSessionClose": 0,
        "bySetup": {},
    }

    results = []

    for row in rows:
        signal_id = str(row.get("signal_id") or "").strip()
        setup_key = str(row.get("setup_slug") or "unknown")
        summary["bySetup"].setdefault(setup_key, {
            "rows": 0,
            "replayOk": 0,
            "worked": 0,
            "failed": 0,
            "sessionClose": 0,
            "invalid": 0,
            "errors": 0,
            "signalNotFound": 0,
            "missingRequiredFields": 0,
        })
        summary["bySetup"][setup_key]["rows"] += 1

        try:
            probe = await engine_research_signal_replay_dry_run(signal_id=signal_id)
            summary["probed"] += 1

            if not isinstance(probe, dict):
                summary["errors"] += 1
                summary["bySetup"][setup_key]["errors"] += 1
                results.append({
                    "signalId": signal_id,
                    "ok": False,
                    "error": "probe_returned_non_dict",
                    "sourceOutcome": {
                        "symbol": row.get("symbol"),
                        "setupSlug": row.get("setup_slug"),
                        "sessionDate": row.get("session_date"),
                        "status": row.get("status"),
                        "triggerTime": row.get("trigger_time"),
                    },
                })
                continue

            if probe.get("error") == "signal_not_found":
                summary["signalNotFound"] += 1
                summary["bySetup"][setup_key]["signalNotFound"] += 1

            if probe.get("error") == "missing_required_signal_fields":
                summary["missingRequiredFields"] += 1
                summary["bySetup"][setup_key]["missingRequiredFields"] += 1

            candles = probe.get("candles") if isinstance(probe.get("candles"), dict) else {}
            future_rows = int(candles.get("futureRowsAfterTrigger") or 0) if isinstance(candles, dict) else 0
            if future_rows <= 0:
                summary["futureRowsZero"] += 1

            outcome = probe.get("dryRunOutcome") if isinstance(probe.get("dryRunOutcome"), dict) else {}
            result = outcome.get("result") if isinstance(outcome, dict) else None
            bucket = _s840b_result_bucket(result)

            if probe.get("ok") and outcome.get("ok"):
                summary["replayOk"] += 1
                summary["bySetup"][setup_key]["replayOk"] += 1

            if bucket in {"worked", "failed", "sessionClose", "invalid", "open", "other"}:
                summary[bucket] += 1
                if bucket in summary["bySetup"][setup_key]:
                    summary["bySetup"][setup_key][bucket] += 1

            if bucket in {"worked", "failed"}:
                summary["wouldBecomeClosedTpStop"] += 1
            elif bucket == "sessionClose":
                summary["wouldRemainSessionClose"] += 1

            payload = {}
            try:
                payload = json.loads(row.get("payload_json") or "{}")
            except Exception:
                payload = {}

            results.append({
                "signalId": signal_id,
                "ok": bool(probe.get("ok")),
                "error": probe.get("error"),
                "sourceOutcome": {
                    "symbol": row.get("symbol"),
                    "setupSlug": row.get("setup_slug"),
                    "sessionDate": row.get("session_date"),
                    "status": row.get("status"),
                    "resultR": row.get("result_r"),
                    "mfeR": row.get("mfe_r"),
                    "maeR": row.get("mae_r"),
                    "triggerTime": row.get("trigger_time"),
                    "storedAt": row.get("stored_at"),
                    "payloadHasEntry": payload.get("entry") is not None,
                    "payloadHasStop": payload.get("stop") is not None,
                    "payloadHasTp1": payload.get("tp1") is not None or bool(payload.get("targets")),
                    "payloadKeys": sorted(list(payload.keys()))[:30] if isinstance(payload, dict) else [],
                },
                "replaySignal": probe.get("signal"),
                "candles": probe.get("candles"),
                "validation": probe.get("validation"),
                "dryRunOutcome": outcome,
                "resultBucket": bucket,
                "wouldRepairTo": {
                    "status": "WORKED" if bucket == "worked" else "FAILED" if bucket == "failed" else "EXPIRED_SESSION" if bucket == "sessionClose" else "UNCHANGED",
                    "result": result,
                    "resultR": outcome.get("resultR") if isinstance(outcome, dict) else None,
                    "mfeR": outcome.get("mfeR") if isinstance(outcome, dict) else None,
                    "maeR": outcome.get("maeR") if isinstance(outcome, dict) else None,
                    "firstEvent": outcome.get("firstEvent") if isinstance(outcome, dict) else None,
                    "firstEventAt": outcome.get("firstEventAt") if isinstance(outcome, dict) else None,
                    "candlesChecked": outcome.get("candlesChecked") if isinstance(outcome, dict) else None,
                },
            })

        except Exception as error:
            summary["errors"] += 1
            summary["bySetup"][setup_key]["errors"] += 1
            results.append({
                "signalId": signal_id,
                "ok": False,
                "error": repr(error),
                "sourceOutcome": {
                    "symbol": row.get("symbol"),
                    "setupSlug": row.get("setup_slug"),
                    "sessionDate": row.get("session_date"),
                    "status": row.get("status"),
                    "triggerTime": row.get("trigger_time"),
                },
            })

    return {
        "ok": True,
        "storageVersion": S840B_OUTCOME_OPEN_REPLAY_PROBE_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "mode": "open_outcome_replay_probe_read_only",
        "filters": {
            "setupSlug": setup_slug,
            "symbol": symbol,
            "sessionDate": session_date,
            "limit": safe_limit,
        },
        "summary": summary,
        "policy": {
            "readOnly": True,
            "writesDb": False,
            "changesOutcomes": False,
            "changesClientDelivery": False,
            "sendsTelegram": False,
            "changesRegistry": False,
            "usesExistingSignalReplayDryRun": True,
            "probeOnly": True,
        },
        "nextAllowedStep": "If probe shows reliable WORKED/FAILED/SESSION_CLOSE rebuilds, build S8.40C controlled executor with backup table, setup filter, dryRun default and confirm=true writes.",
        "results": results,
    }

