# === S8.64 Unified SkillEdge AI Signal Output ================================
S864_UNIFIED_SKILLEDGE_OUTPUT_VERSION = "s8_64_unified_skilledge_ai_signal_output_v1"


def _s864_report_dir():
    from pathlib import Path
    return Path("/opt/skilledge/stock-engine/reports/unified_skilledge_output")


def _s864_db_path():
    return "/opt/skilledge/stock-engine/data/stock_engine.db"


def _s864_read_json_report(path):
    import json
    from pathlib import Path

    p = Path(path)
    if not p.exists():
        return {}
    try:
        return json.loads(p.read_text(encoding="utf-8"))
    except Exception as error:
        return {"ok": False, "error": repr(error), "path": str(p)}


def _s864_json_loads(value):
    import json

    if isinstance(value, dict):
        return value
    if not value:
        return {}
    try:
        data = json.loads(value)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _s864_to_float(value, fallback=None):
    try:
        if value is None or value == "":
            return fallback
        return float(value)
    except Exception:
        return fallback


def _s864_to_int(value, fallback=0):
    try:
        if value is None or value == "":
            return fallback
        return int(value)
    except Exception:
        return fallback


def _s864_bool(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    if isinstance(value, (int, float)):
        return bool(value)
    return str(value).strip().lower() in {"1", "true", "yes", "y", "approved", "ok"}


def _s864_arr(value):
    return value if isinstance(value, list) else []


def _s864_dict(value):
    return value if isinstance(value, dict) else {}


def _s864_pick(payload, *paths, fallback=None):
    for path in paths:
        cur = payload
        ok = True
        for part in str(path).split("."):
            if isinstance(cur, dict) and part in cur:
                cur = cur.get(part)
            else:
                ok = False
                break
        if ok and cur is not None:
            return cur
    return fallback


def _s864_extract_direction(signal_payload, row):
    direction = _s864_pick(
        signal_payload,
        "direction", "signal.direction", "setup.direction", "candidate.direction", "payload.direction",
        fallback=None,
    )
    if direction:
        return str(direction).upper()
    setup_slug = str(row.get("setup_slug") or "").lower()
    if "short" in setup_slug or "crap" in setup_slug or "rejection" in setup_slug or "breakdown" in setup_slug:
        return "SHORT"
    if "long" in setup_slug or "reclaim" in setup_slug or "breakout" in setup_slug or "continuation" in setup_slug:
        return "LONG"
    return "UNKNOWN"


def _s864_extract_price(signal_payload, *names):
    for name in names:
        value = _s864_pick(signal_payload, name, fallback=None)
        if value is not None:
            return _s864_to_float(value, None)
    return None


def _s864_extract_entry(signal_payload):
    direct = _s864_extract_price(
        signal_payload,
        "entry", "entryPrice", "signal.entry", "signal.entryPrice",
        "candidate.entry", "candidate.entryPrice", "payload.entry", "payload.entryPrice",
    )
    if direct is not None:
        return direct

    zone = _s864_pick(signal_payload, "entry_zone", "entryZone", "candidate.entry_zone", "candidate.entryZone", fallback=None)
    if isinstance(zone, dict):
        lo = _s864_to_float(zone.get("min"), None)
        hi = _s864_to_float(zone.get("max"), None)
        if lo is not None and hi is not None:
            return round((lo + hi) / 2.0, 4)
        return lo if lo is not None else hi

    return None


def _s864_extract_targets(signal_payload):
    targets = _s864_pick(signal_payload, "targets", "signal.targets", "candidate.targets", "payload.targets", fallback=[])
    out = []
    for target in _s864_arr(targets):
        if isinstance(target, dict):
            price = _s864_to_float(target.get("price") or target.get("target") or target.get("value"), None)
            r_value = _s864_to_float(target.get("r") or target.get("rr") or target.get("riskReward"), None)
            if price is not None or r_value is not None:
                out.append({"price": price, "r": r_value})
        else:
            price = _s864_to_float(target, None)
            if price is not None:
                out.append({"price": price, "r": None})
    return out[:4]


def _s864_extract_rr(signal_payload, row):
    for path in [
        "rr", "riskReward", "risk_reward", "riskRewardRatio", "signal.rr", "signal.riskReward",
        "candidate.rr", "candidate.riskReward", "payload.rr", "payload.riskReward",
    ]:
        value = _s864_pick(signal_payload, path, fallback=None)
        rr = _s864_to_float(value, None)
        if rr is not None:
            return rr

    targets = _s864_extract_targets(signal_payload)
    r_values = [_s864_to_float(t.get("r"), None) for t in targets if isinstance(t, dict)]
    r_values = [r for r in r_values if r is not None]
    if r_values:
        return max(r_values)

    entry = _s864_extract_entry(signal_payload)
    stop = _s864_extract_price(signal_payload, "stop", "stopPrice", "signal.stop", "candidate.stop", "payload.stop")
    if entry is not None and stop is not None and targets:
        first_target = _s864_to_float(targets[0].get("price"), None)
        if first_target is not None:
            risk = abs(entry - stop)
            reward = abs(entry - first_target)
            if risk > 0:
                return round(reward / risk, 2)
    return None


def _s864_fetch_recent_signals(limit=50):
    import sqlite3

    safe_limit = max(5, min(int(limit or 50), 500))
    con = sqlite3.connect(_s864_db_path())
    con.row_factory = sqlite3.Row

    rows = con.execute(
        """
        SELECT
            s.storage_key,
            s.signal_id,
            s.symbol,
            s.setup_slug,
            s.session_date,
            s.lifecycle_status,
            s.quality_status,
            s.signal_grade,
            s.signal_score,
            s.premium_signal,
            s.telegram_eligible,
            s.created_at,
            s.trigger_time,
            s.stored_at,
            s.updated_at,
            s.payload_json AS signal_payload_json,
            o.status AS outcome_status,
            o.result_r AS outcome_result_r,
            o.mfe_r AS outcome_mfe_r,
            o.mae_r AS outcome_mae_r,
            o.first_event AS outcome_first_event
        FROM signal_records s
        LEFT JOIN outcome_records o ON o.signal_id = s.signal_id
        ORDER BY COALESCE(s.updated_at, s.stored_at, s.trigger_time, s.created_at) DESC
        LIMIT ?
        """,
        (safe_limit,),
    ).fetchall()

    con.close()
    return [dict(row) for row in rows]


def _s864_manual_approval(signal_payload, row):
    signal_id = str(
        (row or {}).get("signal_id")
        or (row or {}).get("signalId")
        or _s864_pick(signal_payload, "signalId", "id", fallback="")
        or ""
    ).strip()

    if signal_id and "_s867_get_signal_manual_approval" in globals():
        manual_state = _s867_get_signal_manual_approval(signal_id)
        if isinstance(manual_state, dict):
            if manual_state.get("clientVisibleApproved") is True:
                return True
            if str(manual_state.get("status") or "").upper() in {"REJECTED", "BLOCKED", "REVOKED"}:
                return False

    approval = _s864_pick(
        signal_payload,
        "clientVisibleApproved", "manualApproval.clientVisibleApproved", "approval.clientVisibleApproved",
        "admin.clientVisibleApproved", "delivery.clientVisibleApproved",
        fallback=None,
    )
    if approval is not None:
        return _s864_bool(approval)

    approved_by = _s864_pick(signal_payload, "approvedByAdmin", "manualApproval.approved", "approval.approved", fallback=None)
    return _s864_bool(approved_by)

# === S8.69B Unified Eligibility Derivation Fix ===============================
S869B_UNIFIED_ELIGIBILITY_VERSION = "s8_69b_unified_eligibility_derivation_fix_v1"


def _s869b_payload_get(payload, *paths):
    if not isinstance(payload, dict):
        return None

    for path in paths:
        current = payload
        ok = True
        for part in str(path or "").split("."):
            if not part:
                continue
            if isinstance(current, dict) and part in current:
                current = current.get(part)
            else:
                ok = False
                break
        if ok and current is not None:
            return current

    return None


def _s869b_has_trigger_evidence(row, signal_payload):
    direct_values = [
        row.get("trigger_time"),
        row.get("primary_trigger"),
        row.get("primaryTrigger"),
        _s869b_payload_get(signal_payload, "triggerTime", "trigger_time"),
        _s869b_payload_get(signal_payload, "primaryTrigger", "primary_trigger"),
        _s869b_payload_get(signal_payload, "trigger", "triggerName", "trigger_name"),
        _s869b_payload_get(signal_payload, "confirmation.primaryTrigger"),
        _s869b_payload_get(signal_payload, "rawSignal.primaryTrigger"),
        _s869b_payload_get(signal_payload, "signal.primaryTrigger"),
    ]

    for value in direct_values:
        if value is not None and str(value).strip():
            return True

    trigger_lists = [
        _s869b_payload_get(signal_payload, "triggers"),
        _s869b_payload_get(signal_payload, "confirmation.triggers"),
        _s869b_payload_get(signal_payload, "rawSignal.triggers"),
        _s869b_payload_get(signal_payload, "signal.triggers"),
    ]

    for value in trigger_lists:
        if isinstance(value, list) and len(value) > 0:
            return True

    metrics = _s869b_payload_get(signal_payload, "qualityGuard.metrics")
    if isinstance(metrics, dict):
        for key in ("executionTriggerCount", "triggerCount"):
            count = _s864_to_float(metrics.get(key), 0.0) or 0.0
            if count > 0:
                return True

    return False


def _s869b_unified_delivery_eligibility(row, signal_payload, rr):
    lifecycle = str(row.get("lifecycle_status") or "").upper()
    quality = str(row.get("quality_status") or "").upper()
    grade = str(row.get("signal_grade") or "").upper()
    score = _s864_to_float(row.get("signal_score"), 0.0) or 0.0
    rr_value = _s864_to_float(rr, 0.0) or 0.0

    stored_premium = _s864_bool(row.get("premium_signal"))
    stored_telegram = _s864_bool(row.get("telegram_eligible"))

    payload_premium = _s864_bool(
        _s869b_payload_get(
            signal_payload,
            "premiumSignal",
            "premium_signal",
            "signal.premiumSignal",
            "payload.premiumSignal",
            "rawSignal.premiumSignal",
        )
    )
    payload_telegram = _s864_bool(
        _s869b_payload_get(
            signal_payload,
            "telegramEligible",
            "telegram_eligible",
            "signal.telegramEligible",
            "payload.telegramEligible",
            "rawSignal.telegramEligible",
        )
    )

    has_trigger = _s869b_has_trigger_evidence(row, signal_payload)

    strict_gate_reasons = []
    if lifecycle != "ACTIVE":
        strict_gate_reasons.append("not_active_lifecycle")
    if quality != "PASSED":
        strict_gate_reasons.append("quality_not_passed")
    if grade not in ("A", "A+"):
        strict_gate_reasons.append("grade_below_A")
    if score < 78:
        strict_gate_reasons.append("score_below_78")
    if rr_value < 2:
        strict_gate_reasons.append("rr_below_2")
    if not has_trigger:
        strict_gate_reasons.append("trigger_missing")

    derived_from_strict_gate = len(strict_gate_reasons) == 0

    premium_signal = bool(stored_premium or payload_premium or derived_from_strict_gate)
    telegram_eligible = bool(stored_telegram or payload_telegram or derived_from_strict_gate)

    if stored_premium and stored_telegram:
        source = "stored_flags"
    elif payload_premium and payload_telegram:
        source = "payload_flags"
    elif derived_from_strict_gate:
        source = "derived_from_s864_strict_gate"
    else:
        source = "blocked_by_strict_gate"

    return {
        "version": S869B_UNIFIED_ELIGIBILITY_VERSION,
        "premiumSignal": premium_signal,
        "telegramEligible": telegram_eligible,
        "source": source,
        "derivedFromStrictGate": derived_from_strict_gate,
        "strictGateReasons": strict_gate_reasons,
        "stored": {
            "premiumSignal": stored_premium,
            "telegramEligible": stored_telegram,
        },
        "payload": {
            "premiumSignal": payload_premium,
            "telegramEligible": payload_telegram,
        },
        "checks": {
            "lifecycle": lifecycle,
            "qualityStatus": quality,
            "grade": grade,
            "score": score,
            "riskReward": rr_value,
            "hasTriggerEvidence": has_trigger,
            "manualApprovalStillRequired": True,
        },
        "policy": {
            "manualApprovalIsFinalGateOnly": True,
            "doesNotBypassQualityGate": True,
            "doesNotBypassRiskRewardGate": True,
            "doesNotBypassGradeGate": True,
            "doesNotBypassLifecycleGate": True,
            "doesNotSendTelegram": True,
            "fixesStalePersistedEligibilityFlagsOnly": True,
        },
    }

def _s864_block_reasons(row, signal_payload, rr):
    reasons = []

    lifecycle = str(row.get("lifecycle_status") or "").upper()
    quality = str(row.get("quality_status") or "").upper()
    grade = str(row.get("signal_grade") or "").upper()
    score = _s864_to_float(row.get("signal_score"), 0.0) or 0.0
    eligibility = _s869b_unified_delivery_eligibility(row, signal_payload, rr)
    telegram_eligible = bool(eligibility.get("telegramEligible"))
    premium_signal = bool(eligibility.get("premiumSignal"))
    approved = _s864_manual_approval(signal_payload, row)

    if lifecycle != "ACTIVE":
        reasons.append("not_active_lifecycle")
    if quality != "PASSED":
        reasons.append("quality_not_passed")
    if grade not in ("A", "A+"):
        reasons.append("grade_below_A")
    if score < 78:
        reasons.append("score_below_78")
    if rr is None or rr < 2:
        reasons.append("rr_below_2")
    if "trigger_missing" in eligibility.get("strictGateReasons", []):
        reasons.append("trigger_missing")
    if not premium_signal:
        reasons.append("not_premium_signal")
    if not telegram_eligible:
        reasons.append("telegram_eligible_false")
    if not approved:
        reasons.append("manual_client_approval_missing")

    # S8.70F: autonomous strategy calibration policy is an additional client gate.
    # Manual approval is final-only and cannot bypass weak/unproven setup policy.
    try:
        _s870f_signal_payload = signal_payload if "signal_payload" in locals() else None
        _s870f_policy_decision = _s870f_strategy_policy_decision(row, signal_payload=_s870f_signal_payload)
        for _s870f_reason in (_s870f_policy_decision.get("blockReasons") or []):
            if _s870f_reason and _s870f_reason not in reasons:
                reasons.append(_s870f_reason)
    except Exception:
        if "strategy_policy_error" not in reasons:
            reasons.append("strategy_policy_error")

    return reasons


def _s864_unified_signal_card(row):
    signal_payload = _s864_json_loads(row.get("signal_payload_json"))
    rr = _s864_extract_rr(signal_payload, row)
    eligibility = _s869b_unified_delivery_eligibility(row, signal_payload, rr)
    block_reasons = _s864_block_reasons(row, signal_payload, rr)
    client_visible = len(block_reasons) == 0

    entry = _s864_extract_entry(signal_payload)
    stop = _s864_extract_price(signal_payload, "stop", "stopPrice", "signal.stop", "candidate.stop", "payload.stop")
    targets = _s864_extract_targets(signal_payload)
    direction = _s864_extract_direction(signal_payload, row)

    lifecycle = str(row.get("lifecycle_status") or "UNKNOWN").upper()
    setup_slug = str(row.get("setup_slug") or "unknown_setup")
    symbol = str(row.get("symbol") or "UNKNOWN").upper()

    if client_visible:
        display_state = "CLIENT_VISIBLE_READY"
        client_headline = f"{symbol} {direction} setup is ready"
    elif lifecycle == "ACTIVE":
        display_state = "INTERNAL_ACTIVE_BLOCKED"
        client_headline = f"{symbol} is under SkillEdge AI review"
    else:
        display_state = "WATCHING_OR_RESEARCH_ONLY"
        client_headline = f"{symbol} is being monitored by SkillEdge AI"

    return {
        "signalId": row.get("signal_id"),
        "symbol": symbol,
        "setupSlug": setup_slug,
        "sourceLabel": "SkillEdge AI",
        "internalDeskHidden": True,
        "displayState": display_state,
        "clientVisible": client_visible,
        "clientVisibleApproved": _s864_manual_approval(signal_payload, row),
        "blockedReasons": block_reasons,
        "headline": client_headline,
        "direction": direction,
        "lifecycleStatus": lifecycle,
        "qualityStatus": row.get("quality_status"),
        "grade": row.get("signal_grade"),
        "score": _s864_to_float(row.get("signal_score"), None),
        "riskReward": rr,
        "premiumSignal": bool(eligibility.get("premiumSignal")),
        "telegramEligible": bool(eligibility.get("telegramEligible")),
        "deliveryEligibility": eligibility,
        "levels": {"entry": entry, "stop": stop, "targets": targets},
        "timing": {
            "sessionDate": row.get("session_date"),
            "createdAt": row.get("created_at"),
            "triggerTime": row.get("trigger_time"),
            "storedAt": row.get("stored_at"),
            "updatedAt": row.get("updated_at"),
        },
        "outcomeSnapshot": {
            "status": row.get("outcome_status"),
            "resultR": _s864_to_float(row.get("outcome_result_r"), None),
            "mfeR": _s864_to_float(row.get("outcome_mfe_r"), None),
            "maeR": _s864_to_float(row.get("outcome_mae_r"), None),
            "firstEvent": row.get("outcome_first_event"),
        },
        "safeClientCopy": {
            "title": client_headline,
            "subtitle": "Unified SkillEdge AI signal layer",
            "riskNote": "Use only after the signal passes all quality, RR and manual approval gates.",
            "status": display_state,
        },
    }


def _s864_display_state(visible_cards, blocked_cards, desk_report, strategy_report):
    if visible_cards:
        return "CLIENT_VISIBLE_SIGNALS_READY"
    active_blocked = [card for card in blocked_cards if card.get("displayState") == "INTERNAL_ACTIVE_BLOCKED"]
    if active_blocked:
        return "INTERNAL_SIGNALS_BLOCKED_BY_GATES"

    summary = _s864_dict(strategy_report.get("summary"))
    promote_count = _s864_to_int(summary.get("promoteCandidateCount"), 0)
    if promote_count > 0:
        return "PROMOTION_CANDIDATES_REQUIRE_MANUAL_APPROVAL"

    return "NO_CLIENT_VISIBLE_SIGNALS_READY"


def _s864_build_report(limit=50):
    from datetime import datetime, timezone

    safe_limit = max(5, min(int(limit or 50), 500))

    strategy_path = "/opt/skilledge/stock-engine/reports/strategy_reranking_draft/latest_s862.json"
    desks_path = "/opt/skilledge/stock-engine/reports/ai_trader_desks/latest_s863.json"
    blockers_path = "/opt/skilledge/stock-engine/reports/signal_blockers/latest_s858.json"

    strategy_report = _s864_read_json_report(strategy_path)
    desk_report = _s864_read_json_report(desks_path)
    blockers_report = _s864_read_json_report(blockers_path)

    rows = _s864_fetch_recent_signals(limit=safe_limit)
    cards = [_s864_unified_signal_card(row) for row in rows]

    visible_cards = [card for card in cards if card.get("clientVisible") is True]
    blocked_cards = [card for card in cards if card.get("clientVisible") is not True]

    display_state = _s864_display_state(visible_cards, blocked_cards, desk_report, strategy_report)

    blocked_reason_counts = {}
    for card in blocked_cards:
        for reason in card.get("blockedReasons") or []:
            blocked_reason_counts[reason] = int(blocked_reason_counts.get(reason, 0) or 0) + 1

    client_output = {
        "brand": "SkillEdge AI",
        "displayState": display_state,
        "clientVisibleCount": len(visible_cards),
        "researchOnlyCount": len(blocked_cards),
        "cards": visible_cards[:10],
        "emptyState": {
            "title": "No approved SkillEdge AI signals right now",
            "message": "The engine is monitoring the market, but no signal has passed the full quality, RR and manual approval gate yet.",
            "showInternalDesks": False,
        },
    }

    internal_output = {
        "recentUnifiedCards": cards[:25],
        "blockedReasonCounts": dict(sorted(blocked_reason_counts.items(), key=lambda item: int(item[1] or 0), reverse=True)),
        "deskSummary": _s864_dict(desk_report.get("summary")),
        "strategySummary": _s864_dict(strategy_report.get("summary")),
        "signalBlockersSummary": _s864_dict(blockers_report.get("summary")),
    }

    return {
        "ok": True,
        "storageVersion": S864_UNIFIED_SKILLEDGE_OUTPUT_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "source": {
            "dbPath": _s864_db_path(),
            "strategyRerankingDraft": strategy_path,
            "aiTraderDesks": desks_path,
            "signalBlockers": blockers_path,
            "strategyRerankingVersion": strategy_report.get("storageVersion"),
            "aiTraderDesksVersion": desk_report.get("storageVersion"),
            "signalBlockersVersion": blockers_report.get("storageVersion"),
            "limit": safe_limit,
        },
        "summary": {
            "rowsEvaluated": len(rows),
            "unifiedCardCount": len(cards),
            "clientVisibleCount": len(visible_cards),
            "researchOnlyCount": len(blocked_cards),
            "displayState": display_state,
            "topBlockedReason": next(iter(internal_output["blockedReasonCounts"]), None),
            "nextAction": "Use this as the unified SkillEdge AI output adapter. Keep all internal desks hidden from clients.",
        },
        "clientOutput": client_output,
        "internalOutput": internal_output,
        "policy": {
            "readOnly": True,
            "researchOnly": True,
            "sendsTelegram": False,
            "changesTelegramGate": False,
            "changesClientDelivery": False,
            "writesDb": False,
            "manualApprovalRequiredBeforeClientVisible": True,
            "hideInternalDesksFromClient": True,
            "clientSeesUnifiedSkillEdgeAIOnly": True,
        },
    }


def _s864_persist_report(report):
    import json

    out_dir = _s864_report_dir()
    out_dir.mkdir(parents=True, exist_ok=True)

    generated_at = str(report.get("generatedAt") or "unknown").replace(":", "-")
    latest = out_dir / "latest_s864.json"
    snapshot = out_dir / f"{generated_at}_s864.json"

    report["persistence"] = {
        "filePersisted": True,
        "latestPath": str(latest),
        "snapshotPath": str(snapshot),
    }

    latest.write_text(json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    snapshot.write_text(json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")

    return report


def _s864_run_report(limit=50, publish=True):
    report = _s864_build_report(limit=limit)
    if publish:
        report = _s864_persist_report(report)
    return report


@app.post("/engine/research/unified-skilledge-output/run")
def engine_research_unified_skilledge_output_run(limit: int = 50, publish: bool = True):
    return _s864_run_report(limit=limit, publish=publish)


@app.get("/engine/research/unified-skilledge-output/latest")
def engine_research_unified_skilledge_output_latest():
    import json

    latest = _s864_report_dir() / "latest_s864.json"
    if not latest.exists():
        return {
            "ok": False,
            "storageVersion": S864_UNIFIED_SKILLEDGE_OUTPUT_VERSION,
            "error": "unified_skilledge_output_report_not_found",
            "nextAction": "Run POST /engine/research/unified-skilledge-output/run?publish=true first.",
            "policy": {
                "readOnly": True,
                "researchOnly": True,
                "changesClientDelivery": False,
                "clientSeesUnifiedSkillEdgeAIOnly": True,
            },
        }

    return json.loads(latest.read_text(encoding="utf-8"))



# === S8.67 Admin Manual Approval Gate =======================================
S867_SIGNAL_MANUAL_APPROVAL_VERSION = "s8_67_signal_manual_approval_gate_v1"


def _s867_now_iso():
    return datetime.now(timezone.utc).isoformat()


def _s867_db_path():
    try:
        return _s864_db_path()
    except Exception:
        return "/opt/skilledge/stock-engine/data/stock_engine.db"


def _s867_connect():
    import sqlite3

    con = sqlite3.connect(_s867_db_path())
    con.row_factory = sqlite3.Row
    return con


def _s867_json_dumps(value):
    import json

    try:
        return json.dumps(value, ensure_ascii=False, default=str)
    except Exception:
        return "{}"


def _s867_init_table():
    con = _s867_connect()
    cur = con.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS signal_manual_approvals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            signal_id TEXT NOT NULL UNIQUE,
            symbol TEXT,
            setup_slug TEXT,
            session_date TEXT,
            status TEXT NOT NULL DEFAULT 'PENDING',
            approved INTEGER NOT NULL DEFAULT 0,
            client_visible INTEGER NOT NULL DEFAULT 0,
            reviewed_by TEXT,
            reason TEXT,
            notes TEXT,
            source TEXT,
            payload_json TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        )
        """
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_signal_manual_approvals_status ON signal_manual_approvals(status)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_signal_manual_approvals_updated_at ON signal_manual_approvals(updated_at)")
    con.commit()
    con.close()


def _s867_row_to_dict(row):
    if row is None:
        return None
    data = dict(row)
    return {
        "id": data.get("id"),
        "signalId": data.get("signal_id"),
        "symbol": data.get("symbol"),
        "setupSlug": data.get("setup_slug"),
        "sessionDate": data.get("session_date"),
        "status": data.get("status"),
        "approved": bool(data.get("approved")),
        "clientVisibleApproved": bool(data.get("approved")) and bool(data.get("client_visible")),
        "reviewedBy": data.get("reviewed_by"),
        "reason": data.get("reason"),
        "notes": data.get("notes"),
        "source": data.get("source"),
        "createdAt": data.get("created_at"),
        "updatedAt": data.get("updated_at"),
        "storageVersion": S867_SIGNAL_MANUAL_APPROVAL_VERSION,
    }


def _s867_get_signal_manual_approval(signal_id: str):
    clean_signal_id = str(signal_id or "").strip()
    if not clean_signal_id:
        return {
            "status": "MISSING_SIGNAL_ID",
            "approved": False,
            "clientVisibleApproved": False,
            "storageVersion": S867_SIGNAL_MANUAL_APPROVAL_VERSION,
        }

    try:
        _s867_init_table()
        con = _s867_connect()
        row = con.execute(
            "SELECT * FROM signal_manual_approvals WHERE signal_id = ? LIMIT 1",
            (clean_signal_id,),
        ).fetchone()
        con.close()

        if row is None:
            return {
                "signalId": clean_signal_id,
                "status": "NO_MANUAL_APPROVAL_RECORD",
                "approved": False,
                "clientVisibleApproved": False,
                "storageVersion": S867_SIGNAL_MANUAL_APPROVAL_VERSION,
            }

        out = _s867_row_to_dict(row)
        return out if isinstance(out, dict) else {
            "signalId": clean_signal_id,
            "status": "NO_MANUAL_APPROVAL_RECORD",
            "approved": False,
            "clientVisibleApproved": False,
            "storageVersion": S867_SIGNAL_MANUAL_APPROVAL_VERSION,
        }
    except Exception as error:
        return {
            "signalId": clean_signal_id,
            "status": "MANUAL_APPROVAL_READ_ERROR",
            "approved": False,
            "clientVisibleApproved": False,
            "error": repr(error),
            "storageVersion": S867_SIGNAL_MANUAL_APPROVAL_VERSION,
        }


def _s867_upsert_signal_manual_approval(payload, *, status: str, approved: bool, client_visible: bool):
    body = payload if isinstance(payload, dict) else {}
    signal_id = str(body.get("signalId") or body.get("signal_id") or "").strip()

    if not signal_id:
        return {
            "ok": False,
            "error": "missing_signal_id",
            "storageVersion": S867_SIGNAL_MANUAL_APPROVAL_VERSION,
        }

    now_iso = _s867_now_iso()
    status_clean = str(status or "").upper().strip() or "PENDING"

    symbol = str(body.get("symbol") or "").upper().strip() or None
    setup_slug = str(body.get("setupSlug") or body.get("setup_slug") or "").strip() or None
    session_date = str(body.get("sessionDate") or body.get("session_date") or "")[:10] or None
    reviewed_by = str(body.get("reviewedBy") or body.get("reviewed_by") or "admin").strip() or "admin"
    reason = str(body.get("reason") or "").strip() or None
    notes = str(body.get("notes") or "").strip() or None
    source = str(body.get("source") or "admin_manual_gate").strip() or "admin_manual_gate"

    _s867_init_table()
    con = _s867_connect()
    cur = con.cursor()
    existing = cur.execute(
        "SELECT created_at FROM signal_manual_approvals WHERE signal_id = ? LIMIT 1",
        (signal_id,),
    ).fetchone()
    created_at = str(existing["created_at"]) if existing and existing["created_at"] else now_iso

    cur.execute(
        """
        INSERT INTO signal_manual_approvals (
            signal_id, symbol, setup_slug, session_date, status, approved, client_visible,
            reviewed_by, reason, notes, source, payload_json, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(signal_id) DO UPDATE SET
            symbol = excluded.symbol,
            setup_slug = excluded.setup_slug,
            session_date = excluded.session_date,
            status = excluded.status,
            approved = excluded.approved,
            client_visible = excluded.client_visible,
            reviewed_by = excluded.reviewed_by,
            reason = excluded.reason,
            notes = excluded.notes,
            source = excluded.source,
            payload_json = excluded.payload_json,
            updated_at = excluded.updated_at
        """,
        (
            signal_id,
            symbol,
            setup_slug,
            session_date,
            status_clean,
            1 if approved else 0,
            1 if (approved and client_visible) else 0,
            reviewed_by,
            reason,
            notes,
            source,
            _s867_json_dumps(body),
            created_at,
            now_iso,
        ),
    )
    con.commit()
    row = cur.execute(
        "SELECT * FROM signal_manual_approvals WHERE signal_id = ? LIMIT 1",
        (signal_id,),
    ).fetchone()
    con.close()

    return {
        "ok": True,
        "approval": _s867_row_to_dict(row),
        "policy": {
            "manualApprovalIsFinalGateOnly": True,
            "doesNotBypassQualityGate": True,
            "doesNotBypassRiskRewardGate": True,
            "doesNotBypassGradeGate": True,
            "doesNotBypassLifecycleGate": True,
            "doesNotSendTelegram": True,
            "doesNotCreateSignal": True,
        },
        "storageVersion": S867_SIGNAL_MANUAL_APPROVAL_VERSION,
    }


def _s867_list_signal_manual_approvals(limit: int = 100, signal_id: str | None = None):
    _s867_init_table()
    safe_limit = max(1, min(int(limit or 100), 500))
    clean_signal_id = str(signal_id or "").strip()

    con = _s867_connect()
    if clean_signal_id:
        rows = con.execute(
            "SELECT * FROM signal_manual_approvals WHERE signal_id = ? ORDER BY updated_at DESC LIMIT ?",
            (clean_signal_id, safe_limit),
        ).fetchall()
    else:
        rows = con.execute(
            "SELECT * FROM signal_manual_approvals ORDER BY updated_at DESC LIMIT ?",
            (safe_limit,),
        ).fetchall()
    con.close()

    items = [_s867_row_to_dict(row) for row in rows]
    items = [item for item in items if isinstance(item, dict)]

    return {
        "ok": True,
        "items": items,
        "summary": {
            "count": len(items),
            "approvedCount": len([item for item in items if item.get("approved") is True]),
            "clientVisibleApprovedCount": len([item for item in items if item.get("clientVisibleApproved") is True]),
            "limit": safe_limit,
            "signalId": clean_signal_id or None,
        },
        "policy": {
            "adminOnly": True,
            "manualApprovalIsFinalGateOnly": True,
            "changesClientDeliveryOnlyAfterS864Regenerates": True,
            "doesNotBypassSignalGates": True,
        },
        "storageVersion": S867_SIGNAL_MANUAL_APPROVAL_VERSION,
    }


@app.get("/engine/admin/manual-approvals/list")
def engine_admin_manual_approvals_list(limit: int = 100, signal_id: str | None = None):
    return _s867_list_signal_manual_approvals(limit=limit, signal_id=signal_id)


@app.post("/engine/admin/manual-approvals/approve")
def engine_admin_manual_approvals_approve(payload: dict[str, Any] | None = None):
    body = payload if isinstance(payload, dict) else {}
    return _s867_upsert_signal_manual_approval(
        body,
        status="APPROVED",
        approved=True,
        client_visible=True,
    )


@app.post("/engine/admin/manual-approvals/reject")
def engine_admin_manual_approvals_reject(payload: dict[str, Any] | None = None):
    body = payload if isinstance(payload, dict) else {}
    return _s867_upsert_signal_manual_approval(
        body,
        status="REJECTED",
        approved=False,
        client_visible=False,
    )


# === S8.70A Ready Candidate Quality Audit ===================================
S870A_READY_QUALITY_AUDIT_VERSION = "s8_70a_ready_candidate_quality_audit_v1"
S870B_READY_QUALITY_RR_SEMANTICS_VERSION = "s8_70b_ready_quality_rr_semantics_hotfix_v1"
S870C_CALIBRATED_EDGE_GATE_VERSION = "s8_70c_calibrated_edge_gate_no_hard_limit_v1"


# S8.70A Path hotfix: keep pathlib dependency local so app.py does not depend on a global Path import.
def _s870a_reports_dir():
    from pathlib import Path as _Path

    try:
        root = _Path(__file__).resolve().parents[2]
    except Exception:
        root = _Path(".")
    out_dir = root / "reports" / "ready_candidate_quality"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s870a_nested(obj, path, default=None):
    current = obj
    for part in str(path or "").split("."):
        if not part:
            continue
        if isinstance(current, dict):
            current = current.get(part)
        else:
            return default
        if current is None:
            return default
    return current


def _s870a_float(value, default=None):
    try:
        if value is None or value == "":
            return default
        return float(value)
    except Exception:
        return default


def _s870a_reasons(card):
    raw = card.get("blockedReasons") if isinstance(card, dict) else []
    if isinstance(raw, list):
        return [str(item or "").strip() for item in raw if str(item or "").strip()]
    return []


def _s870a_is_ready_for_manual_review(card):
    if not isinstance(card, dict):
        return False
    reasons = _s870a_reasons(card)
    return bool(
        card.get("premiumSignal") is True
        and card.get("telegramEligible") is True
        and str(card.get("lifecycleStatus") or "").upper() == "ACTIVE"
        and str(card.get("qualityStatus") or "").upper() == "PASSED"
        and str(card.get("grade") or "").upper() in ("A", "A+")
        and (_s870a_float(card.get("score"), 0.0) or 0.0) >= 78
        and (_s870a_float(card.get("riskReward"), 0.0) or 0.0) >= 2
        and len(reasons) == 1
        and reasons[0] == "manual_client_approval_missing"
        and card.get("clientVisible") is not True
    )


def _s870a_side(card):
    side = str(card.get("direction") or "").strip().upper()
    setup_slug = str(card.get("setupSlug") or "").strip().lower()
    if side in ("LONG", "BUY", "BULLISH"):
        return "LONG"
    if side in ("SHORT", "SELL", "BEARISH"):
        return "SHORT"
    if setup_slug.endswith("_short") or "short" in setup_slug or "rejection" in setup_slug or "breakdown" in setup_slug:
        return "SHORT"
    if setup_slug.endswith("_long") or "long" in setup_slug or "reclaim" in setup_slug or "breakout" in setup_slug or "continuation" in setup_slug:
        return "LONG"
    return "UNKNOWN"


def _s870a_parse_dt(value):
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00"))
    except Exception:
        return None


def _s870a_age_minutes(card):
    candidates = [
        _s870a_nested(card, "timing.triggerTime"),
        _s870a_nested(card, "timing.createdAt"),
        _s870a_nested(card, "timing.storedAt"),
        card.get("createdAt"),
        card.get("triggerTime"),
        card.get("storedAt"),
    ]
    dt = None
    for item in candidates:
        dt = _s870a_parse_dt(item)
        if dt:
            break
    if not dt:
        return None
    try:
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return round((datetime.now(timezone.utc) - dt.astimezone(timezone.utc)).total_seconds() / 60.0, 1)
    except Exception:
        return None


def _s870a_add_flag(flags, severity, code, message, value=None):
    flags.append({"severity": severity, "code": code, "message": message, "value": value})


def _s870a_audit_card(card, duplicate_symbol_count=1, duplicate_setup_count=1):
    symbol = str(card.get("symbol") or "").upper()
    setup_slug = str(card.get("setupSlug") or "")
    side = _s870a_side(card)

    entry = _s870a_float(_s870a_nested(card, "levels.entry"))
    stop = _s870a_float(_s870a_nested(card, "levels.stop"))
    targets = _s870a_nested(card, "levels.targets", [])
    target_prices = []
    target_declared_rs = []
    tp1 = None
    tp1_declared_r = None
    max_declared_r = None

    if isinstance(targets, list):
        for target in targets:
            if not isinstance(target, dict):
                continue
            price = _s870a_float(target.get("price"))
            declared_r = _s870a_float(target.get("r"))
            if price is not None:
                target_prices.append(price)
            if declared_r is not None:
                target_declared_rs.append(declared_r)

    if target_prices:
        tp1 = target_prices[0]
    if target_declared_rs:
        tp1_declared_r = target_declared_rs[0]
        max_declared_r = max(target_declared_rs)

    reported_rr = _s870a_float(card.get("riskReward"))
    score = _s870a_float(card.get("score"), 0.0) or 0.0
    age_minutes = _s870a_age_minutes(card)
    flags = []

    if not symbol:
        _s870a_add_flag(flags, "CRITICAL", "symbol_missing", "Symbol is missing.")
    if side == "UNKNOWN":
        _s870a_add_flag(flags, "HIGH", "side_unknown", "Signal side could not be inferred.")
    if entry is None:
        _s870a_add_flag(flags, "CRITICAL", "entry_missing", "Entry is missing.")
    if stop is None:
        _s870a_add_flag(flags, "CRITICAL", "stop_missing", "Stop is missing.")
    if tp1 is None:
        _s870a_add_flag(flags, "CRITICAL", "tp1_missing", "TP1 is missing.")

    stop_distance_pct = None
    tp1_distance_pct = None
    calculated_tp1_r = None
    calculated_max_r = None
    reported_rr_reference = None
    geometry_ok = None

    if entry and stop and tp1:
        risk = abs(entry - stop)
        reward = abs(tp1 - entry)
        stop_distance_pct = round((risk / abs(entry)) * 100.0, 3) if entry else None
        tp1_distance_pct = round((reward / abs(entry)) * 100.0, 3) if entry else None
        calculated_tp1_r = round(reward / risk, 3) if risk > 0 else None

        if risk > 0 and target_prices:
            calculated_target_rs = [round(abs(price - entry) / risk, 3) for price in target_prices]
            calculated_max_r = max(calculated_target_rs) if calculated_target_rs else None

        reported_rr_reference = (
            max_declared_r
            if max_declared_r is not None
            else calculated_max_r
            if calculated_max_r is not None
            else calculated_tp1_r
        )

        if side == "LONG":
            geometry_ok = bool(stop < entry < tp1)
            if not geometry_ok:
                _s870a_add_flag(flags, "CRITICAL", "long_geometry_invalid", "LONG requires stop < entry < TP1.", {"entry": entry, "stop": stop, "tp1": tp1})
        elif side == "SHORT":
            geometry_ok = bool(stop > entry > tp1)
            if not geometry_ok:
                _s870a_add_flag(flags, "CRITICAL", "short_geometry_invalid", "SHORT requires stop > entry > TP1.", {"entry": entry, "stop": stop, "tp1": tp1})

        if stop_distance_pct is not None:
            if stop_distance_pct < 0.12:
                _s870a_add_flag(flags, "HIGH", "stop_distance_too_tight", "Stop distance is very tight and may be noise-sensitive.", stop_distance_pct)
            elif stop_distance_pct > 8.0:
                _s870a_add_flag(flags, "HIGH", "stop_distance_too_wide", "Stop distance is too wide for fast signal delivery.", stop_distance_pct)
            elif stop_distance_pct > 4.0:
                _s870a_add_flag(flags, "MEDIUM", "stop_distance_wide", "Stop distance is wide; manual context required.", stop_distance_pct)

        if calculated_tp1_r is not None:
            if calculated_tp1_r < 1.8:
                _s870a_add_flag(flags, "HIGH", "tp1_rr_below_1_8", "Calculated TP1 R is below the quality threshold.", calculated_tp1_r)
            elif calculated_tp1_r < 2.0:
                _s870a_add_flag(flags, "MEDIUM", "tp1_rr_below_2", "Calculated TP1 R is slightly below 2R.", calculated_tp1_r)

        if reported_rr is not None and reported_rr_reference is not None:
            rr_diff = abs(reported_rr - reported_rr_reference)
            rr_context = {
                "reportedRR": reported_rr,
                "reportedRRReference": reported_rr_reference,
                "tp1DeclaredR": tp1_declared_r,
                "maxDeclaredR": max_declared_r,
                "calculatedTp1R": calculated_tp1_r,
                "calculatedMaxR": calculated_max_r,
            }

            if rr_diff >= 1.0:
                _s870a_add_flag(flags, "HIGH", "reported_rr_mismatch", "Reported RR differs strongly from max target R reference.", rr_context)
            elif rr_diff >= 0.5:
                _s870a_add_flag(flags, "MEDIUM", "reported_rr_minor_mismatch", "Reported RR differs from max target R reference.", rr_context)

    if reported_rr == 3.0 and tp1_declared_r == 2.0:
        if (
            (max_declared_r is None or max_declared_r < 2.8)
            and (calculated_max_r is None or calculated_max_r < 2.8)
        ):
            _s870a_add_flag(flags, "MEDIUM", "rr_default_like", "Reported RR is 3R while no 3R target reference is visible; verify targets are not default-shaped.", {
                "reportedRR": reported_rr,
                "tp1DeclaredR": tp1_declared_r,
                "maxDeclaredR": max_declared_r,
                "calculatedMaxR": calculated_max_r,
            })
        else:
            _s870a_add_flag(flags, "LOW", "rr_uses_max_target_not_tp1", "Reported RR appears to reference max target while TP1 remains 2R.", {
                "reportedRR": reported_rr,
                "tp1DeclaredR": tp1_declared_r,
                "maxDeclaredR": max_declared_r,
                "calculatedMaxR": calculated_max_r,
            })
    if score >= 99:
        _s870a_add_flag(flags, "LOW", "score_saturated", "Score is saturated near 100; verify score is not over-compressed.", score)
    if duplicate_symbol_count > 1:
        _s870a_add_flag(flags, "MEDIUM", "duplicate_symbol_in_ready_queue", "Multiple ready signals exist for the same symbol.", duplicate_symbol_count)
    if duplicate_setup_count > 12:
        _s870a_add_flag(flags, "MEDIUM", "setup_overcrowded_ready_queue", "One setup dominates the ready queue; verify no template/default burst.", {"setupSlug": setup_slug, "count": duplicate_setup_count})
    if symbol in ("SPY", "QQQ", "IWM", "DIA"):
        _s870a_add_flag(flags, "MEDIUM", "broad_etf_requires_context", "Broad ETF signal requires separate large-cap/index context.", symbol)
    if age_minutes is None:
        _s870a_add_flag(flags, "MEDIUM", "signal_time_missing", "Signal time could not be evaluated.")
    elif age_minutes > 90:
        _s870a_add_flag(flags, "HIGH", "signal_too_old_for_manual_release", "Signal is too old for live client release without revalidation.", age_minutes)
    elif age_minutes > 45:
        _s870a_add_flag(flags, "MEDIUM", "signal_age_requires_recheck", "Signal is aging; price/context recheck required before approval.", age_minutes)

    critical = sum(1 for item in flags if item.get("severity") == "CRITICAL")
    high = sum(1 for item in flags if item.get("severity") == "HIGH")
    medium = sum(1 for item in flags if item.get("severity") == "MEDIUM")

    if critical > 0:
        decision = "FAIL_CRITICAL"
    elif high > 0:
        decision = "REVIEW_HIGH_RISK"
    elif medium > 0:
        decision = "REVIEW_REQUIRED"
    else:
        decision = "PASS_READY_QUALITY"

    return {
        "symbol": symbol,
        "setupSlug": setup_slug,
        "signalId": card.get("signalId"),
        "side": side,
        "decision": decision,
        "severityCounts": {"critical": critical, "high": high, "medium": medium, "low": sum(1 for item in flags if item.get("severity") == "LOW")},
        "metrics": {
            "entry": entry,
            "stop": stop,
            "tp1": tp1,
            "reportedRR": reported_rr,
            "reportedRRReference": reported_rr_reference,
            "tp1DeclaredR": tp1_declared_r,
            "maxDeclaredR": max_declared_r,
            "calculatedTp1R": calculated_tp1_r,
            "calculatedMaxR": calculated_max_r,
            "stopDistancePct": stop_distance_pct,
            "tp1DistancePct": tp1_distance_pct,
            "score": score,
            "ageMinutes": age_minutes,
            "geometryOk": geometry_ok,
            "duplicateSymbolCount": duplicate_symbol_count,
            "duplicateSetupCount": duplicate_setup_count,
        },
        "flags": flags,
        "readyCard": {
            "lifecycleStatus": card.get("lifecycleStatus"),
            "qualityStatus": card.get("qualityStatus"),
            "grade": card.get("grade"),
            "premiumSignal": card.get("premiumSignal"),
            "telegramEligible": card.get("telegramEligible"),
            "blockedReasons": _s870a_reasons(card),
        },
    }


def _s870a_count_by(items, key):
    counts = {}
    for item in items:
        value = str(item.get(key) or "unknown")
        counts[value] = counts.get(value, 0) + 1
    return counts


def _s870a_flag_counts(audits):
    counts = {}
    for audit in audits:
        for flag in audit.get("flags", []):
            code = str(flag.get("code") or "unknown")
            counts[code] = counts.get(code, 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: kv[1], reverse=True))



# === S8.70C Calibrated Edge Gate / No Hard Limit =============================
def _s870c_edge_root_dir():
    from pathlib import Path as _Path

    try:
        return _Path(__file__).resolve().parents[2]
    except Exception:
        return _Path(".")


def _s870c_edge_float(value, default=None):
    try:
        if value is None or value == "":
            return default
        return float(value)
    except Exception:
        return default


def _s870c_edge_int(value, default=0):
    try:
        if value is None or value == "":
            return default
        return int(value)
    except Exception:
        return default


def _s870c_edge_safe_div(num, den):
    try:
        den = float(den)
        if den == 0:
            return None
        return float(num) / den
    except Exception:
        return None


def _s870c_edge_db_candidates():
    root = _s870c_edge_root_dir()
    dirs = [
        root / "data",
        root / "app" / "data",
        root / "reports",
    ]
    patterns = ["*.db", "*.sqlite", "*.sqlite3"]

    found = []
    seen = set()
    for directory in dirs:
        try:
            if not directory.exists():
                continue
            for pattern in patterns:
                for path in directory.rglob(pattern):
                    key = str(path.resolve())
                    if key in seen:
                        continue
                    if ".venv" in key or "__pycache__" in key:
                        continue
                    seen.add(key)
                    found.append(path)
        except Exception:
            continue

    return found[:20]


def _s870c_edge_column(columns, *names):
    lowered = {str(col).lower(): col for col in columns}
    for name in names:
        direct = lowered.get(str(name).lower())
        if direct:
            return direct
    return None


def _s870c_edge_outcome_kind(row, result_col=None, status_col=None, r_col=None):
    text_parts = []
    if result_col and result_col in row:
        text_parts.append(str(row.get(result_col) or ""))
    if status_col and status_col in row:
        text_parts.append(str(row.get(status_col) or ""))

    text = " ".join(text_parts).upper()
    result_r = _s870c_edge_float(row.get(r_col)) if r_col and r_col in row else None

    if any(token in text for token in ("WORKED", "TP1", "TP2", "TARGET", "WIN")):
        return "WIN", result_r
    if any(token in text for token in ("FAILED", "STOP", "LOSS")):
        return "LOSS", result_r

    if result_r is not None:
        if result_r > 0:
            return "WIN", result_r
        if result_r < 0:
            return "LOSS", result_r

    return "OPEN_OR_UNKNOWN", result_r


def _s870c_edge_empty_stats(setup_slug, symbol=None, source="not_found"):
    return {
        "setupSlug": setup_slug,
        "symbol": symbol,
        "source": source,
        "statsAvailable": False,
        "closedTrades": 0,
        "wins": 0,
        "losses": 0,
        "winRate": None,
        "expectedWinRate": None,
        "avgR": None,
        "expectancyR": None,
        "sampleQuality": "NO_STATS_FOUND",
        "note": "No closed outcome statistics found yet. Signal remains eligible for research/manual review, but edge is not statistically proven.",
    }


def _s870c_edge_stats_from_sqlite(setup_slug, symbol=None):
    import sqlite3

    setup_slug = str(setup_slug or "").strip()
    symbol = str(symbol or "").strip().upper() if symbol else None

    if not setup_slug:
        return _s870c_edge_empty_stats(setup_slug, symbol, source="missing_setup_slug")

    aggregate = {
        "closedTrades": 0,
        "wins": 0,
        "losses": 0,
        "rValues": [],
        "sources": [],
    }

    for db_path in _s870c_edge_db_candidates():
        conn = None
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=2)
            conn.row_factory = sqlite3.Row
            tables = conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
        except Exception:
            try:
                if conn:
                    conn.close()
            except Exception:
                pass
            continue

        for table_row in tables:
            table = table_row[0]
            try:
                info = conn.execute(f'PRAGMA table_info("{table}")').fetchall()
                columns = [row[1] for row in info]
                if not columns:
                    continue

                setup_col = _s870c_edge_column(columns, "setup_slug", "setupSlug", "setup", "strategy_slug", "strategySlug")
                if not setup_col:
                    continue

                result_col = _s870c_edge_column(columns, "result", "outcome", "outcome_status", "outcomeStatus", "result_status", "resultStatus", "first_event", "firstEvent")
                status_col = _s870c_edge_column(columns, "status", "state", "lifecycle_status", "lifecycleStatus")
                r_col = _s870c_edge_column(columns, "result_r", "resultR", "r_multiple", "rMultiple", "pnl_r", "pnlR", "realized_r", "realizedR")

                if not result_col and not status_col and not r_col:
                    continue

                rows = conn.execute(f'SELECT * FROM "{table}" WHERE "{setup_col}" = ? LIMIT 5000', [setup_slug]).fetchall()

                table_closed = 0
                table_wins = 0
                table_losses = 0
                table_r_values = []

                for raw in rows:
                    row = dict(raw)
                    kind, result_r = _s870c_edge_outcome_kind(row, result_col=result_col, status_col=status_col, r_col=r_col)

                    if kind not in ("WIN", "LOSS"):
                        continue

                    table_closed += 1
                    if kind == "WIN":
                        table_wins += 1
                    else:
                        table_losses += 1

                    if result_r is not None:
                        table_r_values.append(result_r)

                if table_closed > 0:
                    aggregate["closedTrades"] += table_closed
                    aggregate["wins"] += table_wins
                    aggregate["losses"] += table_losses
                    aggregate["rValues"].extend(table_r_values)
                    aggregate["sources"].append({
                        "db": str(db_path),
                        "table": table,
                        "closedTrades": table_closed,
                        "wins": table_wins,
                        "losses": table_losses,
                    })

            except Exception:
                continue

        try:
            conn.close()
        except Exception:
            pass

    closed = aggregate["closedTrades"]
    if closed <= 0:
        return _s870c_edge_empty_stats(setup_slug, symbol, source="sqlite_scan_no_closed_rows")

    wins = aggregate["wins"]
    losses = aggregate["losses"]
    win_rate = _s870c_edge_safe_div(wins, closed)
    r_values = aggregate["rValues"]
    avg_r = round(sum(r_values) / len(r_values), 4) if r_values else None

    expectancy_r = avg_r if avg_r is not None else round(((wins * 2.0) + (losses * -1.0)) / closed, 4)

    return {
        "setupSlug": setup_slug,
        "symbol": symbol,
        "source": "sqlite_outcome_scan",
        "statsAvailable": True,
        "closedTrades": closed,
        "wins": wins,
        "losses": losses,
        "winRate": round(win_rate, 4) if win_rate is not None else None,
        "expectedWinRate": round(win_rate, 4) if win_rate is not None else None,
        "avgR": avg_r,
        "expectancyR": expectancy_r,
        "sampleQuality": "OK" if closed >= 30 else "SMALL_SAMPLE" if closed >= 10 else "VERY_SMALL_SAMPLE",
        "sources": aggregate["sources"][:10],
    }


def _s870c_edge_status(stats, min_win_rate=0.65, proven_min_closed=30, promising_min_closed=10):
    closed = _s870c_edge_int(stats.get("closedTrades"), 0)
    win_rate = _s870c_edge_float(stats.get("expectedWinRate"))
    expectancy = _s870c_edge_float(stats.get("expectancyR"))

    if not stats.get("statsAvailable"):
        return {
            "edgeStatus": "INSUFFICIENT_SAMPLE",
            "clientEdgeGatePassed": False,
            "reason": "No closed outcome stats available yet.",
        }

    if closed < promising_min_closed:
        return {
            "edgeStatus": "INSUFFICIENT_SAMPLE",
            "clientEdgeGatePassed": False,
            "reason": f"Only {closed} closed trades; need at least {promising_min_closed} for promising edge.",
        }

    if win_rate is None:
        return {
            "edgeStatus": "INSUFFICIENT_SAMPLE",
            "clientEdgeGatePassed": False,
            "reason": "Win rate could not be computed.",
        }

    expectancy_ok = expectancy is None or expectancy > 0

    if closed >= proven_min_closed and win_rate >= min_win_rate and expectancy_ok:
        return {
            "edgeStatus": "PROVEN_EDGE",
            "clientEdgeGatePassed": True,
            "reason": f"Closed trades >= {proven_min_closed}, win rate >= {min_win_rate:.0%}, expectancy positive/unknown.",
        }

    if closed >= promising_min_closed and win_rate >= min_win_rate and expectancy_ok:
        return {
            "edgeStatus": "PROMISING_EDGE",
            "clientEdgeGatePassed": False,
            "reason": f"Win rate >= {min_win_rate:.0%}, but sample below proven threshold.",
        }

    if win_rate >= 0.55 and expectancy_ok:
        return {
            "edgeStatus": "EDGE_WATCHLIST",
            "clientEdgeGatePassed": False,
            "reason": "Edge is not strong enough for 65% target yet, but not weak.",
        }

    return {
        "edgeStatus": "EDGE_WEAK",
        "clientEdgeGatePassed": False,
        "reason": "Historical edge is below target or expectancy is not positive.",
    }


def _s870c_attach_calibrated_edge(audit, min_win_rate=0.65, proven_min_closed=30, promising_min_closed=10):
    if not isinstance(audit, dict):
        return audit

    enriched = dict(audit)
    setup_slug = enriched.get("setupSlug")
    symbol = enriched.get("symbol")

    stats = _s870c_edge_stats_from_sqlite(setup_slug, symbol=symbol)
    status = _s870c_edge_status(
        stats,
        min_win_rate=min_win_rate,
        proven_min_closed=proven_min_closed,
        promising_min_closed=promising_min_closed,
    )

    enriched["calibratedEdge"] = {
        "version": S870C_CALIBRATED_EDGE_GATE_VERSION,
        "targetWinRate": min_win_rate,
        "provenMinClosedTrades": proven_min_closed,
        "promisingMinClosedTrades": promising_min_closed,
        **stats,
        **status,
        "noHardLimitPolicy": {
            "doNotLimitBySetupCount": True,
            "doNotLimitBySymbolCount": True,
            "keepAllSignalsForLearning": True,
            "clientReleaseRequiresSignalQualityAndEdgeOrManualPolicy": True,
        },
    }
    enriched["edgeStatus"] = enriched["calibratedEdge"].get("edgeStatus")
    enriched["expectedWinRate"] = enriched["calibratedEdge"].get("expectedWinRate")
    enriched["clientEdgeGatePassed"] = enriched["calibratedEdge"].get("clientEdgeGatePassed")

    return enriched


def _s870c_edge_counts(audits):
    counts = {}
    for audit in audits:
        status = str((audit.get("calibratedEdge") or {}).get("edgeStatus") or "NOT_EVALUATED")
        counts[status] = counts.get(status, 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: kv[1], reverse=True))


# === /S8.70C Calibrated Edge Gate / No Hard Limit ============================


def _s870a_run_report(limit=50, publish=True, edge_min_win_rate=0.65, proven_min_closed_trades=30, promising_min_closed_trades=10):
    safe_limit = max(1, min(int(limit or 50), 100))
    unified = _s864_run_report(limit=safe_limit, publish=publish)
    internal = unified.get("internalOutput") if isinstance(unified, dict) else {}
    cards = internal.get("recentUnifiedCards") if isinstance(internal, dict) else []
    if not isinstance(cards, list):
        cards = []

    ready_cards = [card for card in cards if _s870a_is_ready_for_manual_review(card)]
    symbol_counts = _s870a_count_by(ready_cards, "symbol")
    setup_counts = _s870a_count_by(ready_cards, "setupSlug")
    audits = [
        _s870a_audit_card(
            card,
            duplicate_symbol_count=symbol_counts.get(str(card.get("symbol") or "unknown"), 1),
            duplicate_setup_count=setup_counts.get(str(card.get("setupSlug") or "unknown"), 1),
        )
        for card in ready_cards
    ]

    audits = [
        _s870c_attach_calibrated_edge(
            audit,
            min_win_rate=edge_min_win_rate,
            proven_min_closed=proven_min_closed_trades,
            promising_min_closed=promising_min_closed_trades,
        )
        for audit in audits
    ]
    edge_counts = _s870c_edge_counts(audits)
    client_edge_gate_passed = [item for item in audits if item.get("clientEdgeGatePassed") is True]

    passed = [item for item in audits if item.get("decision") == "PASS_READY_QUALITY"]
    review_required = [item for item in audits if item.get("decision") in ("REVIEW_REQUIRED", "REVIEW_HIGH_RISK")]
    critical = [item for item in audits if item.get("decision") == "FAIL_CRITICAL"]
    flag_counts = _s870a_flag_counts(audits)

    result = {
        "ok": True,
        "storageVersion": S870C_CALIBRATED_EDGE_GATE_VERSION,
        "baseAuditVersion": S870A_READY_QUALITY_AUDIT_VERSION,
        "baseRrSemanticsVersion": S870B_READY_QUALITY_RR_SEMANTICS_VERSION,
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "source": {
            "unifiedStorageVersion": unified.get("storageVersion") if isinstance(unified, dict) else None,
            "unifiedGeneratedAt": unified.get("generatedAt") if isinstance(unified, dict) else None,
            "limit": safe_limit,
            "publishUnified": bool(publish),
        },
        "summary": {
            "cardsEvaluated": len(cards),
            "readyInputCount": len(ready_cards),
            "passReadyQualityCount": len(passed),
            "reviewRequiredCount": len(review_required),
            "criticalFailCount": len(critical),
            "clientEdgeGatePassedCount": len(client_edge_gate_passed),
            "edgeStatusCounts": edge_counts,
            "edgeMinWinRate": edge_min_win_rate,
            "provenMinClosedTrades": proven_min_closed_trades,
            "promisingMinClosedTrades": promising_min_closed_trades,
            "topFlag": next(iter(flag_counts), None),
            "decisionState": (
                "READY_QUALITY_PASSED"
                if len(ready_cards) > 0 and len(passed) == len(ready_cards)
                else "READY_REVIEW_REQUIRED"
                if len(ready_cards) > 0 and len(critical) == 0
                else "READY_CRITICAL_ISSUES"
                if len(critical) > 0
                else "NO_READY_CANDIDATES"
            ),
        },
        "flagCounts": flag_counts,
        "setupCounts": dict(sorted(setup_counts.items(), key=lambda kv: kv[1], reverse=True)),
        "edgeGate": {
            "version": S870C_CALIBRATED_EDGE_GATE_VERSION,
            "enabled": True,
            "mode": "NO_HARD_LIMIT_RESEARCH_METADATA",
            "targetWinRate": edge_min_win_rate,
            "provenMinClosedTrades": proven_min_closed_trades,
            "promisingMinClosedTrades": promising_min_closed_trades,
            "doNotLimitBySetupCount": True,
            "doNotLimitBySymbolCount": True,
            "keepAllQualitySignalsForLearning": True,
            "clientReleaseRuleTarget": "quality gates + calibrated edge >= target OR explicit admin/manual policy",
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "doesNotChangeClientDelivery": True,
        },
        "audits": audits[:100],
        "policy": {
            "researchOnly": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "doesNotChangeClientDelivery": True,
            "manualApprovalStillRequired": True,
            "purpose": "Audit ready-for-manual-approval signals before trusting them as normal client signals.",
        },
    }

    out_dir = _s870a_reports_dir()
    latest = out_dir / "latest_s870a.json"
    stamp = str(result.get("generatedAt") or "").replace(":", "-").replace(".", "-")
    snapshot = out_dir / f"{stamp}.json"
    text = json.dumps(result, ensure_ascii=False, indent=2)
    latest.write_text(text, encoding="utf-8")
    snapshot.write_text(text, encoding="utf-8")
    return result


@app.post("/engine/research/ready-quality-audit/run")
def engine_research_ready_quality_audit_run(
    limit: int = 50,
    publish: bool = True,
    edge_min_win_rate: float = 0.65,
    proven_min_closed_trades: int = 30,
    promising_min_closed_trades: int = 10,
):
    return _s870a_run_report(
        limit=limit,
        publish=publish,
        edge_min_win_rate=edge_min_win_rate,
        proven_min_closed_trades=proven_min_closed_trades,
        promising_min_closed_trades=promising_min_closed_trades,
    )


@app.get("/engine/research/ready-quality-audit/latest")
def engine_research_ready_quality_audit_latest():
    latest = _s870a_reports_dir() / "latest_s870a.json"
    if not latest.exists():
        return {
            "ok": False,
            "storageVersion": S870A_READY_QUALITY_AUDIT_VERSION,
            "error": "No S8.70A ready candidate quality audit report yet. Run POST /engine/research/ready-quality-audit/run.",
        }
    return json.loads(latest.read_text(encoding="utf-8"))


# S8.70B Ready Quality RR Semantics Hotfix installed: reported RR now compares against max target R, TP1 remains strict >=2R.
# S8.70C Calibrated Edge Gate / No Hard Limit installed: every quality signal stays in research/output; edge is evaluated separately.

# === S8.70D Setup Calibration Segment Finder ================================
S870D_SETUP_CALIBRATION_SEGMENT_FINDER_VERSION = "s8_70d_setup_calibration_segment_finder_v1"


def _s870d_now_iso():
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).isoformat()


def _s870d_reports_dir():
    from pathlib import Path as _Path
    try:
        root = _Path(__file__).resolve().parents[2]
    except Exception:
        root = _Path(".")
    out_dir = root / "reports" / "setup_calibration_segments"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s870d_float(value, default=None):
    try:
        if value is None or value == "":
            return default
        return float(value)
    except Exception:
        return default


def _s870d_int(value, default=0):
    try:
        if value is None or value == "":
            return default
        return int(value)
    except Exception:
        return default


def _s870d_safe_div(num, den):
    try:
        den = float(den)
        if den == 0:
            return None
        return float(num) / den
    except Exception:
        return None


def _s870d_col(columns, *names):
    lowered = {str(col).lower(): col for col in columns}
    for name in names:
        match = lowered.get(str(name).lower())
        if match:
            return match
    return None


def _s870d_db_candidates():
    if "_s870c_edge_db_candidates" in globals():
        try:
            return _s870c_edge_db_candidates()
        except Exception:
            pass

    from pathlib import Path as _Path
    try:
        root = _Path(__file__).resolve().parents[2]
    except Exception:
        root = _Path(".")

    dirs = [root / "data", root / "app" / "data", root / "reports"]
    found = []
    seen = set()

    for directory in dirs:
        try:
            if not directory.exists():
                continue
            for pattern in ("*.db", "*.sqlite", "*.sqlite3"):
                for path in directory.rglob(pattern):
                    key = str(path.resolve())
                    if key in seen:
                        continue
                    if ".venv" in key or "__pycache__" in key:
                        continue
                    seen.add(key)
                    found.append(path)
        except Exception:
            continue

    return found[:30]


def _s870d_outcome_kind(row, result_col=None, status_col=None, r_col=None):
    if "_s870c_edge_outcome_kind" in globals():
        try:
            return _s870c_edge_outcome_kind(row, result_col=result_col, status_col=status_col, r_col=r_col)
        except Exception:
            pass

    text_parts = []
    if result_col and result_col in row:
        text_parts.append(str(row.get(result_col) or ""))
    if status_col and status_col in row:
        text_parts.append(str(row.get(status_col) or ""))

    text = " ".join(text_parts).upper()
    result_r = _s870d_float(row.get(r_col)) if r_col and r_col in row else None

    if any(token in text for token in ("WORKED", "TP1", "TP2", "TARGET", "WIN")):
        return "WIN", result_r
    if any(token in text for token in ("FAILED", "STOP", "LOSS")):
        return "LOSS", result_r

    if result_r is not None:
        if result_r > 0:
            return "WIN", result_r
        if result_r < 0:
            return "LOSS", result_r

    return "OPEN_OR_UNKNOWN", result_r


def _s870d_bucket_score(score):
    score = _s870d_float(score)
    if score is None:
        return "UNKNOWN"
    if score >= 98:
        return "SCORE_98_100"
    if score >= 95:
        return "SCORE_95_97"
    if score >= 90:
        return "SCORE_90_94"
    if score >= 85:
        return "SCORE_85_89"
    if score >= 78:
        return "SCORE_78_84"
    return "SCORE_BELOW_78"


def _s870d_bucket_rr(rr):
    rr = _s870d_float(rr)
    if rr is None:
        return "UNKNOWN"
    if rr >= 3:
        return "RR_3_PLUS"
    if rr >= 2.5:
        return "RR_2_5_2_99"
    if rr >= 2:
        return "RR_2_2_49"
    return "RR_BELOW_2"


def _s870d_bucket_stop_distance(stop_pct):
    stop_pct = _s870d_float(stop_pct)
    if stop_pct is None:
        return "UNKNOWN"
    if stop_pct < 0.12:
        return "STOP_TOO_TIGHT_LT_0_12"
    if stop_pct < 1:
        return "STOP_0_12_0_99"
    if stop_pct <= 2.5:
        return "STOP_1_0_2_5"
    if stop_pct <= 4:
        return "STOP_2_5_4_0"
    if stop_pct <= 8:
        return "STOP_4_0_8_0"
    return "STOP_GT_8"


def _s870d_normal_text(value, fallback="UNKNOWN"):
    text = str(value or "").strip()
    if not text:
        return fallback
    return text.upper().replace(" ", "_")


def _s870d_extract_stop_distance(row, entry_col=None, stop_col=None, stop_distance_col=None):
    direct = _s870d_float(row.get(stop_distance_col)) if stop_distance_col and stop_distance_col in row else None
    if direct is not None:
        return direct

    entry = _s870d_float(row.get(entry_col)) if entry_col and entry_col in row else None
    stop = _s870d_float(row.get(stop_col)) if stop_col and stop_col in row else None
    if entry is None or stop is None or entry == 0:
        return None

    return round(abs(entry - stop) / abs(entry) * 100.0, 4)


def _s870d_extract_normalized_rows(max_rows=100000):
    import sqlite3

    out = []
    sources = []
    max_rows = max(1000, min(int(max_rows or 100000), 300000))

    for db_path in _s870d_db_candidates():
        if len(out) >= max_rows:
            break

        conn = None
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=2)
            conn.row_factory = sqlite3.Row
            tables = conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
        except Exception:
            try:
                if conn:
                    conn.close()
            except Exception:
                pass
            continue

        for table_row in tables:
            if len(out) >= max_rows:
                break

            table = table_row[0]
            try:
                info = conn.execute(f'PRAGMA table_info("{table}")').fetchall()
                columns = [row[1] for row in info]
                if not columns:
                    continue

                setup_col = _s870d_col(columns, "setup_slug", "setupSlug", "setup", "strategy_slug", "strategySlug")
                if not setup_col:
                    continue

                result_col = _s870d_col(columns, "result", "outcome", "outcome_status", "outcomeStatus", "result_status", "resultStatus", "first_event", "firstEvent")
                status_col = _s870d_col(columns, "status", "state", "lifecycle_status", "lifecycleStatus")
                r_col = _s870d_col(columns, "result_r", "resultR", "r_multiple", "rMultiple", "pnl_r", "pnlR", "realized_r", "realizedR")

                if not result_col and not status_col and not r_col:
                    continue

                symbol_col = _s870d_col(columns, "symbol", "ticker")
                direction_col = _s870d_col(columns, "direction", "side", "signal_direction", "signalDirection")
                grade_col = _s870d_col(columns, "signal_grade", "signalGrade", "grade")
                quality_col = _s870d_col(columns, "quality_status", "qualityStatus", "quality", "quality_gate", "qualityGate")
                score_col = _s870d_col(columns, "signal_score", "signalScore", "score", "confidence")
                rr_col = _s870d_col(columns, "risk_reward", "riskReward", "rr", "reported_rr", "reportedRR")
                session_col = _s870d_col(columns, "session", "market_session", "marketSession", "session_type", "sessionType")
                engine_col = _s870d_col(columns, "engine_version", "engineVersion", "algorithm_version", "algorithmVersion", "storage_version", "storageVersion")
                regime_col = _s870d_col(columns, "market_regime", "marketRegime", "regime")
                trigger_col = _s870d_col(columns, "trigger", "trigger_type", "triggerType", "triggers")
                entry_col = _s870d_col(columns, "entry", "entry_price", "entryPrice")
                stop_col = _s870d_col(columns, "stop", "stop_price", "stopPrice")
                stop_distance_col = _s870d_col(columns, "stop_distance_pct", "stopDistancePct", "stop_pct", "stopPct")

                limit_left = max_rows - len(out)
                rows = conn.execute(f'SELECT * FROM "{table}" LIMIT {limit_left}').fetchall()

                table_closed = 0
                for raw in rows:
                    row = dict(raw)
                    setup_slug = str(row.get(setup_col) or "").strip()
                    if not setup_slug:
                        continue

                    kind, result_r = _s870d_outcome_kind(row, result_col=result_col, status_col=status_col, r_col=r_col)
                    if kind not in ("WIN", "LOSS"):
                        continue

                    score = _s870d_float(row.get(score_col)) if score_col and score_col in row else None
                    rr = _s870d_float(row.get(rr_col)) if rr_col and rr_col in row else None
                    stop_distance = _s870d_extract_stop_distance(row, entry_col=entry_col, stop_col=stop_col, stop_distance_col=stop_distance_col)

                    normalized = {
                        "setupSlug": setup_slug,
                        "symbol": str(row.get(symbol_col) or "").upper() if symbol_col and symbol_col in row else None,
                        "result": kind,
                        "isWin": kind == "WIN",
                        "resultR": result_r,
                        "hasRealR": result_r is not None,
                        "score": score,
                        "scoreBucket": _s870d_bucket_score(score),
                        "riskReward": rr,
                        "rrBucket": _s870d_bucket_rr(rr),
                        "stopDistancePct": stop_distance,
                        "stopDistanceBucket": _s870d_bucket_stop_distance(stop_distance),
                        "direction": _s870d_normal_text(row.get(direction_col), "UNKNOWN") if direction_col and direction_col in row else "UNKNOWN",
                        "grade": _s870d_normal_text(row.get(grade_col), "UNKNOWN") if grade_col and grade_col in row else "UNKNOWN",
                        "qualityStatus": _s870d_normal_text(row.get(quality_col), "UNKNOWN") if quality_col and quality_col in row else "UNKNOWN",
                        "session": _s870d_normal_text(row.get(session_col), "UNKNOWN") if session_col and session_col in row else "UNKNOWN",
                        "marketRegime": _s870d_normal_text(row.get(regime_col), "UNKNOWN") if regime_col and regime_col in row else "UNKNOWN",
                        "triggerType": _s870d_normal_text(row.get(trigger_col), "UNKNOWN") if trigger_col and trigger_col in row else "UNKNOWN",
                        "engineVersion": _s870d_normal_text(row.get(engine_col), "UNKNOWN") if engine_col and engine_col in row else "UNKNOWN",
                        "source": {"db": str(db_path), "table": table},
                    }
                    out.append(normalized)
                    table_closed += 1

                if table_closed > 0:
                    sources.append({
                        "db": str(db_path),
                        "table": table,
                        "closedRows": table_closed,
                        "columns": columns[:80],
                    })

            except Exception:
                continue

        try:
            conn.close()
        except Exception:
            pass

    return out, sources


def _s870d_segment_key(setup_slug, filters):
    if not filters:
        return f"{setup_slug}::ALL"
    return f"{setup_slug}::" + "|".join([f"{k}={v}" for k, v in filters])


def _s870d_segment_stats(setup_slug, filters, rows, min_win_rate=0.65, min_closed=30, min_promising_closed=10):
    closed = len(rows)
    wins = sum(1 for row in rows if row.get("isWin") is True)
    losses = closed - wins
    win_rate = _s870d_safe_div(wins, closed)

    real_r_values = [row.get("resultR") for row in rows if row.get("resultR") is not None]
    avg_r = round(sum(real_r_values) / len(real_r_values), 4) if real_r_values else None

    estimated_expectancy_r = round(((wins * 2.0) + (losses * -1.0)) / closed, 4) if closed > 0 else None
    expectancy_r = avg_r

    filter_count = len(filters)
    if closed < min_promising_closed:
        sample_quality = "TOO_SMALL"
    elif closed < min_closed:
        sample_quality = "SMALL_SAMPLE"
    elif closed < (min_closed * 2):
        sample_quality = "OK_BUT_THIN"
    else:
        sample_quality = "OK"

    if closed < min_closed:
        overfit_risk = "HIGH"
    elif filter_count >= 3 and closed < (min_closed * 3):
        overfit_risk = "MEDIUM"
    else:
        overfit_risk = "LOW"

    expectancy_ok = expectancy_r is not None and expectancy_r > 0
    winrate_ok = win_rate is not None and win_rate >= min_win_rate
    sample_ok = closed >= min_closed
    real_r_ok = len(real_r_values) >= max(5, int(closed * 0.5))

    production_eligible = bool(sample_ok and winrate_ok and expectancy_ok and real_r_ok and overfit_risk != "HIGH")
    promising = bool(closed >= min_promising_closed and winrate_ok and expectancy_ok and real_r_ok)

    if production_eligible:
        status = "PRODUCTION_ELIGIBLE"
    elif promising:
        status = "PROMISING_SEGMENT"
    elif sample_quality in ("TOO_SMALL", "SMALL_SAMPLE"):
        status = "INSUFFICIENT_SAMPLE"
    elif not winrate_ok:
        status = "WINRATE_BELOW_TARGET"
    elif not expectancy_ok:
        status = "EXPECTANCY_NOT_PROVEN"
    elif not real_r_ok:
        status = "MISSING_REAL_R_EVIDENCE"
    else:
        status = "NOT_ELIGIBLE"

    return {
        "segmentId": _s870d_segment_key(setup_slug, filters),
        "setupSlug": setup_slug,
        "filters": [{"field": k, "value": v} for k, v in filters],
        "filterCount": filter_count,
        "closedTrades": closed,
        "wins": wins,
        "losses": losses,
        "winRate": round(win_rate, 4) if win_rate is not None else None,
        "avgR": avg_r,
        "expectancyR": expectancy_r,
        "estimatedExpectancyRConservative": estimated_expectancy_r,
        "realRCount": len(real_r_values),
        "sampleQuality": sample_quality,
        "overfitRisk": overfit_risk,
        "status": status,
        "productionEligible": production_eligible,
        "promising": promising,
        "targetWinRate": min_win_rate,
        "rules": {
            "minWinRate": min_win_rate,
            "minClosedTrades": min_closed,
            "minPromisingClosedTrades": min_promising_closed,
            "requiresPositiveRealExpectancyR": True,
            "requiresRealREvidence": True,
            "doesNotUseEstimatedRForProduction": True,
        },
    }


def _s870d_build_segments(rows, min_win_rate=0.65, min_closed=30, min_promising_closed=10):
    by_setup = {}
    for row in rows:
        by_setup.setdefault(row.get("setupSlug"), []).append(row)

    all_segments = []
    per_setup = []

    dimensions = [
        "direction",
        "grade",
        "qualityStatus",
        "scoreBucket",
        "rrBucket",
        "stopDistanceBucket",
        "session",
        "marketRegime",
        "triggerType",
        "engineVersion",
    ]

    pair_dimensions = [
        ("scoreBucket", "grade"),
        ("scoreBucket", "rrBucket"),
        ("scoreBucket", "stopDistanceBucket"),
        ("grade", "qualityStatus"),
        ("direction", "scoreBucket"),
        ("session", "scoreBucket"),
        ("marketRegime", "scoreBucket"),
        ("triggerType", "scoreBucket"),
    ]

    for setup_slug, setup_rows in sorted(by_setup.items()):
        segment_map = {}
        segment_map[()] = setup_rows

        for dim in dimensions:
            values = {}
            for row in setup_rows:
                value = row.get(dim) or "UNKNOWN"
                if value == "UNKNOWN":
                    continue
                values.setdefault(value, []).append(row)
            for value, subset in values.items():
                segment_map[((dim, value),)] = subset

        for d1, d2 in pair_dimensions:
            values = {}
            for row in setup_rows:
                v1 = row.get(d1) or "UNKNOWN"
                v2 = row.get(d2) or "UNKNOWN"
                if v1 == "UNKNOWN" or v2 == "UNKNOWN":
                    continue
                values.setdefault((v1, v2), []).append(row)
            for (v1, v2), subset in values.items():
                segment_map[((d1, v1), (d2, v2))] = subset

        setup_segments = [
            _s870d_segment_stats(
                setup_slug,
                list(filters),
                subset,
                min_win_rate=min_win_rate,
                min_closed=min_closed,
                min_promising_closed=min_promising_closed,
            )
            for filters, subset in segment_map.items()
        ]

        setup_segments = sorted(
            setup_segments,
            key=lambda item: (
                1 if item.get("productionEligible") else 0,
                1 if item.get("promising") else 0,
                item.get("winRate") or 0,
                item.get("expectancyR") if item.get("expectancyR") is not None else -999,
                item.get("closedTrades") or 0,
            ),
            reverse=True,
        )

        baseline = next((item for item in setup_segments if item.get("filterCount") == 0), None)
        eligible = [item for item in setup_segments if item.get("productionEligible")]
        promising = [item for item in setup_segments if item.get("promising") and not item.get("productionEligible")]

        all_segments.extend(setup_segments)
        per_setup.append({
            "setupSlug": setup_slug,
            "baseline": baseline,
            "productionEligibleCount": len(eligible),
            "promisingCount": len(promising),
            "bestProductionEligibleSegments": eligible[:10],
            "bestPromisingSegments": promising[:10],
            "bestSegmentsOverall": setup_segments[:15],
            "calibrationAction": (
                "PROMOTE_SEGMENTS_TO_SHADOW_PRODUCTION_REVIEW"
                if eligible
                else "FORWARD_TEST_PROMISING_SEGMENTS"
                if promising
                else "NEEDS_REWORK_OR_STRICTER_FILTERS"
            ),
        })

    all_segments = sorted(
        all_segments,
        key=lambda item: (
            1 if item.get("productionEligible") else 0,
            1 if item.get("promising") else 0,
            item.get("winRate") or 0,
            item.get("expectancyR") if item.get("expectancyR") is not None else -999,
            item.get("closedTrades") or 0,
        ),
        reverse=True,
    )

    return per_setup, all_segments


def _s870d_run_report(
    min_win_rate=0.65,
    min_closed_trades=30,
    min_promising_closed_trades=10,
    max_rows=100000,
    publish=True,
):
    import json

    min_win_rate = max(0.50, min(float(min_win_rate or 0.65), 0.95))
    min_closed_trades = max(5, min(int(min_closed_trades or 30), 500))
    min_promising_closed_trades = max(3, min(int(min_promising_closed_trades or 10), min_closed_trades))
    max_rows = max(1000, min(int(max_rows or 100000), 300000))

    rows, sources = _s870d_extract_normalized_rows(max_rows=max_rows)
    per_setup, all_segments = _s870d_build_segments(
        rows,
        min_win_rate=min_win_rate,
        min_closed=min_closed_trades,
        min_promising_closed=min_promising_closed_trades,
    )

    eligible = [item for item in all_segments if item.get("productionEligible")]
    promising = [item for item in all_segments if item.get("promising") and not item.get("productionEligible")]
    setup_count = len({row.get("setupSlug") for row in rows if row.get("setupSlug")})

    result = {
        "ok": True,
        "storageVersion": S870D_SETUP_CALIBRATION_SEGMENT_FINDER_VERSION,
        "generatedAt": _s870d_now_iso(),
        "summary": {
            "closedRowsLoaded": len(rows),
            "sourceTableCount": len(sources),
            "setupCount": setup_count,
            "segmentsEvaluated": len(all_segments),
            "productionEligibleSegmentCount": len(eligible),
            "promisingSegmentCount": len(promising),
            "targetWinRate": min_win_rate,
            "minClosedTrades": min_closed_trades,
            "minPromisingClosedTrades": min_promising_closed_trades,
            "decisionState": (
                "PRODUCTION_ELIGIBLE_SEGMENTS_FOUND"
                if eligible
                else "PROMISING_SEGMENTS_FOUND"
                if promising
                else "NO_65_PERCENT_SEGMENTS_FOUND_YET"
            ),
        },
        "policy": {
            "goal": "Find honest 65%+ winrate segments per SkillEdge AI setup/strategy.",
            "noFakeStats": True,
            "usesOnlyClosedOutcomes": True,
            "openSessionCloseNoEvalExcluded": True,
            "requiresPositiveRealExpectancyR": True,
            "requiresRealREvidenceForProduction": True,
            "doesNotUseEstimatedRForProduction": True,
            "doesNotLimitBySetupCount": True,
            "doesNotLimitBySymbolCount": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "doesNotChangeClientDelivery": True,
        },
        "sources": sources[:30],
        "productionEligibleSegments": eligible[:50],
        "promisingSegments": promising[:50],
        "perSetup": per_setup,
        "topSegmentsOverall": all_segments[:100],
    }

    if publish:
        out_dir = _s870d_reports_dir()
        latest = out_dir / "latest_s870d.json"
        stamp = str(result.get("generatedAt") or "").replace(":", "-").replace(".", "-")
        snapshot = out_dir / f"{stamp}.json"
        payload = json.dumps(result, ensure_ascii=False, indent=2)
        latest.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return result


@app.post("/engine/research/setup-calibration-segments/run")
def engine_research_setup_calibration_segments_run(
    min_win_rate: float = 0.65,
    min_closed_trades: int = 30,
    min_promising_closed_trades: int = 10,
    max_rows: int = 100000,
    publish: bool = True,
):
    return _s870d_run_report(
        min_win_rate=min_win_rate,
        min_closed_trades=min_closed_trades,
        min_promising_closed_trades=min_promising_closed_trades,
        max_rows=max_rows,
        publish=publish,
    )


