# === S8.71A Historical Backtest Learning Engine =============================
S871A_HISTORICAL_BACKTEST_LEARNING_VERSION = "s8_71a_historical_backtest_learning_plan_v1"


def _s871a_now_iso():
    from datetime import datetime, timezone

    return datetime.now(timezone.utc).isoformat()


def _s871a_data_lake_dir():
    root = _s870e_root_dir() / "data" / "historical_learning"
    for child in (
        "jobs",
        "raw_candles",
        "normalized_candles",
        "features",
        "setup_candidates",
        "simulated_outcomes",
        "segments",
        "walk_forward",
        "policies",
        "admin_reports",
    ):
        (root / child).mkdir(parents=True, exist_ok=True)
    return root


def _s871a_reports_dir():
    out_dir = _s870e_root_dir() / "reports" / "historical_learning"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s871a_load_strategy_policy():
    try:
        policy = _s870f_load_strategy_policy()
        return policy if isinstance(policy, dict) else None
    except Exception:
        return None


def _s871a_strategy_slugs_from_policy(policy):
    if not isinstance(policy, dict):
        return []
    strategies = policy.get("strategies")
    if not isinstance(strategies, dict):
        return []
    return sorted([str(k) for k in strategies.keys() if k])


def _s871a_job_phase(name, description, output_table, status="PENDING"):
    return {
        "name": name,
        "status": status,
        "description": description,
        "output": output_table,
    }


def _s871a_build_learning_plan(
    years_back=5,
    end_date=None,
    universe_mode="dynamic_us_equities_in_play",
    intervals="1min,5min,1day",
    max_symbols_per_day=5000,
    target_win_rate=0.65,
    min_closed_trades=30,
    min_validation_windows=3,
    publish=True,
):
    import json
    from datetime import date

    data_lake = _s871a_data_lake_dir()
    policy = _s871a_load_strategy_policy()
    strategy_slugs = _s871a_strategy_slugs_from_policy(policy)

    clean_intervals = []
    for item in str(intervals or "1min,5min,1day").split(","):
        item = item.strip()
        if item and item not in clean_intervals:
            clean_intervals.append(item)

    if not end_date:
        end_date = str(date.today())

    years_back = max(1, min(int(years_back or 5), 10))
    max_symbols_per_day = max(100, min(int(max_symbols_per_day or 5000), 25000))
    target_win_rate = max(0.50, min(float(target_win_rate or 0.65), 0.95))
    min_closed_trades = max(5, min(int(min_closed_trades or 30), 1000))
    min_validation_windows = max(1, min(int(min_validation_windows or 3), 20))

    job_id = f"s871a_{str(end_date).replace('-', '')}_{years_back}y"

    phases = [
        _s871a_job_phase(
            "DATA_LAKE_BOOTSTRAP",
            "Create persistent folders/tables for raw candles, normalized candles, features, setup candidates, simulated outcomes and calibration reports.",
            "data/historical_learning/*",
            status="READY",
        ),
        _s871a_job_phase(
            "SYMBOL_UNIVERSE_BUILD",
            "Build each historical trading day's universe without lookahead: in-play stocks, liquid large caps, small/mid cap movers, and strategy-relevant tickers available up to that day.",
            "historical_symbol_universe",
        ),
        _s871a_job_phase(
            "CANDLE_INGESTION",
            "Download/store historical 1m/5m/daily candles and extended-hours data where provider allows it.",
            "historical_candles",
        ),
        _s871a_job_phase(
            "FEATURE_BUILD",
            "Compute VWAP, EMA20, ATR14, RSI14, RVOL, gap %, range %, volume acceleration, session structure and regime fields.",
            "historical_features",
        ),
        _s871a_job_phase(
            "SETUP_REPLAY",
            "Replay every strategy as if the engine lived at that moment. No future candles are allowed in trigger decisions.",
            "historical_setup_candidates",
        ),
        _s871a_job_phase(
            "OUTCOME_SIMULATION",
            "Simulate entry/stop/targets/session-to-close outcomes with realistic RR, spread/slippage placeholders and no hindsight.",
            "historical_simulated_outcomes",
        ),
        _s871a_job_phase(
            "SEGMENT_SEARCH",
            "Search honest segments by setup, direction, grade, score bucket, RR, stop distance, session, trigger type and market regime.",
            "historical_calibration_segments",
        ),
        _s871a_job_phase(
            "WALK_FORWARD_VALIDATION",
            "Validate 65%+ segments across train/validation/out-of-sample windows and reject overfit segments.",
            "historical_walk_forward_results",
        ),
        _s871a_job_phase(
            "POLICY_PROMOTION",
            "Promote only proven segments to production-candidate policy; weak/unproven setups stay shadow/research only.",
            "strategy_calibration_policy",
        ),
        _s871a_job_phase(
            "ADMIN_REPORT",
            "Write Admin Hub feed: what AI tested, what changed, what stayed blocked, what moved to forward-test.",
            "admin_ai_ops_feed",
        ),
    ]

    result = {
        "ok": True,
        "storageVersion": S871A_HISTORICAL_BACKTEST_LEARNING_VERSION,
        "generatedAt": _s871a_now_iso(),
        "job": {
            "jobId": job_id,
            "status": "PLANNED_NOT_RUNNING",
            "yearsBack": years_back,
            "endDate": end_date,
            "universeMode": universe_mode,
            "maxSymbolsPerDay": max_symbols_per_day,
            "intervals": clean_intervals,
            "strategyCount": len(strategy_slugs),
            "strategySlugs": strategy_slugs,
        },
        "dataLake": {
            "root": str(data_lake),
            "jobs": str(data_lake / "jobs"),
            "rawCandles": str(data_lake / "raw_candles"),
            "normalizedCandles": str(data_lake / "normalized_candles"),
            "features": str(data_lake / "features"),
            "setupCandidates": str(data_lake / "setup_candidates"),
            "simulatedOutcomes": str(data_lake / "simulated_outcomes"),
            "segments": str(data_lake / "segments"),
            "walkForward": str(data_lake / "walk_forward"),
            "policies": str(data_lake / "policies"),
            "adminReports": str(data_lake / "admin_reports"),
        },
        "learningGoal": {
            "targetWinRate": target_win_rate,
            "minClosedTrades": min_closed_trades,
            "minValidationWindows": min_validation_windows,
            "requiresPositiveAvgR": True,
            "requiresPositiveExpectancyR": True,
            "requiresOutOfSamplePass": True,
            "requiresForwardShadowPassBeforeClient": True,
            "rejectOverfitRiskHigh": True,
            "realisticSlippageSpreadRequired": True,
        },
        "phases": phases,
        "policy": {
            "autonomousHistoricalLearning": True,
            "noFakeStats": True,
            "noLookahead": True,
            "clientEligibilityRequiresProof": True,
            "doesNotChangeClientDeliveryInThisStep": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "doesNotLimitBySetupCount": True,
            "doesNotLimitBySymbolCount": True,
        },
        "nextEngineeringStep": "S8.71B Historical Data Ingestion Worker: start downloading/storing candles by date/symbol/interval and track ingestion progress.",
    }

    if publish:
        jobs_dir = data_lake / "jobs"
        job_path = jobs_dir / f"{job_id}.json"
        latest_job = jobs_dir / "latest_s871a_job.json"

        reports_dir = _s871a_reports_dir()
        latest_report = reports_dir / "latest_s871a_plan.json"

        payload = json.dumps(result, ensure_ascii=False, indent=2)
        job_path.write_text(payload, encoding="utf-8")
        latest_job.write_text(payload, encoding="utf-8")
        latest_report.write_text(payload, encoding="utf-8")

    return result


