# === S8.71B2 Historical Ingestion Provider Compatibility Adapter =============
S871B2_HISTORICAL_INGESTION_PROVIDER_COMPAT_VERSION = "s8_71b2_historical_ingestion_provider_compat_v1"


def _s871b2_row_date_key(row):
    value = None
    if isinstance(row, dict):
        value = row.get("date") or row.get("datetime") or row.get("timestamp") or row.get("time")
    text = str(value or "").strip()
    if len(text) >= 10 and text[4:5] == "-" and text[7:8] == "-":
        return text[:10]
    return ""


def _s871b2_filter_rows_by_date(rows, start_date, end_date):
    out = []
    for row in rows or []:
        date_key = _s871b2_row_date_key(row)
        if not date_key:
            continue
        if str(start_date) <= date_key <= str(end_date):
            out.append(row)
    return out


async def _s871b2_fetch_engine_client_rows(client, symbol, interval, start_date, end_date):
    normalized_interval = str(interval or "5min").lower().strip()
    clean_symbol = str(symbol or "").upper().strip()

    if normalized_interval in {"1day", "daily"}:
        attempts = [
            ("historical-price-full/" + clean_symbol, {"from": start_date, "to": end_date}, True),
            ("historical-price-full", {"symbol": clean_symbol, "from": start_date, "to": end_date}, False),
        ]

        last_error = None
        for path, params, legacy in attempts:
            try:
                payload = await client.get_json(path, params, legacy=legacy)
                if isinstance(payload, dict) and isinstance(payload.get("historical"), list):
                    rows = payload.get("historical") or []
                elif isinstance(payload, list):
                    rows = payload
                else:
                    rows = []
                return {
                    "ok": True,
                    "providerMode": "engine_fmp_client_daily",
                    "transport": "FmpClient.get_json",
                    "rows": _s871b2_filter_rows_by_date(rows, start_date, end_date),
                    "rawRows": rows,
                    "attempt": {"path": path, "legacy": legacy},
                }
            except Exception as exc:
                last_error = str(exc)

        return {
            "ok": False,
            "providerMode": "engine_fmp_client_daily",
            "transport": "FmpClient.get_json",
            "rows": [],
            "rawRows": [],
            "error": last_error or "daily_fetch_failed",
        }

    try:
        rows = await client.get_intraday_candles(clean_symbol, interval=normalized_interval)
        filtered = _s871b2_filter_rows_by_date(rows, start_date, end_date)
        return {
            "ok": True,
            "providerMode": "engine_fmp_client_intraday",
            "transport": "FmpClient.get_intraday_candles",
            "rows": filtered,
            "rawRows": rows,
            "rawRowCountBeforeDateFilter": len(rows or []),
        }
    except Exception as exc:
        return {
            "ok": False,
            "providerMode": "engine_fmp_client_intraday",
            "transport": "FmpClient.get_intraday_candles",
            "rows": [],
            "rawRows": [],
            "error": str(exc),
        }


async def _s871b2_run_ingestion_compatible(
    symbols=None,
    start_date=None,
    end_date=None,
    intervals="5min",
    max_symbols=10,
    provider="engine_fmp_client",
    publish=True,
):
    import json

    start_date, end_date = _s871b_default_dates(start_date=start_date, end_date=end_date)
    symbol_list = _s871b_parse_symbols(symbols)
    interval_list = _s871b_parse_intervals(intervals)

    if not symbol_list:
        symbol_list = ["AAPL", "NVDA", "TSLA", "SPY", "QQQ"]

    max_symbols = max(1, min(int(max_symbols or 10), 250))
    symbol_list = symbol_list[:max_symbols]

    client = FmpClient()
    configured = bool(client.is_configured())
    data_lake = _s871a_data_lake_dir()

    manifest = {
        "ok": True,
        "storageVersion": S871B_HISTORICAL_DATA_INGESTION_VERSION,
        "compatVersion": S871B2_HISTORICAL_INGESTION_PROVIDER_COMPAT_VERSION,
        "generatedAt": _s871b_now_iso(),
        "provider": provider,
        "providerReady": configured,
        "providerMode": "engine_fmp_client",
        "dateRange": {"startDate": start_date, "endDate": end_date},
        "symbolsRequested": symbol_list,
        "intervalsRequested": interval_list,
        "maxSymbols": max_symbols,
        "summary": {
            "requestsAttempted": 0,
            "requestsSucceeded": 0,
            "requestsFailed": 0,
            "rawRowsStored": 0,
            "normalizedRowsStored": 0,
            "symbolCount": len(symbol_list),
            "intervalCount": len(interval_list),
        },
        "files": [],
        "errors": [],
        "policy": {
            "usesExistingEngineFmpClient": True,
            "doesNotChangeClientDelivery": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "doesNotFabricateData": True,
            "chunkedHistoricalIngestion": True,
        },
        "nextEngineeringStep": "S8.71C Historical Feature Builder: compute VWAP/EMA/ATR/RSI/RVOL/gap/range/session features from normalized candles.",
    }

    if not configured:
        manifest["ok"] = False
        manifest["errors"].append({
            "type": "provider_not_configured",
            "message": "Existing FmpClient is not configured. Check .env.server and app.config get_settings().",
        })
        return manifest

    for symbol in symbol_list:
        for interval in interval_list:
            manifest["summary"]["requestsAttempted"] += 1

            try:
                fetched = await _s871b2_fetch_engine_client_rows(
                    client=client,
                    symbol=symbol,
                    interval=interval,
                    start_date=start_date,
                    end_date=end_date,
                )

                raw_rows = fetched.get("rows") or []
                raw_ok = bool(fetched.get("ok"))

                interval_safe = _s871b_safe_name(interval)
                symbol_safe = _s871b_safe_name(symbol)
                date_safe = f"{_s871b_safe_name(start_date)}_{_s871b_safe_name(end_date)}"

                raw_path = data_lake / "raw_candles" / interval_safe / symbol_safe / f"{date_safe}.json"
                norm_path = data_lake / "normalized_candles" / interval_safe / symbol_safe / f"{date_safe}.jsonl"

                if not raw_ok:
                    manifest["summary"]["requestsFailed"] += 1
                    manifest["errors"].append({
                        "type": "provider_error",
                        "symbol": symbol,
                        "interval": interval,
                        "providerMode": fetched.get("providerMode"),
                        "transport": fetched.get("transport"),
                        "message": fetched.get("error") or "provider_fetch_failed",
                    })
                    continue

                normalized = []
                for row in raw_rows:
                    item = _s871b_normalize_candle(symbol, interval, row)
                    if item:
                        normalized.append(item)

                _s871b_write_json(raw_path, {
                    "symbol": symbol,
                    "interval": interval,
                    "startDate": start_date,
                    "endDate": end_date,
                    "source": "engine_fmp_client",
                    "providerMode": fetched.get("providerMode"),
                    "transport": fetched.get("transport"),
                    "ingestedAt": _s871b_now_iso(),
                    "rowCount": len(raw_rows),
                    "rawRowCountBeforeDateFilter": fetched.get("rawRowCountBeforeDateFilter"),
                    "rows": raw_rows,
                })
                _s871b_write_jsonl(norm_path, normalized)

                manifest["summary"]["requestsSucceeded"] += 1
                manifest["summary"]["rawRowsStored"] += len(raw_rows)
                manifest["summary"]["normalizedRowsStored"] += len(normalized)
                manifest["files"].append({
                    "symbol": symbol,
                    "interval": interval,
                    "providerMode": fetched.get("providerMode"),
                    "transport": fetched.get("transport"),
                    "rawPath": str(raw_path),
                    "normalizedPath": str(norm_path),
                    "rawRows": len(raw_rows),
                    "normalizedRows": len(normalized),
                    "rawRowCountBeforeDateFilter": fetched.get("rawRowCountBeforeDateFilter"),
                })

            except Exception as exc:
                manifest["summary"]["requestsFailed"] += 1
                manifest["errors"].append({
                    "type": "exception",
                    "symbol": symbol,
                    "interval": interval,
                    "message": str(exc),
                })

    if publish:
        reports_dir = _s871b_reports_dir()
        latest_report = reports_dir / "latest_s871b_ingestion.json"
        stamp = str(manifest.get("generatedAt") or "").replace(":", "-").replace(".", "-")
        snapshot = reports_dir / f"{stamp}.json"

        jobs_dir = data_lake / "jobs"
        latest_job = jobs_dir / "latest_s871b_ingestion.json"

        payload = json.dumps(manifest, ensure_ascii=False, indent=2)
        latest_report.write_text(payload, encoding="utf-8")
        latest_job.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return manifest


# === /S8.71B2 Historical Ingestion Provider Compatibility Adapter ============

# === S8.71C Historical Feature Builder ======================================
S871C_HISTORICAL_FEATURE_BUILDER_VERSION = "s8_71c_historical_feature_builder_v1"


def _s871c_reports_dir():
    out_dir = _s870e_root_dir() / "reports" / "historical_learning" / "features"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s871c_parse_symbols(symbols):
    parsed = _s871b_parse_symbols(symbols)
    return parsed


def _s871c_parse_intervals(intervals):
    return _s871b_parse_intervals(intervals or "1min,5min")


def _s871c_read_jsonl(path):
    import json

    rows = []
    try:
        with path.open("r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    item = json.loads(line)
                    if isinstance(item, dict):
                        rows.append(item)
                except Exception:
                    continue
    except Exception:
        return []
    return rows


def _s871c_write_jsonl(path, rows):
    import json

    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")


def _s871c_write_json(path, payload):
    import json

    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


def _s871c_num(value):
    try:
        if value is None or value == "":
            return None
        return float(value)
    except Exception:
        return None


def _s871c_datetime_text(row):
    if not isinstance(row, dict):
        return ""
    return str(row.get("datetime") or row.get("date") or row.get("timestamp") or row.get("time") or "").strip()


def _s871c_date_key(row):
    text = _s871c_datetime_text(row)
    if len(text) >= 10 and text[4:5] == "-" and text[7:8] == "-":
        return text[:10]
    return ""


def _s871c_time_hhmm(row):
    text = _s871c_datetime_text(row)
    if len(text) >= 16 and text[10:11] in {" ", "T"}:
        return text[11:16]
    return ""


def _s871c_session_bucket(row):
    hhmm = _s871c_time_hhmm(row)
    if not hhmm:
        return "unknown"
    # Engine candles are normalized to UTC; US regular session is roughly 13:30-20:00 UTC.
    if "13:30" <= hhmm < "20:00":
        return "regular"
    if hhmm < "13:30":
        return "premarket"
    return "afterhours"


def _s871c_filter_rows(rows, start_date=None, end_date=None):
    out = []
    for row in rows or []:
        date_key = _s871c_date_key(row)
        if not date_key:
            continue
        if start_date and date_key < str(start_date):
            continue
        if end_date and date_key > str(end_date):
            continue
        out.append(row)
    return out


def _s871c_roll_avg(values):
    nums = [v for v in values if v is not None]
    if not nums:
        return None
    return sum(nums) / len(nums)


def _s871c_safe_round(value, digits=6):
    try:
        if value is None:
            return None
        return round(float(value), digits)
    except Exception:
        return None


def _s871c_build_features_for_rows(symbol, interval, rows):
    rows = sorted(rows or [], key=lambda item: _s871c_datetime_text(item))
    features = []

    day_state = {}
    closes = []
    volumes = []
    true_ranges = []
    gains = []
    losses = []

    ema20 = None
    alpha20 = 2 / (20 + 1)
    prev_close = None

    opening_range_by_day = {}

    for idx, row in enumerate(rows):
        date_key = _s871c_date_key(row)
        if not date_key:
            continue

        open_ = _s871c_num(row.get("open"))
        high = _s871c_num(row.get("high"))
        low = _s871c_num(row.get("low"))
        close = _s871c_num(row.get("close"))
        volume = _s871c_num(row.get("volume")) or 0.0

        if close is None or high is None or low is None:
            continue

        typical = ((high or close) + (low or close) + close) / 3

        state = day_state.setdefault(date_key, {"cumPv": 0.0, "cumVolume": 0.0, "barCount": 0})
        state["cumPv"] += typical * volume
        state["cumVolume"] += volume
        state["barCount"] += 1
        vwap = state["cumPv"] / state["cumVolume"] if state["cumVolume"] > 0 else None

        if ema20 is None:
            ema20 = close
        else:
            ema20 = (close * alpha20) + (ema20 * (1 - alpha20))

        if prev_close is None:
            true_range = (high - low) if high is not None and low is not None else None
            change = None
        else:
            true_range = max(
                high - low,
                abs(high - prev_close),
                abs(low - prev_close),
            )
            change = close - prev_close

        true_ranges.append(true_range)
        if len(true_ranges) > 14:
            true_ranges.pop(0)
        atr14 = _s871c_roll_avg(true_ranges)

        if change is not None:
            gains.append(max(change, 0))
            losses.append(abs(min(change, 0)))
            if len(gains) > 14:
                gains.pop(0)
            if len(losses) > 14:
                losses.pop(0)

        rsi14 = None
        if len(gains) >= 14 and len(losses) >= 14:
            avg_gain = _s871c_roll_avg(gains) or 0
            avg_loss = _s871c_roll_avg(losses) or 0
            if avg_loss == 0 and avg_gain > 0:
                rsi14 = 100.0
            elif avg_loss == 0:
                rsi14 = 50.0
            else:
                rs = avg_gain / avg_loss
                rsi14 = 100 - (100 / (1 + rs))

        volumes.append(volume)
        if len(volumes) > 20:
            volumes.pop(0)
        vol_sma20 = _s871c_roll_avg(volumes[:-1] if len(volumes) > 1 else volumes)
        rvol20 = (volume / vol_sma20) if vol_sma20 and vol_sma20 > 0 else None

        closes.append(close)
        if len(closes) > 20:
            closes.pop(0)

        day_or = opening_range_by_day.setdefault(date_key, {"bars": 0, "high": None, "low": None})
        if day_or["bars"] < 3:
            day_or["bars"] += 1
            day_or["high"] = high if day_or["high"] is None else max(day_or["high"], high)
            day_or["low"] = low if day_or["low"] is None else min(day_or["low"], low)

        candle_range = high - low if high is not None and low is not None else None
        bar_range_pct = ((candle_range / close) * 100) if candle_range is not None and close else None
        close_location = ((close - low) / candle_range) if candle_range and candle_range > 0 else None

        item = {
            "symbol": str(symbol).upper(),
            "interval": interval,
            "datetime": _s871c_datetime_text(row),
            "date": date_key,
            "session": _s871c_session_bucket(row),
            "open": open_,
            "high": high,
            "low": low,
            "close": close,
            "volume": volume,
            "vwap": _s871c_safe_round(vwap),
            "ema20": _s871c_safe_round(ema20),
            "atr14": _s871c_safe_round(atr14),
            "rsi14": _s871c_safe_round(rsi14),
            "volumeSma20": _s871c_safe_round(vol_sma20),
            "rvol20": _s871c_safe_round(rvol20),
            "volumeAcceleration": _s871c_safe_round(rvol20),
            "barRangePct": _s871c_safe_round(bar_range_pct),
            "closeLocation": _s871c_safe_round(close_location),
            "distanceFromVwapPct": _s871c_safe_round(((close - vwap) / vwap) * 100 if vwap else None),
            "distanceFromEma20Pct": _s871c_safe_round(((close - ema20) / ema20) * 100 if ema20 else None),
            "openingRangeHigh": _s871c_safe_round(day_or.get("high")),
            "openingRangeLow": _s871c_safe_round(day_or.get("low")),
            "openingRangeBars": day_or.get("bars"),
            "source": "s8_71c_feature_builder",
            "featureVersion": S871C_HISTORICAL_FEATURE_BUILDER_VERSION,
        }

        features.append(item)
        prev_close = close

    return features


def _s871c_find_normalized_files(symbols=None, intervals=None, max_files=1000):
    data_lake = _s871a_data_lake_dir()
    base = data_lake / "normalized_candles"
    symbol_filter = set(_s871c_parse_symbols(symbols)) if symbols else None
    interval_filter = set(_s871c_parse_intervals(intervals)) if intervals else None

    files = []
    if not base.exists():
        return files

    for interval_dir in sorted([p for p in base.iterdir() if p.is_dir()]):
        interval = interval_dir.name
        if interval_filter and interval not in interval_filter:
            continue
        for symbol_dir in sorted([p for p in interval_dir.iterdir() if p.is_dir()]):
            symbol = symbol_dir.name.upper()
            if symbol_filter and symbol not in symbol_filter:
                continue
            for path in sorted(symbol_dir.glob("*.jsonl")):
                files.append({"path": path, "symbol": symbol, "interval": interval})
                if len(files) >= int(max_files or 1000):
                    return files
    return files


def _s871c_build_features(
    symbols=None,
    intervals="1min,5min",
    start_date=None,
    end_date=None,
    max_files=1000,
    publish=True,
):
    import json

    files = _s871c_find_normalized_files(symbols=symbols, intervals=intervals, max_files=max_files)
    data_lake = _s871a_data_lake_dir()

    manifest = {
        "ok": True,
        "storageVersion": S871C_HISTORICAL_FEATURE_BUILDER_VERSION,
        "generatedAt": _s871b_now_iso(),
        "symbols": _s871c_parse_symbols(symbols) if symbols else None,
        "intervals": _s871c_parse_intervals(intervals),
        "dateRange": {"startDate": start_date, "endDate": end_date},
        "summary": {
            "filesScanned": len(files),
            "filesSucceeded": 0,
            "filesFailed": 0,
            "normalizedRowsRead": 0,
            "featureRowsWritten": 0,
        },
        "files": [],
        "errors": [],
        "policy": {
            "doesNotChangeClientDelivery": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "doesNotFabricateData": True,
            "usesOnlyIngestedHistoricalCandles": True,
        },
        "nextEngineeringStep": "S8.71D Historical Setup Replay: run setup algorithms on point-in-time feature rows and create historical setup candidates.",
    }

    for item in files:
        path = item.get("path")
        symbol = item.get("symbol")
        interval = item.get("interval")
        try:
            rows = _s871c_read_jsonl(path)
            rows = _s871c_filter_rows(rows, start_date=start_date, end_date=end_date)
            features = _s884b_build_features_robust(symbol, interval, rows)

            date_safe = f"{_s871b_safe_name(start_date or 'all')}_{_s871b_safe_name(end_date or 'all')}"
            out_path = data_lake / "features" / interval / symbol / f"{date_safe}.jsonl"
            _s871c_write_jsonl(out_path, features)

            manifest["summary"]["filesSucceeded"] += 1
            manifest["summary"]["normalizedRowsRead"] += len(rows)
            manifest["summary"]["featureRowsWritten"] += len(features)
            manifest["files"].append({
                "symbol": symbol,
                "interval": interval,
                "sourcePath": str(path),
                "featurePath": str(out_path),
                "normalizedRows": len(rows),
                "featureRows": len(features),
            })
        except Exception as exc:
            manifest["summary"]["filesFailed"] += 1
            manifest["errors"].append({
                "type": "exception",
                "symbol": symbol,
                "interval": interval,
                "path": str(path),
                "message": str(exc),
            })

    if publish:
        reports_dir = _s871c_reports_dir()
        latest_report = reports_dir / "latest_s871c_features.json"
        stamp = str(manifest.get("generatedAt") or "").replace(":", "-").replace(".", "-")
        snapshot = reports_dir / f"{stamp}.json"

        jobs_dir = data_lake / "jobs"
        latest_job = jobs_dir / "latest_s871c_features.json"

        payload = json.dumps(manifest, ensure_ascii=False, indent=2)
        latest_report.write_text(payload, encoding="utf-8")
        latest_job.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return manifest


@app.post("/engine/research/historical-learning/features/build")
def engine_research_historical_learning_features_build(
    symbols: str = None,
    intervals: str = "1min,5min",
    start_date: str = None,
    end_date: str = None,
    max_files: int = 1000,
    publish: bool = True,
):
    return _s871c_build_features(
        symbols=symbols,
        intervals=intervals,
        start_date=start_date,
        end_date=end_date,
        max_files=max_files,
        publish=publish,
    )


