def engine_research_historical_learning_features_latest():
    import json

    latest = _s871c_reports_dir() / "latest_s871c_features.json"
    if not latest.exists():
        return {
            "ok": False,
            "storageVersion": S871C_HISTORICAL_FEATURE_BUILDER_VERSION,
            "error": "No S8.71C feature report yet. Run POST /engine/research/historical-learning/features/build.",
        }
    return json.loads(latest.read_text(encoding="utf-8"))


@app.get("/engine/research/historical-learning/features/status")
def engine_research_historical_learning_features_status():
    latest = engine_research_historical_learning_features_latest()
    if not isinstance(latest, dict) or not latest.get("ok"):
        return latest
    return {
        "ok": True,
        "storageVersion": S871C_HISTORICAL_FEATURE_BUILDER_VERSION,
        "dateRange": latest.get("dateRange"),
        "summary": latest.get("summary"),
        "fileCount": len(latest.get("files") or []),
        "errorCount": len(latest.get("errors") or []),
        "nextEngineeringStep": latest.get("nextEngineeringStep"),
    }


# === S8.71D Historical Setup Replay =========================================
S871D_HISTORICAL_SETUP_REPLAY_VERSION = "s8_71d_historical_setup_replay_v1"


def _s871d_reports_dir():
    out_dir = _s870e_root_dir() / "reports" / "historical_learning" / "setup_replay"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s871d_find_feature_files(symbols=None, intervals=None, max_files=1000):
    data_lake = _s871a_data_lake_dir()
    base = data_lake / "features"
    symbol_filter = set(_s871c_parse_symbols(symbols)) if symbols else None
    interval_filter = set(_s871c_parse_intervals(intervals)) if intervals else None

    files = []
    if not base.exists():
        return files

    for interval_dir in sorted([p for p in base.iterdir() if p.is_dir()]):
        interval = interval_dir.name
        if interval_filter and interval not in interval_filter:
            continue
        for symbol_dir in sorted([p for p in interval_dir.iterdir() if p.is_dir()]):
            symbol = symbol_dir.name.upper()
            if symbol_filter and symbol not in symbol_filter:
                continue
            for path in sorted(symbol_dir.glob("*.jsonl")):
                files.append({"path": path, "symbol": symbol, "interval": interval})
                if len(files) >= int(max_files or 1000):
                    return files
    return files


def _s871d_policy_strategy_slugs():
    policy = _s871a_load_strategy_policy()
    slugs = _s871a_strategy_slugs_from_policy(policy)
    if slugs:
        return set(slugs)
    return {
        "vwap_reclaim_long",
        "vwap_rejection_short",
        "opening_range_breakout_long",
        "opening_range_breakdown_short",
        "large_cap_vwap_trend_long",
        "premarket_pump_short",
        "gap_and_crap_short",
        "gap_hold_continuation_long",
        "large_cap_gap_continuation",
        "orb_pullback_continuation",
    }


def _s871d_float(row, key, default=None):
    try:
        value = row.get(key) if isinstance(row, dict) else None
        if value is None or value == "":
            return default
        return float(value)
    except Exception:
        return default


def _s871d_grade(score):
    try:
        score = float(score)
    except Exception:
        score = 0
    if score >= 92:
        return "A+"
    if score >= 84:
        return "A"
    if score >= 76:
        return "B"
    return "C"


def _s871d_clamp_score(score):
    try:
        return max(1.0, min(float(score), 100.0))
    except Exception:
        return 1.0


def _s871d_reason_score(base=76, rvol=None, dist=None, close_location=None, rsi=None):
    score = float(base)
    if rvol is not None:
        score += min(max(float(rvol) - 1.0, 0.0), 5.0) * 3.0
    if dist is not None:
        score += min(abs(float(dist)), 3.0)
    if close_location is not None:
        score += max(0.0, min(float(close_location), 1.0)) * 4.0
    if rsi is not None:
        rsi = float(rsi)
        if 35 <= rsi <= 70:
            score += 3.0
        elif rsi > 70:
            score += 1.0
    return _s871d_clamp_score(score)


def _s871d_make_candidate(row, setup_slug, direction, score, reasons):
    symbol = str(row.get("symbol") or "").upper().strip()
    interval = str(row.get("interval") or "")
    dt = str(row.get("datetime") or "")
    close = _s871d_float(row, "close")
    atr = _s871d_float(row, "atr14")
    high = _s871d_float(row, "high")
    low = _s871d_float(row, "low")

    if not symbol or not dt or close is None:
        return None

    fallback_risk = max(close * 0.003, 0.01)
    risk = max(float(atr or 0), fallback_risk)
    if risk <= 0:
        risk = fallback_risk

    direction = str(direction or "").upper().strip()
    if direction == "SHORT":
        stop = close + risk
        targets = [
            {"price": round(close - risk * 2, 6), "r": 2.0},
            {"price": round(close - risk * 3, 6), "r": 3.0},
        ]
        invalidation = "Short invalidates if price reclaims stop above trigger candle / ATR risk."
    else:
        direction = "LONG"
        stop = close - risk
        targets = [
            {"price": round(close + risk * 2, 6), "r": 2.0},
            {"price": round(close + risk * 3, 6), "r": 3.0},
        ]
        invalidation = "Long invalidates if price loses stop below trigger candle / ATR risk."

    score = _s871d_clamp_score(score)
    grade = _s871d_grade(score)

    return {
        "candidateId": f"historical:{symbol}:{setup_slug}:{dt}",
        "symbol": symbol,
        "setupSlug": setup_slug,
        "setupName": str(setup_slug).replace("_", " ").title(),
        "direction": direction,
        "interval": interval,
        "datetime": dt,
        "date": row.get("date"),
        "session": row.get("session"),
        "status": "HISTORICAL_CANDIDATE",
        "score": round(score, 2),
        "grade": grade,
        "qualityStatus": "PASSED" if score >= 78 else "RESEARCH_ONLY",
        "riskReward": 3.0,
        "entry": round(close, 6),
        "stop": round(stop, 6),
        "targets": targets,
        "invalidation": invalidation,
        "reasons": reasons,
        "source": {
            "type": "historical_feature_replay",
            "featureVersion": row.get("featureVersion"),
            "replayVersion": S871D_HISTORICAL_SETUP_REPLAY_VERSION,
            "pointInTime": True,
            "noLookahead": True,
            "features": {
                "vwap": row.get("vwap"),
                "ema20": row.get("ema20"),
                "atr14": row.get("atr14"),
                "rsi14": row.get("rsi14"),
                "rvol20": row.get("rvol20"),
                "barRangePct": row.get("barRangePct"),
                "closeLocation": row.get("closeLocation"),
                "distanceFromVwapPct": row.get("distanceFromVwapPct"),
                "distanceFromEma20Pct": row.get("distanceFromEma20Pct"),
                "openingRangeHigh": row.get("openingRangeHigh"),
                "openingRangeLow": row.get("openingRangeLow"),
                "openingRangeBars": row.get("openingRangeBars"),
                "high": high,
                "low": low,
                "close": close,
            },
        },
        "clientEligible": False,
        "clientReleaseAllowed": False,
        "policy": {
            "researchOnly": True,
            "requiresOutcomeSimulation": True,
            "requiresSegmentValidation": True,
            "requiresWalkForwardValidation": True,
        },
    }


def _s871d_detect_candidates(row, prev_row, allowed_slugs):
    candidates = []

    close = _s871d_float(row, "close")
    vwap = _s871d_float(row, "vwap")
    ema20 = _s871d_float(row, "ema20")
    rvol = _s871d_float(row, "rvol20")
    rsi = _s871d_float(row, "rsi14")
    dist_vwap = _s871d_float(row, "distanceFromVwapPct")
    dist_ema = _s871d_float(row, "distanceFromEma20Pct")
    close_location = _s871d_float(row, "closeLocation")
    or_high = _s871d_float(row, "openingRangeHigh")
    or_low = _s871d_float(row, "openingRangeLow")
    or_bars = _s871d_float(row, "openingRangeBars", 0)
    session = str(row.get("session") or "")

    prev_close = _s871d_float(prev_row or {}, "close")
    prev_vwap = _s871d_float(prev_row or {}, "vwap")

    if close is None or vwap is None:
        return candidates

    def add(slug, direction, base, reasons):
        if slug not in allowed_slugs:
            return
        score = _s871d_reason_score(base=base, rvol=rvol, dist=dist_vwap, close_location=close_location, rsi=rsi)
        item = _s871d_make_candidate(row, slug, direction, score, reasons)
        if item:
            candidates.append(item)

    if (
        "vwap_reclaim_long" in allowed_slugs
        and prev_close is not None
        and prev_vwap is not None
        and prev_close <= prev_vwap
        and close > vwap
        and (ema20 is None or close >= ema20)
        and (rvol is None or rvol >= 1.0)
    ):
        add("vwap_reclaim_long", "LONG", 80, ["price_reclaimed_vwap", "close_above_ema20_or_ema_missing", "point_in_time_feature_row"])

    if (
        "vwap_rejection_short" in allowed_slugs
        and prev_close is not None
        and prev_vwap is not None
        and prev_close >= prev_vwap
        and close < vwap
        and (ema20 is None or close <= ema20)
        and (rvol is None or rvol >= 1.0)
    ):
        add("vwap_rejection_short", "SHORT", 80, ["price_lost_vwap", "close_below_ema20_or_ema_missing", "point_in_time_feature_row"])

    if (
        "opening_range_breakout_long" in allowed_slugs
        and or_high is not None
        and or_bars >= 3
        and close > or_high
        and (rvol is None or rvol >= 1.0)
    ):
        add("opening_range_breakout_long", "LONG", 78, ["close_above_opening_range_high", "opening_range_completed", "point_in_time_feature_row"])

    if (
        "opening_range_breakdown_short" in allowed_slugs
        and or_low is not None
        and or_bars >= 3
        and close < or_low
        and (rvol is None or rvol >= 1.0)
    ):
        add("opening_range_breakdown_short", "SHORT", 78, ["close_below_opening_range_low", "opening_range_completed", "point_in_time_feature_row"])

    if (
        "large_cap_vwap_trend_long" in allowed_slugs
        and close > vwap
        and (ema20 is None or close > ema20)
        and dist_vwap is not None
        and 0 <= dist_vwap <= 1.5
        and (rvol is None or rvol >= 1.0)
    ):
        add("large_cap_vwap_trend_long", "LONG", 79, ["trend_above_vwap", "not_overextended_from_vwap", "point_in_time_feature_row"])

    if (
        "premarket_pump_short" in allowed_slugs
        and dist_vwap is not None
        and dist_vwap >= 1.5
        and (rsi is None or rsi >= 68)
        and (close_location is None or close_location <= 0.65)
    ):
        add("premarket_pump_short", "SHORT", 77, ["extended_above_vwap", "possible_exhaustion_pressure", "point_in_time_feature_row"])

    if (
        "gap_and_crap_short" in allowed_slugs
        and or_low is not None
        and or_bars >= 3
        and close < or_low
        and (dist_ema is None or dist_ema < 0)
    ):
        add("gap_and_crap_short", "SHORT", 79, ["lost_opening_range_low", "below_ema20_or_ema_missing", "point_in_time_feature_row"])

    if (
        "gap_hold_continuation_long" in allowed_slugs
        and or_high is not None
        and or_bars >= 3
        and close > or_high
        and close > vwap
        and (rvol is None or rvol >= 1.2)
    ):
        add("gap_hold_continuation_long", "LONG", 78, ["held_above_opening_range", "above_vwap", "point_in_time_feature_row"])

    if (
        "large_cap_gap_continuation" in allowed_slugs
        and close > vwap
        and (ema20 is None or close > ema20)
        and (rvol is None or rvol >= 1.2)
    ):
        add("large_cap_gap_continuation", "LONG", 77, ["large_cap_continuation_proxy", "above_vwap_and_ema", "point_in_time_feature_row"])

    if (
        "orb_pullback_continuation" in allowed_slugs
        and close > vwap
        and ema20 is not None
        and close > ema20
        and dist_ema is not None
        and 0 <= dist_ema <= 0.8
        and session == "regular"
    ):
        add("orb_pullback_continuation", "LONG", 77, ["pullback_near_ema20", "above_vwap", "point_in_time_feature_row"])

    return candidates


def _s871d_replay_rows(rows, allowed_slugs, max_candidates=5000):
    candidates = []
    prev_row = None

    for row in rows or []:
        detected = _s871d_detect_candidates(row, prev_row, allowed_slugs)
        for item in detected:
            candidates.append(item)
            if len(candidates) >= int(max_candidates or 5000):
                return candidates
        prev_row = row

    return candidates


def _s871d_counts_by_setup(candidates):
    counts = {}
    for item in candidates or []:
        slug = item.get("setupSlug") or "unknown"
        counts[slug] = counts.get(slug, 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: kv[1], reverse=True))


def _s871d_counts_by_symbol(candidates):
    counts = {}
    for item in candidates or []:
        symbol = item.get("symbol") or "unknown"
        counts[symbol] = counts.get(symbol, 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: kv[1], reverse=True))


def _s871d_run_setup_replay(
    symbols=None,
    intervals="5min",
    start_date=None,
    end_date=None,
    max_files=1000,
    max_candidates_per_file=5000,
    publish=True,
):
    import json

    feature_files = _s871d_find_feature_files(symbols=symbols, intervals=intervals, max_files=max_files)
    allowed_slugs = _s871d_policy_strategy_slugs()
    data_lake = _s871a_data_lake_dir()

    manifest = {
        "ok": True,
        "storageVersion": S871D_HISTORICAL_SETUP_REPLAY_VERSION,
        "generatedAt": _s871b_now_iso(),
        "symbols": _s871c_parse_symbols(symbols) if symbols else None,
        "intervals": _s871c_parse_intervals(intervals),
        "dateRange": {"startDate": start_date, "endDate": end_date},
        "strategySlugs": sorted(list(allowed_slugs)),
        "summary": {
            "filesScanned": len(feature_files),
            "filesSucceeded": 0,
            "filesFailed": 0,
            "featureRowsRead": 0,
            "candidatesWritten": 0,
        },
        "countsBySetup": {},
        "countsBySymbol": {},
        "files": [],
        "errors": [],
        "policy": {
            "pointInTimeReplay": True,
            "noLookahead": True,
            "clientEligible": False,
            "doesNotChangeClientDelivery": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "requiresOutcomeSimulationNext": True,
        },
        "nextEngineeringStep": "S8.71E Historical Outcome Simulator: evaluate candidates against future candles to compute WORKED/FAILED/resultR/MFE/MAE without lookahead.",
    }

    all_candidates = []

    for item in feature_files:
        path = item.get("path")
        symbol = item.get("symbol")
        interval = item.get("interval")
        try:
            rows = _s871c_read_jsonl(path)
            rows = _s871c_filter_rows(rows, start_date=start_date, end_date=end_date)
            candidates = _s871d_replay_rows(rows, allowed_slugs, max_candidates=max_candidates_per_file)

            date_safe = f"{_s871b_safe_name(start_date or 'all')}_{_s871b_safe_name(end_date or 'all')}"
            out_path = data_lake / "setup_candidates" / interval / symbol / f"{date_safe}.jsonl"
            _s871c_write_jsonl(out_path, candidates)

            manifest["summary"]["filesSucceeded"] += 1
            manifest["summary"]["featureRowsRead"] += len(rows)
            manifest["summary"]["candidatesWritten"] += len(candidates)
            all_candidates.extend(candidates)

            manifest["files"].append({
                "symbol": symbol,
                "interval": interval,
                "sourcePath": str(path),
                "candidatePath": str(out_path),
                "featureRows": len(rows),
                "candidates": len(candidates),
                "countsBySetup": _s871d_counts_by_setup(candidates),
            })
        except Exception as exc:
            manifest["summary"]["filesFailed"] += 1
            manifest["errors"].append({
                "type": "exception",
                "symbol": symbol,
                "interval": interval,
                "path": str(path),
                "message": str(exc),
            })

    manifest["countsBySetup"] = _s871d_counts_by_setup(all_candidates)
    manifest["countsBySymbol"] = _s871d_counts_by_symbol(all_candidates)

    if publish:
        reports_dir = _s871d_reports_dir()
        latest_report = reports_dir / "latest_s871d_setup_replay.json"
        stamp = str(manifest.get("generatedAt") or "").replace(":", "-").replace(".", "-")
        snapshot = reports_dir / f"{stamp}.json"

        jobs_dir = data_lake / "jobs"
        latest_job = jobs_dir / "latest_s871d_setup_replay.json"

        payload = json.dumps(manifest, ensure_ascii=False, indent=2)
        latest_report.write_text(payload, encoding="utf-8")
        latest_job.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return manifest


@app.post("/engine/research/historical-learning/setup-replay/run")
def engine_research_historical_learning_setup_replay_run(
    symbols: str = None,
    intervals: str = "5min",
    start_date: str = None,
    end_date: str = None,
    max_files: int = 1000,
    max_candidates_per_file: int = 5000,
    publish: bool = True,
):
    return _s871d_run_setup_replay(
        symbols=symbols,
        intervals=intervals,
        start_date=start_date,
        end_date=end_date,
        max_files=max_files,
        max_candidates_per_file=max_candidates_per_file,
        publish=publish,
    )


@app.get("/engine/research/historical-learning/setup-replay/latest")
def engine_research_historical_learning_setup_replay_latest():
    import json

    latest = _s871d_reports_dir() / "latest_s871d_setup_replay.json"
    if not latest.exists():
        return {
            "ok": False,
            "storageVersion": S871D_HISTORICAL_SETUP_REPLAY_VERSION,
            "error": "No S8.71D setup replay report yet. Run POST /engine/research/historical-learning/setup-replay/run.",
        }
    return json.loads(latest.read_text(encoding="utf-8"))


@app.get("/engine/research/historical-learning/setup-replay/status")
def engine_research_historical_learning_setup_replay_status():
    latest = engine_research_historical_learning_setup_replay_latest()
    if not isinstance(latest, dict) or not latest.get("ok"):
        return latest
    return {
        "ok": True,
        "storageVersion": S871D_HISTORICAL_SETUP_REPLAY_VERSION,
        "dateRange": latest.get("dateRange"),
        "summary": latest.get("summary"),
        "countsBySetup": latest.get("countsBySetup"),
        "countsBySymbol": latest.get("countsBySymbol"),
        "fileCount": len(latest.get("files") or []),
        "errorCount": len(latest.get("errors") or []),
        "nextEngineeringStep": latest.get("nextEngineeringStep"),
    }


# === S8.72B Historical Learning Supabase Sync ===============================
S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION = "s8_72b_historical_learning_supabase_sync_v1"


def _s872b_reports_dir():
    out_dir = _s870e_root_dir() / "reports" / "historical_learning" / "supabase_sync"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s872b_now_iso():
    from datetime import datetime, timezone

    return datetime.now(timezone.utc).isoformat()


# === S8.72B3 Supabase Sync JSON Read Path Hotfix ============================
S872B3_SUPABASE_SYNC_JSON_READ_PATH_HOTFIX_VERSION = "s8_72b3_supabase_sync_json_read_path_hotfix_v1"


def _s872b_json_read(path):
    import json
    from pathlib import Path

    try:
        p = Path(path)
        if not p.exists():
            return None
        return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        return None


def _s872b_hash(value):
    import hashlib

    return hashlib.sha1(str(value or "").encode("utf-8", errors="ignore")).hexdigest()[:16]


def _s872b_supabase_config():
    import os

    url = (
        os.getenv("SUPABASE_URL")
        or os.getenv("NEXT_PUBLIC_SUPABASE_URL")
        or os.getenv("SUPABASE_PROJECT_URL")
        or ""
    ).strip().rstrip("/")

    key = (
        os.getenv("SUPABASE_SERVICE_ROLE_KEY")
        or os.getenv("SUPABASE_SERVICE_KEY")
        or os.getenv("SUPABASE_SERVICE_ROLE")
        or os.getenv("SUPABASE_SECRET_KEY")
        or ""
    ).strip()

    return {
        "url": url,
        "serviceKey": key,
        "configured": bool(url and key),
        "missing": [name for name, value in {
            "SUPABASE_URL_or_NEXT_PUBLIC_SUPABASE_URL": url,
            "SUPABASE_SERVICE_ROLE_KEY": key,
        }.items() if not value],
        "masked": {
            "url": url,
            "serviceKeyPresent": bool(key),
            "serviceKeyLength": len(key),
            "serviceKeyFirst4": key[:4] if key else "",
            "serviceKeyLast4": key[-4:] if key else "",
        },
    }


def _s872b_rest_url(cfg, table, on_conflict=None):
    import urllib.parse as _urlparse

    base = f"{cfg.get('url')}/rest/v1/{table}"
    if on_conflict:
        return base + "?on_conflict=" + _urlparse.quote(str(on_conflict))
    return base


# === S8.73A Backfill Duplicate Outcome Hotfix ===============================
S873A_BACKFILL_DUPLICATE_OUTCOME_HOTFIX_VERSION = "s8_73a_backfill_duplicate_outcome_hotfix_v1"


def _s873a_dedupe_rows_for_on_conflict(rows, on_conflict):
    if not rows or not on_conflict:
        return rows or []

    cols = [str(c).strip() for c in str(on_conflict).split(",") if str(c).strip()]
    if not cols:
        return rows

    seen = {}
    ordered_keys = []

    for row in rows or []:
        if not isinstance(row, dict):
            key = ("__raw__", str(row))
        else:
            key = tuple(str(row.get(col) or "") for col in cols)

        if key not in seen:
            ordered_keys.append(key)
        seen[key] = row

    return [seen[key] for key in ordered_keys]


def _s873a_dedupe_candidates_by_id(candidates, seen_ids=None):
    seen_ids = seen_ids if seen_ids is not None else set()
    out = []

    for candidate in candidates or []:
        if not isinstance(candidate, dict):
            continue
        cid = str(candidate.get("candidateId") or "").strip()
        if cid and cid in seen_ids:
            continue
        if cid:
            seen_ids.add(cid)
        out.append(candidate)

    return out


# === /S8.73A Backfill Duplicate Outcome Hotfix ==============================


def _s872b_supabase_upsert(table, rows, on_conflict, cfg, chunk_size=250):
    import json
    import urllib.error as _urlerror
    import urllib.request as _urlrequest

    if not rows:
        return {
            "ok": True,
            "table": table,
            "rowCount": 0,
            "chunks": 0,
            "statusCodes": [],
        }

    original_row_count = len(rows or [])
    rows = _s873a_dedupe_rows_for_on_conflict(rows, on_conflict)
    deduped_row_count = len(rows or [])

    key = cfg.get("serviceKey") or ""
    headers = {
        "apikey": key,
        "Authorization": f"Bearer {key}",
        "Content-Type": "application/json",
        "Prefer": "resolution=merge-duplicates,return=minimal",
    }

    status_codes = []
    errors = []
    total = 0

    for start in range(0, len(rows), int(chunk_size or 250)):
        chunk = rows[start:start + int(chunk_size or 250)]
        body = json.dumps(chunk, ensure_ascii=False, default=str).encode("utf-8")
        url = _s872b_rest_url(cfg, table, on_conflict=on_conflict)

        req = _urlrequest.Request(
            url,
            data=body,
            headers=headers,
            method="POST",
        )

        try:
            with _urlrequest.urlopen(req, timeout=60) as resp:
                status_codes.append(int(getattr(resp, "status", 200) or 200))
                total += len(chunk)
        except _urlerror.HTTPError as exc:
            try:
                detail = exc.read().decode("utf-8", errors="replace")[:1200]
            except Exception:
                detail = str(exc)
            errors.append({
                "statusCode": int(getattr(exc, "code", 0) or 0),
                "error": detail,
                "chunkStart": start,
                "chunkRows": len(chunk),
            })
        except Exception as exc:
            errors.append({
                "statusCode": 0,
                "error": str(exc),
                "chunkStart": start,
                "chunkRows": len(chunk),
            })

    return {
        "ok": len(errors) == 0,
        "table": table,
        "rowCount": total,
        "originalRowCount": original_row_count,
        "dedupedRowCount": deduped_row_count,
        "duplicatesDropped": max(0, original_row_count - deduped_row_count),
        "chunks": (len(rows) + int(chunk_size or 250) - 1) // int(chunk_size or 250),
        "statusCodes": status_codes,
        "errors": errors,
    }


def _s872b_to_date(value):
    text = str(value or "").strip()
    if len(text) >= 10 and text[4:5] == "-" and text[7:8] == "-":
        return text[:10]
    return None


def _s872b_to_timestamptz(value):
    text = str(value or "").strip()
    if not text:
        return None
    if len(text) >= 10 and text[4:5] == "-" and text[7:8] == "-":
        text = text.replace(" ", "T")
        if "T" not in text and len(text) == 10:
            return text + "T00:00:00+00:00"
        if text.endswith("Z") or "+" in text[10:] or "-" in text[10:]:
            return text
        return text + "+00:00"
    return None


def _s872b_date_range(manifest):
    dr = manifest.get("dateRange") if isinstance(manifest, dict) else {}
    if not isinstance(dr, dict):
        dr = {}
    return _s872b_to_date(dr.get("startDate")), _s872b_to_date(dr.get("endDate"))


def _s872b_array(values):
    if not values:
        return []
    if isinstance(values, list):
        return [str(v) for v in values if v is not None and str(v).strip()]
    return [str(values)]


def _s872b_job_row(job_type, manifest):
    storage_version = str(manifest.get("storageVersion") or manifest.get("compatVersion") or S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION)
    generated_at = str(manifest.get("generatedAt") or _s872b_now_iso())
    start_date, end_date = _s872b_date_range(manifest)
    intervals = _s872b_array(manifest.get("intervals") or manifest.get("intervalsRequested"))
    symbols = _s872b_array(manifest.get("symbols") or manifest.get("symbolsRequested"))
    strategy_slugs = _s872b_array(manifest.get("strategySlugs"))

    job_key = f"{job_type}:{storage_version}:{_s872b_hash(generated_at + str(symbols) + str(intervals))}"

    return {
        "job_key": job_key,
        "job_type": job_type,
        "status": "completed",
        "storage_version": storage_version,
        "source": "stock-engine",
        "start_date": start_date,
        "end_date": end_date,
        "intervals": intervals,
        "strategy_slugs": strategy_slugs,
        "payload": manifest,
        "summary": manifest.get("summary") if isinstance(manifest.get("summary"), dict) else {},
        "finished_at": _s872b_to_timestamptz(generated_at),
    }


def _s872b_file_format(path):
    text = str(path or "").lower()
    if text.endswith(".jsonl"):
        return "jsonl"
    if text.endswith(".json"):
        return "json"
    if text.endswith(".gz"):
        return "gz"
    if text.endswith(".parquet"):
        return "parquet"
    return "unknown"


def _s872b_build_data_file_rows(ingestion_manifest, job_key):
    rows = []
    if not isinstance(ingestion_manifest, dict):
        return rows
    start_date, end_date = _s872b_date_range(ingestion_manifest)
    provider = ingestion_manifest.get("provider")
    for item in ingestion_manifest.get("files") or []:
        if not isinstance(item, dict):
            continue
        symbol = str(item.get("symbol") or "").upper()
        interval = str(item.get("interval") or "")
        provider_mode = item.get("providerMode") or ingestion_manifest.get("providerMode")
        transport = item.get("transport")

        raw_path = item.get("rawPath")
        if raw_path:
            rows.append({
                "file_key": f"raw:{symbol}:{interval}:{start_date}:{end_date}:{_s872b_hash(raw_path)}",
                "job_key": job_key,
                "file_kind": "raw_candles",
                "provider": provider,
                "provider_mode": provider_mode,
                "transport": transport,
                "symbol": symbol,
                "interval": interval,
                "start_date": start_date,
                "end_date": end_date,
                "row_count": int(item.get("rawRows") or 0),
                "file_path": raw_path,
                "file_format": _s872b_file_format(raw_path),
                "status": "ready",
                "metadata": item,
            })

        norm_path = item.get("normalizedPath")
        if norm_path:
            rows.append({
                "file_key": f"normalized:{symbol}:{interval}:{start_date}:{end_date}:{_s872b_hash(norm_path)}",
                "job_key": job_key,
                "file_kind": "normalized_candles",
                "provider": provider,
                "provider_mode": provider_mode,
                "transport": transport,
                "symbol": symbol,
                "interval": interval,
                "start_date": start_date,
                "end_date": end_date,
                "row_count": int(item.get("normalizedRows") or 0),
                "file_path": norm_path,
                "file_format": _s872b_file_format(norm_path),
                "status": "ready",
                "metadata": item,
            })
    return rows


def _s872b_build_feature_file_rows(features_manifest, job_key):
    rows = []
    if not isinstance(features_manifest, dict):
        return rows
    start_date, end_date = _s872b_date_range(features_manifest)
    for item in features_manifest.get("files") or []:
        if not isinstance(item, dict):
            continue
        symbol = str(item.get("symbol") or "").upper()
        interval = str(item.get("interval") or "")
        feature_path = item.get("featurePath")
        if not feature_path:
            continue
        source_path = item.get("sourcePath")
        rows.append({
            "file_key": f"feature:{symbol}:{interval}:{start_date}:{end_date}:{_s872b_hash(feature_path)}",
            "job_key": job_key,
            "symbol": symbol,
            "interval": interval,
            "start_date": start_date,
            "end_date": end_date,
            "feature_version": features_manifest.get("storageVersion"),
            "source_data_file_key": f"normalized:{symbol}:{interval}:{start_date}:{end_date}:{_s872b_hash(source_path)}" if source_path else None,
            "feature_rows": int(item.get("featureRows") or 0),
            "file_path": feature_path,
            "file_format": _s872b_file_format(feature_path),
            "status": "ready",
            "feature_columns": [
                "vwap", "ema20", "atr14", "rsi14", "volumeSma20", "rvol20",
                "volumeAcceleration", "barRangePct", "closeLocation",
                "distanceFromVwapPct", "distanceFromEma20Pct",
                "openingRangeHigh", "openingRangeLow", "session",
            ],
            "metadata": item,
        })
    return rows


def _s872b_candidate_row(candidate, job_key, source_file_key=None):
    source = candidate.get("source") if isinstance(candidate.get("source"), dict) else {}
    return {
        "candidate_id": str(candidate.get("candidateId") or ""),
        "job_key": job_key,
        "symbol": str(candidate.get("symbol") or "").upper(),
        "setup_slug": str(candidate.get("setupSlug") or ""),
        "setup_name": candidate.get("setupName"),
        "direction": str(candidate.get("direction") or ""),
        "interval": str(candidate.get("interval") or ""),
        "candidate_at": _s872b_to_timestamptz(candidate.get("datetime")),
        "session_date": _s872b_to_date(candidate.get("date")),
        "session": candidate.get("session"),
        "status": str(candidate.get("status") or "historical_candidate").lower(),
        "score": candidate.get("score"),
        "grade": candidate.get("grade"),
        "quality_status": candidate.get("qualityStatus"),
        "risk_reward": candidate.get("riskReward"),
        "entry": candidate.get("entry"),
        "stop": candidate.get("stop"),
        "targets": candidate.get("targets") if isinstance(candidate.get("targets"), list) else [],
        "reasons": _s872b_array(candidate.get("reasons")),
        "source_file_key": source_file_key,
        "source": source,
        "payload": candidate,
        "client_eligible": bool(candidate.get("clientEligible")),
        "client_release_allowed": bool(candidate.get("clientReleaseAllowed")),
    }


def _s872b_build_candidate_rows(replay_manifest, job_key, max_candidates=5000):
    from pathlib import Path

    rows = []
    if not isinstance(replay_manifest, dict):
        return rows
    start_date, end_date = _s872b_date_range(replay_manifest)

    for item in replay_manifest.get("files") or []:
        if not isinstance(item, dict):
            continue
        symbol = str(item.get("symbol") or "").upper()
        interval = str(item.get("interval") or "")
        candidate_path = item.get("candidatePath")
        if not candidate_path:
            continue
        source_file_key = f"candidate_file:{symbol}:{interval}:{start_date}:{end_date}:{_s872b_hash(candidate_path)}"
        candidates = _s871c_read_jsonl(Path(candidate_path))
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            row = _s872b_candidate_row(candidate, job_key, source_file_key=source_file_key)
            if not row.get("candidate_id"):
                continue
            rows.append(row)
            if len(rows) >= int(max_candidates or 5000):
                return rows
    return rows


def _s872b_admin_event_row(sync_manifest):
    generated_at = str(sync_manifest.get("generatedAt") or _s872b_now_iso())
    summary = sync_manifest.get("summary") if isinstance(sync_manifest.get("summary"), dict) else {}
    return {
        "event_key": f"s872b_sync:{_s872b_hash(generated_at + str(summary))}",
        "agent_name": "SkillEdge AI Autonomous Ops",
        "event_type": "historical_learning_supabase_sync",
        "severity": "info" if sync_manifest.get("ok") else "warning",
        "title": "Historical learning Supabase sync completed" if sync_manifest.get("ok") else "Historical learning Supabase sync needs attention",
        "message": f"Synced jobs={summary.get('jobsUpserted', 0)}, dataFiles={summary.get('dataFilesUpserted', 0)}, featureFiles={summary.get('featureFilesUpserted', 0)}, candidates={summary.get('candidatesUpserted', 0)}.",
        "source_report_path": str(_s872b_reports_dir() / "latest_s872b_sync.json"),
        "source": {
            "storageVersion": sync_manifest.get("storageVersion"),
            "supabaseConfigured": bool(sync_manifest.get("supabase", {}).get("configured")),
        },
        "payload": sync_manifest,
    }


# === S8.72B.1 Supabase Sync Report Path Fix =================================
S872B1_SUPABASE_SYNC_REPORT_PATH_FIX_VERSION = "s8_72b1_supabase_sync_report_path_fix_v1"


# === S8.72B2 Supabase Sync Path Import Hotfix ===============================
S872B2_SUPABASE_SYNC_PATH_IMPORT_HOTFIX_VERSION = "s8_72b2_supabase_sync_path_import_hotfix_v1"


def _s872b1_existing_report_path(file_name, preferred_dirs=None):
    from pathlib import Path

    candidates = []

    for d in preferred_dirs or []:
        try:
            candidates.append(Path(d) / file_name)
        except Exception:
            pass

    try:
        root = _s870e_root_dir()
        candidates.extend([
            root / "reports" / "historical_learning" / "ingestion" / file_name,
            root / "reports" / "historical_learning" / "features" / file_name,
            root / "reports" / "historical_learning" / "setup_replay" / file_name,
            root / "data" / "reports" / "historical_learning" / "ingestion" / file_name,
            root / "data" / "reports" / "historical_learning" / "features" / file_name,
            root / "data" / "reports" / "historical_learning" / "setup_replay" / file_name,
        ])
    except Exception:
        pass

    candidates.extend([
        Path("/opt/skilledge/stock-engine/reports/historical_learning/ingestion") / file_name,
        Path("/opt/skilledge/stock-engine/reports/historical_learning/features") / file_name,
        Path("/opt/skilledge/stock-engine/reports/historical_learning/setup_replay") / file_name,
        Path("/opt/skilledge/stock-engine/data/reports/historical_learning/ingestion") / file_name,
        Path("/opt/skilledge/stock-engine/data/reports/historical_learning/features") / file_name,
        Path("/opt/skilledge/stock-engine/data/reports/historical_learning/setup_replay") / file_name,
    ])

    seen = set()
    for p in candidates:
        key = str(p)
        if key in seen:
            continue
        seen.add(key)
        try:
            if p.exists():
                return p
        except Exception:
            continue

    for base in [Path("/opt/skilledge/stock-engine"), Path.cwd()]:
        try:
            if base.exists():
                matches = list(base.glob(f"**/{file_name}"))
                if matches:
                    return sorted(matches, key=lambda p: str(p))[0]
        except Exception:
            continue

    if candidates:
        return candidates[0]
    return Path(file_name)


# === /S8.72B.1 Supabase Sync Report Path Fix ================================


def _s872b_run_supabase_sync(sync_candidates=True, max_candidates=5000, publish=True):
    import json

    cfg = _s872b_supabase_config()
    root = _s870e_root_dir()

    ingestion_path = _s872b1_existing_report_path(
        "latest_s871b_ingestion.json",
        preferred_dirs=[_s871b_reports_dir()],
    )
    features_path = _s872b1_existing_report_path(
        "latest_s871c_features.json",
        preferred_dirs=[_s871c_reports_dir()],
    )
    replay_path = _s872b1_existing_report_path(
        "latest_s871d_setup_replay.json",
        preferred_dirs=[_s871d_reports_dir()],
    )

    ingestion = _s872b_json_read(ingestion_path)
    features = _s872b_json_read(features_path)
    replay = _s872b_json_read(replay_path)

    manifest = {
        "ok": True,
        "storageVersion": S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION,
        "pathFixVersion": S872B1_SUPABASE_SYNC_REPORT_PATH_FIX_VERSION,
        "pathImportHotfixVersion": S872B2_SUPABASE_SYNC_PATH_IMPORT_HOTFIX_VERSION,
        "jsonReadPathHotfixVersion": S872B3_SUPABASE_SYNC_JSON_READ_PATH_HOTFIX_VERSION,
        "generatedAt": _s872b_now_iso(),
        "supabase": {
            "configured": cfg.get("configured"),
            "masked": cfg.get("masked"),
            "missing": cfg.get("missing"),
        },
        "sourceReports": {
            "ingestion": str(ingestion_path),
            "features": str(features_path),
            "setupReplay": str(replay_path),
            "ingestionFound": isinstance(ingestion, dict),
            "featuresFound": isinstance(features, dict),
            "setupReplayFound": isinstance(replay, dict),
        },
        "summary": {
            "jobsPrepared": 0,
            "jobsUpserted": 0,
            "dataFilesPrepared": 0,
            "dataFilesUpserted": 0,
            "featureFilesPrepared": 0,
            "featureFilesUpserted": 0,
            "candidatesPrepared": 0,
            "candidatesUpserted": 0,
            "adminEventsPrepared": 0,
            "adminEventsUpserted": 0,
        },
        "operations": [],
        "errors": [],
        "policy": {
            "doesNotStoreHeavyCandlesInSupabase": True,
            "storesOnlyFileManifestsAndResearchIndexes": True,
            "doesNotChangeClientDelivery": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
        },
        "nextEngineeringStep": "S8.71E Historical Outcome Simulator: evaluate candidates against future candles and write honest closed outcomes into Supabase historical_outcomes.",
    }

    if not cfg.get("configured"):
        manifest["ok"] = False
        manifest["errors"].append({
            "type": "missing_supabase_config",
            "missing": cfg.get("missing"),
            "message": "Set SUPABASE_URL/NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY in the stock-engine server environment.",
        })
        if publish:
            latest = _s872b_reports_dir() / "latest_s872b_sync.json"
            latest.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
        return manifest

    jobs = []
    job_keys = {}

    if isinstance(ingestion, dict):
        row = _s872b_job_row("s871b_ingestion", ingestion)
        jobs.append(row)
        job_keys["ingestion"] = row["job_key"]
    if isinstance(features, dict):
        row = _s872b_job_row("s871c_features", features)
        jobs.append(row)
        job_keys["features"] = row["job_key"]
    if isinstance(replay, dict):
        row = _s872b_job_row("s871d_setup_replay", replay)
        jobs.append(row)
        job_keys["replay"] = row["job_key"]

    manifest["summary"]["jobsPrepared"] = len(jobs)
    op = _s872b_supabase_upsert("historical_learning_jobs", jobs, "job_key", cfg)
    manifest["operations"].append(op)
    manifest["summary"]["jobsUpserted"] = op.get("rowCount", 0) if op.get("ok") else 0

    data_rows = _s872b_build_data_file_rows(ingestion, job_keys.get("ingestion")) if isinstance(ingestion, dict) else []
    manifest["summary"]["dataFilesPrepared"] = len(data_rows)
    op = _s872b_supabase_upsert("historical_data_files", data_rows, "file_key", cfg)
    manifest["operations"].append(op)
    manifest["summary"]["dataFilesUpserted"] = op.get("rowCount", 0) if op.get("ok") else 0

    feature_rows = _s872b_build_feature_file_rows(features, job_keys.get("features")) if isinstance(features, dict) else []
    manifest["summary"]["featureFilesPrepared"] = len(feature_rows)
    op = _s872b_supabase_upsert("historical_feature_files", feature_rows, "file_key", cfg)
    manifest["operations"].append(op)
    manifest["summary"]["featureFilesUpserted"] = op.get("rowCount", 0) if op.get("ok") else 0

    candidate_rows = []
    if bool(sync_candidates) and isinstance(replay, dict):
        candidate_rows = _s872b_build_candidate_rows(replay, job_keys.get("replay"), max_candidates=max_candidates)
    manifest["summary"]["candidatesPrepared"] = len(candidate_rows)
    op = _s872b_supabase_upsert("historical_setup_candidates", candidate_rows, "candidate_id", cfg, chunk_size=100)
    manifest["operations"].append(op)
    manifest["summary"]["candidatesUpserted"] = op.get("rowCount", 0) if op.get("ok") else 0

    failed_ops = [item for item in manifest["operations"] if not item.get("ok")]
    if failed_ops:
        manifest["ok"] = False
        manifest["errors"].append({
            "type": "supabase_upsert_failed",
            "failedTables": [item.get("table") for item in failed_ops],
            "details": failed_ops,
        })

    admin_event = _s872b_admin_event_row(manifest)
    manifest["summary"]["adminEventsPrepared"] = 1
    op = _s872b_supabase_upsert("admin_ai_ops_events", [admin_event], "event_key", cfg)
    manifest["operations"].append(op)
    manifest["summary"]["adminEventsUpserted"] = op.get("rowCount", 0) if op.get("ok") else 0

    if not op.get("ok"):
        manifest["ok"] = False
        manifest["errors"].append({
            "type": "admin_event_upsert_failed",
            "details": op,
        })

    if publish:
        reports_dir = _s872b_reports_dir()
        latest_report = reports_dir / "latest_s872b_sync.json"
        stamp = str(manifest.get("generatedAt") or "").replace(":", "-").replace(".", "-")
        snapshot = reports_dir / f"{stamp}.json"

        payload = json.dumps(manifest, ensure_ascii=False, indent=2, default=str)
        latest_report.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return manifest


@app.post("/engine/research/historical-learning/supabase-sync/run")
def engine_research_historical_learning_supabase_sync_run(
    sync_candidates: bool = True,
    max_candidates: int = 5000,
    publish: bool = True,
):
    return _s872b_run_supabase_sync(
        sync_candidates=sync_candidates,
        max_candidates=max_candidates,
        publish=publish,
    )


@app.get("/engine/research/historical-learning/supabase-sync/latest")
def engine_research_historical_learning_supabase_sync_latest():
    import json

    latest = _s872b_reports_dir() / "latest_s872b_sync.json"
    if not latest.exists():
        return {
            "ok": False,
            "storageVersion": S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION,
            "error": "No S8.72B sync report yet. Run POST /engine/research/historical-learning/supabase-sync/run.",
        }
    return json.loads(latest.read_text(encoding="utf-8"))


@app.get("/engine/research/historical-learning/supabase-sync/status")
def engine_research_historical_learning_supabase_sync_status():
    latest = engine_research_historical_learning_supabase_sync_latest()
    if not isinstance(latest, dict) or not latest.get("ok"):
        return latest
    return {
        "ok": True,
        "storageVersion": S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION,
        "supabase": latest.get("supabase"),
        "sourceReports": latest.get("sourceReports"),
        "summary": latest.get("summary"),
        "operationCount": len(latest.get("operations") or []),
        "errorCount": len(latest.get("errors") or []),
        "nextEngineeringStep": latest.get("nextEngineeringStep"),
    }


# === S8.71E Historical Outcome Simulator ====================================
S871E_HISTORICAL_OUTCOME_SIMULATOR_VERSION = "s8_71e_historical_outcome_simulator_v1"


def _s871e_reports_dir():
    out_dir = _s870e_root_dir() / "reports" / "historical_learning" / "outcomes"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s871e_find_candidate_files(symbols=None, intervals=None, max_files=1000):
    data_lake = _s871a_data_lake_dir()
    base = data_lake / "setup_candidates"
    symbol_filter = set(_s871c_parse_symbols(symbols)) if symbols else None
    interval_filter = set(_s871c_parse_intervals(intervals)) if intervals else None

    files = []
    if not base.exists():
        return files

    for interval_dir in sorted([p for p in base.iterdir() if p.is_dir()]):
        interval = interval_dir.name
        if interval_filter and interval not in interval_filter:
            continue
        for symbol_dir in sorted([p for p in interval_dir.iterdir() if p.is_dir()]):
            symbol = symbol_dir.name.upper()
            if symbol_filter and symbol not in symbol_filter:
                continue
            for path in sorted(symbol_dir.glob("*.jsonl")):
                files.append({"path": path, "symbol": symbol, "interval": interval})
                if len(files) >= int(max_files or 1000):
                    return files
    return files


def _s871e_find_normalized_candle_file(symbol, interval, start_date=None, end_date=None):
    data_lake = _s871a_data_lake_dir()
    base = data_lake / "normalized_candles" / str(interval) / str(symbol).upper()

    if not base.exists():
        return None

    if start_date and end_date:
        exact = base / f"{_s871b_safe_name(start_date)}_{_s871b_safe_name(end_date)}.jsonl"
        if exact.exists():
            return exact

    files = sorted(base.glob("*.jsonl"))
    if not files:
        return None

    if start_date or end_date:
        wanted = []
        for p in files:
            name = p.stem
            if start_date and str(start_date) not in name:
                continue
            if end_date and str(end_date) not in name:
                continue
            wanted.append(p)
        if wanted:
            return wanted[-1]

    return files[-1]


def _s871e_dt_text(row):
    if not isinstance(row, dict):
        return ""
    return str(row.get("datetime") or row.get("date") or row.get("timestamp") or row.get("time") or "").strip()


def _s871e_date_key_from_text(value):
    text = str(value or "").strip()
    if len(text) >= 10 and text[4:5] == "-" and text[7:8] == "-":
        return text[:10]
    return ""


def _s871e_float(value, default=None):
    try:
        if value is None or value == "":
            return default
        return float(value)
    except Exception:
        return default


def _s871e_candidate_targets(candidate):
    targets = candidate.get("targets") if isinstance(candidate, dict) else []
    out = []
    if isinstance(targets, list):
        for item in targets:
            if not isinstance(item, dict):
                continue
            price = _s871e_float(item.get("price"))
            r = _s871e_float(item.get("r"))
            if price is not None and r is not None:
                out.append({"price": price, "r": r})
    return sorted(out, key=lambda x: float(x.get("r") or 0))


def _s871e_future_candles(candles, candidate_dt, session_date=None, session_to_close=True, max_future_bars=500):
    future = []
    candidate_dt = str(candidate_dt or "")
    session_date = str(session_date or _s871e_date_key_from_text(candidate_dt) or "")

    for row in sorted(candles or [], key=lambda item: _s871e_dt_text(item)):
        dt = _s871e_dt_text(row)
        if not dt or dt <= candidate_dt:
            continue
        if session_to_close and session_date and _s871e_date_key_from_text(dt) != session_date:
            continue
        future.append(row)
        if len(future) >= int(max_future_bars or 500):
            break

    return future


def _s871e_eval_candidate(candidate, candles, session_to_close=True, max_future_bars=500):
    candidate_id = str(candidate.get("candidateId") or "")
    symbol = str(candidate.get("symbol") or "").upper()
    setup_slug = str(candidate.get("setupSlug") or "")
    direction = str(candidate.get("direction") or "").upper()
    interval = str(candidate.get("interval") or "")
    candidate_dt = str(candidate.get("datetime") or "")
    session_date = str(candidate.get("date") or _s871e_date_key_from_text(candidate_dt))

    entry = _s871e_float(candidate.get("entry"))
    stop = _s871e_float(candidate.get("stop"))
    targets = _s871e_candidate_targets(candidate)

    if not candidate_id or not symbol or entry is None or stop is None or not targets:
        return {
            "outcomeId": f"historical_outcome:{candidate_id or _s872b_hash(str(candidate))}",
            "candidateId": candidate_id,
            "symbol": symbol,
            "setupSlug": setup_slug,
            "direction": direction,
            "interval": interval,
            "candidateAt": candidate_dt,
            "sessionDate": session_date,
            "resultStatus": "no_eval",
            "terminalEvent": "missing_entry_stop_or_targets",
            "resultR": None,
            "mfeR": None,
            "maeR": None,
            "entry": entry,
            "stop": stop,
            "tp1": targets[0]["price"] if targets else None,
            "tp2": targets[1]["price"] if len(targets) > 1 else None,
            "candlesChecked": 0,
            "outcomeVersion": S871E_HISTORICAL_OUTCOME_SIMULATOR_VERSION,
            "payload": {"candidate": candidate},
        }

    risk = abs(entry - stop)
    if risk <= 0:
        risk = max(abs(entry) * 0.003, 0.01)

    future = _s871e_future_candles(
        candles,
        candidate_dt=candidate_dt,
        session_date=session_date,
        session_to_close=session_to_close,
        max_future_bars=max_future_bars,
    )

    if not future:
        return {
            "outcomeId": f"historical_outcome:{candidate_id}",
            "candidateId": candidate_id,
            "symbol": symbol,
            "setupSlug": setup_slug,
            "direction": direction,
            "interval": interval,
            "candidateAt": candidate_dt,
            "sessionDate": session_date,
            "resultStatus": "no_eval",
            "terminalEvent": "no_future_candles",
            "resultR": None,
            "mfeR": None,
            "maeR": None,
            "entry": entry,
            "stop": stop,
            "tp1": targets[0]["price"] if targets else None,
            "tp2": targets[1]["price"] if len(targets) > 1 else None,
            "candlesChecked": 0,
            "outcomeVersion": S871E_HISTORICAL_OUTCOME_SIMULATOR_VERSION,
            "payload": {"candidate": candidate, "futureCandleCount": 0},
        }

    mfe_r = 0.0
    mae_r = 0.0
    terminal = None
    checked = 0

    first_target = targets[0]
    tp1 = first_target["price"]
    tp2 = targets[1]["price"] if len(targets) > 1 else None

    for row in future:
        checked += 1
        high = _s871e_float(row.get("high"))
        low = _s871e_float(row.get("low"))
        close = _s871e_float(row.get("close"))
        dt = _s871e_dt_text(row)

        if high is None or low is None:
            continue

        if direction == "SHORT":
            mfe = (entry - low) / risk
            mae = (high - entry) / risk
            mfe_r = max(mfe_r, mfe)
            mae_r = max(mae_r, mae)

            # Conservative ambiguity handling: if stop and target are both inside the same candle, stop wins.
            if high >= stop:
                terminal = {
                    "resultStatus": "failed",
                    "terminalEvent": "stop",
                    "resultR": -1.0,
                    "firstEventAt": dt,
                    "eventCandle": row,
                }
                break
            if low <= tp1:
                terminal = {
                    "resultStatus": "worked",
                    "terminalEvent": "tp1",
                    "resultR": float(first_target.get("r") or 2.0),
                    "firstEventAt": dt,
                    "eventCandle": row,
                }
                break
        else:
            mfe = (high - entry) / risk
            mae = (entry - low) / risk
            mfe_r = max(mfe_r, mfe)
            mae_r = max(mae_r, mae)

            # Conservative ambiguity handling: if stop and target are both inside the same candle, stop wins.
            if low <= stop:
                terminal = {
                    "resultStatus": "failed",
                    "terminalEvent": "stop",
                    "resultR": -1.0,
                    "firstEventAt": dt,
                    "eventCandle": row,
                }
                break
            if high >= tp1:
                terminal = {
                    "resultStatus": "worked",
                    "terminalEvent": "tp1",
                    "resultR": float(first_target.get("r") or 2.0),
                    "firstEventAt": dt,
                    "eventCandle": row,
                }
                break

    if terminal is None:
        last = future[-1]
        last_close = _s871e_float(last.get("close"), entry)
        last_dt = _s871e_dt_text(last)
        if direction == "SHORT":
            final_r = (entry - last_close) / risk
        else:
            final_r = (last_close - entry) / risk
        terminal = {
            "resultStatus": "session_close" if session_to_close else "open",
            "terminalEvent": "session_close" if session_to_close else "max_future_bars",
            "resultR": final_r,
            "firstEventAt": last_dt,
            "eventCandle": last,
        }

    return {
        "outcomeId": f"historical_outcome:{candidate_id}",
        "candidateId": candidate_id,
        "symbol": symbol,
        "setupSlug": setup_slug,
        "direction": direction,
        "interval": interval,
        "candidateAt": candidate_dt,
        "sessionDate": session_date,
        "resultStatus": terminal.get("resultStatus"),
        "terminalEvent": terminal.get("terminalEvent"),
        "resultR": round(float(terminal.get("resultR")), 6) if terminal.get("resultR") is not None else None,
        "mfeR": round(float(mfe_r), 6),
        "maeR": round(float(mae_r), 6),
        "entry": entry,
        "stop": stop,
        "tp1": tp1,
        "tp2": tp2,
        "firstEventAt": terminal.get("firstEventAt"),
        "candlesChecked": checked,
        "outcomeVersion": S871E_HISTORICAL_OUTCOME_SIMULATOR_VERSION,
        "slippageModel": {
            "enabled": False,
            "note": "S8.71E v1 uses candle OHLC path with conservative same-candle stop-first handling. Slippage/spread model is a later calibration layer.",
        },
        "payload": {
            "candidate": candidate,
            "futureCandleCount": len(future),
            "eventCandle": terminal.get("eventCandle"),
            "sessionToClose": bool(session_to_close),
            "noLookahead": True,
        },
    }


def _s871e_counts(outcomes):
    counts = {
        "total": len(outcomes or []),
        "worked": 0,
        "failed": 0,
        "session_close": 0,
        "open": 0,
        "no_eval": 0,
        "closed": 0,
    }
    by_setup = {}
    for item in outcomes or []:
        status = str(item.get("resultStatus") or "unknown")
        counts[status] = counts.get(status, 0) + 1
        if status in {"worked", "failed", "session_close"}:
            counts["closed"] += 1
        slug = str(item.get("setupSlug") or "unknown")
        by_setup.setdefault(slug, {"total": 0, "worked": 0, "failed": 0, "session_close": 0, "no_eval": 0, "closed": 0})
        by_setup[slug]["total"] += 1
        by_setup[slug][status] = by_setup[slug].get(status, 0) + 1
        if status in {"worked", "failed", "session_close"}:
            by_setup[slug]["closed"] += 1

    for slug, row in by_setup.items():
        closed_wl = int(row.get("worked") or 0) + int(row.get("failed") or 0)
        row["winRateWorkedFailed"] = round((row.get("worked") or 0) / closed_wl, 6) if closed_wl > 0 else None
    return counts, dict(sorted(by_setup.items(), key=lambda kv: kv[1].get("total", 0), reverse=True))


def _s871e_supabase_outcome_row(outcome, job_key=None):
    return {
        "outcome_id": outcome.get("outcomeId"),
        "candidate_id": outcome.get("candidateId"),
        "job_key": job_key,
        "symbol": outcome.get("symbol"),
        "setup_slug": outcome.get("setupSlug"),
        "direction": outcome.get("direction"),
        "interval": outcome.get("interval"),
        "candidate_at": _s872b_to_timestamptz(outcome.get("candidateAt")) if "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals() else outcome.get("candidateAt"),
        "session_date": _s872b_to_date(outcome.get("sessionDate")) if "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals() else outcome.get("sessionDate"),
        "result_status": outcome.get("resultStatus"),
        "terminal_event": outcome.get("terminalEvent"),
        "result_r": outcome.get("resultR"),
        "mfe_r": outcome.get("mfeR"),
        "mae_r": outcome.get("maeR"),
        "entry": outcome.get("entry"),
        "stop": outcome.get("stop"),
        "tp1": outcome.get("tp1"),
        "tp2": outcome.get("tp2"),
        "first_event_at": _s872b_to_timestamptz(outcome.get("firstEventAt")) if "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals() else outcome.get("firstEventAt"),
        "candles_checked": outcome.get("candlesChecked"),
        "outcome_version": outcome.get("outcomeVersion"),
        "slippage_model": outcome.get("slippageModel") if isinstance(outcome.get("slippageModel"), dict) else {},
        "payload": outcome.get("payload") if isinstance(outcome.get("payload"), dict) else outcome,
    }


def _s871e_run_outcomes(
    symbols=None,
    intervals="5min",
    start_date=None,
    end_date=None,
    max_files=1000,
    max_candidates=5000,
    max_future_bars=500,
    session_to_close=True,
    sync_supabase=True,
    publish=True,
):
    import json

    candidate_files = _s871e_find_candidate_files(symbols=symbols, intervals=intervals, max_files=max_files)
    data_lake = _s871a_data_lake_dir()

    manifest = {
        "ok": True,
        "storageVersion": S871E_HISTORICAL_OUTCOME_SIMULATOR_VERSION,
        "generatedAt": _s871b_now_iso(),
        "symbols": _s871c_parse_symbols(symbols) if symbols else None,
        "intervals": _s871c_parse_intervals(intervals),
        "dateRange": {"startDate": start_date, "endDate": end_date},
        "summary": {
            "filesScanned": len(candidate_files),
            "filesSucceeded": 0,
            "filesFailed": 0,
            "candidatesRead": 0,
            "outcomesWritten": 0,
            "worked": 0,
            "failed": 0,
            "session_close": 0,
            "open": 0,
            "no_eval": 0,
            "closed": 0,
        },
        "countsBySetup": {},
        "files": [],
        "supabase": {
            "requested": bool(sync_supabase),
            "configured": False,
            "operations": [],
        },
        "errors": [],
        "policy": {
            "pointInTimeEvaluation": True,
            "noLookahead": True,
            "sameCandleAmbiguityHandling": "conservative_stop_first",
            "sessionCloseIsNotWinOrLoss": True,
            "noEvalIsNotWinOrLoss": True,
            "doesNotChangeClientDelivery": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
        },
        "nextEngineeringStep": "S8.71F Historical Setup Stats + Segment Recalibration: aggregate outcomes, compute honest WR/avgR/MFE/MAE, then update calibration segments.",
    }

    all_outcomes = []
    candidates_seen = 0
    seen_candidate_ids = set()

    for file_item in candidate_files:
        path = file_item.get("path")
        symbol = file_item.get("symbol")
        interval = file_item.get("interval")

        try:
            candidates = _s871c_read_jsonl(path)
            if start_date or end_date:
                filtered = []
                for candidate in candidates:
                    cdate = _s871e_date_key_from_text(candidate.get("date") or candidate.get("datetime"))
                    if start_date and cdate < str(start_date):
                        continue
                    if end_date and cdate > str(end_date):
                        continue
                    filtered.append(candidate)
                candidates = filtered

            if max_candidates and candidates_seen + len(candidates) > int(max_candidates):
                candidates = candidates[: max(0, int(max_candidates) - candidates_seen)]

            candle_path = _s871e_find_normalized_candle_file(symbol, interval, start_date=start_date, end_date=end_date)
            candles = _s871c_read_jsonl(candle_path) if candle_path else []

            candidates = _s873a_dedupe_candidates_by_id(candidates, seen_candidate_ids)

            outcomes = []
            for candidate in candidates:
                outcome = _s871e_eval_candidate(
                    candidate,
                    candles,
                    session_to_close=bool(session_to_close),
                    max_future_bars=max_future_bars,
                )
                outcomes.append(outcome)

            date_safe = f"{_s871b_safe_name(start_date or 'all')}_{_s871b_safe_name(end_date or 'all')}"
            out_path = data_lake / "simulated_outcomes" / str(interval) / str(symbol).upper() / f"{date_safe}.jsonl"
            _s871c_write_jsonl(out_path, outcomes)

            candidates_seen += len(candidates)
            all_outcomes.extend(outcomes)

            manifest["summary"]["filesSucceeded"] += 1
            manifest["summary"]["candidatesRead"] += len(candidates)
            manifest["summary"]["outcomesWritten"] += len(outcomes)
            manifest["files"].append({
                "symbol": symbol,
                "interval": interval,
                "candidatePath": str(path),
                "candlePath": str(candle_path) if candle_path else None,
                "outcomePath": str(out_path),
                "candidates": len(candidates),
                "candles": len(candles),
                "outcomes": len(outcomes),
            })

            if max_candidates and candidates_seen >= int(max_candidates):
                break

        except Exception as exc:
            manifest["summary"]["filesFailed"] += 1
            manifest["errors"].append({
                "type": "exception",
                "symbol": symbol,
                "interval": interval,
                "path": str(path),
                "message": str(exc),
            })

    total_counts, by_setup = _s871e_counts(all_outcomes)
    for key in ["worked", "failed", "session_close", "open", "no_eval", "closed"]:
        manifest["summary"][key] = total_counts.get(key, 0)
    manifest["countsBySetup"] = by_setup

    if sync_supabase and "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals():
        try:
            cfg = _s872b_supabase_config()
            manifest["supabase"]["configured"] = bool(cfg.get("configured"))
            manifest["supabase"]["masked"] = cfg.get("masked")

            if cfg.get("configured"):
                job_row = _s872b_job_row("s871e_outcome_simulation", manifest)
                job_key = job_row.get("job_key")
                op_job = _s872b_supabase_upsert("historical_learning_jobs", [job_row], "job_key", cfg)
                manifest["supabase"]["operations"].append(op_job)

                outcome_rows = [_s871e_supabase_outcome_row(item, job_key=job_key) for item in all_outcomes]
                op_outcomes = _s872b_supabase_upsert("historical_outcomes", outcome_rows, "outcome_id", cfg, chunk_size=100)
                manifest["supabase"]["operations"].append(op_outcomes)

                if not op_job.get("ok") or not op_outcomes.get("ok"):
                    manifest["ok"] = False
                    manifest["errors"].append({
                        "type": "supabase_outcome_sync_failed",
                        "operations": [op_job, op_outcomes],
                    })
            else:
                manifest["errors"].append({
                    "type": "supabase_not_configured",
                    "message": "Outcome simulation completed locally, but Supabase sync was skipped because service config is missing.",
                    "missing": cfg.get("missing"),
                })
        except Exception as exc:
            manifest["ok"] = False
            manifest["errors"].append({
                "type": "supabase_sync_exception",
                "message": str(exc),
            })

    if publish:
        reports_dir = _s871e_reports_dir()
        latest_report = reports_dir / "latest_s871e_outcomes.json"
        stamp = str(manifest.get("generatedAt") or "").replace(":", "-").replace(".", "-")
        snapshot = reports_dir / f"{stamp}.json"

        jobs_dir = data_lake / "jobs"
        latest_job = jobs_dir / "latest_s871e_outcomes.json"

        payload = json.dumps(manifest, ensure_ascii=False, indent=2, default=str)
        latest_report.write_text(payload, encoding="utf-8")
        latest_job.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return manifest


@app.post("/engine/research/historical-learning/outcomes/run")
def engine_research_historical_learning_outcomes_run(
    symbols: str = None,
    intervals: str = "5min",
    start_date: str = None,
    end_date: str = None,
    max_files: int = 1000,
    max_candidates: int = 5000,
    max_future_bars: int = 500,
    session_to_close: bool = True,
    sync_supabase: bool = True,
    publish: bool = True,
):
    return _s871e_run_outcomes(
        symbols=symbols,
        intervals=intervals,
        start_date=start_date,
        end_date=end_date,
        max_files=max_files,
        max_candidates=max_candidates,
        max_future_bars=max_future_bars,
        session_to_close=session_to_close,
        sync_supabase=sync_supabase,
        publish=publish,
    )


@app.get("/engine/research/historical-learning/outcomes/latest")
def engine_research_historical_learning_outcomes_latest():
    import json

    latest = _s871e_reports_dir() / "latest_s871e_outcomes.json"
    if not latest.exists():
        return {
            "ok": False,
            "storageVersion": S871E_HISTORICAL_OUTCOME_SIMULATOR_VERSION,
            "error": "No S8.71E outcome report yet. Run POST /engine/research/historical-learning/outcomes/run.",
        }
    return json.loads(latest.read_text(encoding="utf-8"))


@app.get("/engine/research/historical-learning/outcomes/status")
def engine_research_historical_learning_outcomes_status():
    latest = engine_research_historical_learning_outcomes_latest()
    if not isinstance(latest, dict) or not latest.get("ok"):
        return latest
    return {
        "ok": True,
        "storageVersion": S871E_HISTORICAL_OUTCOME_SIMULATOR_VERSION,
        "dateRange": latest.get("dateRange"),
        "summary": latest.get("summary"),
        "countsBySetup": latest.get("countsBySetup"),
        "fileCount": len(latest.get("files") or []),
        "errorCount": len(latest.get("errors") or []),
        "supabase": latest.get("supabase"),
        "nextEngineeringStep": latest.get("nextEngineeringStep"),
    }


# === S8.71F Historical Setup Stats + Segment Recalibration ===================
S871F_HISTORICAL_SETUP_STATS_VERSION = "s8_71f_historical_setup_stats_segment_recalibration_v1"


def _s871f_reports_dir():
    out_dir = _s870e_root_dir() / "reports" / "historical_learning" / "stats"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s871f_latest_outcome_manifest_path():
    return _s871e_reports_dir() / "latest_s871e_outcomes.json"


def _s871f_find_outcome_files(symbols=None, intervals=None, max_files=1000):
    data_lake = _s871a_data_lake_dir()
    base = data_lake / "simulated_outcomes"
    symbol_filter = set(_s871c_parse_symbols(symbols)) if symbols else None
    interval_filter = set(_s871c_parse_intervals(intervals)) if intervals else None

    files = []
    if not base.exists():
        return files

    for interval_dir in sorted([p for p in base.iterdir() if p.is_dir()]):
        interval = interval_dir.name
        if interval_filter and interval not in interval_filter:
            continue
        for symbol_dir in sorted([p for p in interval_dir.iterdir() if p.is_dir()]):
            symbol = symbol_dir.name.upper()
            if symbol_filter and symbol not in symbol_filter:
                continue
            for path in sorted(symbol_dir.glob("*.jsonl")):
                files.append({"path": path, "symbol": symbol, "interval": interval})
                if len(files) >= int(max_files or 1000):
                    return files
    return files


def _s871f_outcome_date(outcome):
    if not isinstance(outcome, dict):
        return ""
    return str(outcome.get("sessionDate") or _s871e_date_key_from_text(outcome.get("candidateAt")) or "")[:10]


def _s871f_filter_outcomes(outcomes, start_date=None, end_date=None):
    rows = []
    for outcome in outcomes or []:
        d = _s871f_outcome_date(outcome)
        if start_date and d < str(start_date):
            continue
        if end_date and d > str(end_date):
            continue
        rows.append(outcome)
    return rows


def _s871f_score_bucket(score):
    try:
        score = float(score)
    except Exception:
        return "score_unknown"
    if score >= 92:
        return "score_92_plus"
    if score >= 84:
        return "score_84_91"
    if score >= 78:
        return "score_78_83"
    return "score_below_78"


def _s871f_rvol_bucket(value):
    try:
        value = float(value)
    except Exception:
        return "rvol_unknown"
    if value >= 3:
        return "rvol_3_plus"
    if value >= 2:
        return "rvol_2_3"
    if value >= 1.2:
        return "rvol_1_2_2"
    return "rvol_below_1_2"


def _s871f_dist_bucket(value):
    try:
        value = abs(float(value))
    except Exception:
        return "vwap_dist_unknown"
    if value >= 3:
        return "vwap_dist_3_plus"
    if value >= 1.5:
        return "vwap_dist_1_5_3"
    if value >= 0.5:
        return "vwap_dist_0_5_1_5"
    return "vwap_dist_below_0_5"


def _s871f_outcome_candidate(outcome):
    payload = outcome.get("payload") if isinstance(outcome, dict) else {}
    if isinstance(payload, dict) and isinstance(payload.get("candidate"), dict):
        return payload.get("candidate")
    return {}


def _s871f_feature_value(outcome, key):
    candidate = _s871f_outcome_candidate(outcome)
    source = candidate.get("source") if isinstance(candidate, dict) else {}
    features = source.get("features") if isinstance(source, dict) else {}
    if isinstance(features, dict):
        return features.get(key)
    return None


def _s871f_group_key(outcome, mode="setup"):
    candidate = _s871f_outcome_candidate(outcome)

    setup = str(outcome.get("setupSlug") or "unknown")
    direction = str(outcome.get("direction") or "unknown")
    interval = str(outcome.get("interval") or "unknown")

    if mode == "setup":
        return {
            "key": f"{setup}|{direction}|{interval}",
            "setupSlug": setup,
            "direction": direction,
            "interval": interval,
            "filters": {},
            "segmentKey": None,
        }

    grade = str(candidate.get("grade") or "grade_unknown")
    session = str(candidate.get("session") or outcome.get("session") or "session_unknown")
    score_bucket = _s871f_score_bucket(candidate.get("score"))
    rvol_bucket = _s871f_rvol_bucket(_s871f_feature_value(outcome, "rvol20"))
    dist_bucket = _s871f_dist_bucket(_s871f_feature_value(outcome, "distanceFromVwapPct"))

    filters = {
        "grade": grade,
        "session": session,
        "scoreBucket": score_bucket,
        "rvolBucket": rvol_bucket,
        "vwapDistanceBucket": dist_bucket,
    }

    segment_key = f"{setup}|{direction}|{interval}|{grade}|{session}|{score_bucket}|{rvol_bucket}|{dist_bucket}"
    return {
        "key": segment_key,
        "setupSlug": setup,
        "direction": direction,
        "interval": interval,
        "filters": filters,
        "segmentKey": segment_key,
    }


def _s871f_init_agg(meta):
    return {
        "setupSlug": meta.get("setupSlug"),
        "direction": meta.get("direction"),
        "interval": meta.get("interval"),
        "filters": meta.get("filters") or {},
        "segmentKey": meta.get("segmentKey"),
        "total": 0,
        "worked": 0,
        "failed": 0,
        "session_close": 0,
        "open": 0,
        "no_eval": 0,
        "closedTrades": 0,
        "decisionTrades": 0,
        "wins": 0,
        "losses": 0,
        "resultRs": [],
        "decisionResultRs": [],
        "mfeRs": [],
        "maeRs": [],
    }


def _s871f_add_outcome(agg, outcome):
    status = str(outcome.get("resultStatus") or "unknown")
    result_r = _s871e_float(outcome.get("resultR"))
    mfe_r = _s871e_float(outcome.get("mfeR"))
    mae_r = _s871e_float(outcome.get("maeR"))

    agg["total"] += 1
    agg[status] = agg.get(status, 0) + 1

    # "closedTrades" includes session_close as finished evaluation.
    # "decisionTrades" is the honest win/loss denominator: worked + failed only.
    if status in {"worked", "failed", "session_close"}:
        agg["closedTrades"] += 1
        if result_r is not None:
            agg["resultRs"].append(result_r)

    if status in {"worked", "failed"}:
        agg["decisionTrades"] += 1
        if result_r is not None:
            agg["decisionResultRs"].append(result_r)

    if status == "worked":
        agg["wins"] += 1
    if status == "failed":
        agg["losses"] += 1

    if mfe_r is not None:
        agg["mfeRs"].append(mfe_r)
    if mae_r is not None:
        agg["maeRs"].append(mae_r)


def _s871f_avg(values):
    nums = [float(v) for v in values or [] if v is not None]
    if not nums:
        return None
    return sum(nums) / len(nums)


def _s871f_overfit_risk(decision_trades, segment=False):
    try:
        n = int(decision_trades or 0)
    except Exception:
        n = 0
    if n < 10:
        return "HIGH"
    if segment and n < 30:
        return "HIGH"
    if n < 30:
        return "MEDIUM"
    return "LOW"


def _s871f_sample_status(row, target_win_rate=0.65, min_closed_trades=30):
    decision_trades = int(row.get("decisionTrades") or 0)
    win_rate = row.get("winRate")
    expectancy = row.get("expectancyR")
    overfit = row.get("overfitRisk")

    if decision_trades < int(min_closed_trades or 30):
        return "insufficient_sample"
    if win_rate is not None and float(win_rate) >= float(target_win_rate or 0.65) and expectancy is not None and float(expectancy) > 0 and overfit != "HIGH":
        return "production_candidate"
    if expectancy is not None and float(expectancy) > 0:
        return "promising_research"
    return "research_rework"


def _s871f_finalize_agg(agg, target_win_rate=0.65, min_closed_trades=30, segment=False):
    decision_trades = int(agg.get("decisionTrades") or 0)
    wins = int(agg.get("wins") or 0)
    win_rate = (wins / decision_trades) if decision_trades > 0 else None
    avg_r = _s871f_avg(agg.get("decisionResultRs"))
    expectancy = avg_r
    avg_mfe = _s871f_avg(agg.get("mfeRs"))
    avg_mae = _s871f_avg(agg.get("maeRs"))
    overfit = _s871f_overfit_risk(decision_trades, segment=segment)

    row = {
        "setupSlug": agg.get("setupSlug"),
        "direction": agg.get("direction"),
        "interval": agg.get("interval"),
        "filters": agg.get("filters") or {},
        "segmentKey": agg.get("segmentKey"),
        "totalTrades": int(agg.get("total") or 0),
        "closedTrades": int(agg.get("closedTrades") or 0),
        "decisionTrades": decision_trades,
        "wins": wins,
        "losses": int(agg.get("losses") or 0),
        "worked": int(agg.get("worked") or 0),
        "failed": int(agg.get("failed") or 0),
        "sessionClose": int(agg.get("session_close") or 0),
        "open": int(agg.get("open") or 0),
        "noEval": int(agg.get("no_eval") or 0),
        "winRate": round(win_rate, 6) if win_rate is not None else None,
        "avgR": round(avg_r, 6) if avg_r is not None else None,
        "expectancyR": round(expectancy, 6) if expectancy is not None else None,
        "avgMfeR": round(avg_mfe, 6) if avg_mfe is not None else None,
        "avgMaeR": round(avg_mae, 6) if avg_mae is not None else None,
        "overfitRisk": overfit,
    }
    row["sampleStatus"] = _s871f_sample_status(row, target_win_rate=target_win_rate, min_closed_trades=min_closed_trades)
    row["productionEligible"] = row["sampleStatus"] == "production_candidate"
    row["promising"] = row["sampleStatus"] in {"production_candidate", "promising_research"}
    return row


def _s871f_stats_supabase_row(row, job_key=None, start_date=None, end_date=None):
    key_source = f"{row.get('setupSlug')}|{row.get('direction')}|{row.get('interval')}|{row.get('segmentKey') or 'base'}|{start_date}|{end_date}"
    return {
        "stats_key": f"s871f_stats:{_s872b_hash(key_source)}",
        "job_key": job_key,
        "setup_slug": row.get("setupSlug"),
        "direction": row.get("direction"),
        "interval": row.get("interval"),
        "segment_key": row.get("segmentKey"),
        "start_date": _s872b_to_date(start_date) if "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals() else start_date,
        "end_date": _s872b_to_date(end_date) if "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals() else end_date,
        "total_trades": row.get("totalTrades") or 0,
        "closed_trades": row.get("decisionTrades") or 0,
        "wins": row.get("wins") or 0,
        "losses": row.get("losses") or 0,
        "no_eval": row.get("noEval") or 0,
        "win_rate": row.get("winRate"),
        "avg_r": row.get("avgR"),
        "expectancy_r": row.get("expectancyR"),
        "avg_mfe_r": row.get("avgMfeR"),
        "avg_mae_r": row.get("avgMaeR"),
        "sample_status": row.get("sampleStatus"),
        "overfit_risk": row.get("overfitRisk"),
        "source": {
            "version": S871F_HISTORICAL_SETUP_STATS_VERSION,
            "note": "closed_trades in this table uses worked+failed decision trades. session_close/no_eval are not wins/losses.",
        },
        "payload": row,
    }


def _s871f_segment_supabase_row(row, job_key=None, start_date=None, end_date=None):
    key_source = row.get("segmentKey") or f"{row.get('setupSlug')}|{row.get('direction')}|{row.get('interval')}|{row.get('filters')}"
    return {
        "segment_key": f"s871f_segment:{_s872b_hash(key_source)}",
        "job_key": job_key,
        "setup_slug": row.get("setupSlug"),
        "direction": row.get("direction"),
        "interval": row.get("interval"),
        "filters": row.get("filters") if isinstance(row.get("filters"), dict) else {},
        "start_date": _s872b_to_date(start_date) if "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals() else start_date,
        "end_date": _s872b_to_date(end_date) if "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals() else end_date,
        "closed_trades": row.get("decisionTrades") or 0,
        "wins": row.get("wins") or 0,
        "losses": row.get("losses") or 0,
        "win_rate": row.get("winRate"),
        "avg_r": row.get("avgR"),
        "expectancy_r": row.get("expectancyR"),
        "overfit_risk": row.get("overfitRisk"),
        "status": row.get("sampleStatus"),
        "production_eligible": bool(row.get("productionEligible")),
        "promising": bool(row.get("promising")),
        "payload": row,
    }


def _s871f_run_stats(
    symbols=None,
    intervals="5min",
    start_date=None,
    end_date=None,
    max_files=1000,
    target_win_rate=0.65,
    min_closed_trades=30,
    sync_supabase=True,
    publish=True,
):
    import json

    files = _s871f_find_outcome_files(symbols=symbols, intervals=intervals, max_files=max_files)

    manifest = {
        "ok": True,
        "storageVersion": S871F_HISTORICAL_SETUP_STATS_VERSION,
        "generatedAt": _s871b_now_iso(),
        "symbols": _s871c_parse_symbols(symbols) if symbols else None,
        "intervals": _s871c_parse_intervals(intervals),
        "dateRange": {"startDate": start_date, "endDate": end_date},
        "thresholds": {
            "targetWinRate": float(target_win_rate or 0.65),
            "minClosedTrades": int(min_closed_trades or 30),
            "winLossDenominator": "worked_plus_failed_only",
            "sessionCloseIsNotWinOrLoss": True,
            "noEvalIsNotWinOrLoss": True,
        },
        "summary": {
            "filesScanned": len(files),
            "filesSucceeded": 0,
            "filesFailed": 0,
            "outcomesRead": 0,
            "setupStatsWritten": 0,
            "segmentsWritten": 0,
            "productionEligibleSegments": 0,
            "promisingSegments": 0,
        },
        "setupStats": [],
        "segments": [],
        "topSegments": [],
        "supabase": {"requested": bool(sync_supabase), "configured": False, "operations": []},
        "errors": [],
        "policy": {
            "honestWinRate": True,
            "sessionCloseIsNotWinOrLoss": True,
            "noEvalIsNotWinOrLoss": True,
            "doesNotChangeClientDelivery": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "requiresWalkForwardBeforePromotion": True,
        },
        "nextEngineeringStep": "S8.71G Walk-Forward Validation Foundation: validate any promising/production-candidate segments across time windows before promotion.",
    }

    setup_groups = {}
    segment_groups = {}
    seen_outcome_ids = set()

    for item in files:
        path = item.get("path")
        try:
            outcomes = _s871c_read_jsonl(path)
            outcomes = _s871f_filter_outcomes(outcomes, start_date=start_date, end_date=end_date)

            unique_outcomes = []
            for outcome in outcomes:
                oid = str(outcome.get("outcomeId") or outcome.get("candidateId") or "").strip() if isinstance(outcome, dict) else ""
                if oid and oid in seen_outcome_ids:
                    continue
                if oid:
                    seen_outcome_ids.add(oid)
                unique_outcomes.append(outcome)
            outcomes = unique_outcomes

            for outcome in outcomes:
                meta = _s871f_group_key(outcome, mode="setup")
                agg = setup_groups.setdefault(meta["key"], _s871f_init_agg(meta))
                _s871f_add_outcome(agg, outcome)

                seg_meta = _s871f_group_key(outcome, mode="segment")
                seg_agg = segment_groups.setdefault(seg_meta["key"], _s871f_init_agg(seg_meta))
                _s871f_add_outcome(seg_agg, outcome)

            manifest["summary"]["filesSucceeded"] += 1
            manifest["summary"]["outcomesRead"] += len(outcomes)
        except Exception as exc:
            manifest["summary"]["filesFailed"] += 1
            manifest["errors"].append({
                "type": "exception",
                "path": str(path),
                "message": str(exc),
            })

    setup_rows = [
        _s871f_finalize_agg(agg, target_win_rate=target_win_rate, min_closed_trades=min_closed_trades, segment=False)
        for agg in setup_groups.values()
    ]
    segment_rows = [
        _s871f_finalize_agg(agg, target_win_rate=target_win_rate, min_closed_trades=min_closed_trades, segment=True)
        for agg in segment_groups.values()
    ]

    setup_rows = sorted(setup_rows, key=lambda r: (r.get("decisionTrades") or 0, r.get("winRate") or 0), reverse=True)
    segment_rows = sorted(segment_rows, key=lambda r: (r.get("productionEligible"), r.get("promising"), r.get("winRate") or 0, r.get("decisionTrades") or 0), reverse=True)

    manifest["setupStats"] = setup_rows
    manifest["segments"] = segment_rows
    manifest["topSegments"] = segment_rows[:25]
    manifest["summary"]["setupStatsWritten"] = len(setup_rows)
    manifest["summary"]["segmentsWritten"] = len(segment_rows)
    manifest["summary"]["productionEligibleSegments"] = len([r for r in segment_rows if r.get("productionEligible")])
    manifest["summary"]["promisingSegments"] = len([r for r in segment_rows if r.get("promising")])

    if sync_supabase and "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals():
        try:
            cfg = _s872b_supabase_config()
            manifest["supabase"]["configured"] = bool(cfg.get("configured"))
            manifest["supabase"]["masked"] = cfg.get("masked")

            if cfg.get("configured"):
                job_row = _s872b_job_row("s871f_stats_segment_recalibration", manifest)
                job_key = job_row.get("job_key")
                op_job = _s872b_supabase_upsert("historical_learning_jobs", [job_row], "job_key", cfg)
                manifest["supabase"]["operations"].append(op_job)

                stats_rows = [_s871f_stats_supabase_row(r, job_key=job_key, start_date=start_date, end_date=end_date) for r in setup_rows]
                op_stats = _s872b_supabase_upsert("historical_setup_stats", stats_rows, "stats_key", cfg, chunk_size=100)
                manifest["supabase"]["operations"].append(op_stats)

                segment_upsert_rows = [_s871f_segment_supabase_row(r, job_key=job_key, start_date=start_date, end_date=end_date) for r in segment_rows]
                op_segments = _s872b_supabase_upsert("historical_segments", segment_upsert_rows, "segment_key", cfg, chunk_size=100)
                manifest["supabase"]["operations"].append(op_segments)

                if not op_job.get("ok") or not op_stats.get("ok") or not op_segments.get("ok"):
                    manifest["ok"] = False
                    manifest["errors"].append({
                        "type": "supabase_stats_sync_failed",
                        "operations": [op_job, op_stats, op_segments],
                    })
            else:
                manifest["errors"].append({
                    "type": "supabase_not_configured",
                    "message": "Stats completed locally, but Supabase sync was skipped because service config is missing.",
                    "missing": cfg.get("missing"),
                })
        except Exception as exc:
            manifest["ok"] = False
            manifest["errors"].append({
                "type": "supabase_sync_exception",
                "message": str(exc),
            })

    if publish:
        reports_dir = _s871f_reports_dir()
        latest_report = reports_dir / "latest_s871f_stats.json"
        stamp = str(manifest.get("generatedAt") or "").replace(":", "-").replace(".", "-")
        snapshot = reports_dir / f"{stamp}.json"

        data_lake = _s871a_data_lake_dir()
        jobs_dir = data_lake / "jobs"
        latest_job = jobs_dir / "latest_s871f_stats.json"

        payload = json.dumps(manifest, ensure_ascii=False, indent=2, default=str)
        latest_report.write_text(payload, encoding="utf-8")
        latest_job.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return manifest


@app.post("/engine/research/historical-learning/stats/run")
def engine_research_historical_learning_stats_run(
    symbols: str = None,
    intervals: str = "5min",
    start_date: str = None,
    end_date: str = None,
    max_files: int = 1000,
    target_win_rate: float = 0.65,
    min_closed_trades: int = 30,
    sync_supabase: bool = True,
    publish: bool = True,
):
    return _s871f_run_stats(
        symbols=symbols,
        intervals=intervals,
        start_date=start_date,
        end_date=end_date,
        max_files=max_files,
        target_win_rate=target_win_rate,
        min_closed_trades=min_closed_trades,
        sync_supabase=sync_supabase,
        publish=publish,
    )


@app.get("/engine/research/historical-learning/stats/latest")
def engine_research_historical_learning_stats_latest():
    import json

    latest = _s871f_reports_dir() / "latest_s871f_stats.json"
    if not latest.exists():
        return {
            "ok": False,
            "storageVersion": S871F_HISTORICAL_SETUP_STATS_VERSION,
            "error": "No S8.71F stats report yet. Run POST /engine/research/historical-learning/stats/run.",
        }
    return json.loads(latest.read_text(encoding="utf-8"))


@app.get("/engine/research/historical-learning/stats/status")
def engine_research_historical_learning_stats_status():
    latest = engine_research_historical_learning_stats_latest()
    if not isinstance(latest, dict) or not latest.get("ok"):
        return latest
    return {
        "ok": True,
        "storageVersion": S871F_HISTORICAL_SETUP_STATS_VERSION,
        "dateRange": latest.get("dateRange"),
        "thresholds": latest.get("thresholds"),
        "summary": latest.get("summary"),
        "topSetupStats": (latest.get("setupStats") or [])[:10],
        "topSegments": latest.get("topSegments"),
        "supabase": latest.get("supabase"),
        "errorCount": len(latest.get("errors") or []),
        "nextEngineeringStep": latest.get("nextEngineeringStep"),
    }


# === S8.73 Historical Backfill Orchestrator =================================
S873_HISTORICAL_BACKFILL_ORCHESTRATOR_VERSION = "s8_73_historical_backfill_orchestrator_v1"


def _s873_backfill_dir():
    out_dir = _s871a_data_lake_dir() / "backfill"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s873_reports_dir():
    out_dir = _s870e_root_dir() / "reports" / "historical_learning" / "backfill"
    out_dir.mkdir(parents=True, exist_ok=True)
    return out_dir


def _s873_queue_path():
    return _s873_backfill_dir() / "latest_s873_queue.json"


def _s873_json_read(path, default=None):
    import json
    from pathlib import Path

    try:
        p = Path(path)
        if not p.exists():
            return default
        return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        return default


def _s873_json_write(path, payload):
    import json

    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, default=str), encoding="utf-8")


# === S8.75B2 Completed-Day Backfill Guard ===================================
S875B_COMPLETED_DAY_BACKFILL_GUARD_VERSION = "s8_75b2_completed_day_backfill_guard_v2"


def _s873_date_list(start_date=None, end_date=None, years_back=5, max_days=10):
    from datetime import date, timedelta

    today = date.today()
    last_completed_day = today - timedelta(days=1)

    if end_date:
        end = date.fromisoformat(str(end_date))
        if end >= today:
            end = last_completed_day
    else:
        end = last_completed_day

    if start_date:
        start = date.fromisoformat(str(start_date))
    else:
        start = end - timedelta(days=int(float(years_back or 5) * 365))

    if start > end:
        return []

    days = []
    d = start
    while d <= end:
        # Calendar days, not full US exchange calendar yet.
        # S8.75B2 guard: only completed server-local dates are allowed.
        if d.weekday() < 5:
            days.append(d.isoformat())
        d += timedelta(days=1)

    if max_days and int(max_days) > 0:
        days = days[-int(max_days):]

    return days


def _s873_make_chunks(days, chunk_days=1):
    chunk_days = max(1, int(chunk_days or 1))
    chunks = []
    current = []

    for d in days or []:
        current.append(d)
        if len(current) >= chunk_days:
            chunks.append({"startDate": current[0], "endDate": current[-1], "days": list(current)})
            current = []

    if current:
        chunks.append({"startDate": current[0], "endDate": current[-1], "days": list(current)})

    return chunks


def _s873_load_queue():
    return _s873_json_read(_s873_queue_path(), default=None)


def _s873_save_queue(queue):
    _s873_json_write(_s873_queue_path(), queue)
    reports_path = _s873_reports_dir() / "latest_s873_backfill_queue.json"
    _s873_json_write(reports_path, queue)
    return queue


def _s873_create_plan(
    symbols=None,
    intervals="5min",
    start_date=None,
    end_date=None,
    years_back=5,
    max_days=10,
    chunk_days=1,
    reset=True,
    publish=True,
):
    symbol_list = _s871b_parse_symbols(symbols) or ["AAPL", "NVDA", "TSLA"]
    interval_list = _s871c_parse_intervals(intervals or "5min")
    days = _s873_date_list(start_date=start_date, end_date=end_date, years_back=years_back, max_days=max_days)
    chunks = _s873_make_chunks(days, chunk_days=chunk_days)

    jobs = []
    for idx, chunk in enumerate(chunks, start=1):
        job_id = f"s873:{_s872b_hash(str(symbol_list)+str(interval_list)+chunk['startDate']+chunk['endDate'])}"
        jobs.append({
            "jobId": job_id,
            "status": "PENDING",
            "symbols": symbol_list,
            "intervals": interval_list,
            "startDate": chunk["startDate"],
            "endDate": chunk["endDate"],
            "days": chunk.get("days") or [],
            "attempts": 0,
            "createdAt": _s871b_now_iso(),
            "startedAt": None,
            "finishedAt": None,
            "steps": [],
            "error": None,
        })

    queue = {
        "ok": True,
        "storageVersion": S873_HISTORICAL_BACKFILL_ORCHESTRATOR_VERSION,
        "generatedAt": _s871b_now_iso(),
        "status": "READY",
        "symbols": symbol_list,
        "intervals": interval_list,
        "plan": {
            "yearsBack": years_back,
            "startDate": start_date,
            "endDate": end_date,
            "maxDays": max_days,
            "chunkDays": chunk_days,
            "calendarMode": "weekday_completed_days_v2",
            "completedDayGuardVersion": S875B_COMPLETED_DAY_BACKFILL_GUARD_VERSION,
            "skipsCurrentOrFutureServerLocalDates": True,
        },
        "summary": {
            "totalJobs": len(jobs),
            "pending": len(jobs),
            "running": 0,
            "completed": 0,
            "failed": 0,
            "skipped": 0,
        },
        "jobs": jobs,
        "policy": {
            "safeChunkedBackfill": True,
            "doesNotChangeClientDelivery": True,
            "doesNotApproveSignals": True,
            "doesNotRejectSignals": True,
            "doesNotSendTelegram": True,
            "doesNotPromoteStrategies": True,
            "fullFiveYearRunRequiresSchedulerAndLimits": True,
            "completedDayGuard": True,
        },
        "nextEngineeringStep": "S8.74 Historical Learning Scheduler: run backfill chunks automatically on VPS with rate-limit safe cadence.",
    }

    if publish:
        _s873_save_queue(queue)

    return queue


def _s873_refresh_summary(queue):
    jobs = queue.get("jobs") or []
    summary = {
        "totalJobs": len(jobs),
        "pending": 0,
        "running": 0,
        "completed": 0,
        "failed": 0,
        "skipped": 0,
    }
    for job in jobs:
        status = str(job.get("status") or "").upper()
        if status == "PENDING":
            summary["pending"] += 1
        elif status == "RUNNING":
            summary["running"] += 1
        elif status == "COMPLETED":
            summary["completed"] += 1
        elif status == "FAILED":
            summary["failed"] += 1
        elif status == "SKIPPED":
            summary["skipped"] += 1
    queue["summary"] = summary
    if summary["pending"] == 0 and summary["running"] == 0 and summary["failed"] == 0 and summary["completed"] > 0:
        queue["status"] = "COMPLETED"
    elif summary["failed"] > 0:
        queue["status"] = "HAS_FAILURES"
    else:
        queue["status"] = "READY"
    return queue


# === S8.76A Candidate Sync Before Outcomes Hotfix ============================
S876A_CANDIDATE_SYNC_BEFORE_OUTCOMES_VERSION = "s8_76a_candidate_sync_before_outcomes_hotfix_v1"


async def _s873_run_one_job(job, sync_supabase=True, max_candidates=5000):
    result = {
        "jobId": job.get("jobId"),
        "ok": True,
        "startedAt": _s871b_now_iso(),
        "finishedAt": None,
        "steps": [],
        "summary": {},
        "errors": [],
    }

    symbols = ",".join(job.get("symbols") or [])
    intervals = ",".join(job.get("intervals") or [])
    start_date = job.get("startDate")
    end_date = job.get("endDate")

    def _record_step(name, payload):
        step = {
            "name": name,
            "ok": bool(isinstance(payload, dict) and payload.get("ok", True)),
            "storageVersion": payload.get("storageVersion") if isinstance(payload, dict) else None,
            "dedupeHotfixVersion": S873A_BACKFILL_DUPLICATE_OUTCOME_HOTFIX_VERSION,
            "candidateSyncHotfixVersion": S876A_CANDIDATE_SYNC_BEFORE_OUTCOMES_VERSION,
            "summary": payload.get("summary") if isinstance(payload, dict) else None,
            "errorCount": len(payload.get("errors") or []) if isinstance(payload, dict) else 0,
        }
        result["steps"].append(step)
        if not step["ok"]:
            result["ok"] = False
            result["errors"].append({"step": name, "payloadErrors": payload.get("errors") if isinstance(payload, dict) else payload})
        return step

    try:
        ingestion = await _s871b2_run_ingestion_compatible(
            symbols=symbols,
            start_date=start_date,
            end_date=end_date,
            intervals=intervals,
            max_symbols=len(job.get("symbols") or []),
            provider="engine_fmp_client",
            publish=True,
        )
        _record_step("ingestion", ingestion)

        ingestion_summary = ingestion.get("summary") if isinstance(ingestion, dict) else {}
        raw_rows = int(ingestion_summary.get("rawRowsStored") or 0)
        normalized_rows = int(ingestion_summary.get("normalizedRowsStored") or 0)

        if raw_rows <= 0 and normalized_rows <= 0:
            result["ok"] = True
            result["skipped"] = True
            result["skipReason"] = "no_provider_rows_for_chunk"
            result["noDataGuardVersion"] = S881A_NO_DATA_CHUNK_GUARD_VERSION
            result["summary"] = {
                "ingestion": ingestion_summary,
                "noData": True,
                "reason": "Provider returned zero raw/normalized rows for this date/symbol/interval chunk.",
            }
            result["finishedAt"] = _s871b_now_iso()
            return result

        features = _s884b_build_features_robust(
            symbols=symbols,
            intervals=intervals,
            start_date=start_date,
            end_date=end_date,
            max_files=1000,
            publish=True,
        )
        _record_step("features", features)

        replay = _s884a_run_setup_replay_robust(
            symbols=symbols,
            intervals=intervals,
            start_date=start_date,
            end_date=end_date,
            max_files=1000,
            max_candidates_per_file=int(max_candidates or 5000),
            publish=True,
        )
        _record_step("setup_replay", replay)

        candidate_sync = None
        if bool(sync_supabase) and "S872B_HISTORICAL_LEARNING_SUPABASE_SYNC_VERSION" in globals():
            # Critical FK guard:
            # historical_outcomes.candidate_id references historical_setup_candidates(candidate_id).
            # Backfill creates fresh historical candidates, so they must be upserted before outcomes.
            candidate_sync = _s872b_run_supabase_sync(
                sync_candidates=True,
                max_candidates=int(max_candidates or 5000),
                publish=True,
            )
            _record_step("candidate_supabase_sync", candidate_sync)

        outcomes = _s884d_run_outcomes_robust(
            symbols=symbols,
            intervals=intervals,
            start_date=start_date,
            end_date=end_date,
            max_files=1000,
            max_candidates=int(max_candidates or 5000),
            max_future_bars=500,
            session_to_close=True,
            sync_supabase=bool(sync_supabase),
            publish=True,
        )
        _record_step("outcomes", outcomes)

        stats = _s871f_run_stats(
            symbols=symbols,
            intervals=intervals,
            start_date=start_date,
            end_date=end_date,
            max_files=1000,
            target_win_rate=0.65,
            min_closed_trades=30,
            sync_supabase=bool(sync_supabase),
            publish=True,
        )
        _record_step("stats", stats)

        result["summary"] = {
            "ingestion": ingestion.get("summary") if isinstance(ingestion, dict) else None,
            "features": features.get("summary") if isinstance(features, dict) else None,
            "setupReplay": replay.get("summary") if isinstance(replay, dict) else None,
            "candidateSync": candidate_sync.get("summary") if isinstance(candidate_sync, dict) else None,
            "outcomes": outcomes.get("summary") if isinstance(outcomes, dict) else None,
            "stats": stats.get("summary") if isinstance(stats, dict) else None,
        }

    except Exception as exc:
        result["ok"] = False
        result["errors"].append({"type": "exception", "message": str(exc)})

    result["finishedAt"] = _s871b_now_iso()
    return result


async def _s873_run_next(max_jobs=1, sync_supabase=True, max_candidates=5000, publish=True):
    import json

    queue = _s873_load_queue()
    if not isinstance(queue, dict):
        queue = _s873_create_plan(
            symbols="AAPL,NVDA,TSLA",
            intervals="5min",
            max_days=3,
            chunk_days=1,
            reset=True,
            publish=True,
        )

    jobs = queue.get("jobs") or []
    pending_indexes = [i for i, job in enumerate(jobs) if str(job.get("status") or "").upper() == "PENDING"]

    run_results = []
    for idx in pending_indexes[: int(max_jobs or 1)]:
        job = jobs[idx]
        job["status"] = "RUNNING"
        job["startedAt"] = _s871b_now_iso()
        job["attempts"] = int(job.get("attempts") or 0) + 1
        _s873_refresh_summary(queue)
        if publish:
            _s873_save_queue(queue)

        result = await _s873_run_one_job(job, sync_supabase=sync_supabase, max_candidates=max_candidates)
        run_results.append(result)

        job["finishedAt"] = _s871b_now_iso()
        job["steps"] = result.get("steps") or []
        job["lastResultSummary"] = result.get("summary") or {}
        if result.get("ok"):
            job["status"] = "COMPLETED"
            job["error"] = None
        else:
            job["status"] = "FAILED"
            job["error"] = result.get("errors")

        _s873_refresh_summary(queue)
        if publish:
            _s873_save_queue(queue)

    manifest = {
        "ok": all(item.get("ok") for item in run_results) if run_results else True,
        "storageVersion": S873_HISTORICAL_BACKFILL_ORCHESTRATOR_VERSION,
        "generatedAt": _s871b_now_iso(),
        "runResults": run_results,
        "queueSummary": queue.get("summary"),
        "queueStatus": queue.get("status"),
        "policy": {
            "safeChunkedBackfill": True,
            "maxJobsThisRun": int(max_jobs or 1),
            "doesNotChangeClientDelivery": True,
            "doesNotSendTelegram": True,
            "doesNotPromoteStrategies": True,
        },
    }

    if publish:
        reports_dir = _s873_reports_dir()
        latest_report = reports_dir / "latest_s873_backfill_run.json"
        stamp = str(manifest.get("generatedAt") or "").replace(":", "-").replace(".", "-")
        snapshot = reports_dir / f"{stamp}.json"
        payload = json.dumps(manifest, ensure_ascii=False, indent=2, default=str)
        latest_report.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return manifest


