# === S8.78 Promotion Policy Writer ==========================================
S878_PROMOTION_POLICY_WRITER_VERSION = "s8_78_promotion_policy_writer_v1"


def _s878_reports_dir():
    d = _s870e_root_dir() / "reports" / "historical_learning" / "promotion_policy"
    d.mkdir(parents=True, exist_ok=True)
    return d


def _s878_policy_dir():
    d = _s871a_data_lake_dir() / "policies"
    d.mkdir(parents=True, exist_ok=True)
    return d


def _s878_latest_walk_forward():
    try:
        return _s877_latest_report()
    except Exception:
        return None


def _s878_policy_status(result, min_total_decision_trades=300, min_windows=3):
    total = result.get("total") or {}
    total_decision = int(total.get("decisionTrades") or 0)
    wf_pass_windows = int(result.get("walkForwardPassWindows") or 0)
    wf_pass = bool(result.get("walkForwardPass"))

    reasons = []

    if total_decision < int(min_total_decision_trades or 300):
        reasons.append("INSUFFICIENT_TOTAL_DECISION_TRADES")
    if wf_pass_windows < int(min_windows or 3):
        reasons.append("INSUFFICIENT_WALK_FORWARD_WINDOWS")
    if not wf_pass:
        reasons.append("WALK_FORWARD_NOT_PASSED")
    if not reasons:
        # Still not released: forward/shadow/manual gates are required.
        reasons.append("FORWARD_SHADOW_AND_MANUAL_APPROVAL_REQUIRED")
        return "FORWARD_SHADOW_REQUIRED", reasons

    return "BLOCKED_RESEARCH_ONLY", reasons


def _s878_build_policy_from_walk_forward(
    min_total_decision_trades=300,
    min_windows=3,
    min_win_rate=0.65,
    publish=True,
    sync_supabase=True,
):
    import json
    import hashlib

    wf = _s878_latest_walk_forward()
    if not isinstance(wf, dict) or not wf.get("ok", True):
        return {
            "ok": False,
            "storageVersion": S878_PROMOTION_POLICY_WRITER_VERSION,
            "error": "No valid S8.77 walk-forward report found. Run /walk-forward/run first.",
        }

    results = wf.get("results") or wf.get("topResults") or []
    generated_at = _s871b_now_iso()
    job_seed = f"{generated_at}|{len(results)}|{wf.get('jobId')}"
    job_id = "s878_" + hashlib.sha1(job_seed.encode("utf-8")).hexdigest()[:16]

    policies = []
    for result in results:
        total = result.get("total") or {}
        setup_slug = str(result.get("setupSlug") or "unknown_setup")
        direction = str(result.get("direction") or "UNKNOWN").upper()
        interval = str(result.get("interval") or "5min")

        status, reasons = _s878_policy_status(
            result,
            min_total_decision_trades=min_total_decision_trades,
            min_windows=min_windows,
        )

        total_win_rate = total.get("winRate")
        try:
            total_win_rate_f = float(total_win_rate) if total_win_rate is not None else None
        except Exception:
            total_win_rate_f = None

        if total_win_rate_f is not None and total_win_rate_f < float(min_win_rate or 0.65):
            if "TOTAL_WIN_RATE_BELOW_TARGET" not in reasons:
                reasons.append("TOTAL_WIN_RATE_BELOW_TARGET")
            status = "BLOCKED_RESEARCH_ONLY"

        policy_key = f"{setup_slug}|{direction}|{interval}"
        policies.append({
            "policyKey": policy_key,
            "setupSlug": setup_slug,
            "direction": direction,
            "interval": interval,
            "status": status,
            "clientReleaseAllowed": False,
            "productionEligible": False,
            "telegramAllowed": False,
            "manualApprovalRequired": True,
            "forwardShadowRequired": True,
            "reasons": reasons,
            "walkForward": {
                "walkForwardPass": bool(result.get("walkForwardPass")),
                "walkForwardPassWindows": int(result.get("walkForwardPassWindows") or 0),
                "promotionAllowedFromWalkForward": False,
                "sourceJobId": wf.get("jobId"),
            },
            "stats": {
                "totalTrades": int(total.get("totalTrades") or 0),
                "decisionTrades": int(total.get("decisionTrades") or 0),
                "wins": int(total.get("wins") or 0),
                "losses": int(total.get("losses") or 0),
                "ignored": int(total.get("ignored") or 0),
                "winRate": total.get("winRate"),
                "avgR": total.get("avgR"),
                "expectancyR": total.get("expectancyR"),
                "avgMfeR": total.get("avgMfeR"),
                "avgMaeR": total.get("avgMaeR"),
            },
            "thresholds": {
                "minTotalDecisionTrades": int(min_total_decision_trades or 300),
                "minWalkForwardWindows": int(min_windows or 3),
                "minWinRate": float(min_win_rate or 0.65),
            },
            "updatedAt": generated_at,
            "writerVersion": S878_PROMOTION_POLICY_WRITER_VERSION,
        })

    summary = {
        "policiesWritten": len(policies),
        "clientReleaseAllowed": len([p for p in policies if p.get("clientReleaseAllowed")]),
        "productionEligible": len([p for p in policies if p.get("productionEligible")]),
        "forwardShadowRequired": len([p for p in policies if p.get("status") == "FORWARD_SHADOW_REQUIRED"]),
        "blockedResearchOnly": len([p for p in policies if p.get("status") == "BLOCKED_RESEARCH_ONLY"]),
    }

    supabase = {"requested": bool(sync_supabase), "configured": False, "operations": []}
    if sync_supabase:
        rows = []
        for p in policies:
            rows.append({
                "policy_key": p.get("policyKey"),
                "setup_slug": p.get("setupSlug"),
                "direction": p.get("direction"),
                "interval": p.get("interval"),
                "status": p.get("status"),
                "client_release_allowed": bool(p.get("clientReleaseAllowed")),
                "production_eligible": bool(p.get("productionEligible")),
                "telegram_allowed": bool(p.get("telegramAllowed")),
                "manual_approval_required": bool(p.get("manualApprovalRequired")),
                "forward_shadow_required": bool(p.get("forwardShadowRequired")),
                "reasons": p.get("reasons"),
                "walk_forward": p.get("walkForward"),
                "stats": p.get("stats"),
                "thresholds": p.get("thresholds"),
                "writer_version": p.get("writerVersion"),
                "updated_at": p.get("updatedAt"),
            })

        try:
            cfg = _s872b_supabase_config()
            supabase = {
                "requested": True,
                "configured": bool(cfg.get("configured")),
                "operations": [],
                "masked": cfg.get("masked"),
            }
            if cfg.get("configured"):
                supabase["operations"].append(_s872b_supabase_upsert(
                    "strategy_promotion_policy",
                    rows,
                    "policy_key",
                    cfg,
                    chunk_size=100,
                ))
        except Exception as exc:
            supabase = {
                "requested": True,
                "configured": False,
                "operations": [{"ok": False, "table": "strategy_promotion_policy", "errors": [{"message": str(exc)}]}],
            }

    report = {
        "ok": True,
        "storageVersion": S878_PROMOTION_POLICY_WRITER_VERSION,
        "generatedAt": generated_at,
        "jobId": job_id,
        "sourceWalkForwardJobId": wf.get("jobId"),
        "summary": summary,
        "policies": policies,
        "supabase": supabase,
        "policy": {
            "researchOnly": True,
            "doesNotChangeClientDelivery": True,
            "doesNotSendTelegram": True,
            "doesNotAutoApproveStrategies": True,
            "clientReleaseRequiresManualApprovalForwardShadowAndStrictGate": True,
        },
        "nextEngineeringStep": "S8.79 Promotion Policy Hook: use strategy_promotion_policy as another hard block inside unified/client eligibility.",
        "errors": [],
    }

    if publish:
        payload = json.dumps(report, ensure_ascii=False, indent=2, default=str)
        latest_report = _s878_reports_dir() / "latest_s878_promotion_policy.json"
        latest_data = _s878_policy_dir() / "latest_s878_promotion_policy.json"
        stamp = str(generated_at).replace(":", "-").replace(".", "-")
        snapshot = _s878_reports_dir() / f"{stamp}.json"
        latest_report.write_text(payload, encoding="utf-8")
        latest_data.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return report


