# === S8.79 Promotion Policy Hook ============================================
S879_PROMOTION_POLICY_HOOK_VERSION = "s8_79_promotion_policy_hook_v1"


def _s879_payload_get(payload, keys, default=None):
    if not isinstance(payload, dict):
        return default

    for key in keys:
        if key in payload and payload.get(key) is not None:
            return payload.get(key)

    nested_names = [
        "signal", "candidate", "setup", "source", "metadata", "policy",
        "strategy", "setupCandidate", "payload", "row",
    ]
    for nested_name in nested_names:
        nested = payload.get(nested_name)
        if isinstance(nested, dict):
            got = _s879_payload_get(nested, keys, default=None)
            if got is not None:
                return got

    return default


def _s879_normalize_policy_key(setup_slug=None, direction=None, interval=None):
    setup_slug = str(setup_slug or "").strip()
    direction = str(direction or "").upper().strip()
    interval = str(interval or "5min").strip()
    if not setup_slug:
        setup_slug = "unknown_setup"
    if not direction:
        direction = "UNKNOWN"
    if not interval:
        interval = "5min"
    return f"{setup_slug}|{direction}|{interval}"


def _s879_extract_signal_policy_key(payload):
    setup_slug = _s879_payload_get(payload, [
        "setupSlug", "setup_slug", "setup", "strategySlug", "strategy_slug", "playbookSlug",
    ])
    direction = _s879_payload_get(payload, ["direction", "side"])
    interval = _s879_payload_get(payload, ["interval", "timeframe"])

    return {
        "setupSlug": str(setup_slug or "unknown_setup").strip(),
        "direction": str(direction or "UNKNOWN").upper().strip(),
        "interval": str(interval or "5min").strip(),
        "policyKey": _s879_normalize_policy_key(setup_slug, direction, interval),
    }


def _s879_supabase_select_policy(policy_key=None, setup_slug=None, direction=None, interval=None):
    import json
    import urllib.parse
    import urllib.request

    cfg = _s872b_supabase_config()
    if not cfg.get("configured"):
        return {
            "ok": False,
            "configured": False,
            "policy": None,
            "reason": "supabase_not_configured",
            "masked": cfg.get("masked"),
        }

    key = cfg.get("serviceKey") or ""
    base = (cfg.get("url") or "").rstrip("/")
    headers = {
        "apikey": key,
        "Authorization": f"Bearer {key}",
        "Accept": "application/json",
    }

    select_cols = "policy_key,setup_slug,direction,interval,status,client_release_allowed,production_eligible,telegram_allowed,manual_approval_required,forward_shadow_required,reasons,walk_forward,stats,thresholds,writer_version,updated_at"

    if policy_key:
        query = urllib.parse.urlencode({
            "select": select_cols,
            "policy_key": f"eq.{policy_key}",
            "limit": "1",
        })
    else:
        query = urllib.parse.urlencode({
            "select": select_cols,
            "setup_slug": f"eq.{setup_slug}",
            "direction": f"eq.{direction}",
            "interval": f"eq.{interval}",
            "limit": "1",
        })

    url = f"{base}/rest/v1/strategy_promotion_policy?{query}"

    try:
        req = urllib.request.Request(url, headers=headers, method="GET")
        with urllib.request.urlopen(req, timeout=30) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
            rows = json.loads(raw or "[]")
    except Exception as exc:
        return {
            "ok": False,
            "configured": True,
            "policy": None,
            "reason": "supabase_policy_read_failed",
            "error": str(exc),
            "masked": cfg.get("masked"),
        }

    if not rows:
        return {
            "ok": True,
            "configured": True,
            "policy": None,
            "reason": "policy_missing",
            "masked": cfg.get("masked"),
        }

    return {
        "ok": True,
        "configured": True,
        "policy": rows[0],
        "reason": None,
        "masked": cfg.get("masked"),
    }


def _s879_evaluate_policy_gate(payload=None, setup_slug=None, direction=None, interval=None, require_client_release=True):
    payload = payload or {}
    extracted = _s879_extract_signal_policy_key(payload)
    if setup_slug:
        extracted["setupSlug"] = str(setup_slug).strip()
    if direction:
        extracted["direction"] = str(direction).upper().strip()
    if interval:
        extracted["interval"] = str(interval).strip()
    extracted["policyKey"] = _s879_normalize_policy_key(
        extracted.get("setupSlug"),
        extracted.get("direction"),
        extracted.get("interval"),
    )

    policy_lookup = _s879_supabase_select_policy(policy_key=extracted.get("policyKey"))
    policy = policy_lookup.get("policy")

    block_reasons = []
    warnings = []

    if not policy_lookup.get("ok"):
        block_reasons.append(policy_lookup.get("reason") or "promotion_policy_lookup_failed")
    if not policy:
        block_reasons.append("promotion_policy_missing")
    else:
        status = str(policy.get("status") or "").upper()
        if status in {"BLOCKED_RESEARCH_ONLY", "BLOCKED", "RESEARCH_ONLY", "DISABLED"}:
            block_reasons.append(f"promotion_policy_status_{status}")

        if bool(require_client_release) and not bool(policy.get("client_release_allowed")):
            block_reasons.append("client_release_not_allowed_by_promotion_policy")

        if not bool(policy.get("production_eligible")):
            block_reasons.append("production_not_eligible_by_promotion_policy")

        if not bool(policy.get("telegram_allowed")):
            warnings.append("telegram_not_allowed_by_promotion_policy")

        if bool(policy.get("forward_shadow_required")):
            block_reasons.append("forward_shadow_required_by_promotion_policy")

        if bool(policy.get("manual_approval_required")):
            block_reasons.append("manual_approval_required_by_promotion_policy")

    allowed = len(block_reasons) == 0

    return {
        "ok": True,
        "storageVersion": S879_PROMOTION_POLICY_HOOK_VERSION,
        "allowed": allowed,
        "clientReleaseAllowed": allowed,
        "telegramAllowed": bool(policy.get("telegram_allowed")) if policy else False,
        "productionEligible": bool(policy.get("production_eligible")) if policy else False,
        "policyKey": extracted.get("policyKey"),
        "setupSlug": extracted.get("setupSlug"),
        "direction": extracted.get("direction"),
        "interval": extracted.get("interval"),
        "blockReasons": block_reasons,
        "warnings": warnings,
        "policy": policy,
        "lookup": {
            "ok": bool(policy_lookup.get("ok")),
            "configured": bool(policy_lookup.get("configured")),
            "reason": policy_lookup.get("reason"),
            "masked": policy_lookup.get("masked"),
        },
        "hardGate": {
            "promotionPolicyIsHardBlock": True,
            "missingPolicyBlocks": True,
            "blockedResearchOnlyBlocks": True,
            "forwardShadowRequiredBlocks": True,
            "manualApprovalRequiredBlocks": True,
            "doesNotOverrideManualApproval": True,
        },
    }


def _s879_apply_promotion_policy_to_signal(signal):
    if not isinstance(signal, dict):
        return signal

    gate = _s879_evaluate_policy_gate(payload=signal)
    signal["promotionPolicyGate"] = gate

    if not gate.get("allowed"):
        signal["clientVisible"] = False
        signal["clientEligible"] = False
        signal["clientReleaseAllowed"] = False
        signal["telegramEligible"] = False
        signal["premiumSignal"] = False

        blocked = signal.get("blockedReasons")
        if not isinstance(blocked, list):
            blocked = []
        for reason in gate.get("blockReasons") or []:
            if reason not in blocked:
                blocked.append(reason)
        signal["blockedReasons"] = blocked

    return signal


def _s879_patch_unified_payload(payload):
    if not isinstance(payload, dict):
        return payload

    candidate_lists = [
        "signals", "items", "rows", "candidates", "clientSignals", "clientVisibleSignals",
        "unifiedSignals", "results",
    ]

    patched_count = 0
    blocked_count = 0

    for key in candidate_lists:
        value = payload.get(key)
        if isinstance(value, list):
            new_items = []
            for item in value:
                if isinstance(item, dict):
                    before = bool(item.get("clientVisible") or item.get("clientEligible") or item.get("clientReleaseAllowed") or item.get("telegramEligible"))
                    patched = _s879_apply_promotion_policy_to_signal(item)
                    after = bool(patched.get("clientVisible") or patched.get("clientEligible") or patched.get("clientReleaseAllowed") or patched.get("telegramEligible"))
                    if before and not after:
                        blocked_count += 1
                    patched_count += 1
                    new_items.append(patched)
                else:
                    new_items.append(item)
            payload[key] = new_items

    payload["promotionPolicyHook"] = {
        "version": S879_PROMOTION_POLICY_HOOK_VERSION,
        "patchedItems": patched_count,
        "blockedItems": blocked_count,
        "hardBlockEnabled": True,
    }

    # Recalculate common counters if they exist.
    for count_key in ["clientVisibleCount", "clientEligibleCount", "telegramEligibleCount"]:
        if count_key in payload:
            total = 0
            for key in candidate_lists:
                value = payload.get(key)
                if isinstance(value, list):
                    for item in value:
                        if isinstance(item, dict):
                            if count_key == "telegramEligibleCount" and item.get("telegramEligible"):
                                total += 1
                            elif count_key in {"clientVisibleCount", "clientEligibleCount"} and (item.get("clientVisible") or item.get("clientEligible") or item.get("clientReleaseAllowed")):
                                total += 1
            payload[count_key] = total

    return payload


def _s879_try_install_runtime_wrappers():
    installed = []

    # Wrap S8.64 unified output if present. This makes promotion policy a hard
    # post-processing gate without changing the original S8.64 logic.
    target_name = "_s864_run_unified_skilledge_output"
    fn = globals().get(target_name)
    if callable(fn) and not getattr(fn, "_s879_wrapped", False):
        original = fn

        def _s879_wrapped_s864(*args, **kwargs):
            payload = original(*args, **kwargs)
            return _s879_patch_unified_payload(payload)

        _s879_wrapped_s864._s879_wrapped = True
        _s879_wrapped_s864._s879_original = original
        globals()[target_name] = _s879_wrapped_s864
        installed.append(target_name)

    return {
        "ok": True,
        "storageVersion": S879_PROMOTION_POLICY_HOOK_VERSION,
        "installedWrappers": installed,
        "hardBlockEnabled": True,
    }


_S879_RUNTIME_WRAPPERS = _s879_try_install_runtime_wrappers()


