def _s880_latest_json(path):
    import json
    try:
        if not path or not path.exists():
            return None
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def _s880_supabase_get(path, params=None, timeout=30):
    import json
    import urllib.parse
    import urllib.request

    cfg = _s872b_supabase_config()
    if not cfg.get("configured"):
        return {
            "ok": False,
            "configured": False,
            "rows": [],
            "error": "supabase_not_configured",
            "masked": cfg.get("masked"),
        }

    key = cfg.get("serviceKey") or ""
    base = (cfg.get("url") or "").rstrip("/")
    params = params or {}
    query = urllib.parse.urlencode(params)
    url = f"{base}/rest/v1/{path}"
    if query:
        url += f"?{query}"

    headers = {
        "apikey": key,
        "Authorization": f"Bearer {key}",
        "Accept": "application/json",
    }

    try:
        req = urllib.request.Request(url, headers=headers, method="GET")
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
        return {
            "ok": True,
            "configured": True,
            "rows": json.loads(raw or "[]"),
            "masked": cfg.get("masked"),
        }
    except Exception as exc:
        return {
            "ok": False,
            "configured": True,
            "rows": [],
            "error": str(exc),
            "masked": cfg.get("masked"),
        }


def _s880_policy_counts_from_supabase():
    rows_result = _s880_supabase_get(
        "strategy_promotion_policy",
        {
            "select": "status,client_release_allowed,production_eligible,telegram_allowed,manual_approval_required,forward_shadow_required",
        },
    )
    rows = rows_result.get("rows") or []

    counts = {
        "policies": len(rows),
        "clientReleaseAllowed": 0,
        "productionEligible": 0,
        "telegramAllowed": 0,
        "manualApprovalRequired": 0,
        "forwardShadowRequired": 0,
        "blockedResearchOnly": 0,
    }

    for row in rows:
        if bool(row.get("client_release_allowed")):
            counts["clientReleaseAllowed"] += 1
        if bool(row.get("production_eligible")):
            counts["productionEligible"] += 1
        if bool(row.get("telegram_allowed")):
            counts["telegramAllowed"] += 1
        if bool(row.get("manual_approval_required")):
            counts["manualApprovalRequired"] += 1
        if bool(row.get("forward_shadow_required")):
            counts["forwardShadowRequired"] += 1
        if str(row.get("status") or "").upper() == "BLOCKED_RESEARCH_ONLY":
            counts["blockedResearchOnly"] += 1

    return {
        "ok": bool(rows_result.get("ok")),
        "counts": counts,
        "source": "supabase.strategy_promotion_policy",
        "error": rows_result.get("error"),
    }


