def _s880_build_investor_report(publish=True):
    import json

    generated_at = _s871b_now_iso()
    supabase_summary = _s880_admin_summary_from_supabase()
    policy_counts = _s880_policy_counts_from_supabase()
    latest = _s880_latest_reports()

    admin_summary = supabase_summary.get("summary") or {}
    wf = (latest.get("walkForward") or {}).get("payload") or {}
    promotion = (latest.get("promotionPolicy") or {}).get("payload") or {}
    universe = (latest.get("universe") or {}).get("payload") or {}
    backfill_queue = (latest.get("backfillQueue") or {}).get("payload") or {}

    policy_count_summary = policy_counts.get("counts") or {}

    historical_counts = {
        "jobsCount": int(admin_summary.get("jobs_count") or admin_summary.get("job_count") or 0),
        "dataFilesCount": int(admin_summary.get("data_files_count") or 0),
        "dataRowsIndexed": int(admin_summary.get("data_rows_indexed") or 0),
        "featureFilesCount": int(admin_summary.get("feature_files_count") or 0),
        "featureRowsIndexed": int(admin_summary.get("feature_rows_indexed") or 0),
        "setupCandidatesCount": int(admin_summary.get("setup_candidates_count") or 0),
        "closedOutcomesCount": int(admin_summary.get("closed_outcomes_count") or 0),
        "productionEligible": int(admin_summary.get("production_eligible") or admin_summary.get("production_eligible_count") or 0),
        "clientRelease": int(admin_summary.get("client_release") or admin_summary.get("client_release_count") or 0),
    }

    backfill_summary = backfill_queue.get("summary") or {}
    wf_summary = wf.get("summary") or {}
    promotion_summary = promotion.get("summary") or {}
    universe_summary = universe.get("summary") or {}

    release_state = {
        "clientReleaseAllowed": int(policy_count_summary.get("clientReleaseAllowed") or 0),
        "productionEligible": int(policy_count_summary.get("productionEligible") or 0),
        "telegramAllowed": int(policy_count_summary.get("telegramAllowed") or 0),
        "blockedResearchOnly": int(policy_count_summary.get("blockedResearchOnly") or 0),
        "manualApprovalRequired": int(policy_count_summary.get("manualApprovalRequired") or 0),
        "forwardShadowRequired": int(policy_count_summary.get("forwardShadowRequired") or 0),
    }

    risk_warnings = []
    if release_state["clientReleaseAllowed"] == 0:
        risk_warnings.append("No strategy is approved for client release.")
    if release_state["productionEligible"] == 0:
        risk_warnings.append("No strategy is production eligible.")
    if int(wf_summary.get("walkForwardPassedGroups") or 0) == 0:
        risk_warnings.append("No setup group passed walk-forward validation yet.")
    if int(wf_summary.get("uniqueDates") or 0) < 20:
        risk_warnings.append("Historical sample is still too small for investor-grade claims.")
    if int(wf_summary.get("windows") or 0) < 3:
        risk_warnings.append("Walk-forward windows are below the promotion threshold.")

    investor_ready = (
        release_state["clientReleaseAllowed"] > 0
        and release_state["productionEligible"] > 0
        and int(wf_summary.get("walkForwardPassedGroups") or 0) > 0
        and int(wf_summary.get("windows") or 0) >= 3
    )

    report = {
        "ok": True,
        "storageVersion": S880_ADMIN_INVESTOR_RESEARCH_REPORT_VERSION,
        "generatedAt": generated_at,
        "title": "SkillEdge AI Historical Learning / Investor Research Report",
        "honestStatus": {
            "investorReady": bool(investor_ready),
            "clientReleaseReady": bool(release_state["clientReleaseAllowed"] > 0),
            "productionSignalReady": bool(release_state["productionEligible"] > 0),
            "currentMode": "RESEARCH_ONLY",
            "plainEnglish": "Historical learning pipeline works, but no strategy is approved for client/production release yet.",
        },
        "historicalCounts": historical_counts,
        "backfill": {
            "queueStatus": backfill_queue.get("status"),
            "summary": backfill_summary,
            "guardVersion": backfill_queue.get("guardVersion"),
            "plan": backfill_queue.get("plan"),
        },
        "universe": {
            "storageVersion": universe.get("storageVersion"),
            "summary": universe_summary,
            "symbols": universe.get("symbols"),
        },
        "walkForward": {
            "storageVersion": wf.get("storageVersion"),
            "summary": wf_summary,
            "thresholds": wf.get("thresholds"),
            "topResults": wf.get("topResults"),
        },
        "promotionPolicy": {
            "storageVersion": promotion.get("storageVersion"),
            "summary": promotion_summary,
            "policyCounts": policy_count_summary,
            "topPolicies": (promotion.get("policies") or [])[:25],
        },
        "releaseState": release_state,
        "riskWarnings": risk_warnings,
        "supabase": {
            "adminSummary": supabase_summary,
            "policyCounts": policy_counts,
        },
        "safety": {
            "manualApprovalRequired": True,
            "promotionPolicyHardBlock": True,
            "clientReleaseAllowedByDefault": False,
            "telegramAllowedByDefault": False,
            "researchOnlyUntilValidated": True,
        },
        "nextEngineeringStep": "S8.81 Scale Backfill Plan: gradually expand dates/symbols with scheduler, then rerun walk-forward and policy writer.",
        "errors": [],
    }

    if publish:
        payload = json.dumps(report, ensure_ascii=False, indent=2, default=str)
        latest_path = _s880_reports_dir() / "latest_s880_investor_report.json"
        stamp = str(generated_at).replace(":", "-").replace(".", "-")
        snapshot = _s880_reports_dir() / f"{stamp}.json"
        latest_path.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return report


