# === S8.82 Provider Coverage Probe ==========================================
S882_PROVIDER_COVERAGE_PROBE_VERSION = "s8_82_provider_coverage_probe_v1"


def _s882_reports_dir():
    d = _s870e_root_dir() / "reports" / "historical_learning" / "provider_coverage"
    d.mkdir(parents=True, exist_ok=True)
    return d


def _s882_coverage_dir():
    d = _s871a_data_lake_dir() / "provider_coverage"
    d.mkdir(parents=True, exist_ok=True)
    return d


def _s882_probe_symbols(symbols=None, max_symbols=10):
    parsed = _s871b_parse_symbols(symbols) if symbols else []
    if not parsed:
        latest_universe = None
        try:
            latest_universe = _s876_latest_universe()
        except Exception:
            latest_universe = None
        parsed = [str(s).upper() for s in ((latest_universe or {}).get("symbols") or [])]
    if not parsed:
        parsed = ["AAPL", "NVDA", "TSLA", "MSFT", "META"]
    return [str(s).upper() for s in parsed[: int(max_symbols or 10)]]


def _s882_probe_dates(start_date=None, end_date=None, max_days=10):
    # Reuse completed-day guard date logic from S8.75B2/S8.73.
    return _s873_date_list(
        start_date=start_date,
        end_date=end_date,
        years_back=5,
        max_days=int(max_days or 10),
    )


def _s882_count_existing_rows(symbol, interval, date_str):
    path = _s871a_data_lake_dir() / "normalized_candles" / interval / str(symbol).upper() / f"{date_str}_{date_str}.jsonl"
    if not path.exists():
        return 0
    try:
        return len([line for line in path.read_text(encoding="utf-8").splitlines() if line.strip()])
    except Exception:
        return 0


def _s882_probe_provider_day(symbols=None, date_str=None, interval="5min", max_symbols=10, write_cache=False):
    rows = []
    symbol_list = _s882_probe_symbols(symbols=symbols, max_symbols=max_symbols)

    if write_cache:
        # Uses the proven ingestion adapter. It writes normal/raw candle files, but does not run
        # features/replay/outcomes/stats.
        try:
            import asyncio
            payload = asyncio.run(_s871b2_run_ingestion_compatible(
                symbols=",".join(symbol_list),
                start_date=date_str,
                end_date=date_str,
                intervals=interval,
                max_symbols=len(symbol_list),
                provider="engine_fmp_client",
                publish=True,
            ))
        except RuntimeError:
            # If already inside event loop context, fall back to no async run. API route below calls
            # this function from sync context, so this is defensive only.
            payload = {"ok": False, "error": "asyncio_runtime_context_not_supported"}
    else:
        payload = None

    for symbol in symbol_list:
        existing_rows = _s882_count_existing_rows(symbol, interval, date_str)
        rows.append({
            "symbol": symbol,
            "date": date_str,
            "interval": interval,
            "normalizedRows": existing_rows,
            "hasData": existing_rows > 0,
        })

    return {
        "date": date_str,
        "interval": interval,
        "symbolsChecked": len(symbol_list),
        "symbolsWithData": len([r for r in rows if r.get("hasData")]),
        "symbolsWithoutData": len([r for r in rows if not r.get("hasData")]),
        "rows": rows,
        "ingestion": payload.get("summary") if isinstance(payload, dict) else None,
        "ingestionOk": payload.get("ok") if isinstance(payload, dict) else None,
    }


def _s882_run_provider_coverage_probe(
    symbols=None,
    intervals="5min",
    start_date=None,
    end_date=None,
    max_days=10,
    max_symbols=10,
    write_cache=True,
    publish=True,
):
    import json

    interval_list = _s871c_parse_intervals(intervals or "5min")
    # Keep S8.82 intentionally focused; probe first interval by default.
    interval = interval_list[0] if interval_list else "5min"
    dates = _s882_probe_dates(start_date=start_date, end_date=end_date, max_days=max_days)
    symbol_list = _s882_probe_symbols(symbols=symbols, max_symbols=max_symbols)

    day_results = []
    for d in dates:
        day_results.append(_s882_probe_provider_day(
            symbols=",".join(symbol_list),
            date_str=d,
            interval=interval,
            max_symbols=len(symbol_list),
            write_cache=bool(write_cache),
        ))

    usable_dates = [d.get("date") for d in day_results if int(d.get("symbolsWithData") or 0) > 0]
    empty_dates = [d.get("date") for d in day_results if int(d.get("symbolsWithData") or 0) == 0]

    symbol_coverage = {}
    for day in day_results:
        for row in day.get("rows") or []:
            s = row.get("symbol")
            symbol_coverage.setdefault(s, {"symbol": s, "daysWithData": 0, "daysWithoutData": 0, "rows": 0})
            if row.get("hasData"):
                symbol_coverage[s]["daysWithData"] += 1
            else:
                symbol_coverage[s]["daysWithoutData"] += 1
            symbol_coverage[s]["rows"] += int(row.get("normalizedRows") or 0)

    symbol_coverage_list = sorted(
        symbol_coverage.values(),
        key=lambda r: (int(r.get("daysWithData") or 0), int(r.get("rows") or 0), str(r.get("symbol") or "")),
        reverse=True,
    )

    report = {
        "ok": True,
        "storageVersion": S882_PROVIDER_COVERAGE_PROBE_VERSION,
        "generatedAt": _s871b_now_iso(),
        "inputs": {
            "symbols": symbol_list,
            "interval": interval,
            "startDate": start_date,
            "endDate": end_date,
            "maxDays": int(max_days or 10),
            "maxSymbols": int(max_symbols or 10),
            "writeCache": bool(write_cache),
        },
        "summary": {
            "datesChecked": len(dates),
            "usableDates": len(usable_dates),
            "emptyDates": len(empty_dates),
            "symbolsChecked": len(symbol_list),
            "totalSymbolDays": len(dates) * len(symbol_list),
            "symbolDaysWithData": sum([int(d.get("symbolsWithData") or 0) for d in day_results]),
            "symbolDaysWithoutData": sum([int(d.get("symbolsWithoutData") or 0) for d in day_results]),
        },
        "usableDates": usable_dates,
        "emptyDates": empty_dates,
        "dayResults": day_results,
        "symbolCoverage": symbol_coverage_list,
        "recommendation": {
            "safeBackfillDates": usable_dates,
            "avoidDates": empty_dates,
            "nextAction": "Create backfill queues only from dates with provider coverage, or add exchange-calendar/provider coverage filtering.",
        },
        "policy": {
            "researchOnly": True,
            "doesNotRunFeaturesReplayOutcomesStats": True,
            "doesNotChangeClientDelivery": True,
            "doesNotSendTelegram": True,
            "doesNotPromoteStrategies": True,
        },
        "nextEngineeringStep": "S8.83 Coverage-Aware Queue Builder: create queues only for usable provider dates.",
        "errors": [],
    }

    if publish:
        payload = json.dumps(report, ensure_ascii=False, indent=2, default=str)
        latest = _s882_reports_dir() / "latest_s882_provider_coverage.json"
        data_latest = _s882_coverage_dir() / "latest_s882_provider_coverage.json"
        stamp = str(report.get("generatedAt")).replace(":", "-").replace(".", "-")
        snapshot = _s882_reports_dir() / f"{stamp}.json"
        latest.write_text(payload, encoding="utf-8")
        data_latest.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return report


def _s882_latest_report():
    import json
    p = _s882_reports_dir() / "latest_s882_provider_coverage.json"
    if not p.exists():
        return None
    return json.loads(p.read_text(encoding="utf-8"))


