def _s883b_create_queue_safe(max_dates=None, symbols=None, intervals=None, publish=True):
    import hashlib
    import json

    coverage = _s883b_latest_coverage_report()
    if not isinstance(coverage, dict):
        return {
            "ok": False,
            "storageVersion": "s8_73_historical_backfill_orchestrator_v1",
            "coverageAwareQueueVersion": globals().get("S883_COVERAGE_AWARE_QUEUE_BUILDER_VERSION", "s8_83_coverage_aware_queue_builder_v1"),
            "coverageQueueSafeEndpointVersion": S883B_COVERAGE_QUEUE_SAFE_ENDPOINT_VERSION,
            "error": "No valid S8.82 coverage report found. Run provider-coverage/probe first.",
        }

    inputs = coverage.get("inputs") or {}
    usable_dates = [str(d) for d in (coverage.get("usableDates") or []) if str(d).strip()]
    avoid_dates = [str(d) for d in (coverage.get("emptyDates") or []) if str(d).strip()]

    if max_dates is not None:
        usable_dates = usable_dates[: int(max_dates)]

    symbol_list = _s883b_parse_symbols(symbols)
    if not symbol_list:
        symbol_list = _s883b_parse_symbols(inputs.get("symbols") or [])
    if not symbol_list:
        symbol_list = ["AAPL", "NVDA", "TSLA", "MSFT", "META"]

    interval_value = str(intervals or inputs.get("interval") or "5min").strip() or "5min"
    generated_at = _s871b_now_iso()

    jobs = []
    for date_str in usable_dates:
        seed = f"{S883B_COVERAGE_QUEUE_SAFE_ENDPOINT_VERSION}|{date_str}|{','.join(symbol_list)}|{interval_value}"
        jobs.append({
            "jobId": "s883b:" + hashlib.sha1(seed.encode("utf-8")).hexdigest()[:16],
            "status": "PENDING",
            "createdAt": generated_at,
            "startDate": date_str,
            "endDate": date_str,
            "symbols": symbol_list,
            "intervals": interval_value,
            "provider": "engine_fmp_client",
            "source": S883B_COVERAGE_QUEUE_SAFE_ENDPOINT_VERSION,
            "coverageValidated": True,
            "coverageSourceVersion": coverage.get("storageVersion"),
            "coverageSourceGeneratedAt": coverage.get("generatedAt"),
            "researchOnly": True,
        })

    queue = {
        "ok": True,
        "storageVersion": "s8_73_historical_backfill_orchestrator_v1",
        "coverageAwareQueueVersion": globals().get("S883_COVERAGE_AWARE_QUEUE_BUILDER_VERSION", "s8_83_coverage_aware_queue_builder_v1"),
        "coverageQueueSafeEndpointVersion": S883B_COVERAGE_QUEUE_SAFE_ENDPOINT_VERSION,
        "status": "READY" if jobs else "EMPTY",
        "createdAt": generated_at,
        "updatedAt": generated_at,
        "summary": _s883b_queue_summary(jobs),
        "plan": {
            "calendarMode": "provider_coverage_aware_safe_v1",
            "providerCoverageVersion": coverage.get("storageVersion"),
            "coverageGeneratedAt": coverage.get("generatedAt"),
            "maxDays": len(usable_dates),
            "chunkDays": 1,
            "usableDates": usable_dates,
            "avoidDates": avoid_dates,
            "symbols": symbol_list,
            "intervals": interval_value,
            "skipsCurrentOrFutureServerLocalDates": True,
        },
        "policy": {
            "researchOnly": True,
            "doesNotChangeClientDelivery": True,
            "doesNotSendTelegram": True,
            "doesNotPromoteStrategies": True,
            "usesProviderCoverageBeforeBackfill": True,
            "emptyDatesAreExcluded": True,
        },
        "jobs": jobs,
    }

    if publish:
        _s873_save_queue(queue)
        payload = json.dumps(queue, ensure_ascii=False, indent=2, default=str)
        latest = _s883b_reports_dir() / "latest_s883b_coverage_queue_safe.json"
        stamp = str(generated_at).replace(":", "-").replace(".", "-")
        snapshot = _s883b_reports_dir() / f"{stamp}.json"
        latest.write_text(payload, encoding="utf-8")
        snapshot.write_text(payload, encoding="utf-8")

    return queue


