S888B_ROBUST_FMP_STABLE_INTRADAY_INGESTION_VERSION = "s8_88b_robust_fmp_stable_intraday_ingestion_v1"


def _s888b_parse_csv(value, default=None):
    if not value:
        return list(default or [])
    if isinstance(value, list):
        return [str(x).strip() for x in value if str(x).strip()]
    return [p.strip() for p in str(value).replace(";", ",").split(",") if p.strip()]


def _s888b_symbols(value):
    return [s.upper() for s in _s888b_parse_csv(value)]


def _s888b_intervals(value):
    vals = _s888b_parse_csv(value or "5min")
    return vals or ["5min"]


def _s888b_completed_dates(start_date, end_date):
    from datetime import date, timedelta

    s = date.fromisoformat(str(start_date))
    e = date.fromisoformat(str(end_date or start_date))
    if e < s:
        s, e = e, s

    out = []
    cur = s
    while cur <= e:
        if cur.weekday() < 5:
            out.append(cur.isoformat())
        cur += timedelta(days=1)
    return out


def _s888b_load_fmp_key():
    import os
    import re
    from pathlib import Path

    names = [
        "FMP_API_KEY",
        "FMP_API_TOKEN",
        "FMP_KEY",
        "FMP_TOKEN",
        "FINANCIAL_MODELING_PREP_API_KEY",
        "FINANCIALMODELINGPREP_API_KEY",
        "NEXT_PUBLIC_FMP_API_KEY",
        "STOCK_ENGINE_FMP_API_KEY",
        "STOCK_ENGINE_FMP_KEY",
        "MARKET_DATA_FMP_API_KEY",
        "MARKET_DATA_FMP_KEY",
    ]

    for name in names:
        value = (os.environ.get(name) or "").strip()
        if value:
            return value, f"env:{name}"

    # Try running service process env if this function is called outside that process.
    try:
        import subprocess
        pid_raw = subprocess.check_output(
            ["systemctl", "show", "-p", "MainPID", "--value", "skilledge-stock-engine-api.service"],
            text=True,
        ).strip()
        pid = int(pid_raw or "0")
        env_path = Path(f"/proc/{pid}/environ")
        if pid > 0 and env_path.exists():
            parts = env_path.read_bytes().split(b"\x00")
            env = {}
            for item in parts:
                if item and b"=" in item:
                    k, v = item.split(b"=", 1)
                    env[k.decode("utf-8", errors="ignore")] = v.decode("utf-8", errors="ignore")
            for name in names:
                value = (env.get(name) or "").strip()
                if value:
                    return value, f"proc:{name}"
    except Exception:
        pass

    paths = [
        Path("/opt/skilledge/stock-engine/.env"),
        Path("/opt/skilledge/stock-engine/.env.local"),
        Path("/opt/skilledge/stock-engine/.env.production"),
        Path("/etc/skilledge-stock-engine.env"),
        Path("/etc/default/skilledge-stock-engine"),
        Path("/etc/systemd/system/skilledge-stock-engine-api.service"),
        Path("/etc/systemd/system/skilledge-stock-engine-api.service.d/override.conf"),
    ]

    for path in paths:
        if not path.exists():
            continue
        try:
            txt = path.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue

        for name in names:
            m = re.search(rf"{name}\s*=\s*['\"]?([^'\"\s]+)", txt)
            if m and m.group(1).strip():
                return m.group(1).strip(), f"file:{name}:{path}"

    return None, None


def _s888b_session_from_datetime(dt):
    value = str(dt or "")
    hhmm = value[11:16] if len(value) >= 16 else ""
    if "04:00" <= hhmm < "09:30":
        return "premarket"
    if "09:30" <= hhmm <= "16:00":
        return "regular"
    if "16:00" < hhmm <= "20:00":
        return "afterhours"
    return "unknown"


def _s888b_float(value, default=None):
    try:
        if value is None:
            return default
        return float(value)
    except Exception:
        return default


def _s888b_int(value, default=0):
    try:
        if value is None:
            return default
        return int(float(value))
    except Exception:
        return default


def _s888b_fetch_fmp_stable_intraday(symbol, day, interval, api_key):
    import json
    from urllib.parse import urlencode
    from urllib.request import Request, urlopen
    from urllib.error import HTTPError, URLError

    params = urlencode({
        "symbol": str(symbol).upper(),
        "from": day,
        "to": day,
        "apikey": api_key,
    })
    url = f"https://financialmodelingprep.com/stable/historical-chart/{interval}?{params}"
    safe_url = url.split("apikey=")[0] + "apikey=***"

    req = Request(url, headers={"User-Agent": "SkillEdge-S8.88B/1.0"})
    try:
        with urlopen(req, timeout=90) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
            payload = json.loads(raw)
            if isinstance(payload, list):
                return {"ok": True, "statusCode": resp.status, "rows": payload, "url": safe_url, "error": None}
            if isinstance(payload, dict):
                for key in ["historical", "data", "results", "candles"]:
                    if isinstance(payload.get(key), list):
                        return {"ok": True, "statusCode": resp.status, "rows": payload[key], "url": safe_url, "error": None}
                return {"ok": True, "statusCode": resp.status, "rows": [], "url": safe_url, "error": None, "payloadType": "dict_no_rows"}
            return {"ok": True, "statusCode": resp.status, "rows": [], "url": safe_url, "error": None, "payloadType": str(type(payload))}
    except HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")
        return {"ok": False, "statusCode": e.code, "rows": [], "url": safe_url, "error": body[:1000]}
    except URLError as e:
        return {"ok": False, "statusCode": None, "rows": [], "url": safe_url, "error": repr(e)}
    except Exception as e:
        return {"ok": False, "statusCode": None, "rows": [], "url": safe_url, "error": repr(e)}


def _s888b_normalize_row(symbol, interval, row):
    dt = str(row.get("date") or row.get("datetime") or row.get("time") or row.get("timestamp") or "")
    session_date = dt[:10]
    return {
        "symbol": str(symbol).upper(),
        "interval": str(interval),
        "datetime": dt,
        "date": session_date,
        "session": _s888b_session_from_datetime(dt),
        "open": _s888b_float(row.get("open")),
        "high": _s888b_float(row.get("high")),
        "low": _s888b_float(row.get("low")),
        "close": _s888b_float(row.get("close")),
        "volume": _s888b_int(row.get("volume")),
        "source": {
            "provider": "fmp",
            "endpoint": "stable_historical_chart_query_symbol",
            "ingestionVersion": S888B_ROBUST_FMP_STABLE_INTRADAY_INGESTION_VERSION,
        },
    }


def _s888b_write_jsonl(path, rows):
    import json
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as fh:
        for row in rows:
            fh.write(json.dumps(row, ensure_ascii=False, default=str) + "\n")


def _s888b_run_ingestion_robust_fmp(
    symbols=None,
    start_date=None,
    end_date=None,
    intervals="5min",
    publish=True,
):
    import json

    api_key, key_source = _s888b_load_fmp_key()
    if not api_key:
        return {
            "ok": False,
            "storageVersion": "s8_71b_historical_data_ingestion_worker_v2",
            "ingestionHotfixVersion": S888B_ROBUST_FMP_STABLE_INTRADAY_INGESTION_VERSION,
            "summary": {
                "requestsAttempted": 0,
                "requestsSucceeded": 0,
                "requestsFailed": 1,
                "rawRowsStored": 0,
                "normalizedRowsStored": 0,
                "symbolCount": 0,
                "intervalCount": 0,
            },
            "errorCount": 1,
            "errors": [{"type": "fmp_key_missing"}],
            "policy": {"researchOnly": True, "doesNotChangeClientDelivery": True},
        }

    symbol_list = _s888b_symbols(symbols)
    interval_list = _s888b_intervals(intervals or "5min")
    dates = _s888b_completed_dates(start_date, end_date or start_date)

    root = _s871a_data_lake_dir()
    raw_root = root / "raw_candles"
    normalized_root = root / "normalized_candles"

    requests_attempted = 0
    requests_succeeded = 0
    requests_failed = 0
    raw_rows_stored = 0
    normalized_rows_stored = 0
    files_written = 0
    errors = []
    per_symbol = {}

    for interval in interval_list:
        for symbol in symbol_list:
            for day in dates:
                requests_attempted += 1
                fetched = _s888b_fetch_fmp_stable_intraday(symbol, day, interval, api_key)
                rows = fetched.get("rows") or []

                per_symbol.setdefault(symbol, {"requests": 0, "rows": 0, "usableDates": [], "emptyDates": []})
                per_symbol[symbol]["requests"] += 1

                if not fetched.get("ok"):
                    requests_failed += 1
                    errors.append({
                        "type": "provider_request_failed",
                        "symbol": symbol,
                        "date": day,
                        "interval": interval,
                        "statusCode": fetched.get("statusCode"),
                        "error": fetched.get("error"),
                    })
                    per_symbol[symbol]["emptyDates"].append(day)
                    continue

                requests_succeeded += 1

                raw_rows = []
                normalized_rows = []
                for row in rows:
                    if not isinstance(row, dict):
                        continue
                    raw = dict(row)
                    raw["symbol"] = symbol
                    raw["interval"] = interval
                    raw["source"] = {
                        "provider": "fmp",
                        "endpoint": "stable_historical_chart_query_symbol",
                        "ingestionVersion": S888B_ROBUST_FMP_STABLE_INTRADAY_INGESTION_VERSION,
                    }
                    norm = _s888b_normalize_row(symbol, interval, row)
                    if not norm.get("datetime") or norm.get("open") is None or norm.get("close") is None:
                        continue
                    raw_rows.append(raw)
                    normalized_rows.append(norm)

                raw_rows.sort(key=lambda x: str(x.get("date") or x.get("datetime") or ""))
                normalized_rows.sort(key=lambda x: str(x.get("datetime") or ""))

                per_symbol[symbol]["rows"] += len(normalized_rows)
                if normalized_rows:
                    per_symbol[symbol]["usableDates"].append(day)
                else:
                    per_symbol[symbol]["emptyDates"].append(day)

                if publish:
                    raw_path = raw_root / interval / symbol / f"{day}_{day}.jsonl"
                    norm_path = normalized_root / interval / symbol / f"{day}_{day}.jsonl"
                    _s888b_write_jsonl(raw_path, raw_rows)
                    _s888b_write_jsonl(norm_path, normalized_rows)
                    files_written += 2

                raw_rows_stored += len(raw_rows)
                normalized_rows_stored += len(normalized_rows)

    summary = {
        "requestsAttempted": requests_attempted,
        "requestsSucceeded": requests_succeeded,
        "requestsFailed": requests_failed,
        "rawRowsStored": raw_rows_stored,
        "normalizedRowsStored": normalized_rows_stored,
        "symbolCount": len(symbol_list),
        "intervalCount": len(interval_list),
        "dateCount": len(dates),
        "filesWritten": files_written,
    }

    return {
        "ok": requests_failed == 0,
        "storageVersion": "s8_71b_historical_data_ingestion_worker_v2",
        "ingestionHotfixVersion": S888B_ROBUST_FMP_STABLE_INTRADAY_INGESTION_VERSION,
        "providerEndpoint": "stable_historical_chart_query_symbol",
        "keySource": key_source.split(":")[0] if key_source else None,
        "summary": summary,
        "perSymbol": per_symbol,
        "errorCount": len(errors),
        "errors": errors[:50],
        "policy": {
            "researchOnly": True,
            "doesNotChangeClientDelivery": True,
            "doesNotSendTelegram": True,
        },
    }


