def _s885_completed_weekdays(start_date, end_date):
    from datetime import date, datetime, timedelta

    if isinstance(start_date, datetime):
        start = start_date.date()
    elif isinstance(start_date, date):
        start = start_date
    else:
        start = date.fromisoformat(str(start_date))

    if isinstance(end_date, datetime):
        end = end_date.date()
    elif isinstance(end_date, date):
        end = end_date
    else:
        end = date.fromisoformat(str(end_date))

    today = datetime.now().date()
    if end >= today:
        end = today - timedelta(days=1)

    out = []
    cur = start
    while cur <= end:
        if cur.weekday() < 5:
            out.append(cur.isoformat())
        cur += timedelta(days=1)
    return out


def _s885_years_ago_end_window(years, end_date=None):
    from datetime import date, timedelta

    if end_date:
        end = date.fromisoformat(str(end_date))
    else:
        end = date.today() - timedelta(days=1)

    today = date.today()
    if end >= today:
        end = today - timedelta(days=1)

    start = date(end.year - int(years), end.month, end.day)
    return start.isoformat(), end.isoformat()


def _s885_chunk_dates(dates, days_per_job=1):
    days_per_job = max(1, int(days_per_job or 1))
    return [dates[i:i + days_per_job] for i in range(0, len(dates), days_per_job)]


def _s885_build_phase_plan(symbols, dates, interval="5min", phase="P3_5Y_CORE_RESEARCH", days_per_job=1, max_symbols_per_job=25):
    import hashlib

    jobs = []
    chunks = _s885_chunk_dates(dates, days_per_job=days_per_job)
    symbols = list(symbols or [])
    max_symbols_per_job = max(1, int(max_symbols_per_job or 25))
    symbol_batches = [symbols[i:i + max_symbols_per_job] for i in range(0, len(symbols), max_symbols_per_job)]

    for date_chunk in chunks:
        for symbol_batch in symbol_batches:
            start_date = date_chunk[0]
            end_date = date_chunk[-1]
            raw = "|".join([phase, interval, start_date, end_date, ",".join(symbol_batch)])
            job_id = "s885:" + hashlib.sha1(raw.encode("utf-8")).hexdigest()[:18]
            jobs.append({
                "jobId": job_id,
                "phase": phase,
                "status": "PLANNED",
                "interval": interval,
                "startDate": start_date,
                "endDate": end_date,
                "symbols": symbol_batch,
                "symbolCount": len(symbol_batch),
                "dateCount": len(date_chunk),
                "researchOnly": True,
                "doesNotChangeClientDelivery": True,
                "expectedPipeline": [
                    "ingestion",
                    "features/build-robust",
                    "setup-replay/run-robust",
                    "outcomes/run-robust",
                    "walk-forward",
                    "optimizer",
                    "promotion-policy",
                    "investor-report",
                ],
            })

    return jobs


def _s885_create_long_history_plan(
    years=5,
    end_date=None,
    symbols=None,
    interval="5min",
    days_per_job=1,
    max_symbols_per_job=25,
    publish=True,
):
    symbols_list = _s885_parse_symbols(symbols)
    start_date, resolved_end_date = _s885_years_ago_end_window(years=years, end_date=end_date)
    dates = _s885_completed_weekdays(start_date, resolved_end_date)

    phases = [
        {
            "phase": "P1_6M_CORE_VALIDATION",
            "description": "First scalable proof stage: about 6 months on 25 core symbols.",
            "goal": "Validate provider coverage, storage volume, robust feature/replay/outcome chain, and nightly runtime.",
            "releaseImpact": "research_only_no_client_delivery",
        },
        {
            "phase": "P2_1Y_CORE_VALIDATION",
            "description": "One year on core symbols after P1 passes.",
            "goal": "Increase sample size and walk-forward windows before any investor-grade claims.",
            "releaseImpact": "research_only_no_client_delivery",
        },
        {
            "phase": "P3_5Y_CORE_RESEARCH",
            "description": "Five years on core symbols.",
            "goal": "Long-horizon setup statistics, market regime segmentation, and optimizer search foundation.",
            "releaseImpact": "research_only_no_client_delivery",
        },
        {
            "phase": "P4_EXPANDED_UNIVERSE_RESEARCH",
            "description": "Optional expansion to larger symbol universe after P3 resource profile is known.",
            "goal": "Broaden coverage to more movers/small caps/large caps without blocking live signal engine.",
            "releaseImpact": "research_only_no_client_delivery",
        },
    ]

    jobs = _s885_build_phase_plan(
        symbols=symbols_list,
        dates=dates,
        interval=interval,
        phase="P3_5Y_CORE_RESEARCH",
        days_per_job=days_per_job,
        max_symbols_per_job=max_symbols_per_job,
    )

