# === S8.84D Robust Outcome Simulator Hotfix =================================
S884D_ROBUST_OUTCOME_SIMULATOR_HOTFIX_VERSION = "s8_84d_robust_outcome_simulator_hotfix_v1"


def _s884d_parse_symbols(value):
    if not value:
        return []
    if isinstance(value, list):
        return [str(x).strip().upper() for x in value if str(x).strip()]
    return [p.strip().upper() for p in str(value).replace(";", ",").split(",") if p.strip()]


def _s884d_parse_intervals(value):
    try:
        return _s871c_parse_intervals(value or "5min")
    except Exception:
        return [p.strip() for p in str(value or "5min").replace(";", ",").split(",") if p.strip()]


def _s884d_date_set(start_date, end_date):
    from datetime import date, timedelta

    if not start_date:
        start_date = end_date
    if not end_date:
        end_date = start_date

    s = date.fromisoformat(str(start_date))
    e = date.fromisoformat(str(end_date))
    if e < s:
        s, e = e, s

    out = []
    cur = s
    while cur <= e:
        out.append(cur.isoformat())
        cur += timedelta(days=1)
    return set(out)


def _s884d_float(value, default=None):
    try:
        if value is None:
            return default
        return float(value)
    except Exception:
        return default


def _s884d_hash_id(parts):
    import hashlib
    return hashlib.sha1("|".join([str(p) for p in parts]).encode("utf-8")).hexdigest()[:24]


def _s884d_read_json_records(path):
    import json

    out = []
    try:
        if path.suffix == ".jsonl":
            for line in path.read_text(encoding="utf-8").splitlines():
                line = line.strip()
                if line:
                    payload = json.loads(line)
                    if isinstance(payload, dict):
                        out.append(payload)
        elif path.suffix == ".json":
            payload = json.loads(path.read_text(encoding="utf-8") or "null")
            if isinstance(payload, list):
                out.extend([x for x in payload if isinstance(x, dict)])
            elif isinstance(payload, dict):
                for key in ["candidates", "candles", "rows", "items", "results", "data", "outcomes"]:
                    if isinstance(payload.get(key), list):
                        out.extend([x for x in payload[key] if isinstance(x, dict)])
                        break
                else:
                    out.append(payload)
    except Exception:
        return []

    return out


def _s884d_row_date(row):
    value = row.get("date") or row.get("sessionDate") or row.get("candidateDate") or row.get("candidateAt") or row.get("datetime") or row.get("time") or row.get("timestamp")
    return str(value or "")[:10]


def _s884d_row_datetime(row):
    return str(row.get("datetime") or row.get("candidateAt") or row.get("time") or row.get("timestamp") or row.get("date") or "")


def _s884d_read_candidates(symbols, intervals, start_date, end_date):
    root = _s871a_data_lake_dir() / "setup_candidates"
    symbol_list = _s884d_parse_symbols(symbols)
    interval_list = _s884d_parse_intervals(intervals or "5min")
    dates = _s884d_date_set(start_date, end_date)

    files_scanned = 0
    files_succeeded = 0
    files_failed = 0
    rows = []

    for interval in interval_list:
        for symbol in symbol_list:
            folder = root / interval / symbol
            if not folder.exists():
                continue

            for path in list(folder.glob("*.jsonl")) + list(folder.glob("*.json")):
                path_text = str(path)
                if not any(d in path_text for d in dates):
                    continue

                files_scanned += 1
                try:
                    records = _s884d_read_json_records(path)
                    files_succeeded += 1
                except Exception:
                    records = []
                    files_failed += 1

                for row in records:
                    row_symbol = str(row.get("symbol") or symbol).upper()
                    row_interval = str(row.get("interval") or interval)
                    row_date = _s884d_row_date(row)

                    if row_symbol != symbol:
                        continue
                    if row_interval != interval:
                        continue
                    if row_date not in dates:
                        continue

                    normalized = dict(row)
                    normalized["symbol"] = row_symbol
                    normalized["interval"] = row_interval
                    normalized["date"] = row_date
                    normalized["datetime"] = _s884d_row_datetime(row) or f"{row_date}T00:00:00"
                    rows.append(normalized)

    rows.sort(key=lambda r: (str(r.get("symbol")), str(r.get("interval")), str(r.get("date")), str(r.get("datetime")), str(r.get("candidateId"))))
    return {
        "filesScanned": files_scanned,
        "filesSucceeded": files_succeeded,
        "filesFailed": files_failed,
        "rows": rows,
    }


def _s884d_read_candles(symbols, intervals, start_date, end_date):
    root = _s871a_data_lake_dir() / "normalized_candles"
    symbol_list = _s884d_parse_symbols(symbols)
    interval_list = _s884d_parse_intervals(intervals or "5min")
    dates = _s884d_date_set(start_date, end_date)

    by_key = {}

    for interval in interval_list:
        for symbol in symbol_list:
            folder = root / interval / symbol
            rows = []
            if not folder.exists():
                by_key[(symbol, interval)] = rows
                continue

            for path in list(folder.glob("*.jsonl")) + list(folder.glob("*.json")):
                path_text = str(path)
                if not any(d in path_text for d in dates):
                    continue

                for row in _s884d_read_json_records(path):
                    row_date = _s884d_row_date(row)
                    if row_date not in dates:
                        continue

                    row_symbol = str(row.get("symbol") or symbol).upper()
                    row_interval = str(row.get("interval") or interval)

                    if row_symbol != symbol or row_interval != interval:
                        continue

                    r = dict(row)
                    r["symbol"] = row_symbol
                    r["interval"] = row_interval
                    r["date"] = row_date
                    r["datetime"] = _s884d_row_datetime(row) or f"{row_date}T00:00:00"
                    rows.append(r)

            rows.sort(key=lambda r: (str(r.get("date")), str(r.get("datetime"))))
            by_key[(symbol, interval)] = rows

    return by_key


def _s884d_target_price(candidate, r_value=2.0):
    targets = candidate.get("targets")
    if isinstance(targets, list):
        best = None
        for t in targets:
            if not isinstance(t, dict):
                continue
            tr = _s884d_float(t.get("r"), None)
            price = _s884d_float(t.get("price"), None)
            if tr is None or price is None:
                continue
            if tr >= r_value:
                if best is None or tr < best[0]:
                    best = (tr, price)
        if best:
            return best[1]

        for t in targets:
            if isinstance(t, dict):
                price = _s884d_float(t.get("price"), None)
                if price is not None:
                    return price

    return None


def _s884d_simulate_one(candidate, candles):
    entry = _s884d_float(candidate.get("entry"), None)
    stop = _s884d_float(candidate.get("stop"), None)
    direction = str(candidate.get("direction") or "").upper()
    symbol = str(candidate.get("symbol") or "").upper()
    interval = str(candidate.get("interval") or "5min")
    cdate = str(candidate.get("date") or _s884d_row_date(candidate))[:10]
    candidate_at = str(candidate.get("datetime") or candidate.get("candidateAt") or f"{cdate}T00:00:00")
    setup_slug = str(candidate.get("setupSlug") or candidate.get("setup_slug") or "unknown_setup")

    if entry is None or stop is None or entry <= 0 or stop <= 0 or direction not in ["LONG", "SHORT"]:
        risk = None
    else:
        risk = (entry - stop) if direction == "LONG" else (stop - entry)

    tp1 = _s884d_target_price(candidate, 2.0)
    tp2 = _s884d_target_price(candidate, 3.0)

    if risk is None or risk <= 0 or tp1 is None:
        return {
            "resultStatus": "NO_EVAL",
            "terminalEvent": "NO_EVAL",
            "resultR": 0.0,
            "mfeR": 0.0,
            "maeR": 0.0,
            "firstEventAt": None,
            "candlesChecked": 0,
            "entry": entry,
            "stop": stop,
            "tp1": tp1,
            "tp2": tp2,
        }

    future = []
    for row in candles:
        if str(row.get("date")) != cdate:
            continue
        dt = str(row.get("datetime") or "")
        if dt >= candidate_at:
            future.append(row)

    if not future:
        return {
            "resultStatus": "NO_EVAL",
            "terminalEvent": "NO_EVAL",
            "resultR": 0.0,
            "mfeR": 0.0,
            "maeR": 0.0,
            "firstEventAt": None,
            "candlesChecked": 0,
            "entry": entry,
            "stop": stop,
            "tp1": tp1,
            "tp2": tp2,
        }

    mfe_r = 0.0
    mae_r = 0.0
    terminal = None
    result_status = None
    result_r = None
    first_event_at = None
    checked = 0

    for row in future:
        checked += 1
        high = _s884d_float(row.get("high"), None)
        low = _s884d_float(row.get("low"), None)

        if high is None or low is None:
            continue

        if direction == "LONG":
            mfe_r = max(mfe_r, (high - entry) / risk)
            mae_r = max(mae_r, (entry - low) / risk)

            # Same-candle ambiguity: stop first, conservative.
            if low <= stop:
                terminal = "STOP"
                result_status = "FAILED"
                result_r = -1.0
                first_event_at = str(row.get("datetime") or "")
                break
            if tp2 is not None and high >= tp2:
                terminal = "TP2"
                result_status = "WORKED"
                result_r = 3.0
                first_event_at = str(row.get("datetime") or "")
                break
            if high >= tp1:
                terminal = "TP1"
                result_status = "WORKED"
                result_r = 2.0
                first_event_at = str(row.get("datetime") or "")
                break

        else:
            mfe_r = max(mfe_r, (entry - low) / risk)
            mae_r = max(mae_r, (high - entry) / risk)

            # Same-candle ambiguity: stop first, conservative.
            if high >= stop:
                terminal = "STOP"
                result_status = "FAILED"
                result_r = -1.0
                first_event_at = str(row.get("datetime") or "")
                break
            if tp2 is not None and low <= tp2:
                terminal = "TP2"
                result_status = "WORKED"
                result_r = 3.0
                first_event_at = str(row.get("datetime") or "")
                break
            if low <= tp1:
                terminal = "TP1"
                result_status = "WORKED"
                result_r = 2.0
                first_event_at = str(row.get("datetime") or "")
                break

    if terminal is None:
        last = future[-1]
        close = _s884d_float(last.get("close"), entry)
        if direction == "LONG":
            result_r = (close - entry) / risk
        else:
            result_r = (entry - close) / risk

        terminal = "SESSION_CLOSE"
        result_status = "SESSION_CLOSE"
        first_event_at = str(last.get("datetime") or "")

    return {
        "resultStatus": result_status,
        "terminalEvent": terminal,
        "resultR": round(float(result_r or 0.0), 6),
        "mfeR": round(float(mfe_r or 0.0), 6),
        "maeR": round(float(mae_r or 0.0), 6),
        "firstEventAt": first_event_at,
        "candlesChecked": checked,
        "entry": round(float(entry), 6) if entry is not None else None,
        "stop": round(float(stop), 6) if stop is not None else None,
        "tp1": round(float(tp1), 6) if tp1 is not None else None,
        "tp2": round(float(tp2), 6) if tp2 is not None else None,
    }


def _s884d_run_outcomes_robust(
    symbols=None,
    start_date=None,
    end_date=None,
    intervals="5min",
    publish=True,
    sync_supabase=False,
    max_candidates=25000,
    **kwargs,
):
    import json
    from collections import defaultdict, Counter

    interval_value = intervals or kwargs.get("interval") or "5min"
    symbols_list = _s884d_parse_symbols(symbols)
    intervals_list = _s884d_parse_intervals(interval_value)

    read = _s884d_read_candidates(
        symbols=",".join(symbols_list),
        intervals=",".join(intervals_list),
        start_date=start_date,
        end_date=end_date,
    )
    candidates = read.get("rows") or []
    if max_candidates:
        candidates = candidates[: int(max_candidates)]

    candles_by_key = _s884d_read_candles(
        symbols=",".join(symbols_list),
        intervals=",".join(intervals_list),
        start_date=start_date,
        end_date=end_date,
    )

    outcomes = []
    counts = Counter()

    for cand in candidates:
        symbol = str(cand.get("symbol") or "").upper()
        interval = str(cand.get("interval") or "5min")
        candles = candles_by_key.get((symbol, interval), [])

        sim = _s884d_simulate_one(cand, candles)

        candidate_id = str(cand.get("candidateId") or cand.get("candidate_id") or "")
        cdate = str(cand.get("date") or _s884d_row_date(cand))[:10]
        candidate_at = str(cand.get("datetime") or cand.get("candidateAt") or f"{cdate}T00:00:00")
        setup_slug = str(cand.get("setupSlug") or cand.get("setup_slug") or "unknown_setup")
        direction = str(cand.get("direction") or "").upper()

        oid = "s884d:" + _s884d_hash_id([candidate_id, symbol, setup_slug, direction, interval, candidate_at, sim.get("terminalEvent")])

        out = {
            "outcomeId": oid,
            "candidateId": candidate_id,
            "symbol": symbol,
            "setupSlug": setup_slug,
            "direction": direction,
            "interval": interval,
            "candidateAt": candidate_at,
            "sessionDate": cdate,
            "resultStatus": sim.get("resultStatus"),
            "terminalEvent": sim.get("terminalEvent"),
            "resultR": sim.get("resultR"),
            "mfeR": sim.get("mfeR"),
            "maeR": sim.get("maeR"),
            "entry": sim.get("entry"),
            "stop": sim.get("stop"),
            "tp1": sim.get("tp1"),
            "tp2": sim.get("tp2"),
            "firstEventAt": sim.get("firstEventAt"),
            "candlesChecked": sim.get("candlesChecked"),
            "outcomeVersion": S884D_ROBUST_OUTCOME_SIMULATOR_HOTFIX_VERSION,
            "slippageModel": "none_research_only_conservative_stop_first",
            "payload": {
                "candidate": cand,
                "policy": {
                    "researchOnly": True,
                    "doesNotChangeClientDelivery": True,
                    "clientReleaseAllowed": False,
                    "syncSupabaseRequested": bool(sync_supabase),
                    "syncSupabasePerformed": False,
                },
            },
        }

        outcomes.append(out)
        counts[str(out.get("resultStatus") or "UNKNOWN").lower()] += 1

    files_written = 0
    if publish:
        out_root = _s871a_data_lake_dir() / "simulated_outcomes"
        by_symbol_interval = defaultdict(list)
        for row in outcomes:
            by_symbol_interval[(row.get("symbol"), row.get("interval"))].append(row)

        for (symbol, interval), rows_out in by_symbol_interval.items():
            folder = out_root / str(interval) / str(symbol).upper()
            folder.mkdir(parents=True, exist_ok=True)
            path = folder / f"{start_date}_{end_date}.jsonl"
            with path.open("w", encoding="utf-8") as fh:
                for row in rows_out:
                    fh.write(json.dumps(row, ensure_ascii=False, default=str) + "\n")
            files_written += 1

    worked = int(counts.get("worked", 0))
    failed = int(counts.get("failed", 0))
    session_close = int(counts.get("session_close", 0))
    no_eval = int(counts.get("no_eval", 0))
    closed = worked + failed + session_close

    summary = {
        "filesScanned": int(read.get("filesScanned") or 0),
        "filesSucceeded": int(read.get("filesSucceeded") or 0),
        "filesFailed": int(read.get("filesFailed") or 0),
        "candidatesRead": len(candidates),
        "outcomesWritten": len(outcomes),
        "worked": worked,
        "failed": failed,
        "session_close": session_close,
        "open": 0,
        "no_eval": no_eval,
        "closed": closed,
        "filesWritten": files_written,
    }

    return {
        "ok": True,
        "storageVersion": "s8_71e_historical_outcome_simulator_v1",
        "outcomeSimulatorHotfixVersion": S884D_ROBUST_OUTCOME_SIMULATOR_HOTFIX_VERSION,
        "summary": summary,
        "errorCount": 0,
        "errors": [],
        "policy": {
            "researchOnly": True,
            "doesNotChangeClientDelivery": True,
            "doesNotSendTelegram": True,
            "clientReleaseAllowed": False,
            "syncSupabaseRequested": bool(sync_supabase),
            "syncSupabasePerformed": False,
        },
    }


@app.post("/engine/research/historical-learning/outcomes/run-robust")
def engine_research_historical_learning_outcomes_run_robust(
    symbols: str = None,
    start_date: str = None,
    end_date: str = None,
    intervals: str = "5min",
    publish: bool = True,
    sync_supabase: bool = False,
    max_candidates: int = 25000,
):
    return _s884d_run_outcomes_robust(
        symbols=symbols,
        start_date=start_date,
        end_date=end_date,
        intervals=intervals,
        publish=publish,
        sync_supabase=sync_supabase,
        max_candidates=max_candidates,
    )


