# === S8.84B Robust Feature Builder Hotfix ===================================
S884B_ROBUST_FEATURE_BUILDER_HOTFIX_VERSION = "s8_84b_robust_feature_builder_hotfix_v1"


def _s884b_parse_symbols(value):
    if not value:
        return []
    if isinstance(value, list):
        return [str(x).strip().upper() for x in value if str(x).strip()]
    return [p.strip().upper() for p in str(value).replace(";", ",").split(",") if p.strip()]


def _s884b_parse_intervals(value):
    try:
        return _s871c_parse_intervals(value or "5min")
    except Exception:
        return [p.strip() for p in str(value or "5min").replace(";", ",").split(",") if p.strip()]


def _s884b_date_set(start_date, end_date):
    from datetime import date, timedelta

    if not start_date:
        start_date = end_date
    if not end_date:
        end_date = start_date

    s = date.fromisoformat(str(start_date))
    e = date.fromisoformat(str(end_date))
    if e < s:
        s, e = e, s

    out = []
    cur = s
    while cur <= e:
        out.append(cur.isoformat())
        cur += timedelta(days=1)
    return set(out)


def _s884b_float(value, default=None):
    try:
        if value is None:
            return default
        return float(value)
    except Exception:
        return default


def _s884b_read_json_records(path):
    import json

    out = []
    try:
        if path.suffix == ".jsonl":
            for line in path.read_text(encoding="utf-8").splitlines():
                line = line.strip()
                if line:
                    payload = json.loads(line)
                    if isinstance(payload, dict):
                        out.append(payload)
        elif path.suffix == ".json":
            payload = json.loads(path.read_text(encoding="utf-8") or "null")
            if isinstance(payload, list):
                out.extend([x for x in payload if isinstance(x, dict)])
            elif isinstance(payload, dict):
                for key in ["candles", "rows", "items", "results", "data"]:
                    if isinstance(payload.get(key), list):
                        out.extend([x for x in payload[key] if isinstance(x, dict)])
                        break
                else:
                    out.append(payload)
    except Exception:
        return []

    return out


def _s884b_row_date(row):
    value = row.get("date") or row.get("sessionDate") or row.get("datetime") or row.get("time") or row.get("timestamp")
    return str(value or "")[:10]


def _s884b_row_datetime(row):
    return str(row.get("datetime") or row.get("time") or row.get("timestamp") or row.get("date") or "")


def _s884b_read_normalized_rows(symbols, intervals, start_date, end_date):
    root = _s871a_data_lake_dir() / "normalized_candles"
    symbol_list = _s884b_parse_symbols(symbols)
    interval_list = _s884b_parse_intervals(intervals or "5min")
    dates = _s884b_date_set(start_date, end_date)

    files_scanned = 0
    files_succeeded = 0
    files_failed = 0
    rows = []

    for interval in interval_list:
        for symbol in symbol_list:
            folder = root / interval / symbol
            if not folder.exists():
                continue

            for path in list(folder.glob("*.jsonl")) + list(folder.glob("*.json")):
                path_text = str(path)
                if not any(d in path_text for d in dates):
                    continue

                files_scanned += 1
                try:
                    records = _s884b_read_json_records(path)
                    files_succeeded += 1
                except Exception:
                    records = []
                    files_failed += 1

                for row in records:
                    row_date = _s884b_row_date(row)
                    if row_date not in dates:
                        continue

                    row_symbol = str(row.get("symbol") or symbol).upper()
                    row_interval = str(row.get("interval") or interval)

                    if row_symbol != symbol:
                        continue
                    if row_interval != interval:
                        continue

                    normalized = dict(row)
                    normalized["symbol"] = row_symbol
                    normalized["interval"] = row_interval
                    normalized["date"] = row_date
                    normalized["datetime"] = _s884b_row_datetime(row) or f"{row_date}T00:00:00"
                    rows.append(normalized)

    rows.sort(key=lambda r: (str(r.get("symbol")), str(r.get("interval")), str(r.get("date")), str(r.get("datetime"))))
    return {
        "filesScanned": files_scanned,
        "filesSucceeded": files_succeeded,
        "filesFailed": files_failed,
        "rows": rows,
    }


def _s884b_ema(prev, value, period):
    if value is None:
        return prev
    if prev is None:
        return value
    alpha = 2.0 / (float(period) + 1.0)
    return (value * alpha) + (prev * (1.0 - alpha))


def _s884b_build_features_for_group(rows):
    from collections import deque

    out = []
    ema20 = None
    prev_close = None
    gains = deque(maxlen=14)
    losses = deque(maxlen=14)
    trs = deque(maxlen=14)
    volumes = deque(maxlen=20)
    cum_pv = 0.0
    cum_vol = 0.0
    opening_high = None
    opening_low = None
    opening_bars = 0

    for row in rows:
        open_ = _s884b_float(row.get("open"), None)
        high = _s884b_float(row.get("high"), None)
        low = _s884b_float(row.get("low"), None)
        close = _s884b_float(row.get("close"), None)
        volume = _s884b_float(row.get("volume"), 0.0)

        if close is None or high is None or low is None:
            continue

        if open_ is None:
            open_ = close

        typical = (high + low + close) / 3.0
        if volume and volume > 0:
            cum_pv += typical * volume
            cum_vol += volume
        vwap = (cum_pv / cum_vol) if cum_vol > 0 else close

        ema20 = _s884b_ema(ema20, close, 20)

        if prev_close is None:
            tr = high - low
            change = 0.0
        else:
            tr = max(high - low, abs(high - prev_close), abs(low - prev_close))
            change = close - prev_close

        trs.append(tr)
        atr14 = sum(trs) / len(trs) if trs else None

        gains.append(max(change, 0.0))
        losses.append(abs(min(change, 0.0)))
        avg_gain = sum(gains) / len(gains) if gains else 0.0
        avg_loss = sum(losses) / len(losses) if losses else 0.0
        if avg_loss == 0:
            rsi14 = 100.0 if avg_gain > 0 else 50.0
        else:
            rs = avg_gain / avg_loss
            rsi14 = 100.0 - (100.0 / (1.0 + rs))

        prev_volume = volumes[-1] if len(volumes) else None
        volumes.append(volume or 0.0)
        volume_sma20 = sum(volumes) / len(volumes) if volumes else 0.0
        rvol20 = (volume / volume_sma20) if volume_sma20 and volume is not None else None
        volume_acceleration = (volume / prev_volume) if prev_volume and prev_volume > 0 and volume is not None else None

        if opening_bars < 5:
            opening_high = high if opening_high is None else max(opening_high, high)
            opening_low = low if opening_low is None else min(opening_low, low)
            opening_bars += 1

        bar_range_pct = ((high - low) / close * 100.0) if close else None
        close_location = ((close - low) / (high - low)) if high != low else 0.5
        distance_vwap = ((close - vwap) / vwap * 100.0) if vwap else None
        distance_ema20 = ((close - ema20) / ema20 * 100.0) if ema20 else None

        feature = {
            "symbol": row.get("symbol"),
            "interval": row.get("interval"),
            "datetime": row.get("datetime"),
            "date": row.get("date"),
            "session": row.get("session") or "regular",
            "open": round(open_, 6),
            "high": round(high, 6),
            "low": round(low, 6),
            "close": round(close, 6),
            "volume": volume,
            "vwap": round(vwap, 6) if vwap is not None else None,
            "ema20": round(ema20, 6) if ema20 is not None else None,
            "atr14": round(atr14, 6) if atr14 is not None else None,
            "rsi14": round(rsi14, 6) if rsi14 is not None else None,
            "volumeSma20": round(volume_sma20, 6) if volume_sma20 is not None else None,
            "rvol20": round(rvol20, 6) if rvol20 is not None else None,
            "volumeAcceleration": round(volume_acceleration, 6) if volume_acceleration is not None else None,
            "barRangePct": round(bar_range_pct, 6) if bar_range_pct is not None else None,
            "closeLocation": round(close_location, 6) if close_location is not None else None,
            "distanceFromVwapPct": round(distance_vwap, 6) if distance_vwap is not None else None,
            "distanceFromEma20Pct": round(distance_ema20, 6) if distance_ema20 is not None else None,
            "openingRangeHigh": round(opening_high, 6) if opening_high is not None else None,
            "openingRangeLow": round(opening_low, 6) if opening_low is not None else None,
            "openingRangeBars": opening_bars,
            "source": {
                "normalizedFeatureHotfixVersion": S884B_ROBUST_FEATURE_BUILDER_HOTFIX_VERSION,
            },
            "featureVersion": S884B_ROBUST_FEATURE_BUILDER_HOTFIX_VERSION,
        }

        out.append(feature)
        prev_close = close

    return out


def _s884b_build_features_robust(
    symbols=None,
    start_date=None,
    end_date=None,
    intervals="5min",
    publish=True,
    **kwargs,
):
    import json
    from collections import defaultdict

    interval_value = intervals or kwargs.get("interval") or "5min"

    read = _s884b_read_normalized_rows(
        symbols=symbols,
        intervals=interval_value,
        start_date=start_date,
        end_date=end_date,
    )
    rows = read.get("rows") or []

    groups = defaultdict(list)
    for row in rows:
        groups[(row.get("symbol"), row.get("interval"), row.get("date"))].append(row)

    features = []
    for key, group_rows in groups.items():
        group_rows.sort(key=lambda r: str(r.get("datetime") or ""))
        features.extend(_s884b_build_features_for_group(group_rows))

    files_written = 0
    if publish:
        out_root = _s871a_data_lake_dir() / "features"
        by_symbol_interval = defaultdict(list)
        for feature in features:
            by_symbol_interval[(feature.get("symbol"), feature.get("interval"))].append(feature)

        for (symbol, interval), rows_out in by_symbol_interval.items():
            folder = out_root / str(interval) / str(symbol).upper()
            folder.mkdir(parents=True, exist_ok=True)
            path = folder / f"{start_date}_{end_date}.jsonl"
            with path.open("w", encoding="utf-8") as fh:
                for feature in rows_out:
                    fh.write(json.dumps(feature, ensure_ascii=False, default=str) + "\n")
            files_written += 1

    summary = {
        "filesScanned": int(read.get("filesScanned") or 0),
        "filesSucceeded": int(read.get("filesSucceeded") or 0),
        "filesFailed": int(read.get("filesFailed") or 0),
        "normalizedRowsRead": len(rows),
        "featureRowsWritten": len(features),
        "filesWritten": files_written,
    }

    return {
        "ok": True,
        "storageVersion": "s8_71c_historical_feature_builder_v1",
        "featureBuilderHotfixVersion": S884B_ROBUST_FEATURE_BUILDER_HOTFIX_VERSION,
        "summary": summary,
        "errorCount": 0,
        "errors": [],
        "policy": {
            "researchOnly": True,
            "doesNotChangeClientDelivery": True,
            "clientReleaseAllowed": False,
        },
    }


@app.post("/engine/research/historical-learning/features/build-robust")
def engine_research_historical_learning_features_build_robust(
    symbols: str = None,
    start_date: str = None,
    end_date: str = None,
    intervals: str = "5min",
    publish: bool = True,
):
    return _s884b_build_features_robust(
        symbols=symbols,
        start_date=start_date,
        end_date=end_date,
        intervals=intervals,
        publish=publish,
    )


