# === S8.84A Setup Replay JSONL Reader Hotfix ================================
S884A_SETUP_REPLAY_JSONL_READER_HOTFIX_VERSION = "s8_84a_setup_replay_jsonl_reader_hotfix_v1"


def _s884a_parse_symbols(value):
    if not value:
        return []
    if isinstance(value, list):
        return [str(x).strip().upper() for x in value if str(x).strip()]
    return [p.strip().upper() for p in str(value).replace(";", ",").split(",") if p.strip()]


def _s884a_parse_intervals(value):
    try:
        return _s871c_parse_intervals(value or "5min")
    except Exception:
        return [p.strip() for p in str(value or "5min").split(",") if p.strip()]


def _s884a_date_set(start_date, end_date):
    from datetime import date, timedelta

    if not start_date:
        start_date = end_date
    if not end_date:
        end_date = start_date

    s = date.fromisoformat(str(start_date))
    e = date.fromisoformat(str(end_date))
    if e < s:
        s, e = e, s

    out = []
    cur = s
    while cur <= e:
        out.append(cur.isoformat())
        cur += timedelta(days=1)
    return set(out)


def _s884a_float(value, default=None):
    try:
        if value is None:
            return default
        return float(value)
    except Exception:
        return default


def _s884a_grade(score):
    if score >= 90:
        return "A+"
    if score >= 80:
        return "A"
    if score >= 70:
        return "B"
    return "C"


def _s884a_hash_id(parts):
    import hashlib
    return hashlib.sha1("|".join([str(p) for p in parts]).encode("utf-8")).hexdigest()[:20]


def _s884a_read_json_records(path):
    import json

    out = []
    try:
        if path.suffix == ".jsonl":
            for line in path.read_text(encoding="utf-8").splitlines():
                line = line.strip()
                if line:
                    payload = json.loads(line)
                    if isinstance(payload, dict):
                        out.append(payload)
        elif path.suffix == ".json":
            payload = json.loads(path.read_text(encoding="utf-8") or "null")
            if isinstance(payload, list):
                out.extend([x for x in payload if isinstance(x, dict)])
            elif isinstance(payload, dict):
                for key in ["features", "rows", "items", "results"]:
                    if isinstance(payload.get(key), list):
                        out.extend([x for x in payload[key] if isinstance(x, dict)])
                        break
                else:
                    out.append(payload)
    except Exception:
        return []

    return out


def _s884a_read_feature_rows(symbols, intervals, start_date, end_date):
    feature_root = _s871a_data_lake_dir() / "features"
    symbol_set = set(_s884a_parse_symbols(symbols))
    interval_list = _s884a_parse_intervals(intervals or "5min")
    dates = _s884a_date_set(start_date, end_date)

    files_scanned = 0
    files_succeeded = 0
    files_failed = 0
    rows = []

    for interval in interval_list:
        for symbol in symbol_set:
            folder = feature_root / interval / symbol
            if not folder.exists():
                continue

            for path in list(folder.glob("*.jsonl")) + list(folder.glob("*.json")):
                # Fast path filter by filename if date is present.
                path_text = str(path)
                if not any(d in path_text for d in dates):
                    continue

                files_scanned += 1
                try:
                    records = _s884a_read_json_records(path)
                    files_succeeded += 1
                except Exception:
                    records = []
                    files_failed += 1

                for row in records:
                    row_date = str(row.get("date") or row.get("sessionDate") or row.get("candidateDate") or "")[:10]
                    if row_date not in dates:
                        continue
                    if str(row.get("symbol") or "").upper() != symbol:
                        continue
                    if str(row.get("interval") or interval) != interval:
                        continue
                    rows.append(row)

    return {
        "filesScanned": files_scanned,
        "filesSucceeded": files_succeeded,
        "filesFailed": files_failed,
        "rows": rows,
    }


def _s884a_make_candidate(row, setup_slug, direction, reasons, score=78):
    symbol = str(row.get("symbol") or "").upper()
    interval = str(row.get("interval") or "5min")
    row_date = str(row.get("date") or "")[:10]
    dt = str(row.get("datetime") or row.get("time") or f"{row_date}T00:00:00")

    close = _s884a_float(row.get("close"))
    high = _s884a_float(row.get("high"), close)
    low = _s884a_float(row.get("low"), close)
    atr = _s884a_float(row.get("atr14"), None)

    if close is None or close <= 0:
        return None

    risk_unit = atr if atr and atr > 0 else max(close * 0.0125, 0.01)
    risk_unit = max(risk_unit, close * 0.004)

    direction = str(direction).upper()
    if direction == "LONG":
        entry = close
        stop = max(0.0001, close - risk_unit)
        r = entry - stop
        tp1 = entry + (2.0 * r)
        tp2 = entry + (3.0 * r)
    else:
        entry = close
        stop = close + risk_unit
        r = stop - entry
        tp1 = max(0.0001, entry - (2.0 * r))
        tp2 = max(0.0001, entry - (3.0 * r))

    if r <= 0:
        return None

    score = int(score)
    cid = "s884a:" + _s884a_hash_id([symbol, setup_slug, direction, interval, dt, round(entry, 6)])

    setup_names = {
        "vwap_reclaim_long": "VWAP Reclaim Long",
        "vwap_rejection_short": "VWAP Rejection Short",
        "opening_range_breakout_long": "Opening Range Breakout Long",
        "opening_range_breakdown_short": "Opening Range Breakdown Short",
        "large_cap_vwap_trend_long": "Large Cap VWAP Trend Long",
        "premarket_pump_short": "Premarket Pump Short",
        "gap_and_crap_short": "Gap and Crap Short",
        "gap_hold_continuation_long": "Gap Hold Continuation Long",
        "large_cap_gap_continuation": "Large Cap Gap Continuation",
        "orb_pullback_continuation": "ORB Pullback Continuation",
    }

    return {
        "candidateId": cid,
        "symbol": symbol,
        "setupSlug": setup_slug,
        "setupName": setup_names.get(setup_slug, setup_slug),
        "direction": direction,
        "interval": interval,
        "datetime": dt,
        "date": row_date,
        "session": row.get("session") or "regular",
        "status": "HISTORICAL_REPLAY",
        "score": score,
        "grade": _s884a_grade(score),
        "qualityStatus": "PASSED",
        "riskReward": 2.0,
        "entry": round(entry, 6),
        "stop": round(stop, 6),
        "targets": [
            {"r": 2.0, "price": round(tp1, 6)},
            {"r": 3.0, "price": round(tp2, 6)},
        ],
        "invalidation": "Historical replay invalidates at stop.",
        "reasons": list(reasons or []),
        "source": {
            "featureVersion": row.get("featureVersion"),
            "replayHotfixVersion": S884A_SETUP_REPLAY_JSONL_READER_HOTFIX_VERSION,
            "candleContext": {
                "vwap": row.get("vwap"),
                "ema20": row.get("ema20"),
                "atr14": row.get("atr14"),
                "rsi14": row.get("rsi14"),
                "rvol20": row.get("rvol20"),
                "volumeAcceleration": row.get("volumeAcceleration"),
                "distanceFromVwapPct": row.get("distanceFromVwapPct"),
                "openingRangeHigh": row.get("openingRangeHigh"),
                "openingRangeLow": row.get("openingRangeLow"),
            },
        },
        "clientEligible": False,
        "clientReleaseAllowed": False,
        "policy": {
            "researchOnly": True,
            "clientReleaseAllowed": False,
            "doesNotChangeClientDelivery": True,
            "replayHotfixVersion": S884A_SETUP_REPLAY_JSONL_READER_HOTFIX_VERSION,
        },
    }


def _s884a_candidates_for_row(row):
    close = _s884a_float(row.get("close"))
    high = _s884a_float(row.get("high"), close)
    low = _s884a_float(row.get("low"), close)
    vwap = _s884a_float(row.get("vwap"))
    ema20 = _s884a_float(row.get("ema20"))
    rsi = _s884a_float(row.get("rsi14"), 50)
    rvol = _s884a_float(row.get("rvol20"), 1)
    vol_acc = _s884a_float(row.get("volumeAcceleration"), 1)
    dist_vwap = _s884a_float(row.get("distanceFromVwapPct"), 0)
    orh = _s884a_float(row.get("openingRangeHigh"))
    orl = _s884a_float(row.get("openingRangeLow"))

    if close is None or high is None or low is None:
        return []

    out = []

    def add(slug, direction, cond, reasons, base_score=76):
        if cond:
            score = base_score
            if rvol and rvol >= 1.5:
                score += 4
            if vol_acc and vol_acc >= 1.2:
                score += 4
            cand = _s884a_make_candidate(row, slug, direction, reasons, score=min(score, 94))
            if cand:
                out.append(cand)

    add(
        "large_cap_vwap_trend_long",
        "LONG",
        bool(vwap and ema20 and close > vwap and close > ema20 and rsi >= 50),
        ["close_above_vwap", "close_above_ema20", "rsi_supportive"],
        80,
    )
    add(
        "vwap_reclaim_long",
        "LONG",
        bool(vwap and ema20 and low <= vwap and close > vwap and close > ema20),
        ["vwap_reclaim", "close_above_ema20"],
        82,
    )
    add(
        "vwap_rejection_short",
        "SHORT",
        bool(vwap and ema20 and high >= vwap and close < vwap and close < ema20),
        ["vwap_rejection", "close_below_ema20"],
        82,
    )
    add(
        "opening_range_breakout_long",
        "LONG",
        bool(orh and close > orh and (vol_acc or 0) >= 1.0),
        ["opening_range_breakout", "volume_confirmation"],
        78,
    )
    add(
        "opening_range_breakdown_short",
        "SHORT",
        bool(orl and close < orl and (vol_acc or 0) >= 1.0),
        ["opening_range_breakdown", "volume_confirmation"],
        78,
    )
    add(
        "gap_hold_continuation_long",
        "LONG",
        bool(vwap and close > vwap and (vol_acc or 0) >= 1.05 and rsi >= 48),
        ["gap_hold_proxy", "above_vwap", "volume_acceleration"],
        76,
    )
    add(
        "large_cap_gap_continuation",
        "LONG",
        bool(vwap and close > vwap and (rvol or 0) >= 1.15),
        ["large_cap_gap_continuation_proxy", "above_vwap", "rvol_supportive"],
        76,
    )
    add(
        "orb_pullback_continuation",
        "LONG",
        bool(orh and ema20 and close > orh and low <= orh and close > ema20),
        ["orb_breakout_pullback_hold", "above_ema20"],
        80,
    )
    add(
        "premarket_pump_short",
        "SHORT",
        bool(vwap and ema20 and dist_vwap and dist_vwap >= 1.0 and close < ema20),
        ["extended_above_vwap_proxy", "ema20_loss"],
        77,
    )
    add(
        "gap_and_crap_short",
        "SHORT",
        bool(vwap and close < vwap and (vol_acc or 0) >= 1.0),
        ["vwap_loss", "gap_and_crap_proxy"],
        77,
    )

    return out


def _s884a_run_setup_replay_robust(
    symbols=None,
    start_date=None,
    end_date=None,
    intervals="5min",
    max_candidates=25000,
    publish=True,
    **kwargs,
):
    import json
    from collections import defaultdict

    symbols_list = _s884a_parse_symbols(symbols)
    intervals_value = intervals or kwargs.get("interval") or "5min"
    intervals_list = _s884a_parse_intervals(intervals_value)

    read = _s884a_read_feature_rows(
        symbols=",".join(symbols_list),
        intervals=",".join(intervals_list),
        start_date=start_date,
        end_date=end_date,
    )
    feature_rows = read.get("rows") or []

    candidates = []
    seen = set()
    max_candidates = int(max_candidates or 25000)

    for row in feature_rows:
        for cand in _s884a_candidates_for_row(row):
            cid = cand.get("candidateId")
            if cid in seen:
                continue
            seen.add(cid)
            candidates.append(cand)
            if len(candidates) >= max_candidates:
                break
        if len(candidates) >= max_candidates:
            break

    written_by_symbol_interval = defaultdict(list)
    for cand in candidates:
        written_by_symbol_interval[(cand.get("symbol"), cand.get("interval"))].append(cand)

    files_written = 0
    if publish:
        out_root = _s871a_data_lake_dir() / "setup_candidates"
        for (symbol, interval), rows in written_by_symbol_interval.items():
            folder = out_root / str(interval) / str(symbol).upper()
            folder.mkdir(parents=True, exist_ok=True)
            path = folder / f"{start_date}_{end_date}.jsonl"
            with path.open("w", encoding="utf-8") as fh:
                for cand in rows:
                    fh.write(json.dumps(cand, ensure_ascii=False, default=str) + "\n")
            files_written += 1

    summary = {
        "filesScanned": int(read.get("filesScanned") or 0),
        "filesSucceeded": int(read.get("filesSucceeded") or 0),
        "filesFailed": int(read.get("filesFailed") or 0),
        "featureRowsRead": len(feature_rows),
        "candidatesWritten": len(candidates),
        "filesWritten": files_written,
    }

    return {
        "ok": True,
        "storageVersion": "s8_71d_historical_setup_replay_v1",
        "setupReplayHotfixVersion": S884A_SETUP_REPLAY_JSONL_READER_HOTFIX_VERSION,
        "summary": summary,
        "errorCount": 0,
        "errors": [],
        "policy": {
            "researchOnly": True,
            "doesNotChangeClientDelivery": True,
            "clientReleaseAllowed": False,
        },
    }


@app.post("/engine/research/historical-learning/setup-replay/run-robust")
def engine_research_historical_learning_setup_replay_run_robust(
    symbols: str = None,
    start_date: str = None,
    end_date: str = None,
    intervals: str = "5min",
    max_candidates: int = 25000,
    publish: bool = True,
):
    return _s884a_run_setup_replay_robust(
        symbols=symbols,
        start_date=start_date,
        end_date=end_date,
        intervals=intervals,
        max_candidates=max_candidates,
        publish=publish,
    )


